$0 ~ ("^" section ":[[:space:]]*$") {
  in_section = 1
  next
}

in_section && $0 ~ /^[^[:space:]]/ {
  in_section = 0
}

in_section && $0 ~ ("^[[:space:]]{2}" key ":[[:space:]]*") {
  value = $0
  sub("^[[:space:]]{2}" key ":[[:space:]]*", "", value)
  print value
  exit
}

$0 ~ ("^" section ":[[:space:]]*$") {
  in_section = 1
  in_subsection = 0
  next
}

in_section && $0 ~ /^[^[:space:]]/ {
  in_section = 0
  in_subsection = 0
}

in_section && $0 ~ ("^[[:space:]]{2}" subsection ":[[:space:]]*$") {
  in_subsection = 1
  next
}

in_section && in_subsection && $0 ~ /^[[:space:]]{2}[A-Za-z0-9_-]+:[[:space:]]*$/ && $0 !~ ("^[[:space:]]{2}" subsection ":[[:space:]]*$") {
  in_subsection = 0
}

in_section && in_subsection && $0 ~ ("^[[:space:]]{4}" key ":[[:space:]]*") {
  value = $0
  sub("^[[:space:]]{4}" key ":[[:space:]]*", "", value)
  print value
  exit
}

function trim(value) {
  sub(/^[[:space:]]+/, "", value)
  sub(/[[:space:]]+$/, "", value)
  gsub(/^"/, "", value)
  gsub(/"$/, "", value)
  gsub(/^'/, "", value)
  gsub(/'$/, "", value)
  return value
}

$0 ~ ("^" section ":[[:space:]]*$") {
  in_section = 1
  next
}

in_section && $0 ~ /^[^[:space:]]/ {
  in_section = 0
}

in_section && $0 ~ /^[[:space:]]*-[[:space:]]+name:[[:space:]]*/ {
  value = $0
  sub(/^[[:space:]]*-[[:space:]]+name:[[:space:]]*/, "", value)
  print trim(value)
  exit
}

statements.syntax:
if (!configFile || !deploymentFile || process.argv.length !== 4) {
  throw new Error('Usage: node scripts/render-litellm-deployment.mjs <config.yaml> <deployment.yaml>');
}

deployment.spec.template.metadata.annotations = {
  ...deployment.spec.template.metadata.annotations,
  'checksum/litellm-config': crypto.createHash('sha256').update(config).digest('hex'),
};

function validate(policy, namespace, postgres, application) {
  if (policy.schemaVersion !== 1 || !identifier(namespace) || !identifier(postgres.auth?.existingSecret)
    || typeof postgres.auth.secretKeys?.adminPasswordKey !== 'string' || !/^[a-zA-Z0-9._-]+$/.test(postgres.auth.secretKeys.adminPasswordKey)
    || postgres.auth.database !== 'litellm' || application?.metadata?.name !== 'litellm') throw new Error('POSTGRES_RECOVERY_CONFIGURATION_INVALID');
  for (const key of ['backupIntervalMinutes', 'verificationIntervalMinutes', 'maximumAgeSeconds', 'maximumDurationSeconds', 'verificationDeadlineSeconds', 'maximumBackupBytes', 'maximumRetainedBytes']) {
    if (!Number.isSafeInteger(policy[key]) || policy[key] < 1) throw new Error(`POSTGRES_RECOVERY_POLICY_INVALID:${key}`);
  }
  validateBudgets(policy);
  validateStorage(policy);
}

function validateBudgets(policy) {
  if (policy.maximumDurationSeconds >= policy.maximumAgeSeconds || policy.maximumBackupBytes + 67108864 > policy.maximumRetainedBytes) throw new Error('POSTGRES_RECOVERY_BUDGET_INVALID');
  if (policy.backupIntervalMinutes > 60 || policy.verificationIntervalMinutes > 30
    || policy.verificationIntervalMinutes > policy.backupIntervalMinutes
    || 2 * policy.maximumDurationSeconds + policy.verificationIntervalMinutes * 60 + policy.verificationDeadlineSeconds + 60 >= policy.maximumAgeSeconds) throw new Error('POSTGRES_RECOVERY_SCHEDULE_RPO_INVALID');
}

function validateStorage(policy) {
  if (!/^[1-9][0-9]*(?:Gi|Ti)$/.test(policy.persistence?.size)
    || (policy.persistence.storageClass !== null && !identifier(policy.persistence.storageClass))) throw new Error('POSTGRES_RECOVERY_STORAGE_INVALID');
  if (!policy.resources?.requests?.cpu || !policy.resources.requests.memory || !policy.resources.limits?.cpu || !policy.resources.limits.memory) throw new Error('POSTGRES_RECOVERY_RESOURCES_REQUIRED');
}

function applicationSecret(application) {
  const secrets = application.spec.template.spec.containers.find(container => container.name === 'litellm')?.envFrom?.filter(value => value.secretRef);
  if (secrets?.length !== 1 || secrets[0].prefix || !identifier(secrets[0].secretRef.name)) throw new Error('POSTGRES_RECOVERY_APPLICATION_SECRET_AMBIGUOUS');
  return secrets[0].secretRef.name;
}

function validateCredentialAuthority(application, applicationFile) {
  const config = load(fs.readFileSync(path.join(path.dirname(applicationFile), 'litellm-config.yaml'), 'utf8'));
  const environment = application.spec.template.spec.containers.find(container => container.name === 'litellm')?.env ?? [];
  if (config.general_settings?.master_key !== 'os.environ/LITELLM_MASTER_KEY'
    || environment.some(value => ['LITELLM_MASTER_KEY', 'LITELLM_SALT_KEY'].includes(value.name))) throw new Error('POSTGRES_RECOVERY_CREDENTIAL_AUTHORITY_UNSUPPORTED');
}

function configuration(policy, postgres, application, service, namespace) {
  const applicationImage = application.spec.template.spec.containers.find(container => container.name === 'litellm')?.image;
  if (!/^[a-zA-Z0-9._/-]+@sha256:[a-f0-9]{64}$/.test(applicationImage)) throw new Error('POSTGRES_RECOVERY_APPLICATION_PIN_REQUIRED');
  const [major, minor] = infrastructureChart('postgresql').appVersion.split('.').map(Number);
  return { PGHOST: service.name, PGPORT: String(service.port), PGDATABASE: postgres.auth.database, PGUSER: 'postgres',
    BACKUP_ROOT: '/backups/litellm', BACKUP_INTERVAL_SECONDS: String(policy.backupIntervalMinutes * 60), BACKUP_MAXIMUM_BYTES: String(policy.maximumBackupBytes),
    BACKUP_MAXIMUM_RETAINED_BYTES: String(policy.maximumRetainedBytes), BACKUP_MAXIMUM_AGE_SECONDS: String(policy.maximumAgeSeconds),
    BACKUP_MAXIMUM_DURATION_SECONDS: String(policy.maximumDurationSeconds), BACKUP_EXPECTED_SERVER_VERSION: String(major * 10000 + minor),
    BACKUP_CREDENTIAL_AUTHORITY_REF: `kubernetes-secret:${namespace}/${applicationSecret(application)}`,
    BACKUP_APPLICATION_IMAGE: applicationImage };
}

function cronJob(context) {
  const { policy, postgres, metadata, image, checksum, application } = context;
  const container = { name: 'backup', image, imagePullPolicy: 'IfNotPresent',
    command: ['bash', '/recovery/postgresql-recovery.sh', 'scheduled'],
    envFrom: [{ configMapRef: { name: `${name}-settings` } }], resources: policy.resources,
    securityContext: { allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: { drop: ['ALL'] } },
    volumeMounts: [{ name: 'backups', mountPath: '/backups', readOnly: false }, { name: 'script', mountPath: '/recovery', readOnly: true }, { name: 'tmp', mountPath: '/tmp' }] };
  container.env = [{ name: 'PGPASSWORD', valueFrom: { secretKeyRef: { name: postgres.auth.existingSecret, key: postgres.auth.secretKeys.adminPasswordKey } } },
    { name: 'LITELLM_MASTER_KEY', valueFrom: { secretKeyRef: { name: applicationSecret(application), key: 'LITELLM_MASTER_KEY' } } },
    { name: 'LITELLM_SALT_KEY', valueFrom: { secretKeyRef: { name: applicationSecret(application), key: 'LITELLM_SALT_KEY', optional: true } } }];
  return { apiVersion: 'batch/v1', kind: 'CronJob', metadata: { ...metadata, name }, spec: {
    schedule: `*/${policy.verificationIntervalMinutes} * * * *`, timeZone: 'Etc/UTC', concurrencyPolicy: 'Forbid',
    startingDeadlineSeconds: policy.verificationDeadlineSeconds, successfulJobsHistoryLimit: 3, failedJobsHistoryLimit: 10,
    jobTemplate: { spec: { backoffLimit: 0, activeDeadlineSeconds: policy.maximumDurationSeconds + 60,
      template: { metadata: { labels: metadata.labels, annotations: { 'checksum/recovery': checksum } }, spec: {
        automountServiceAccountToken: false, restartPolicy: 'Never',
        securityContext: { runAsNonRoot: true, runAsUser: 1001, runAsGroup: 1001, fsGroup: 1001, fsGroupChangePolicy: 'OnRootMismatch', seccompProfile: { type: 'RuntimeDefault' } },
        containers: [container], volumes: [{ name: 'backups', persistentVolumeClaim: { claimName: name } },
          { name: 'script', configMap: { name: `${name}-script`, defaultMode: 0o444 } }, { name: 'tmp', emptyDir: { sizeLimit: '256Mi' } }] },
      } } },
  } };
}

function networkPolicies(metadata, service) {
  const database = { matchLabels: { ...service.selector, 'k8s:io.kubernetes.pod.namespace': metadata.namespace } };
  const backup = { matchLabels: { app: name, 'k8s:io.kubernetes.pod.namespace': metadata.namespace } };
  const ports = [...new Set([service.port, service.targetPort])].map(port => ({ port: String(port), protocol: 'TCP' }));
  return [
    { apiVersion: 'cilium.io/v2', kind: 'CiliumNetworkPolicy', metadata: { ...metadata, name }, spec: { endpointSelector: backup, egress: [
      { toEndpoints: [{ matchLabels: { 'k8s:io.kubernetes.pod.namespace': 'kube-system', 'k8s:k8s-app': 'kube-dns' } }], toPorts: [{ ports: [{ port: '53', protocol: 'UDP' }, { port: '53', protocol: 'TCP' }], rules: { dns: [{ matchPattern: '*' }] } }] },
      { toEndpoints: [database], toPorts: [{ ports }] },
    ] } },
    { apiVersion: 'cilium.io/v2', kind: 'CiliumNetworkPolicy', metadata: { ...metadata, name: `${name}-database` }, spec: { endpointSelector: database, ingress: [{ fromEndpoints: [backup], toPorts: [{ ports: [{ port: String(service.targetPort), protocol: 'TCP' }] }] }] } },
  ];
}

export function renderPostgresqlRecovery(namespace, policyFile, postgresFile, applicationFile, helm = 'helm', release = 'postgresql') {
  const policy = load(fs.readFileSync(policyFile, 'utf8')); const postgres = load(fs.readFileSync(postgresFile, 'utf8'));
  const application = loadAll(fs.readFileSync(applicationFile, 'utf8')).find(value => value?.kind === 'Deployment' && value.metadata?.name === 'litellm');
  validate(policy, namespace, postgres, application);
  validateCredentialAuthority(application, applicationFile);
  const version = JSON.parse(fs.readFileSync(path.join(root, 'versions.json'), 'utf8'));
  const image = version.infrastructure.postgresql.replace(/:[^:@]+@/, '@');
  const script = fs.readFileSync(path.join(root, 'scripts/postgresql-recovery.sh'), 'utf8');
  if (!identifier(release) || release.length > 53) throw new Error('POSTGRES_RECOVERY_RELEASE_INVALID');
  const service = statefulDatabaseService('postgresql', release, namespace, postgresFile, helm);
  const data = configuration(policy, postgres, application, service, namespace);
  const checksum = createHash('sha256').update(script).update(JSON.stringify(data)).digest('hex');
  const metadata = { namespace, labels: { app: name, 'app.kubernetes.io/managed-by': 'kubeclaw-infrastructure' } };
  const storage = { accessModes: ['ReadWriteOnce'], resources: { requests: { storage: policy.persistence.size } },
    ...(policy.persistence.storageClass === null ? {} : { storageClassName: policy.persistence.storageClass }) };
  const context = { policy, postgres, metadata, image, checksum, application };
  return [{ apiVersion: 'v1', kind: 'ConfigMap', metadata: { ...metadata, name: `${name}-settings` }, data },
    { apiVersion: 'v1', kind: 'ConfigMap', metadata: { ...metadata, name: `${name}-script` }, data: { 'postgresql-recovery.sh': script } },
    { apiVersion: 'v1', kind: 'PersistentVolumeClaim', metadata: { ...metadata, name }, spec: storage },
    ...networkPolicies(metadata, service), cronJob(context)];
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const preflight = process.argv[2] === '--preflight';
  const args = process.argv.slice(preflight ? 3 : 2);
  if (![4, 5].includes(args.length)) throw new Error('Usage: render-postgresql-recovery.mjs [--preflight] NAMESPACE POLICY POSTGRES_VALUES LITELLM_DEPLOYMENT [RELEASE]');
  const documents = renderPostgresqlRecovery(...args.slice(0, 4), 'helm', args[4] ?? 'postgresql');
  if (preflight) preflightRecoveryVolume(args[0], documents);
  process.stdout.write(documents.map(value => dump(value, { noRefs: true, lineWidth: -1 })).join('---\n'));
}

function profile(selector) {
  const name = selector?.matchLabels?.['app.kubernetes.io/name'];
  return ['redis', 'postgresql'].includes(name) && selector.matchLabels['app.kubernetes.io/instance'] === name ? name : undefined;
}

function bindSelector(selector, service) {
  selector.matchLabels = { ...selector.matchLabels, ...service.selector };
}

function defaultPorts(name) {
  return { redis: [6379], postgresql: [5432] }[name];
}

function bindPorts(rule, original, ports) {
  if (rule.toPorts?.length !== 1 || rule.toPorts[0].ports?.length !== original.length
    || rule.toPorts[0].ports.some((port, index) => port.port !== String(original[index]) || port.protocol !== 'TCP')) {
    throw new Error('STATEFUL_NETWORK_PORT_CONTRACT_INVALID');
  }
  rule.toPorts[0].ports = [...new Set(ports)].map(port => ({ port: String(port), protocol: 'TCP' }));
}

function bindEgress(rule, services) {
  const selections = (rule.toEndpoints ?? []).map(selector => ({ selector, name: profile(selector) })).filter(item => item.name);
  if (!selections.length) return undefined;
  if (selections.length !== 1 || rule.toEndpoints.length !== 1) throw new Error('STATEFUL_NETWORK_DESTINATION_AMBIGUOUS');
  const { selector, name } = selections[0];
  bindSelector(selector, services[name]);
  bindPorts(rule, defaultPorts(name), services[name].ports.flatMap(port => [port.port, port.targetPort]));
  return name;
}

export function renderStatefulNetworkPolicies(file, namespace, selections, helm = 'helm') {
  const documents = loadAll(fs.readFileSync(file, 'utf8')).filter(Boolean);
  const services = Object.fromEntries(['redis', 'postgresql'].map(name =>
    [name, statefulDatabaseService(name, selections[name].release, namespace, selections[name].values, helm)]));
  const seen = Object.fromEntries(Object.keys(services).map(name => [name, { ingress: 0, egress: 0 }]));
  for (const document of documents) {
    if (document.kind !== 'CiliumNetworkPolicy') continue;
    const owner = profile(document.spec.endpointSelector);
    if (owner) {
      bindSelector(document.spec.endpointSelector, services[owner]);
      for (const rule of document.spec.ingress ?? []) bindPorts(rule, defaultPorts(owner), services[owner].ports.map(port => port.targetPort));
      seen[owner].ingress++;
    }
    for (const rule of document.spec.egress ?? []) {
      const name = bindEgress(rule, services);
      if (name) seen[name].egress++;
    }
  }
  for (const counts of Object.values(seen)) {
    if (!counts.ingress || !counts.egress) throw new Error('STATEFUL_NETWORK_POLICY_MISSING');
  }
  return documents;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 8) throw new Error('Usage: render-stateful-network-policies.mjs POLICY NAMESPACE REDIS_RELEASE REDIS_VALUES POSTGRESQL_RELEASE POSTGRESQL_VALUES');
  const [file, namespace, redisRelease, redisValues, postgresRelease, postgresValues] = process.argv.slice(2);
  const documents = renderStatefulNetworkPolicies(file, namespace, {
    redis: { release: redisRelease, values: redisValues }, postgresql: { release: postgresRelease, values: postgresValues },
  });
  process.stdout.write(documents.map(value => dump(value, { noRefs: true, lineWidth: -1 })).join('---\n'));
}

function validateConfig(config) {
  if (!config || typeof config !== 'object' || Array.isArray(config)
    || Object.keys(config).some(key => !['capacity', 'storageClassName'].includes(key))
    || !/^[1-9][0-9]*(Mi|Gi|Ti)$/.test(config.capacity ?? '')
    || !/^[a-z0-9]([-a-z0-9.]*[a-z0-9])?$/.test(config.storageClassName ?? '')
    || config.storageClassName.length > 253) throw new Error('REGISTRY_STORAGE_CONFIG_INVALID');
}

function dataMount(pod) {
  return pod?.containers?.find(item => item.name === 'registry')?.volumeMounts?.find(item => item.mountPath === dataPath);
}

function validateDeployment(existing) {
  if (existing.kind !== 'Deployment' || existing.metadata?.name !== 'registry-local') throw new Error('REGISTRY_DEPLOYMENT_INVALID');
  const pod = existing.spec?.template?.spec;
  const mount = dataMount(pod);
  const volume = pod?.volumes?.find(item => item.name === mount?.name);
  if (!mount || mount.subPath || mount.subPathExpr || volume?.persistentVolumeClaim?.claimName !== claimName) {
    throw new Error('REGISTRY_EPHEMERAL_MIGRATION_REQUIRED');
  }
}

function validatePvc(pvc, config) {
  if (pvc.kind !== 'PersistentVolumeClaim' || pvc.metadata?.name !== claimName
    || pvc.spec?.accessModes?.length !== 1 || pvc.spec.accessModes[0] !== 'ReadWriteOncePod'
    || pvc.spec.storageClassName !== config.storageClassName
    || pvc.spec.resources?.requests?.storage !== config.capacity) throw new Error('REGISTRY_EXISTING_STORAGE_MISMATCH');
}

export function renderRegistryLocal(config, mode = 'serve', existing = null, existingPvc = null) {
  validateConfig(config);
  if (!['serve', 'gc-dry-run', 'gc'].includes(mode)) throw new Error('REGISTRY_MODE_INVALID');
  // Never replace an old writable container layer with an empty volume.
  // Absence is supplied only by kubectl --ignore-not-found; lookup errors abort.
  if (existing) validateDeployment(existing);
  else if (mode !== 'serve') throw new Error('REGISTRY_GC_EXISTING_DEPLOYMENT_REQUIRED');
  if (existingPvc) validatePvc(existingPvc, config);
  if (existing && !existingPvc) throw new Error('REGISTRY_EXISTING_STORAGE_MISSING');
  const docs = parseAllDocuments(fs.readFileSync(template, 'utf8')).map(doc => {
    if (doc.errors.length) throw new Error('REGISTRY_TEMPLATE_INVALID');
    return doc.toJS();
  });
  const pvc = docs.find(doc => doc.kind === 'PersistentVolumeClaim');
  pvc.spec.storageClassName = config.storageClassName;
  pvc.spec.resources.requests.storage = config.capacity;
  const deployment = docs.find(doc => doc.kind === 'Deployment');
  deployment.spec.replicas = mode === 'serve' ? 1 : 0;
  if (mode !== 'serve') {
    const spec = structuredClone(deployment.spec.template.spec);
    spec.restartPolicy = 'Never';
    const container = spec.containers[0];
    container.args = ['garbage-collect', ...(mode === 'gc-dry-run' ? ['--dry-run'] : []), configPath];
    delete container.ports;
    delete container.readinessProbe;
    delete container.livenessProbe;
    // RWOP prevents overlap even while the old writer Pod is terminating.
    // No delete-untagged: every manifest, including digest-only references, survives.
    docs.push({ apiVersion: 'batch/v1', kind: 'Job', metadata: { name: `registry-local-${mode}` },
      spec: { backoffLimit: 0, template: { metadata: { labels: { app: 'registry-local-gc' } }, spec } } });
  }
  return docs;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const [configFile, mode = 'serve', existingFile, pvcFile, ...extra] = process.argv.slice(2);
  if (!configFile || !existingFile || !pvcFile || extra.length) throw new Error('Usage: render-registry-local.mjs config.json serve|gc-dry-run|gc existing-deployment.json existing-pvc.json');
  const existingText = fs.readFileSync(existingFile, 'utf8').trim();
  const pvcText = fs.readFileSync(pvcFile, 'utf8').trim();
  const docs = renderRegistryLocal(JSON.parse(fs.readFileSync(configFile, 'utf8')), mode, existingText ? JSON.parse(existingText) : null, pvcText ? JSON.parse(pvcText) : null);
  process.stdout.write(docs.map(doc => stringify(doc)).join('---\n'));
}

export function renderNativeWorkerNode(policy) {
  const selected = validateNativeNodePolicy(policy);
  const pools = Object.fromEntries(['buster', 'prism'].map(role => [role, nativePoolPolicy(selected, role)]));
  const version = JSON.parse(fs.readFileSync(path.join(repository, 'versions.json'), 'utf8')).buildArgs.NODE_BASE;
  const nodeVersion = /^node:(\d+\.\d+\.\d+)-/.exec(version)?.[1];
  if (!nodeVersion) throw new Error('NATIVE_HOST_NODE_VERSION_NOT_SELECTED');
  const setup = { schemaVersion: 1, nodeVersion, pools: Object.fromEntries(Object.entries(pools).map(([role, pool]) => [role, pool.limits])) };
  const kubelet = { ...nativeNodeReservation(selected), cgroupDriver: 'systemd', cgroupsPerQOS: true, enforceNodeAllocatable: ['pods'] };
  return {
    'prism-native-values.yaml': dump({ worker: { native: { nodeName: selected.nodeName,
      namespace: selected.pools.prism.namespace, policyDigest: pools.prism.policyDigest }, replicas: 1 } }),
    'native-nri.json': `${JSON.stringify(nriPolicy(selected, pools), null, 2)}\n`,
    'containerd-nri.toml': '[plugins."io.containerd.nri.v1.nri"]\n  disable = false\n',
    'native-node-policy.json': `${JSON.stringify(setup, null, 2)}\n`,
    'buster-pool.json': `${JSON.stringify(pools.buster, null, 2)}\n`,
    'prism-pool.json': `${JSON.stringify(pools.prism, null, 2)}\n`,
    'kubelet-reservations.json': `${JSON.stringify(kubelet, null, 2)}\n`,
    'prepare-native-worker-pools.mjs': fs.readFileSync(path.join(repository, 'scripts/prepare-native-worker-pools.mjs'), 'utf8'),
    'kubeclaw-native-pools.service': unit(),
  };
}

function nriPolicy(selected, pools) {
  const containerdVersion = selected.runtime?.containerdVersion;
  if (typeof containerdVersion !== 'string' || !/^v?2\.(?:[2-9]|[1-9][0-9]+)\.[0-9]+(?:[-+][A-Za-z0-9.-]+)?$/.test(containerdVersion)) {
    throw new Error('NATIVE_NODE_SELECTED_CONTAINERD_VERSION_REQUIRED');
  }
  const roles = Object.fromEntries(['buster', 'prism'].map(role => [role, {
    namespace: selected.pools[role].namespace, container: role === 'buster' ? 'buster-v2-runtime' : 'worker',
    policyDigest: pools[role].policyDigest,
  }]));
  return { schemaVersion: 1, containerdVersion, roles };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 4) throw new Error('Usage: render-native-worker-node.mjs POLICY_YAML NEW_OUTPUT_DIRECTORY');
  const bundle = renderNativeWorkerNode(loadNativeNodePolicy(process.argv[2]));
  const directory = path.resolve(process.argv[3]);
  fs.mkdirSync(directory, { mode: 0o700 }); // Exclusive: never overwrite an operator's previous bundle.
  for (const [name, content] of Object.entries(bundle)) fs.writeFileSync(path.join(directory, name), content, { flag: 'wx', mode: 0o600 });
  process.stdout.write(`${directory}\n`);
}

export function continuousDocuments(result, namespace) {
  const documents = structuredClone(result.documents);
  const application = documents.find(document => document.kind === 'Application');
  application.spec.source = { repoURL: result.values.repository, targetRevision: 'main',
    path: `${environment}/apps`, directory: { include: 'applications.yaml' } };
  if (application.metadata.namespace !== namespace) throw new Error('GITOPS_ARGO_NAMESPACE_MISMATCH');
  return documents;
}

export function continuousApplications(manifest) {
  const documents = yaml.loadAll(manifest).filter(Boolean);
  for (const document of documents) {
    if (document.kind === 'Application') {
      // Unique bundle directories survive later promotions. Tracking main also
      // survives squash merges; no transient PR commit needs to stay reachable.
      document.spec.source.targetRevision = 'main';
    }
  }
  return documents;
}

function configuration(repository) {
  const config = JSON.parse(fs.readFileSync(path.join(repository, environment, 'config.json'), 'utf8'));
  for (const field of ['namespace', 'prismNamespace', 'argoNamespace']) {
    if (!gitOpsName(config[field])) throw new Error(`GITOPS_CONFIG_INVALID:${field}`);
  }
  return config;
}

export function renderContinuousEnvironment(repository, directory, url, revision, config) {
  const result = bootstrapDocuments(repository, directory, url, revision, config.argoNamespace);
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'gitops-continuous-'));
  try {
    const values = path.join(temporary, 'values.yaml');
    fs.writeFileSync(values, yaml.dump(result.values));
    const rendered = execFileSync('helm', ['template', 'runtime', path.join(repository, 'charts/gitops'),
      '-n', config.argoNamespace, '-f', values], { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 });
    return { result: { ...result, documents: continuousDocuments(result, config.argoNamespace) },
      files: { 'apps/applications.yaml': dump(continuousApplications(rendered)),
        'bootstrap.yaml': dump(continuousDocuments(result, config.argoNamespace)),
        'selection.json': JSON.stringify({ directory }, null, 2) + '\n' } };
  } finally { fs.rmSync(temporary, { recursive: true, force: true }); }
}

export function exportContinuousBundle(repository, directory, config, env = process.env) {
  const variables = { ...env };
  const names = { buster: 'BUSTER_VALUES_FILE', nova: 'NOVA_VALUES_FILE', prism: 'PRISM_VALUES_FILE', 'prism-agent': 'PRISM_AGENT_VALUES_FILE' };
