#!/usr/bin/env python3
"""Read-only transport inventory. Never fetch Secret objects or print env literals."""
import json
import os
import re
import subprocess


def identity(obj):
    meta = obj.get("metadata", {})
    return {"namespace": meta.get("namespace"), "name": meta.get("name")}


def reference(source):
    return {kind: {key: value for key, value in ref.items() if key in ("name", "key", "optional")}
            for kind, ref in source.items() if kind in ("secretKeyRef", "configMapKeyRef")}


def inventory(pods, workloads, services, policies, registrations):
    clients = []
    for obj in [*pods, *workloads]:
        spec = obj.get("spec", {})
        if obj.get("kind") == "CronJob":
            spec = spec.get("jobTemplate", {}).get("spec", {})
        spec = spec.get("template", {}).get("spec", spec)
        containers = []
        for container in [*spec.get("initContainers", []), *spec.get("containers", [])]:
            matches = []
            for env in container.get("env", []):
                if re.search(r"redis|registry", env.get("name", ""), re.I):
                    matches.append({"name": env["name"], "literalOmitted": "value" in env,
                                    "reference": reference(env.get("valueFrom", {}))})
            sources = []
            for source in container.get("envFrom", []):
                for kind in ("secretRef", "configMapRef"):
                    if kind in source:
                        sources.append({kind: {"name": source[kind].get("name")}})
            # Config-file-only consumers cannot be inferred from environment names.
            containers.append({"name": container.get("name"), "transportEnvironment": matches,
                               "environmentSources": sources,
                               "mountedVolumes": [v.get("name") for v in container.get("volumeMounts", [])]})
        volumes = []
        for volume in spec.get("volumes", []):
            item = {"name": volume.get("name")}
            if "configMap" in volume:
                item["configMap"] = volume["configMap"].get("name")
            if "secret" in volume:
                item["secret"] = volume["secret"].get("secretName")
            if "csi" in volume:
                item["csiDriver"] = volume["csi"].get("driver")
            if "projected" in volume:
                item["projectedSources"] = [{kind: {"name": ref.get("name")}}
                    for src in volume["projected"].get("sources", [])
                    for kind, ref in src.items() if kind in ("secret", "configMap")]
            volumes.append(item)
        clients.append({**identity(obj), "kind": obj.get("kind"),
                        "node": spec.get("nodeName"), "serviceAccount": spec.get("serviceAccountName", "default"),
                        "hostNetwork": spec.get("hostNetwork", False),
                        "containers": containers, "volumes": volumes})
    selected_services = [{**identity(s), "type": s.get("spec", {}).get("type"),
                          "selector": s.get("spec", {}).get("selector", {}),
                          "ports": [{k: p[k] for k in ("name", "port", "targetPort", "nodePort", "protocol") if k in p}
                                    for p in s.get("spec", {}).get("ports", [])]}
                         for s in services if re.search(r"redis|registry", s.get("metadata", {}).get("name", ""), re.I)]
    return {"scope": "metadata-and-reference-inventory-only", "clientsComplete": False,
            "limitations": ["Host/containerd clients and dynamically loaded configuration require separate inspection.",
                            "Presence of a client is not authorization to access Redis or the registry.",
                            "No reachability, TLS enforcement or certificate rotation proof is established."],
            "workloads": clients, "services": selected_services,
            "networkPolicies": [{**identity(p), "kind": p.get("kind")} for p in policies],
            "spiffeRegistrations": [{**identity(r), "spec": {k: v for k, v in r.get("spec", {}).items()
                if k in ("spiffeIDTemplate", "namespaceSelector", "podSelector", "workloadSelectorTemplates")}}
                for r in registrations]}


def main():
    context = os.environ.get("KUBE_CONTEXT")
    if not context:
        raise SystemExit("Set KUBE_CONTEXT first")

    def get(resource):
        result = subprocess.run(["kubectl", "--context", context, "get", resource, "-A", "-o", "json"],
                                capture_output=True, text=True, timeout=60)
        if result.returncode:
            raise SystemExit(f"Inventory failed reading {resource}; check API access before proceeding")
        return json.loads(result.stdout)["items"]

    result = inventory(get("pods"), get("deployments,statefulsets,daemonsets,cronjobs"), get("services"),
                       get("networkpolicies"), get("clusterspiffeids.spire.spiffe.io"))
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Read installed platform settings for an Argo handover; never read Secrets."""
import hashlib
import json
import os
import re
import subprocess

context = os.environ.get("KUBE_CONTEXT")
if not context:
    raise SystemExit("Set KUBE_CONTEXT before running this inspection")


def run(*args):
    return json.loads(subprocess.check_output(args, text=True))


def scrub(value):
    if isinstance(value, dict):
        result = {}
        for key, item in value.items():
            sensitive = re.search(r"password|token|secret|private.?key|api.?key|credential|dsn|connectionstring", key, re.I)
            # Arbitrary environment variable values can contain credentials.
            sensitive = sensitive or (key == "value" and "name" in value)
            result[key] = "<redacted>" if sensitive else scrub(item)
        return result
    if isinstance(value, list):
        return [scrub(item) for item in value]
    if isinstance(value, str):
        if "\n" in value or "-----BEGIN" in value:
            return "<multiline content omitted>"
        return re.sub(r"(\w+://)[^/\s]*@", r"\1<redacted>@", value)
    return value


def kube(namespace, *args):
    return run("kubectl", "--context", context, "-n", namespace, *args, "-o", "json")


report = {"helm": {}, "litellm": {}, "storage": {}, "csiDrivers": []}
for release, namespace in [("spire", "spire-server"), ("spire-crds", "spire-server"), ("csi-driver-smb", "kube-system")]:
    values = run("helm", "--kube-context", context, "-n", namespace, "get", "values", release, "-o", "json")
    report["helm"][release] = {"namespace": namespace, "values": scrub(values or {})}

deployment = kube("kubeclaw", "get", "deployment", "litellm")
pod = deployment["spec"]["template"]["spec"]
report["litellm"]["replicas"] = deployment["spec"].get("replicas")
report["litellm"]["strategy"] = deployment["spec"].get("strategy")
report["litellm"]["selector"] = deployment["spec"]["selector"]
report["litellm"]["containers"] = []
for container in pod["containers"]:
    selected = {key: container[key] for key in ["name", "image", "imagePullPolicy", "ports", "resources", "volumeMounts", "securityContext", "envFrom"] if key in container}
    selected["env"] = [{"name": entry["name"], **({"valueFrom": entry["valueFrom"]} if "valueFrom" in entry else {"value": "<omitted>"})} for entry in container.get("env", [])]
    selected["probes"] = {key: {field: ({k: v for k, v in value.items() if k != "httpHeaders"} if field == "httpGet" else "<command omitted>" if field == "exec" else value) for field, value in container[key].items()} for key in ["startupProbe", "readinessProbe", "livenessProbe"] if key in container}
    report["litellm"]["containers"].append(selected)
report["litellm"]["volumes"] = [{"name": volume["name"], **{key: volume[key] for key in ["configMap", "secret", "persistentVolumeClaim"] if key in volume}} for volume in pod.get("volumes", [])]
report["litellm"]["service"] = kube("kubeclaw", "get", "service", "litellm")["spec"]
config = kube("kubeclaw", "get", "configmap", "litellm-config")
report["litellm"]["configHashes"] = {key: hashlib.sha256(value.encode()).hexdigest() for key, value in config.get("data", {}).items()}
pods = kube("kubeclaw", "get", "pods", "-l", "app=litellm")
report["litellm"]["images"] = [{"pod": p["metadata"]["name"], "containers": [{key: c.get(key) for key in ["name", "image", "imageID", "ready"]} for c in p.get("status", {}).get("containerStatuses", [])]} for p in pods["items"]]
for namespace in ["spire-server", "spire-system"]:
    claims = kube(namespace, "get", "pvc")
    report["storage"][namespace] = [{"name": c["metadata"]["name"], "spec": c["spec"], "phase": c.get("status", {}).get("phase")} for c in claims["items"]]
report["csiDrivers"] = [item["metadata"]["name"] for item in run("kubectl", "--context", context, "get", "csidrivers", "-o", "json")["items"]]
print(json.dumps(report, indent=2))

#!/usr/bin/env python3
"""Operator-side discovery and credential setup; never prints secret values."""
import ipaddress
import json
import os
from pathlib import Path
import secrets
import subprocess
import sys

context = os.environ['KUBE_CONTEXT']
namespace = os.environ.get('OPS_NAMESPACE', 'kubeclaw-ops')
base = ['kubectl', '--context', context, '--request-timeout=20s']

def kube(args, data=None):
    result = subprocess.run(base + args, input=data, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if result.returncode:
        # stderr from Secret apply can contain the submitted object. Never echo it.
        raise SystemExit('kubectl failed during Ops Pod setup; check context, permissions and named resource availability')
    return result.stdout

def get(kind, name, ns=None):
    args = ['get', kind, name, '--ignore-not-found', '-o', 'json']
    if ns:
        args += ['-n', ns]
    text = kube(args).strip()
    return json.loads(text) if text else None

def apply_secret(name, values):
    kube(['apply', '-f', '-'], json.dumps({'apiVersion': 'v1', 'kind': 'Secret',
         'metadata': {'name': name, 'namespace': namespace}, 'type': 'Opaque', 'stringData': values}))

def discover():
    endpoints = get('endpoints', 'kubernetes', 'default')
    service = get('service', 'kubernetes', 'default')
    if not endpoints or not service:
        raise SystemExit('Kubernetes API endpoint discovery failed')
    addresses = [a['ip'] for s in endpoints.get('subsets', []) for a in s.get('addresses', [])]
    addresses += service['spec'].get('clusterIPs', [service['spec']['clusterIP']])
    cidrs = sorted({str(ipaddress.ip_network(ipaddress.ip_address(address))) for address in addresses})
    ports = {p['port'] for s in endpoints.get('subsets', []) for p in s.get('ports', []) if p.get('name') == 'https'}
    if not cidrs or len(ports) != 1:
        raise SystemExit('Expected ready Kubernetes API addresses and one https endpoint port')
    namespaces = [namespace]
    requested = os.environ.get('OPS_READ_NAMESPACES', 'kubeclaw,argocd,kube-system,cilium,tailscale,spire-server,spire-system').split(',')
    for name in requested:
        name = name.strip()
        if not name:
            continue
        if get('namespace', name):
            namespaces.append(name)
    cilium = get('crd', 'ciliumnetworkpolicies.cilium.io') is not None
    return {'rbac': {'namespaces': list(dict.fromkeys(namespaces))},
            'networkPolicy': {'apiServerCIDRs': cidrs, 'apiServerPort': ports.pop(), 'cilium': cilium}}

def setup_secrets():
    if not get('secret', 'codex-ops-bearer', namespace):
        apply_secret('codex-ops-bearer', {'token': secrets.token_urlsafe(48)})
    if os.environ.get('OPS_COPY_PULL_SECRET', '1') == '1' and not get('secret', 'ghcr-secret', namespace):
        source = get('secret', 'ghcr-secret', os.environ.get('OPS_PULL_SECRET_SOURCE_NAMESPACE', 'kubeclaw'))
        if not source:
            raise SystemExit('Missing ghcr-secret. Create it in the Ops namespace or select a valid source namespace.')
        kube(['apply', '-f', '-'], json.dumps({'apiVersion': 'v1', 'kind': 'Secret',
             'metadata': {'name': 'ghcr-secret', 'namespace': namespace}, 'type': source['type'], 'data': source['data']}))
    for variable, name, key in [('OPS_GITHUB_TOKEN_FILE', 'codex-ops-github', 'token'),
                                ('OPS_TAILSCALE_AUTHKEY_FILE', 'codex-ops-tailscale', 'authkey')]:
        if os.environ.get(variable):
            value = Path(os.environ[variable]).read_text().strip()
            if not value:
                raise SystemExit(variable + ' contains an empty credential')
            apply_secret(name, {key: value})
    print('Ops credentials prepared; existing bearer and pull credentials retained')

if __name__ == '__main__':
    if sys.argv[1:] == ['discover']:
        print(json.dumps(discover(), indent=2))
    elif sys.argv[1:] == ['secrets']:
        setup_secrets()
    else:
        raise SystemExit('Usage: bootstrap.py discover|secrets')

package main

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
)

func (c *controller) ensureTestCredentials(ctx context.Context, item *lease, namespaceName string) (map[string]interface{}, error) {
	request, err := c.credentialRequest(item)
	if err != nil {
		return nil, err
	}
	if request == nil {
		return map[string]interface{}{"credentialsRef": nil, "credentialsAvailable": false}, nil
	}
	if request.Mode == "generate" {
		if item.Metadata.UID == "" {
			return nil, errors.New("generated credentials require a lease UID")
		}
		for _, copied := range stringSlice(item.Spec["secretsToCopy"]) {
			if copied == request.SecretName {
				return nil, errors.New("generated credentials cannot reuse a copied Secret")
			}
		}
	}
	if err := c.ensureCredentialAccess(ctx, namespaceName, request); err != nil {
		return nil, err
	}
	var credentialLease map[string]interface{}
	if request.Mode == "generate" {
		if err := c.kube(ctx, http.MethodGet, c.statusPath(item.Metadata.Name), nil, "application/json", &credentialLease); err != nil {
			return nil, err
		}
		meta := objectValue(credentialLease["metadata"])
		if stringValue(meta["uid"]) != item.Metadata.UID || stringValue(meta["resourceVersion"]) == "" {
			return nil, errors.New("credential lease identity is not established")
		}
		item.Status = objectValue(credentialLease["status"])
	}
	path := "/api/v1/namespaces/" + namespaceName + "/secrets/" + request.SecretName
	var secret map[string]interface{}
	err = c.kube(ctx, http.MethodGet, path, nil, "application/json", &secret)
	if err != nil {
		var apiErr *apiError
		if !errors.As(err, &apiErr) || apiErr.statusCode != http.StatusNotFound {
			return nil, err
		}
		if request.Mode == "existing" {
			placeholder := map[string]interface{}{
				"apiVersion": "v1", "kind": "Secret", "type": "Opaque",
				"metadata": map[string]interface{}{
					"name": request.SecretName, "namespace": namespaceName,
					"labels": mergeStringMaps(ownerLabels(item, namespaceName), map[string]string{"kubeclaw/user-deliverable": "true"}),
				},
			}
			if err := c.kube(ctx, http.MethodPost, "/api/v1/namespaces/"+namespaceName+"/secrets", placeholder, "application/json", nil); err != nil {
				return nil, err
			}
			return map[string]interface{}{"credentialsRef": "secret/" + request.SecretName, "credentialsAvailable": false}, nil
		}
		if len(objectValue(item.Status["generatedCredentialIntent"])) != 0 || len(objectValue(item.Status["generatedCredentials"])) != 0 {
			return nil, errors.New("generated credential creation is unresolved: committed source Secret is missing")
		}
		password := make([]byte, 24)
		if _, err := rand.Read(password); err != nil {
			return nil, fmt.Errorf("generate preview credential: %w", err)
		}
		values := map[string]string{"username": "preview", "password": base64.RawURLEncoding.EncodeToString(password)}
		intent := map[string]interface{}{"leaseUID": item.Metadata.UID, "namespace": namespaceName, "secretName": request.SecretName, "credentialDigest": demoCredentialDigest(values)}
		patch := map[string]interface{}{"metadata": map[string]interface{}{"resourceVersion": objectValue(credentialLease["metadata"])["resourceVersion"]}, "status": map[string]interface{}{"generatedCredentialIntent": intent}}
		if err := c.kube(ctx, http.MethodPatch, c.statusPath(item.Metadata.Name), patch, "application/merge-patch+json", nil); err != nil {
			return nil, err
		}
		item.Status["generatedCredentialIntent"] = intent
		manifest := map[string]interface{}{
			"apiVersion": "v1", "kind": "Secret", "type": "Opaque",
			"immutable": true,
			"metadata": map[string]interface{}{
				"name": request.SecretName, "namespace": namespaceName,
				"labels":      mergeStringMaps(ownerLabels(item, namespaceName), map[string]string{"kubeclaw/user-deliverable": "true"}),
				"annotations": map[string]interface{}{"kubeclaw.forgestack.ai/generated-demo-credentials": "v1", "kubeclaw.forgestack.ai/credential-lease-uid": item.Metadata.UID},
			},
			"stringData": map[string]interface{}{
				"username": values["username"], "password": values["password"],
			},
		}
		if err := c.kube(ctx, http.MethodPost, "/api/v1/namespaces/"+namespaceName+"/secrets", manifest, "application/json", &secret); err != nil {
			return nil, err
		}
	}
	available, err := deliverableCredentialAvailable(secret, request)
	if err != nil {
		return nil, err
	}
	if !available {
		if request.Mode == "existing" {
			return map[string]interface{}{"credentialsRef": "secret/" + request.SecretName, "credentialsAvailable": false}, nil
		}
		return nil, fmt.Errorf("generated test credential Secret %s is incomplete", request.SecretName)
	}
	result := map[string]interface{}{"credentialsRef": "secret/" + request.SecretName, "credentialsAvailable": true}
	if request.Mode == "generate" {
		proof, err := generatedCredentialProof(item, namespaceName, request.SecretName, secret)
		if err != nil {
			return nil, err
		}
		result["generatedCredentials"] = proof
	}
	return result, nil
}

// Provenance is established from the actual immutable Secret and owning lease,
// never from user-deliverable labels or the presence of username/password keys.
func generatedCredentialProof(item *lease, namespace, name string, secret map[string]interface{}) (map[string]interface{}, error) {
	metadata := objectValue(secret["metadata"])
	annotations := objectValue(metadata["annotations"])
	labels := objectValue(metadata["labels"])
	uid, resourceVersion := stringValue(metadata["uid"]), stringValue(metadata["resourceVersion"])
	if item.Metadata.UID == "" || uid == "" || resourceVersion == "" || !boolValue(secret["immutable"]) ||
		stringValue(metadata["name"]) != name || stringValue(metadata["namespace"]) != namespace ||
		stringValue(annotations["kubeclaw.forgestack.ai/generated-demo-credentials"]) != "v1" ||
		stringValue(annotations["kubeclaw.forgestack.ai/credential-lease-uid"]) != item.Metadata.UID ||
		stringValue(labels["kubeclaw/managed-by"]) != "buster-namespace-controller" ||
		stringValue(labels["kubeclaw/buster-lease-uid"]) != item.Metadata.UID {
		return nil, errors.New("generated credential Secret provenance is not established")
	}
	values := map[string]string{}
	data := objectValue(secret["data"])
	if len(data) != 2 {
		return nil, errors.New("generated credential Secret must contain exactly two encoded keys")
	}
	for _, key := range []string{"username", "password"} {
		decoded, err := base64.StdEncoding.Strict().DecodeString(stringValue(data[key]))
		if err != nil || len(decoded) == 0 {
			return nil, errors.New("generated credential Secret data is invalid")
		}
		values[key] = string(decoded)
	}
	credentialDigest := demoCredentialDigest(values)
	intent := objectValue(item.Status["generatedCredentialIntent"])
	if stringValue(intent["leaseUID"]) != item.Metadata.UID || stringValue(intent["namespace"]) != namespace || stringValue(intent["secretName"]) != name || stringValue(intent["credentialDigest"]) != credentialDigest {
		return nil, errors.New("generated credential Secret does not match controller creation intent")
	}
	prior := objectValue(item.Status["generatedCredentials"])
	if len(prior) > 0 && (stringValue(prior["secretUID"]) != uid || stringValue(prior["leaseUID"]) != item.Metadata.UID || stringValue(prior["credentialDigest"]) != credentialDigest) {
		return nil, errors.New("generated credential Secret no longer matches the recorded source")
	}
	return map[string]interface{}{"schemaVersion": "generated-demo-credential-source.v1", "leaseUID": item.Metadata.UID,
		"secretUID": uid, "secretResourceVersion": resourceVersion, "namespace": namespace, "secretName": name,
		"credentialDigest": credentialDigest}, nil
}

func validateDeliverableCredentialSecret(secret map[string]interface{}, request *testCredentialRequest) error {
	available, err := deliverableCredentialAvailable(secret, request)
	if err != nil {
		return err
	}
	if !available {
		return fmt.Errorf("test credential Secret %s is missing a declared key", request.SecretName)
	}
	return nil
}

func deliverableCredentialAvailable(secret map[string]interface{}, request *testCredentialRequest) (bool, error) {
	allowed := map[string]bool{}
	for _, key := range request.Keys {
		allowed[key] = true
	}
	found := map[string]bool{}
	for _, field := range []string{"data", "stringData"} {
		for key, value := range objectValue(secret[field]) {
			if !allowed[key] {
				return false, fmt.Errorf("test credential Secret %s contains undeclared key %s", request.SecretName, key)
			}
			if stringValue(value) != "" {
				found[key] = true
			}
		}
	}
	for _, key := range request.Keys {
		if !found[key] {
			return false, nil
		}
	}
	return true, nil
}

func demoCredentialDigest(values map[string]string) string {
	encoded, _ := json.Marshal(values)
	digest := sha256.Sum256(encoded)
	return "sha256:" + hex.EncodeToString(digest[:])
}

