}

func (c *controller) configureProduct() error {
	enabled := os.Getenv("BUSTER_PRODUCT_ENABLED")
	if enabled == "" || enabled == "false" {
		return nil
	}
	if enabled != "true" || c.readiness == nil {
		return errors.New("DEMO_PRODUCT_CONFIG_INVALID")
	}
	key, err := base64.StdEncoding.Strict().DecodeString(os.Getenv("BUSTER_PRODUCT_VERIFY_KEY"))
	var actors []string
	cfg := &productConfig{Audience: os.Getenv("BUSTER_PRODUCT_AUDIENCE"), Producer: os.Getenv("BUSTER_PRODUCT_PRODUCER"), Issuer: os.Getenv("BUSTER_PRODUCT_ISSUER"), PublicKey: key, Actors: map[string]bool{}}
	parts := strings.Split(cfg.Producer, ":")
	if err != nil || len(key) != ed25519.PublicKeySize || !readyText(cfg.Audience) || !readyText(cfg.Issuer) || len(parts) != 4 || parts[0] != "system" || parts[1] != "serviceaccount" || !readyName.MatchString(parts[2]) || !readyName.MatchString(parts[3]) || cfg.Producer == c.readiness.Producer || json.Unmarshal([]byte(os.Getenv("BUSTER_PRODUCT_ACTORS_JSON")), &actors) != nil || len(actors) == 0 {
		return errors.New("DEMO_PRODUCT_CONFIG_INVALID")
	}
	for _, actor := range actors {
		if !readyText(actor) || cfg.Actors[actor] {
			return errors.New("DEMO_PRODUCT_CONFIG_INVALID")
		}
		cfg.Actors[actor] = true
	}
	c.product = cfg
	return nil
}

// Decode the exact signed bytes. Reject duplicate keys as well as unknown fields,
// trailing values, invalid UTF-8, and nested duplicates before typed decoding.
func productJSON(raw []byte, target interface{}) error {
	if !utf8.Valid(raw) {
		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
	}
	d := json.NewDecoder(bytes.NewReader(raw))
	var walk func() error
	walk = func() error {
		token, err := d.Token()
		if err != nil {
			return err
		}
		delimiter, ok := token.(json.Delim)
		if !ok {
			return nil
		}
		switch delimiter {
		case '{':
			keys := map[string]bool{}
			for d.More() {
				token, err = d.Token()
				if err != nil {
					return err
				}
				key, ok := token.(string)
				if !ok || keys[key] {
					return errors.New("duplicate key")
				}
				keys[key] = true
				if err = walk(); err != nil {
					return err
				}
			}
		case '[':
			for d.More() {
				if err = walk(); err != nil {
					return err
				}
			}
		default:
			return errors.New("invalid delimiter")
		}
		_, err = d.Token()
		return err
	}
	if walk() != nil {
		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
	}
	if _, err := d.Token(); err != io.EOF {
		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
	}
	var fields map[string]json.RawMessage
	if json.Unmarshal(raw, &fields) != nil || fields == nil {
		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
	}
	kind := reflect.TypeOf(target).Elem()
	allowed := map[string]bool{}
	for i := 0; i < kind.NumField(); i++ {
		allowed[strings.Split(kind.Field(i).Tag.Get("json"), ",")[0]] = true
	}
	for key, value := range fields {
		if !allowed[key] || bytes.Equal(bytes.TrimSpace(value), []byte("null")) {
			return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
		}
	}
	d = json.NewDecoder(bytes.NewReader(raw))
	d.DisallowUnknownFields()
	if d.Decode(target) != nil || d.Decode(new(interface{})) != io.EOF {
		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
	}
	return nil
}
func productUTC(s string) (time.Time, error) {
	t, e := time.Parse("2006-01-02T15:04:05Z", s)
	if e != nil || t.Format("2006-01-02T15:04:05Z") != s {
		return time.Time{}, errors.New("DEMO_PRODUCT_TIME_INVALID")
	}
	return t, nil
}
func (c *controller) verifyProduct(envelope productEnvelope) (productDecision, string, error) {
	var d productDecision
	invalid := errors.New("DEMO_PRODUCT_SIGNATURE_INVALID")
	if c.product == nil || envelope.SchemaVersion != "demo-product-decision-envelope.v1" {
		return d, "", invalid
	}
	raw, e := base64.StdEncoding.Strict().DecodeString(envelope.Payload)
	sig, se := base64.StdEncoding.Strict().DecodeString(envelope.Signature)
	if e != nil || se != nil || len(raw) > 8192 || base64.StdEncoding.EncodeToString(raw) != envelope.Payload || base64.StdEncoding.EncodeToString(sig) != envelope.Signature || !ed25519.Verify(c.product.PublicKey, append([]byte(productDomain), raw...), sig) {
		return d, "", invalid
	}
	if e = productJSON(raw, &d); e != nil {
		return d, "", e
	}
	if d.SchemaVersion != "demo-product-decision.v1" || d.Issuer != c.product.Issuer || !c.product.Actors[d.ActorID] || !readyName.MatchString(d.LeaseName) || d.Generation < 1 || d.Generation > 9007199254740991 || !readyText(d.LeaseUID) || !productDecisionID.MatchString(d.DecisionID) || !readyText(d.ExpectedRevision) || len(strings.TrimSpace(d.Reason)) < 1 || len(d.Reason) > 2000 || strings.ContainsAny(d.Reason, "\x00") {
		return d, "", errors.New("DEMO_PRODUCT_REQUEST_INVALID")
	}
	if !readyDigest.MatchString(d.ReadyDigest) || !readyDigest.MatchString(d.CandidateDigest) || !readyDigest.MatchString(d.ResultDigest) || !readyText(d.SourceRevision) {
		return d, "", errors.New("DEMO_PRODUCT_REQUEST_INVALID")
	}
	if d.Action != "accept" && d.Action != "extend" || d.Action == "accept" && d.ExtensionSeconds != nil || d.Action == "extend" && (d.ExtensionSeconds == nil || *d.ExtensionSeconds < 1 || *d.ExtensionSeconds > maximumDemoRetentionSeconds) {
		return d, "", errors.New("DEMO_PRODUCT_REQUEST_INVALID")
	}
	issued, ie := productUTC(d.IssuedAt)
	expires, ee := productUTC(d.ExpiresAt)
	if ie != nil || ee != nil || !expires.After(issued) || expires.Sub(issued) > 5*time.Minute {
		return d, "", errors.New("DEMO_PRODUCT_TIME_INVALID")
	}
	if _, e = time.Parse(time.RFC3339Nano, d.ExpectedExpiry); e != nil {
		return d, "", errors.New("DEMO_PRODUCT_TIME_INVALID")
	}
	digest := sha256.Sum256(raw)
	return d, "sha256:" + hex.EncodeToString(digest[:]), nil
}

func productRecords(item *lease) []interface{} {
	return interfaceSlice(objectValue(item.Status["demoProduct"])["decisions"])
}
func productReceipt(item *lease, decisionID, digest string) (map[string]interface{}, error) {
	for _, record := range productRecords(item) {
		r := objectValue(record)
		if r["decisionId"] == decisionID {
			if r["payloadDigest"] != digest {
				return nil, errors.New("DEMO_PRODUCT_REPLAY_CHANGED")
			}
			return r, nil
		}
	}
	return nil, nil
}
func productDeadline(item *lease, base time.Time) time.Time {
	state := objectValue(item.Status["demoProduct"])
	ready := objectValue(item.Status["demoReadiness"])
	if state["leaseUID"] != item.Metadata.UID || state["readyDigest"] != ready["requestDigest"] {
		return base
	}
	// List-map storage may reorder entries. Follow exact expiry links, not array order.
	original := base
	links := map[string]time.Time{}
	for _, record := range productRecords(item) {
		r := objectValue(record)
		if r["action"] != "extend" {
			continue
		}
		previous, e := time.Parse(time.RFC3339Nano, stringValue(r["previousExpiry"]))
		next, ne := time.Parse(time.RFC3339Nano, stringValue(r["expiresAt"]))
		if e != nil || ne != nil || !next.After(previous) {
			return original
		}
		key := previous.UTC().Format(time.RFC3339Nano)
		if _, exists := links[key]; exists {
			return original
		}
		links[key] = next
	}
	for len(links) > 0 {
		key := base.UTC().Format(time.RFC3339Nano)
		next, exists := links[key]
		if !exists {
			return original
		}
		delete(links, key)
		base = next
	}

	return base
}
func (c *controller) productSubject(ctx context.Context, item *lease) (map[string]interface{}, error) {
	s := objectValue(item.Status["demoReadiness"])
	if item.Metadata.DeletionTimestamp != "" || stringValue(item.Status["phase"]) != "Ready" || item.Metadata.Generation != int64(intValue(s["exposureGeneration"], 0)) || !time.Now().Before(c.expiresAt(item)) {
		return nil, errors.New("DEMO_PRODUCT_NOT_CURRENT")
	}
	if err := c.verifyCommittedReady(ctx, item); err != nil {
		return nil, errors.New("DEMO_PRODUCT_NOT_CURRENT")
	}
	return map[string]interface{}{"leaseName": item.Metadata.Name, "leaseUID": item.Metadata.UID, "sourceRevision": s["sourceRevision"], "candidateDigest": s["candidateDigest"], "resultDigest": s["resultDigest"], "readyDigest": s["requestDigest"], "generation": item.Metadata.Generation, "expectedExpiry": c.expiresAt(item).UTC().Format(time.RFC3339Nano), "expectedRevision": item.Metadata.ResourceVersion, "url": s["url"], "runId": s["runId"]}, nil
}
func (c *controller) commitProduct(ctx context.Context, envelope productEnvelope) (map[string]interface{}, error) {
	d, digest, err := c.verifyProduct(envelope)
	if err != nil {
		return nil, err
	}
	var item lease
	if err = c.kube(ctx, http.MethodGet, c.leasePath(d.LeaseName), nil, "application/json", &item); err != nil {
		return nil, errors.New("DEMO_PRODUCT_LEASE_UNAVAILABLE")
	}
	if item.Metadata.UID != d.LeaseUID {
		return nil, errors.New("DEMO_PRODUCT_NOT_CURRENT")
	}
	if receipt, e := productReceipt(&item, d.DecisionID, digest); e != nil || receipt != nil {
		return receipt, e
	}
	issued, _ := productUTC(d.IssuedAt)
	expires, _ := productUTC(d.ExpiresAt)
	now := time.Now().UTC()
	if now.Before(issued) || !now.Before(expires) {
		return nil, errors.New("DEMO_PRODUCT_DECISION_EXPIRED")
	}
	subject, err := c.productSubject(ctx, &item)
	if err != nil {
		return nil, err
	}
	if subject["readyDigest"] != d.ReadyDigest || subject["sourceRevision"] != d.SourceRevision || subject["candidateDigest"] != d.CandidateDigest || subject["resultDigest"] != d.ResultDigest || item.Metadata.Generation != d.Generation || subject["expectedExpiry"] != d.ExpectedExpiry || item.Metadata.ResourceVersion != d.ExpectedRevision {
		return nil, errors.New("DEMO_PRODUCT_SUBJECT_CHANGED")
	}
	records := productRecords(&item)
	if len(records) >= productMaxDecisions {
		return nil, errors.New("DEMO_PRODUCT_HISTORY_FULL")
	}
	next := c.expiresAt(&item)
	state := "accepted"
	if d.Action == "extend" {
		next, err = demoRetentionDeadline(next, *d.ExtensionSeconds)
		if err != nil {
			return nil, errors.New("DEMO_PRODUCT_EXTENSION_INVALID")
		}
		state = "extended"
	}
	receipt := map[string]interface{}{"schemaVersion": "demo-product-decision-receipt.v1", "decisionId": d.DecisionID, "payloadDigest": digest, "action": d.Action, "leaseName": d.LeaseName, "leaseUID": d.LeaseUID, "readyDigest": d.ReadyDigest, "generation": d.Generation, "actorId": d.ActorID, "issuer": d.Issuer, "appliedAt": now.Format(time.RFC3339Nano), "previousExpiry": d.ExpectedExpiry, "expiresAt": next.Format(time.RFC3339Nano), "state": state, "envelope": map[string]interface{}{"schemaVersion": envelope.SchemaVersion, "payload": envelope.Payload, "signature": envelope.Signature}}
	records = append(records, receipt)
	product := map[string]interface{}{"leaseUID": d.LeaseUID, "readyDigest": d.ReadyDigest, "decisions": records}
	if !time.Now().Before(expires) || !time.Now().Before(c.expiresAt(&item)) {
		return nil, errors.New("DEMO_PRODUCT_DECISION_EXPIRED")
	}
	patch := map[string]interface{}{"metadata": map[string]interface{}{"resourceVersion": d.ExpectedRevision}, "status": map[string]interface{}{"demoProduct": product, "expiresAt": next.Format(time.RFC3339Nano)}}
	err = c.kube(ctx, http.MethodPatch, c.statusPath(d.LeaseName), patch, "application/merge-patch+json", nil)
	if err != nil {
		var apiErr *apiError
		if errors.As(err, &apiErr) && apiErr.statusCode == 409 {
			return nil, errors.New("DEMO_PRODUCT_VERSION_CONFLICT")
		}
		return nil, errors.New("DEMO_PRODUCT_COMMIT_UNCERTAIN")
	}
	var persisted lease
	if c.kube(ctx, http.MethodGet, c.leasePath(d.LeaseName), nil, "application/json", &persisted) != nil || persisted.Metadata.UID != d.LeaseUID {
		return nil, errors.New("DEMO_PRODUCT_COMMIT_UNCERTAIN")
	}
	actual, e := productReceipt(&persisted, d.DecisionID, digest)
	if e != nil || actual == nil {
		return nil, errors.New("DEMO_PRODUCT_COMMIT_UNCERTAIN")
	}
	a, _ := json.Marshal(actual)
	b, _ := json.Marshal(receipt)
	if !bytes.Equal(a, b) {
		return nil, errors.New("DEMO_PRODUCT_COMMIT_UNCERTAIN")
	}
	return actual, nil
}

func (c *controller) productHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "no-store")
	if c.product == nil || r.Method != http.MethodPost || (r.URL.Path != "/v1/demo-product/subjects" && r.URL.Path != "/v1/demo-product/decisions" && r.URL.Path != "/v1/demo-product/status") {
		http.Error(w, "DEMO_PRODUCT_DISABLED_OR_ROUTE_INVALID", 404)
		return
	}
	ctx, cancel := context.WithTimeout(r.Context(), 15*time.Second)
	defer cancel()
	if c.authenticateTransport(ctx, r.Header.Get("Authorization"), &readinessConfig{Audience: c.product.Audience, Producer: c.product.Producer}) != nil {
		http.Error(w, "DEMO_PRODUCT_UNAUTHORIZED", 401)
		return
	}
	raw, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 16384))
	if err != nil {
		http.Error(w, "DEMO_PRODUCT_REQUEST_INVALID", 400)
		return
	}
	var result interface{}
	switch r.URL.Path {
	case "/v1/demo-product/decisions":
		var envelope productEnvelope
		if err = productJSON(raw, &envelope); err == nil {
			result, err = c.commitProduct(ctx, envelope)
		}
	case "/v1/demo-product/subjects":
		var input struct {
			SchemaVersion string `json:"schemaVersion"`
			LeaseName     string `json:"leaseName,omitempty"`
		}
		err = productJSON(raw, &input)
		if err == nil && (input.SchemaVersion != "demo-product-subject-request.v1" || input.LeaseName != "" && !readyName.MatchString(input.LeaseName)) {
			err = errors.New("DEMO_PRODUCT_REQUEST_INVALID")
		}
		if err == nil {
			var list leaseList
			if input.LeaseName != "" {
				var item lease
				err = c.kube(ctx, http.MethodGet, c.leasePath(input.LeaseName), nil, "application/json", &item)
				list.Items = []lease{item}
			} else {
				err = c.kube(ctx, http.MethodGet, c.leasePath(""), nil, "application/json", &list)
			}
			subjects := []map[string]interface{}{}
			if err == nil {
				for i := range list.Items {
					subject, e := c.productSubject(ctx, &list.Items[i])
					if e == nil {
						subjects = append(subjects, subject)
					} else if input.LeaseName != "" {
						err = e
					}
				}
			}
			result = map[string]interface{}{"schemaVersion": "demo-product-subjects.v1", "subjects": subjects}
		}
	case "/v1/demo-product/status":
		var input struct {
			SchemaVersion string `json:"schemaVersion"`
			DecisionID    string `json:"decisionId"`
			LeaseName     string `json:"leaseName"`
			LeaseUID      string `json:"leaseUID"`
			PayloadDigest string `json:"payloadDigest"`
		}
		err = productJSON(raw, &input)
		if err == nil && (input.SchemaVersion != "demo-product-status-request.v1" || !readyName.MatchString(input.LeaseName) || !readyText(input.LeaseUID) || !productDecisionID.MatchString(input.DecisionID) || !readyDigest.MatchString(input.PayloadDigest)) {
			err = errors.New("DEMO_PRODUCT_REQUEST_INVALID")
		}
		if err == nil {
			var item lease
			err = c.kube(ctx, http.MethodGet, c.leasePath(input.LeaseName), nil, "application/json", &item)
			if err == nil {
				if item.Metadata.UID != input.LeaseUID {
					err = errors.New("DEMO_PRODUCT_NOT_CURRENT")
				} else {
					var receipt map[string]interface{}
					receipt, err = productReceipt(&item, input.DecisionID, input.PayloadDigest)
					result = receipt
					if receipt == nil && err == nil {
						err = errors.New("DEMO_PRODUCT_DECISION_NOT_FOUND")
					}
				}
			}
		}
	}
	if err != nil {
		code := err.Error()
		if !strings.HasPrefix(code, "DEMO_PRODUCT_") {
			code = "DEMO_PRODUCT_EVIDENCE_UNAVAILABLE"
		}
		http.Error(w, code, 409)
		return
	}
	_ = json.NewEncoder(w).Encode(result)
}

package main

import (
	"context"
	"crypto/rand"
	"crypto/tls"
	"encoding/hex"
	"encoding/json"
	"errors"
	"net"
	"net/http"
	"os"
	"strings"
	"time"
)

func (c *controller) configureReadiness() error {
	if os.Getenv("BUSTER_READY_LISTEN") == "" {
		return nil
	}
	config := &readinessConfig{Address: os.Getenv("BUSTER_READY_LISTEN"), Audience: os.Getenv("BUSTER_READY_AUDIENCE"), Producer: os.Getenv("BUSTER_READY_PRODUCER"), Certificate: os.Getenv("BUSTER_READY_TLS_CERT"), Key: os.Getenv("BUSTER_READY_TLS_KEY")}
	parts := strings.Split(config.Producer, ":")
	if len(parts) != 4 || parts[0] != "system" || parts[1] != "serviceaccount" || !readyName.MatchString(parts[2]) || !readyName.MatchString(parts[3]) || !readyText(config.Audience) || config.Certificate == "" || config.Key == "" {
		return errors.New("Ready server requires explicit audience, ServiceAccount identity and TLS certificate")
	}
	if _, _, err := net.SplitHostPort(config.Address); err != nil {
		return errors.New("invalid Ready listen address")
	}
	c.readiness = config
	return nil
}
func (c *controller) startReadinessServer(ctx context.Context) error {
	if c.readiness == nil {
		return nil
	}
	certificate, err := tls.LoadX509KeyPair(c.readiness.Certificate, c.readiness.Key)
	if err != nil {
		return errors.New("Ready TLS certificate unavailable")
	}
	listener, err := tls.Listen("tcp", c.readiness.Address, &tls.Config{MinVersion: tls.VersionTLS12, Certificates: []tls.Certificate{certificate}})
	if err != nil {
		return err
	}
	server := &http.Server{Handler: c.readinessHandler(), ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 20 * time.Second, WriteTimeout: 20 * time.Second, IdleTimeout: 30 * time.Second, MaxHeaderBytes: 20 * 1024}
	go func() { <-ctx.Done(); _ = server.Close() }()
	go func() {
		if err := server.Serve(listener); err != nil && !errors.Is(err, http.ErrServerClosed) {
			logJSON("error", "Ready server stopped", "listener failure")
		}
	}()
	return nil
}
func demoReadyDeadline(item *lease) (time.Time, bool) {
	state := objectValue(item.Status["demoReadiness"])
	ready, err := time.Parse(time.RFC3339, stringValue(state["readyAt"]))
	if err != nil {
		return time.Time{}, false
	}
	seconds, err := storedDemoRetention(state)
	if err != nil {
		return time.Time{}, false
	}
	expected, err := demoRetentionDeadline(ready, seconds)
	if err != nil {
		return time.Time{}, false
	}
	expires, err := time.Parse(time.RFC3339, stringValue(state["expiresAt"]))
	if err != nil || !expires.Equal(expected) || state["leaseUID"] != item.Metadata.UID || !readyDigest.MatchString(stringValue(state["requestDigest"])) {
		return time.Time{}, false
	}
	return expires, true
}
func readyStateEqual(left, right *lease) bool {
	a, _ := json.Marshal(left.Status["demoReadiness"])
	b, _ := json.Marshal(right.Status["demoReadiness"])
	pa, _ := json.Marshal(left.Status["demoProduct"])
	pb, _ := json.Marshal(right.Status["demoProduct"])
	return string(a) == string(b) && string(pa) == string(pb)
}

// Every API-backed mutation uses authoritative identity and resource-version CAS.
func (c *controller) patchLeaseStatus(ctx context.Context, item *lease, status map[string]interface{}) error {
	var current lease
	if err := c.kube(ctx, http.MethodGet, c.leasePath(item.Metadata.Name), nil, "application/json", &current); err != nil {
		return err
	}
	if current.Metadata.ResourceVersion == "" || current.Metadata.UID != item.Metadata.UID || current.Metadata.Generation != item.Metadata.Generation || current.Metadata.DeletionTimestamp != item.Metadata.DeletionTimestamp || !readyStateEqual(item, &current) || current.Metadata.Annotations[exposureOwnerAnnotation] != item.Metadata.Annotations[exposureOwnerAnnotation] {
		return errors.New("lease status transition superseded")
	}
	phase := stringValue(current.Status["phase"])
	if (phase == "Expired" || phase == "Deleting" || phase == "Rejected") && phase != stringValue(item.Status["phase"]) {
		return errors.New("lease terminal transition superseded")
	}
	claim := stringValue(objectValue(current.Status["exposureMutation"])["id"])
	terminal := status["phase"] == "Expired" || status["phase"] == "Deleting" || status["phase"] == "Rejected"
	if claim != "" && item.ExposureClaim != claim && !terminal {
		return errors.New("DEMO_READY_EXPOSURE_OPERATION_UNRESOLVED")
	}
	if claim != "" && (terminal || (status["exposurePhase"] != nil && status["exposurePhase"] != "Reconciling")) {
		status["exposureMutation"] = nil
	}
	unchanged := true
	for key, value := range status {
		a, _ := json.Marshal(value)
		b, _ := json.Marshal(current.Status[key])
		if string(a) != string(b) {
			unchanged = false
		}
	}
	if unchanged {
		return nil
	}
	if err := c.kube(ctx, http.MethodPatch, c.statusPath(item.Metadata.Name), map[string]interface{}{"metadata": map[string]interface{}{"resourceVersion": current.Metadata.ResourceVersion}, "status": status}, "application/merge-patch+json", nil); err != nil {
		return err
	}
	if item.Status == nil {
		item.Status = map[string]interface{}{}
	}
	for key, value := range status {
		item.Status[key] = value
	}
	if value, exists := status["exposureMutation"]; exists && value == nil {
		item.ExposureClaim = ""
	}
	return nil
}
func (c *controller) fenceNamespaceCleanup(ctx context.Context, item *lease) error {
	phase := stringValue(item.Status["phase"])
	if phase != "Expired" && phase != "Rejected" {
		phase = "Deleting"
	}
	return c.patchLeaseStatus(ctx, item, map[string]interface{}{"phase": phase})
}
func effectiveExposureOwner(item *lease) string {
	if _, ok := demoReadyDeadline(item); ok {
		return stringValue(objectValue(item.Status["demoReadiness"])["owner"])
	}
	return item.Metadata.Annotations[exposureOwnerAnnotation]
}
func effectiveExposureGeneration(item *lease) int64 {
	if _, ok := demoReadyDeadline(item); ok {
		return int64(intValue(objectValue(item.Status["demoReadiness"])["exposureGeneration"], 0))
	}
	return item.Metadata.Generation
}

func (c *controller) removeFinalizerCAS(ctx context.Context, item *lease) error {
	var current lease
	if err := c.kube(ctx, http.MethodGet, c.leasePath(item.Metadata.Name), nil, "application/json", &current); err != nil {
		return err
	}
	if current.Metadata.UID != item.Metadata.UID || current.Metadata.ResourceVersion == "" || current.Metadata.DeletionTimestamp == "" {
		return errors.New("lease deletion superseded")
	}
	finalizers := []string{}
	for _, value := range current.Metadata.Finalizers {
		if value != c.finalizer {
			finalizers = append(finalizers, value)
		}
	}
	return c.kube(ctx, http.MethodPatch, c.leasePath(item.Metadata.Name), map[string]interface{}{"metadata": map[string]interface{}{"resourceVersion": current.Metadata.ResourceVersion, "finalizers": finalizers}}, "application/merge-patch+json", nil)
}

func (c *controller) fenceExposureMutation(ctx context.Context, item *lease) error {
	// The CAS reservation makes readiness admission reject until the original
	// reconciler publishes the newly observed exposure. A stale pre-Ready worker
	// cannot delete/replace the ingress after the readiness status committed.
	if item.ExposureClaim == "" {
		random := make([]byte, 24)
		if _, err := rand.Read(random); err != nil {
			return err
		}
		item.ExposureClaim = hex.EncodeToString(random)
	}
	if err := c.patchLeaseStatus(ctx, item, map[string]interface{}{"exposurePhase": "Reconciling", "exposureMutation": map[string]interface{}{"id": item.ExposureClaim, "startedAt": time.Now().UTC().Format(time.RFC3339)}}); err != nil {
		return err
	}
	var persisted lease
	if err := c.kube(ctx, http.MethodGet, c.leasePath(item.Metadata.Name), nil, "application/json", &persisted); err != nil {
		return err
	}
	if persisted.Metadata.UID != item.Metadata.UID || persisted.Metadata.DeletionTimestamp != "" || stringValue(objectValue(persisted.Status["exposureMutation"])["id"]) != item.ExposureClaim || !readyStateEqual(item, &persisted) {
		return errors.New("DEMO_READY_EXPOSURE_OPERATION_UNRESOLVED")
	}
	return nil
}

func (c *controller) deleteNamespaceCAS(ctx context.Context, namespaceName string, namespace map[string]interface{}) error {
	meta := objectValue(namespace["metadata"])
	uid, version := stringValue(meta["uid"]), stringValue(meta["resourceVersion"])
	if uid == "" || version == "" {
		return errors.New("namespace deletion identity is missing")
	}
	if err := c.kube(ctx, http.MethodDelete, "/api/v1/namespaces/"+namespaceName, map[string]interface{}{"apiVersion": "v1", "kind": "DeleteOptions", "preconditions": map[string]interface{}{"uid": uid, "resourceVersion": version}}, "application/json", nil); err != nil {
		return err
	}
	return c.waitForNamespaceDeleted(ctx, namespaceName)
}

package main

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"time"
)

const demoRetention = time.Duration(defaultDemoRetentionSeconds) * time.Second

type readinessConfig struct{ Audience, Producer, Certificate, Key, Address string }
type demoReceipt struct {
	SchemaVersion string `json:"schemaVersion"`
	Accepted      bool   `json:"accepted"`
	Target        string `json:"target"`
	Status        int    `json:"status"`
	MessageID     string `json:"messageId"`
	DeliveryID    string `json:"deliveryId"`
	PayloadDigest string `json:"payloadDigest"`
}
type demoReadyRequest struct {
	RetentionSeconds   json.RawMessage `json:"retentionSeconds,omitempty"`
	wireDigest         string
	SchemaVersion      string      `json:"schemaVersion"`
	RequestID          string      `json:"requestId"`
	RunID              string      `json:"runId"`
	SourceRevision     string      `json:"sourceRevision"`
	CandidateDigest    string      `json:"candidateDigest"`
	DecisionDigest     string      `json:"decisionDigest"`
	ResultDigest       string      `json:"resultDigest"`
	LeaseName          string      `json:"leaseName"`
	LeaseUID           string      `json:"leaseUID"`
	Namespace          string      `json:"namespace"`
	ImmutableImage     string      `json:"immutableImage"`
	ManifestDigest     string      `json:"manifestDigest"`
	CredentialDigest   string      `json:"credentialDigest"`
	SecretUID          string      `json:"secretUID"`
	ExposureOwner      string      `json:"exposureOwner"`
	ExposureGeneration int64       `json:"exposureGeneration"`
	URL                string      `json:"url"`
	ObservedAt         string      `json:"observedAt"`
	Receipt            demoReceipt `json:"receipt"`
}
type demoReadyStatusRequest struct {
	SchemaVersion string `json:"schemaVersion"`
	LeaseName     string `json:"leaseName"`
	LeaseUID      string `json:"leaseUID"`
	RequestID     string `json:"requestId"`
}

var readyDigest = regexp.MustCompile(`^sha256:[a-f0-9]{64}$`)
var readyName = regexp.MustCompile(`^[a-z0-9][a-z0-9.-]{0,252}$`)

func readyText(s string) bool {
	return len(s) > 0 && len(s) <= 1024 && !strings.ContainsAny(s, "\x00\r\n")
}
func (r demoReadyRequest) validate() error {
	if _, err := parseDemoRetention(r.RetentionSeconds); err != nil {
		return err
	}
	if r.SchemaVersion != "demo-ready-request.v1" || !readyName.MatchString(r.LeaseName) || !readyName.MatchString(r.Namespace) || r.ExposureGeneration < 1 {
		return errors.New("DEMO_READY_REQUEST_INVALID")
	}
	for _, s := range []string{r.RequestID, r.RunID, r.LeaseUID, r.SecretUID, r.ExposureOwner, r.Receipt.Target, r.Receipt.DeliveryID} {
		if !readyText(s) {
			return errors.New("DEMO_READY_IDENTITY_INVALID")
		}
	}
	for _, s := range []string{r.CandidateDigest, r.DecisionDigest, r.ResultDigest, r.ManifestDigest, r.CredentialDigest, r.Receipt.PayloadDigest} {
		if !readyDigest.MatchString(s) {
			return errors.New("DEMO_READY_DIGEST_INVALID")
		}
	}
	if !regexp.MustCompile(`^git:[a-f0-9]{40}([a-f0-9]{24})?$`).MatchString(r.SourceRevision) || !regexp.MustCompile(`^[^\s]+@sha256:[a-f0-9]{64}$`).MatchString(r.ImmutableImage) {
		return errors.New("DEMO_READY_SOURCE_INVALID")
	}
	u, err := url.Parse(r.URL)
	if err != nil || u.Scheme != "https" || u.Host == "" || u.User != nil || u.Fragment != "" || u.RawQuery != "" || u.String() != r.URL || !readyText(r.URL) {
		return errors.New("DEMO_READY_URL_INVALID")
	}
	if r.Receipt.SchemaVersion != "discord-delivery-receipt.v1" || !r.Receipt.Accepted || r.Receipt.Status < 200 || r.Receipt.Status > 299 || !regexp.MustCompile(`^[1-9][0-9]{0,19}$`).MatchString(r.Receipt.MessageID) || (len(r.Receipt.MessageID) == 20 && r.Receipt.MessageID > "18446744073709551615") {
		return errors.New("DEMO_READY_RECEIPT_INVALID")
	}
	return nil
}
func readyRequestDigest(r demoReadyRequest) string { return r.wireDigest }

func (c *controller) authenticateReady(ctx context.Context, authorization string) error {
	return c.authenticateTransport(ctx, authorization, c.readiness)
}

func (c *controller) authenticateTransport(ctx context.Context, authorization string, cfg *readinessConfig) error {
	if cfg == nil || !strings.HasPrefix(authorization, "Bearer ") || len(authorization) > 16384 {
		return errors.New("DEMO_READY_UNAUTHORIZED")
	}
	token := strings.TrimPrefix(authorization, "Bearer ")
	if token == "" || strings.ContainsAny(token, " \r\n\t") {
		return errors.New("DEMO_READY_UNAUTHORIZED")
	}
	var review struct {
		Status struct {
			Authenticated bool     `json:"authenticated"`
			Audiences     []string `json:"audiences"`
			User          struct {
				Username string `json:"username"`
			} `json:"user"`
		} `json:"status"`
	}
	err := c.kube(ctx, http.MethodPost, "/apis/authentication.k8s.io/v1/tokenreviews", map[string]interface{}{"apiVersion": "authentication.k8s.io/v1", "kind": "TokenReview", "spec": map[string]interface{}{"token": token, "audiences": []string{cfg.Audience}}}, "application/json", &review)
	if err != nil || !review.Status.Authenticated || review.Status.User.Username != cfg.Producer || !contains(review.Status.Audiences, cfg.Audience) {
		return errors.New("DEMO_READY_UNAUTHORIZED")
	}
	return nil
}

func (c *controller) readinessHandler() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if strings.HasPrefix(r.URL.Path, "/v1/demo-product/") {
			c.productHandler(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Cache-Control", "no-store")
		if r.Method != http.MethodPost || (r.URL.Path != "/v1/demo-ready" && r.URL.Path != "/v1/demo-ready/status") {
			http.Error(w, "DEMO_READY_ROUTE_INVALID", 404)
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), 15*time.Second)
		defer cancel()
		if err := c.authenticateReady(ctx, r.Header.Get("Authorization")); err != nil {
			http.Error(w, "DEMO_READY_UNAUTHORIZED", 401)
			return
		}
		raw, readErr := io.ReadAll(http.MaxBytesReader(w, r.Body, 16*1024))
		if readErr != nil {
			http.Error(w, "DEMO_READY_REQUEST_INVALID", 400)
			return
		}
		decoder := json.NewDecoder(bytes.NewReader(raw))
		decoder.DisallowUnknownFields()
		var result map[string]interface{}
		var err error
		if r.URL.Path == "/v1/demo-ready/status" {
			var input demoReadyStatusRequest
			if decoder.Decode(&input) != nil || decoder.Decode(new(interface{})) != io.EOF || input.SchemaVersion != "demo-ready-status-request.v1" || !readyName.MatchString(input.LeaseName) || !readyText(input.LeaseUID) || !readyText(input.RequestID) {
				http.Error(w, "DEMO_READY_REQUEST_INVALID", 400)
				return
			}
			result, err = c.readDemoReady(ctx, input)
		} else {
			var input demoReadyRequest
			if decoder.Decode(&input) != nil || decoder.Decode(new(interface{})) != io.EOF || input.validate() != nil {
				http.Error(w, "DEMO_READY_REQUEST_INVALID", 400)
				return
			}
			digest := sha256.Sum256(raw)
			input.wireDigest = "sha256:" + hex.EncodeToString(digest[:])
			result, err = c.commitDemoReady(ctx, input)
		}
		if err != nil {
			http.Error(w, readyErrorCode(err), 409)
			return
		}
		_ = json.NewEncoder(w).Encode(result)
	})
}

func (c *controller) readDemoReady(ctx context.Context, r demoReadyStatusRequest) (map[string]interface{}, error) {
	var item lease
	if err := c.kube(ctx, http.MethodGet, c.leasePath(r.LeaseName), nil, "application/json", &item); err != nil {
		return nil, err
	}
	if item.Metadata.DeletionTimestamp != "" {
		return nil, errors.New("DEMO_READY_LEASE_DELETING")
	}
	if !time.Now().Before(c.expiresAt(&item)) {
		return nil, errors.New("DEMO_READY_EXPIRED")
	}
	state := objectValue(item.Status["demoReadiness"])
	if item.Metadata.UID != r.LeaseUID || item.Metadata.DeletionTimestamp != "" || stringValue(state["requestId"]) != r.RequestID || stringValue(state["state"]) != "ready-for-acceptance" || !time.Now().Before(c.expiresAt(&item)) || stringValue(item.Status["phase"]) != "Ready" {
		return nil, errors.New("DEMO_READY_NOT_CURRENT")
	}
	if err := c.verifyCommittedReady(ctx, &item); err != nil {
		return nil, err
	}
	return readyResponse(&item, state), nil
}
func readyResponse(item *lease, state map[string]interface{}) map[string]interface{} {
	seconds, _ := storedDemoRetention(state)
	return map[string]interface{}{"retentionSeconds": seconds, "schemaVersion": "demo-ready-response.v1", "leaseName": item.Metadata.Name, "leaseUID": item.Metadata.UID, "requestId": state["requestId"], "state": state["state"], "readyAt": state["readyAt"], "expiresAt": state["expiresAt"], "requestDigest": state["requestDigest"]}
}

func (c *controller) commitDemoReady(ctx context.Context, r demoReadyRequest) (map[string]interface{}, error) {
	if !readyDigest.MatchString(r.wireDigest) {
		return nil, errors.New("DEMO_READY_REQUEST_INVALID")
	}
	var item lease
	if err := c.kube(ctx, http.MethodGet, c.leasePath(r.LeaseName), nil, "application/json", &item); err != nil {
		return nil, err
	}
	if item.Metadata.UID != r.LeaseUID || item.Metadata.ResourceVersion == "" || stringValue(item.Status["phase"]) != "Ready" {
		return nil, errors.New("DEMO_READY_LEASE_NOT_CURRENT")
	}
	if item.Metadata.DeletionTimestamp != "" {
		return nil, errors.New("DEMO_READY_LEASE_DELETING")
	}
	if !time.Now().Before(c.expiresAt(&item)) {
		return nil, errors.New("DEMO_READY_EXPIRED")
	}
	state := objectValue(item.Status["demoReadiness"])
	if len(state) > 0 {
		if state["requestDigest"] != readyRequestDigest(r) || state["state"] != "ready-for-acceptance" {
			receipt := objectValue(state["receipt"])
			if receipt["messageId"] != r.Receipt.MessageID || receipt["deliveryId"] != r.Receipt.DeliveryID || receipt["payloadDigest"] != r.Receipt.PayloadDigest || receipt["target"] != r.Receipt.Target {
				return nil, errors.New("DEMO_READY_RECEIPT_CONFLICT")
			}
			return nil, errors.New("DEMO_READY_REPLAY_CHANGED")
		}
		if err := c.verifyCommittedReady(ctx, &item); err != nil {
			return nil, err
		}
		return readyResponse(&item, state), nil
	}
	if len(objectValue(item.Status["exposureMutation"])) > 0 {
		return nil, errors.New("DEMO_READY_EXPOSURE_OPERATION_UNRESOLVED")
	}
	observed, err := time.Parse(time.RFC3339Nano, r.ObservedAt)
	now := time.Now().UTC()
	if err != nil || observed.After(now) || now.Sub(observed) > 5*time.Minute {
		return nil, errors.New("DEMO_READY_OBSERVATION_STALE")
	}
	if err = c.verifyReadySource(ctx, &item, r); err != nil {
		return nil, err
	}
	now = time.Now().UTC()
	if !now.Before(c.expiresAt(&item)) || now.Sub(observed) > 5*time.Minute {
		return nil, errors.New("DEMO_READY_EXPIRED")
	}
	seconds, err := parseDemoRetention(r.RetentionSeconds)
	if err != nil {
		return nil, err
	}
	expires, err := demoRetentionDeadline(now, seconds)
	if err != nil {
		return nil, err
	}
	state = map[string]interface{}{"retentionSeconds": seconds, "namespace": r.Namespace, "schemaVersion": "demo-readiness.v2", "state": "ready-for-acceptance", "requestId": r.RequestID, "requestDigest": readyRequestDigest(r), "readyAt": now.Format(time.RFC3339Nano), "expiresAt": expires.Format(time.RFC3339Nano), "runId": r.RunID, "sourceRevision": r.SourceRevision, "candidateDigest": r.CandidateDigest, "decisionDigest": r.DecisionDigest, "resultDigest": r.ResultDigest, "leaseUID": r.LeaseUID, "immutableImage": r.ImmutableImage, "manifestDigest": r.ManifestDigest, "credentialDigest": r.CredentialDigest, "secretUID": r.SecretUID, "url": r.URL, "previousOwner": r.ExposureOwner, "owner": "ready:" + readyRequestDigest(r), "exposureGeneration": r.ExposureGeneration, "exposureSpec": item.Spec["exposure"], "receipt": r.Receipt}
	patch := map[string]interface{}{"metadata": map[string]interface{}{"resourceVersion": item.Metadata.ResourceVersion}, "status": map[string]interface{}{"demoReadiness": state, "expiresAt": state["expiresAt"], "exposureOwner": state["owner"]}}
	if err = c.kube(ctx, http.MethodPatch, c.statusPath(r.LeaseName), patch, "application/merge-patch+json", nil); err != nil {
		var apiErr *apiError
		if errors.As(err, &apiErr) && apiErr.statusCode == 409 {
			return nil, errors.New("DEMO_READY_VERSION_CONFLICT")
		}
		return nil, errors.New("DEMO_READY_COMMIT_UNCERTAIN")
	}
	var persisted lease
	if err := c.kube(ctx, http.MethodGet, c.leasePath(r.LeaseName), nil, "application/json", &persisted); err != nil {
		return nil, errors.New("DEMO_READY_COMMIT_UNCERTAIN")
	}
	actual := objectValue(persisted.Status["demoReadiness"])
	actualSeconds, retentionErr := storedDemoRetention(actual)
	if _, present := actual["retentionSeconds"]; !present || retentionErr != nil || actualSeconds != seconds {
		return nil, errors.New("DEMO_READY_COMMIT_UNCERTAIN")
	}
	if persisted.Metadata.UID != item.Metadata.UID || persisted.Metadata.DeletionTimestamp != "" || actual["requestDigest"] != state["requestDigest"] || actual["readyAt"] != state["readyAt"] || actual["expiresAt"] != state["expiresAt"] {
		return nil, errors.New("DEMO_READY_COMMIT_UNCERTAIN")
	}
	if err := c.verifyCommittedReady(ctx, &persisted); err != nil {
		return nil, err
	}
	return readyResponse(&persisted, actual), nil
}

func (c *controller) verifyReadySource(ctx context.Context, item *lease, r demoReadyRequest) error {
	if item.Metadata.Annotations[exposureOwnerAnnotation] != r.ExposureOwner || stringValue(item.Status["exposureOwner"]) != r.ExposureOwner {
		return errors.New("DEMO_READY_EXPOSURE_OWNER_CHANGED")
	}
	if stringValue(item.Spec["purpose"]) != "final-preview" || stringValue(item.Spec["cleanupPolicy"]) != "retain" || stringValue(item.Status["namespaceName"]) != r.Namespace || stringValue(item.Spec["verifiedImage"]) != r.ImmutableImage || stringValue(item.Spec["manifestDigest"]) != r.ManifestDigest || stringValue(item.Status["previewUrl"]) != r.URL || stringValue(item.Status["exposurePhase"]) != "Ready" || item.Metadata.Generation != r.ExposureGeneration || item.Metadata.Annotations[exposureOwnerAnnotation] != r.ExposureOwner || stringValue(item.Status["exposureOwner"]) != r.ExposureOwner || intValue(item.Status["exposureGeneration"], 0) != int(r.ExposureGeneration) {
		return errors.New("DEMO_READY_SOURCE_CHANGED")
	}
	var pending map[string]interface{}
	if json.Unmarshal([]byte(item.Metadata.Annotations["kubeclaw.forgestack.ai/readiness-handoff"]), &pending) != nil || pending["phase"] != "awaiting-readiness" || pending["owner"] != r.ExposureOwner || pending["leaseUID"] != r.LeaseUID || pending["immutableImage"] != r.ImmutableImage || pending["manifestDigest"] != r.ManifestDigest {
		return errors.New("DEMO_READY_HANDOFF_INVALID")
	}
	if err := c.verifyReadyNamespace(ctx, item, r.Namespace); err != nil {
		return err
	}
	if err := c.verifyReadyIngress(ctx, item, r.Namespace, r.URL); err != nil {
		return err
	}
	return c.verifyReadySecret(ctx, item, r.Namespace, r.SecretUID, r.CredentialDigest)
}

package main

import (
	"encoding/json"
	"errors"
	"time"
)

const defaultDemoRetentionSeconds int64 = 604800

// Technical arithmetic bound only; this is not an operational retention policy.
const maximumDemoRetentionSeconds int64 = (1<<63 - 1) / int64(time.Second)

func parseDemoRetention(raw json.RawMessage) (int64, error) {
	if len(raw) == 0 {
		return defaultDemoRetentionSeconds, nil
	}
	var seconds int64
	if string(raw) == "null" || json.Unmarshal(raw, &seconds) != nil || seconds < 1 || seconds > maximumDemoRetentionSeconds {
		return 0, errors.New("DEMO_READY_RETENTION_INVALID")
	}
	return seconds, nil
}

func storedDemoRetention(state map[string]interface{}) (int64, error) {
	value, exists := state["retentionSeconds"]
	if state["schemaVersion"] == "demo-readiness.v1" && !exists {
		// Only the actual historical schema has implicit seven-day retention.
		return defaultDemoRetentionSeconds, nil
	}
	if state["schemaVersion"] != "demo-readiness.v2" || !exists {
		return 0, errors.New("DEMO_READY_RETENTION_INVALID")
	}
	raw, err := json.Marshal(value)
	if err != nil {
		return 0, errors.New("DEMO_READY_RETENTION_INVALID")
	}
	return parseDemoRetention(raw)
}

func demoRetentionDeadline(ready time.Time, seconds int64) (time.Time, error) {
	if seconds < 1 || seconds > maximumDemoRetentionSeconds {
		return time.Time{}, errors.New("DEMO_READY_RETENTION_INVALID")
	}
	expires := ready.Add(time.Duration(seconds) * time.Second)
	if ready.Year() < 1 || ready.Year() > 9999 || expires.Year() < 1 || expires.Year() > 9999 {
		return time.Time{}, errors.New("DEMO_READY_RETENTION_INVALID")
	}
	return expires, nil
}

