		return fallback
	}
	parsed, err := strconv.Atoi(value)
	if err != nil {
		return fallback
	}
	return parsed
}

func controllerPollInterval() (time.Duration, error) {
	value := strings.TrimSpace(os.Getenv("BUSTER_CONTROLLER_POLL_MS"))
	if value == "" {
		value = "3000"
	}
	pollMs, err := strconv.ParseInt(value, 10, 64)
	if err != nil || pollMs <= 0 || pollMs > (1<<63-1)/int64(time.Millisecond) {
		return 0, errors.New("BUSTER_CONTROLLER_POLL_MS must be positive")
	}
	return time.Duration(pollMs) * time.Millisecond, nil
}

func splitCSV(value string) []string {
	parts := strings.Split(value, ",")
	out := []string{}
	for _, part := range parts {
		trimmed := strings.TrimSpace(part)
		if trimmed != "" {
			out = append(out, trimmed)
		}
	}
	return out
}

func stringValue(value interface{}) string {
	switch typed := value.(type) {
	case string:
		return typed
	case fmt.Stringer:
		return typed.String()
	case nil:
		return ""
	default:
		return fmt.Sprint(typed)
	}
}

func stringValueDefault(value interface{}, fallback string) string {
	if result := stringValue(value); result != "" {
		return result
	}
	return fallback
}

func firstString(values ...interface{}) string {
	for _, value := range values {
		if result := stringValue(value); result != "" {
			return result
		}
	}
	return ""
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

func intValue(value interface{}, fallback int) int {
	switch typed := value.(type) {
	case int:
		return typed
	case int64:
		return int(typed)
	case float64:
		return int(typed)
	case json.Number:
		parsed, err := typed.Int64()
		if err == nil {
			return int(parsed)
		}
	case string:
		parsed, err := strconv.Atoi(typed)
		if err == nil {
			return parsed
		}
	}
	return fallback
}

func boolValue(value interface{}) bool {
	typed, ok := value.(bool)
	return ok && typed
}

func objectValue(value interface{}) map[string]interface{} {
	typed, ok := value.(map[string]interface{})
	if !ok || typed == nil {
		return map[string]interface{}{}
	}
	return typed
}

func interfaceSlice(value interface{}) []interface{} {
	if values, ok := value.([]interface{}); ok {
		return values
	}
	return nil
}

func stringMap(value interface{}) map[string]string {
	result := map[string]string{}
	switch values := value.(type) {
	case map[string]string:
		return values
	case map[string]interface{}:
		for key, raw := range values {
			if text, ok := raw.(string); ok {
				result[key] = text
			}
		}
	}
	return result
}

func mergeStringMaps(values ...map[string]string) map[string]string {
	result := map[string]string{}
	for _, value := range values {
		for key, item := range value {
			result[key] = item
		}
	}
	return result
}

func stringSlice(value interface{}) []string {
	items, ok := value.([]interface{})
	if !ok {
		if stringsValue, ok := value.([]string); ok {
			return stringsValue
		}
		return nil
	}
	out := make([]string, 0, len(items))
	for _, item := range items {
		if value := stringValue(item); value != "" {
			out = append(out, value)
		}
	}
	return out
}

func nullableString(value string) interface{} {
	if value == "" {
		return nil
	}
	return value
}

func nullIfEmpty(value string) string {
	if value == "" {
		return ""
	}
	return value
}

func ternaryString(condition bool, whenTrue string, whenFalse string) string {
	if condition {
		return whenTrue
	}
	return whenFalse
}

func contains(values []string, target string) bool {
	for _, value := range values {
		if value == target {
			return true
		}
	}
	return false
}

func sliceString(value string, maxLength int) string {
	if len(value) <= maxLength {
