export function requireIdentity(value) {
  if (typeof value !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$/u.test(value)) throw new Error('IDENTITY_INVALID');
  return value;
}

export class Inventory {
  roots = [];
  files = new Map();
  directories = new Map();
  blockers = [];
  bytesHashed = 0;
  paths = new Set();
  constructor(limits = {}) {
    this.limits = { maximumFiles: 10000, maximumTotalBytes: 256 * 1024 * 1024, maximumSnapshotBytes: 32 * 1024 * 1024, ...limits };
    for (const value of Object.values(this.limits)) {
      if (!Number.isSafeInteger(value) || value < 1) throw new Error('INVENTORY_LIMIT_INVALID');
    }
  }
  block(code, subject) {
    const item = { code, subject };
    if (!this.blockers.some(existing => existing.code === code && existing.subject === subject)) this.blockers.push(item);
  }
  root(directory, owner, scan = true) {
    if (typeof directory !== 'string' || !path.isAbsolute(directory)) throw new Error('ABSOLUTE_ROOT_REQUIRED');
    const canonical = path.resolve(directory);
    let cursor = path.parse(canonical).root;
    for (const segment of canonical.slice(cursor.length).split(path.sep).filter(Boolean)) {
      cursor = path.join(cursor, segment);
      const stat = fs.lstatSync(cursor);
      if (stat.isSymbolicLink() || !stat.isDirectory()) throw new Error('ROOT_DIRECTORY_INVALID');
      this.pinDirectory(cursor, stat);
    }
    const existing = this.roots.find(root => root.path === canonical);
    if (existing) existing.scan ||= scan;
    else this.roots.push({ owner, path: canonical, scan });
    if (scan) this.walk(canonical);
    return canonical;
  }
  pinDirectory(directory, stat = fs.lstatSync(directory)) {
    const identity = `${stat.dev}:${stat.ino}`;
    if (!stat.isDirectory() || stat.isSymbolicLink()
      || (this.directories.has(directory) && this.directories.get(directory) !== identity)) throw new Error('SNAPSHOT_CHANGED');
    this.directories.set(directory, identity);
  }
  checkParents(file) {
    let directory = path.dirname(file);
    while (directory !== path.dirname(directory)) {
      if (this.directories.has(directory)) this.pinDirectory(directory);
      directory = path.dirname(directory);
    }
  }
  walk(directory, depth = 0) {
    this.checkParents(directory);
    this.pinDirectory(directory);
    if (depth > 64) { this.block('INVENTORY_DEPTH_LIMIT', directory); return; }
    const entries = [];
    const handle = fs.opendirSync(directory);
    try {
      for (;;) {
        const entry = handle.readSync();
        if (!entry) break;
        if (entries.length >= this.limits.maximumFiles) { this.block('INVENTORY_FILE_LIMIT', directory); break; }
        entries.push(entry.name);
      }
    } finally { handle.closeSync(); }
    entries.sort();
    for (const name of entries) {
      const file = path.join(directory, name);
      if (this.files.has(file)) continue;
      if (!this.paths.has(file) && this.paths.size >= this.limits.maximumFiles) { this.block('INVENTORY_FILE_LIMIT', directory); return; }
      this.paths.add(file);
      const stat = fs.lstatSync(file);
      if (stat.isSymbolicLink() || (!stat.isFile() && !stat.isDirectory())) { this.block('NON_REGULAR_PATH', file); continue; }
      if (stat.isDirectory()) { this.walk(file, depth + 1); continue; }
      const item = { path: file, bytes: stat.size, hash: null, stamp: stableStat(stat), disposition: 'retain' };
      this.files.set(file, item);
      if (stat.size > this.limits.maximumTotalBytes - this.bytesHashed) { this.block('INVENTORY_BYTE_LIMIT', file); continue; }
      item.hash = this.hashFile(file, stat);
      this.bytesHashed += stat.size;
    }
  }
  hashFile(file, before) {
    this.checkParents(file);
    const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK);
    try {
      if (stableStat(fs.fstatSync(fd)) !== stableStat(before)) throw new Error('SNAPSHOT_CHANGED');
      const hash = crypto.createHash('sha256');
      const buffer = Buffer.alloc(65536);
      let size = 0;
      for (;;) {
        const read = fs.readSync(fd, buffer, 0, buffer.length, null);
        if (!read) break;
        size += read;
        if (size > before.size) throw new Error('SNAPSHOT_CHANGED');
        hash.update(buffer.subarray(0, read));
      }
      if (size !== before.size || stableStat(fs.fstatSync(fd)) !== stableStat(before)) throw new Error('SNAPSHOT_CHANGED');
      return `sha256:${hash.digest('hex')}`;
    } finally { fs.closeSync(fd); }
  }
  text(file) {
    this.checkParents(file);
    const item = this.files.get(file);
    if (!item?.hash) throw new Error('UNINVENTORIED_REFERENCE');
    if (item.bytes > this.limits.maximumSnapshotBytes) throw new Error('SNAPSHOT_BYTE_LIMIT');
    const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK);
    try {
      if (stableStat(fs.fstatSync(fd)) !== item.stamp) throw new Error('SNAPSHOT_CHANGED');
      const bytes = Buffer.alloc(item.bytes);
      let offset = 0;
      while (offset < bytes.length) {
        const read = fs.readSync(fd, bytes, offset, bytes.length - offset, null);
        if (!read) throw new Error('SNAPSHOT_CHANGED');
        offset += read;
      }
      if (fs.readSync(fd, Buffer.alloc(1), 0, 1, null)) throw new Error('SNAPSHOT_CHANGED');
      if (digest(bytes) !== item.hash || stableStat(fs.fstatSync(fd)) !== item.stamp) throw new Error('SNAPSHOT_CHANGED');
      return bytes.toString('utf8');
    } finally { fs.closeSync(fd); }
  }
  json(file) { return JSON.parse(this.text(file)); }
  verifyUnchanged() {
    for (const directory of this.directories.keys()) {
      try { this.checkParents(directory); this.pinDirectory(directory); }
      catch { this.block('SNAPSHOT_CHANGED', directory); return; }
    }
    const before = new Set(this.files.keys());
    for (const root of this.roots) if (root.scan) {
      try { this.walk(root.path); } catch { this.block('SNAPSHOT_CHANGED', root.path); }
    }
    if (this.files.size !== before.size) this.block('SNAPSHOT_CHANGED', 'inventory');
    for (const item of this.files.values()) {
      try {
        const stat = fs.lstatSync(item.path);
        if (!stat.isFile() || stableStat(stat) !== item.stamp) this.block('SNAPSHOT_CHANGED', item.path);
      } catch { this.block('SNAPSHOT_CHANGED', item.path); }
    }
  }
  output() { return [...this.files.values()].map(({ stamp, ...item }) => item); }
}

scripts/prepare-native-worker-pools.mjs.syntax:
function configuration(file) {
  const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK);
  try {
    const stat = fs.fstatSync(fd);
    if (!stat.isFile() || stat.uid !== 0 || (stat.mode & 0o022) !== 0 || stat.size > 65536) throw new Error('NATIVE_SETUP_POLICY_NOT_TRUSTED');
    const policy = JSON.parse(fs.readFileSync(fd, 'utf8'));
    if (policy.schemaVersion !== 1 || policy.nodeVersion !== process.versions.node
      || Object.keys(policy.pools ?? {}).sort().join(',') !== 'buster,prism') throw new Error('NATIVE_SETUP_POLICY_RUNTIME_INVALID');
    for (const pool of Object.values(policy.pools)) validatePool(pool);
    return policy;
  } finally { fs.closeSync(fd); }
}

function validatePool(pool) {
  for (const key of ['memoryBytes', 'tasks', 'cpuQuotaMicroseconds', 'cpuPeriodMicroseconds']) {
    if (!Number.isSafeInteger(pool[key]) || pool[key] < 1) throw new Error('NATIVE_SETUP_LIMIT_INVALID');
  }
  if (pool.memoryBytes % 4096 || pool.cpuPeriodMicroseconds < 1000 || pool.cpuPeriodMicroseconds > 1000000
    || pool.cpuQuotaMicroseconds < 1000) throw new Error('NATIVE_SETUP_LIMIT_INVALID');
}

function verifyExisting(role, pool) {
  const directory = `${root}/${role}`;
  if (!fs.existsSync(directory)) return false;
  if (!fs.lstatSync(directory).isDirectory() || fs.statfsSync(directory).type !== 0x63677270
    || read(`${directory}/cgroup.procs`)) throw new Error('NATIVE_SETUP_EXISTING_POOL_INVALID');
  for (const [file, expected] of Object.entries(controls(pool))) {
    if (read(`${directory}/${file}`) !== expected) throw new Error('NATIVE_SETUP_POOL_CHANGE_REQUIRES_MAINTENANCE');
  }
  if (!required.every(controller => read(`${directory}/cgroup.subtree_control`).split(/\s+/).includes(controller))) {
    throw new Error('NATIVE_SETUP_EXISTING_POOL_NOT_DELEGATED');
  }
  return true;
}

function identity() {
  const machineId = read('/etc/machine-id');
  if (!/^[a-f0-9]{32}$/.test(machineId)) throw new Error('NATIVE_SETUP_MACHINE_ID_INVALID');
  const file = '/etc/kubeclaw/native-node-id';
  if (fs.existsSync(file)) {
    const stat = fs.lstatSync(file);
    if (!stat.isFile() || stat.uid !== 0 || (stat.mode & 0o022) !== 0 || read(file) !== machineId) throw new Error('NATIVE_SETUP_NODE_IDENTITY_CONFLICT');
    return;
  }
  const fd = fs.openSync(file, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL, 0o444);
  try { fs.writeFileSync(fd, `${machineId}\n`); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
  const parent = fs.openSync('/etc/kubeclaw', fs.constants.O_RDONLY);
  try { fs.fsyncSync(parent); } finally { fs.closeSync(parent); }
}

function runtimeIdentity() {
  const own = fs.statSync('/proc/self/ns/cgroup', { bigint: true });
  const host = fs.statSync('/proc/1/ns/cgroup', { bigint: true });
  if (own.dev !== host.dev || own.ino !== host.ino) throw new Error('NATIVE_SETUP_HOST_NAMESPACE_REQUIRED');
  const value = { schemaVersion: 1, bootId: read('/proc/sys/kernel/random/boot_id'),
    cgroupNamespace: { device: String(own.dev), inode: String(own.ino) } };
  const file = '/etc/kubeclaw/native-runtime-identity.json';
  if (fs.existsSync(file)) {
    const stat = fs.lstatSync(file);
    if (!stat.isFile() || stat.uid !== 0 || (stat.mode & 0o022) !== 0 || stat.size > 4096) throw new Error('NATIVE_SETUP_RUNTIME_IDENTITY_NOT_TRUSTED');
    const previous = JSON.parse(read(file));
    if (previous.bootId === value.bootId) {
      if (JSON.stringify(previous) !== JSON.stringify(value)) throw new Error('NATIVE_SETUP_RUNTIME_IDENTITY_CONFLICT');
      return;
    }
  }
  const temporary = `${file}.${process.pid}.pending`;
  const fd = fs.openSync(temporary, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL, 0o444);
  try { fs.writeFileSync(fd, `${JSON.stringify(value)}\n`); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
  fs.renameSync(temporary, file);
  const parent = fs.openSync('/etc/kubeclaw', fs.constants.O_RDONLY);
  try { fs.fsyncSync(parent); } finally { fs.closeSync(parent); }
}

function prepare(policy) {
  if (process.getuid() !== 0 || fs.statfsSync(root).type !== 0x63677270
    || !read('/proc/self/cgroup').split('\n').includes(`0::${root.slice('/sys/fs/cgroup'.length)}/setup`)
    || read(`${root}/cgroup.procs`)) throw new Error('NATIVE_SETUP_DELEGATED_UNIT_REQUIRED');
  const available = read(`${root}/cgroup.controllers`).split(/\s+/);
  if (!required.every(controller => available.includes(controller))) throw new Error('NATIVE_SETUP_CONTROLLERS_UNAVAILABLE');
  const unknown = fs.readdirSync(root, { withFileTypes: true }).filter(entry => entry.isDirectory()
    && !['setup', 'buster', 'prism'].includes(entry.name));
  if (unknown.length) throw new Error('NATIVE_SETUP_UNKNOWN_SUBTREE');
  // Inspect all existing role limits before creating or changing anything.
  const existing = new Set(Object.entries(policy.pools).filter(([role, pool]) => verifyExisting(role, pool)).map(([role]) => role));
  identity();
  runtimeIdentity();
  fs.writeFileSync(`${root}/cgroup.subtree_control`, required.map(controller => `+${controller}`).join(' '));
  for (const [role, pool] of Object.entries(policy.pools)) {
    if (existing.has(role)) continue;
    const directory = `${root}/${role}`;
    fs.mkdirSync(directory);
    for (const [file, value] of Object.entries(controls(pool))) fs.writeFileSync(`${directory}/${file}`, value);
    fs.writeFileSync(`${directory}/cgroup.subtree_control`, required.map(controller => `+${controller}`).join(' '));
    verifyExisting(role, pool);
  }
  process.stdout.write('NATIVE_HOST_POOLS_PREPARED_NODE_CAPACITY_PREFLIGHT_REQUIRED\n');
}

if (serve) {
  // RemainAfterExit retains the unit state, not an empty delegated cgroup.
  // Keep the setup subgroup populated for the entire pool lifetime. Notify only
  // after both pools and their identities have been successfully verified.
  execFileSync('/usr/bin/systemd-notify', ['--ready', '--status=Native worker pools prepared; capacity preflight still required'], { stdio: 'inherit' });
  setInterval(() => {}, 60_000);
}

scripts/render-native-worker-node.mjs.syntax:
export function renderNativeWorkerNode(policy) {
  const selected = validateNativeNodePolicy(policy);
  const pools = Object.fromEntries(['buster', 'prism'].map(role => [role, nativePoolPolicy(selected, role)]));
  const version = JSON.parse(fs.readFileSync(path.join(repository, 'versions.json'), 'utf8')).buildArgs.NODE_BASE;
  const nodeVersion = /^node:(\d+\.\d+\.\d+)-/.exec(version)?.[1];
  if (!nodeVersion) throw new Error('NATIVE_HOST_NODE_VERSION_NOT_SELECTED');
  const setup = { schemaVersion: 1, nodeVersion, pools: Object.fromEntries(Object.entries(pools).map(([role, pool]) => [role, pool.limits])) };
  const kubelet = { ...nativeNodeReservation(selected), cgroupDriver: 'systemd', cgroupsPerQOS: true, enforceNodeAllocatable: ['pods'] };
  return {
    'prism-native-values.yaml': dump({ worker: { native: { nodeName: selected.nodeName,
      namespace: selected.pools.prism.namespace, policyDigest: pools.prism.policyDigest }, replicas: 1 } }),
    'native-nri.json': `${JSON.stringify(nriPolicy(selected, pools), null, 2)}\n`,
    'containerd-nri.toml': '[plugins."io.containerd.nri.v1.nri"]\n  disable = false\n',
    'native-node-policy.json': `${JSON.stringify(setup, null, 2)}\n`,
    'buster-pool.json': `${JSON.stringify(pools.buster, null, 2)}\n`,
    'prism-pool.json': `${JSON.stringify(pools.prism, null, 2)}\n`,
    'kubelet-reservations.json': `${JSON.stringify(kubelet, null, 2)}\n`,
    'prepare-native-worker-pools.mjs': fs.readFileSync(path.join(repository, 'scripts/prepare-native-worker-pools.mjs'), 'utf8'),
    'kubeclaw-native-pools.service': unit(),
  };
}

function nriPolicy(selected, pools) {
  const containerdVersion = selected.runtime?.containerdVersion;
  if (typeof containerdVersion !== 'string' || !/^v?2\.(?:[2-9]|[1-9][0-9]+)\.[0-9]+(?:[-+][A-Za-z0-9.-]+)?$/.test(containerdVersion)) {
    throw new Error('NATIVE_NODE_SELECTED_CONTAINERD_VERSION_REQUIRED');
  }
  const roles = Object.fromEntries(['buster', 'prism'].map(role => [role, {
    namespace: selected.pools[role].namespace, container: role === 'buster' ? 'buster-v2-runtime' : 'worker',
    policyDigest: pools[role].policyDigest,
  }]));
  return { schemaVersion: 1, containerdVersion, roles };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 4) throw new Error('Usage: render-native-worker-node.mjs POLICY_YAML NEW_OUTPUT_DIRECTORY');
  const bundle = renderNativeWorkerNode(loadNativeNodePolicy(process.argv[2]));
  const directory = path.resolve(process.argv[3]);
  fs.mkdirSync(directory, { mode: 0o700 }); // Exclusive: never overwrite an operator's previous bundle.
  for (const [name, content] of Object.entries(bundle)) fs.writeFileSync(path.join(directory, name), content, { flag: 'wx', mode: 0o600 });
  process.stdout.write(`${directory}\n`);
}

scripts/native-worker-node-policy.mjs.syntax:
function positive(value) {
  if (!Number.isSafeInteger(value) || value < 1) throw new Error('NATIVE_NODE_POLICY_LIMIT_INVALID');
}

function resources(value) {
  positive(value?.cpuMillicores); positive(value?.memoryBytes);
  if (value.memoryBytes % 4096 !== 0) throw new Error('NATIVE_NODE_MEMORY_ALIGNMENT_INVALID');
}

export function validateNativeNodePolicy(policy) {
  if (policy?.schemaVersion !== 1 || typeof policy.nodeName !== 'string'
    || !/^[a-z0-9](?:[a-z0-9.-]{0,251}[a-z0-9])?$/.test(policy.nodeName)) throw new Error('NATIVE_NODE_IDENTITY_REQUIRED');
  resources(policy.systemReserve); resources(policy.kubernetesReserve);
  positive(policy.systemReserve.tasks); positive(policy.kubernetesReserve.tasks);
  if (Object.keys(policy.pools ?? {}).sort().join(',') !== 'buster,prism') throw new Error('NATIVE_NODE_ROLE_SET_INVALID');
  for (const pool of Object.values(policy.pools)) {
    if (typeof pool.namespace !== 'string' || !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(pool.namespace)) throw new Error('NATIVE_NODE_NAMESPACE_REQUIRED');
    resources(pool); positive(pool.tasks); positive(pool.maximumActiveScopes);
    if (pool.cpuMillicores > Number.MAX_SAFE_INTEGER / 100) throw new Error('NATIVE_NODE_CPU_RANGE_INVALID');
  }
  const result = structuredClone(policy);
  for (const key of ['cpuMillicores', 'memoryBytes', 'tasks']) {
    const total = Object.values(result.pools).reduce((sum, pool) => sum + BigInt(pool[key]), 0n)
      + BigInt(result.systemReserve[key]) + BigInt(result.kubernetesReserve[key]);
    if (total > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error('NATIVE_NODE_TOTAL_RANGE_INVALID');
  }
  return result;
}

export function nativePoolPolicy(policy, role) {
  const selected = validateNativeNodePolicy(policy);
  const pool = selected.pools[role];
  if (!pool) throw new Error('NATIVE_NODE_ROLE_INVALID');
  return { schemaVersion: 1, role, nodeName: selected.nodeName,
    policyDigest: createHash('sha256').update(JSON.stringify(selected)).digest('hex'),
    cgroupRoot: `${nativePoolRoot}/${role}`, ownershipRoot: `/var/lib/kubeclaw/native/${role}`,
    nodeIdentityFile: '/etc/kubeclaw/native-node-id', runtimeIdentityFile: '/etc/kubeclaw/native-runtime-identity.json',
    maximumActiveScopes: pool.maximumActiveScopes,
    limits: { memoryBytes: pool.memoryBytes, tasks: pool.tasks,
      cpuQuotaMicroseconds: pool.cpuMillicores * 100, cpuPeriodMicroseconds: 100000 } };
}

export function nativeNodeReservation(policy) {
  const selected = validateNativeNodePolicy(policy);
  const system = { ...selected.systemReserve };
  for (const pool of Object.values(selected.pools)) {
    system.cpuMillicores += pool.cpuMillicores; system.memoryBytes += pool.memoryBytes; system.tasks += pool.tasks;
  }
  return { systemReserved: { cpu: `${system.cpuMillicores}m`, memory: String(system.memoryBytes), pid: String(system.tasks) },
    kubeReserved: { cpu: `${selected.kubernetesReserve.cpuMillicores}m`, memory: String(selected.kubernetesReserve.memoryBytes), pid: String(selected.kubernetesReserve.tasks) } };
}

scripts/updates/deployment-release.mjs.syntax:
export function validateReleaseReceipt(receipt, family) {
  const names = families[family];
  if (!names) throw new Error('Unknown release family');
  if (receipt.schemaVersion !== 1 || !/^[a-f0-9]{40}$/u.test(receipt.commit)
    || !Number.isSafeInteger(receipt.sourceRunId) || receipt.sourceRunId < 1
    || !Number.isSafeInteger(receipt.sourceRunAttempt) || receipt.sourceRunAttempt < 1
    || !receipt.images || JSON.stringify(Object.keys(receipt.images).sort()) !== JSON.stringify([...names].sort())) {
    throw new Error('Invalid complete release receipt or source run identity');
  }
  for (const name of names) {
    if (typeof receipt.images[name] !== 'string'
      || !new RegExp(`^ghcr\\.io/[a-z0-9_-]+/kubeclaw-${name}@sha256:[a-f0-9]{64}$`, 'u').test(receipt.images[name])) {
      throw new Error(`Invalid selected image slot: ${name}`);
    }
  }
  if (receipt.code) validateCodeReceipt(receipt.code);
  return receipt;
}

export function selectedRelease(root, family) {
  const names = families[family];
  if (!names) throw new Error('Unknown release family');
  const file = path.join(root, `releases/${family}-images.json`);
  if (!fs.existsSync(file)) throw new Error(`No selected ${family} release. Merge the Promote image release selection PR, then run node scripts/updates/materialize-release.mjs --family=${family}; no latest fallback is available.`);
  const receipt = JSON.parse(fs.readFileSync(file, 'utf8'));
  validateReleaseReceipt(receipt, family);
  execFileSync(process.execPath, [path.join(import.meta.dirname, 'materialize-release.mjs'), `--family=${family}`, '--check'], { cwd: root, stdio: ['ignore', 'pipe', 'pipe'] });
  const code = family === 'runtime' ? selectedCode(root, receipt) : undefined;
  return code ? { ...receipt, code } : receipt;
}

function containerSlots(manifest) {
  const slots = new Map();
  const visit = (value, key) => {
    if (!value || typeof value !== 'object') return;
    for (const field of ['containers', 'initContainers']) {
      for (const container of value[field] ?? []) {
        const id = `${key}/${field}/${container.name}`;
        if (slots.has(id)) throw new Error(`Duplicate image slot: ${id}`);
        slots.set(id, container);
      }
    }
    for (const [field, child] of Object.entries(value)) {
      if (!['containers', 'initContainers'].includes(field)) visit(child, key);
    }
  };
  yaml.loadAll(manifest, document => {
    if (document) visit(document, `${document.kind}/${document.metadata?.name}`);
  });
  return slots;
}

function bundleVariables(container) {
  const variables = new Map();
  for (const variable of container?.env ?? []) {
    if (!/^(?:KUBECLAW_)?CODE_BUNDLE_/u.test(variable.name)) continue;
    if (variables.has(variable.name)) throw new Error(`Duplicate reserved bundle control: ${variable.name}`);
    variables.set(variable.name, variable);
  }
  return variables;
}

function validateBundleVariableShape(actual, expected, slot) {
  for (const [name, variable] of actual) {
    // Authentication can introduce the chart's conditional Secret reference.
    if (name.endsWith('_AUTH_TOKEN')) continue;
    if (!expected.has(name)) throw new Error(`Unexpected reserved bundle control: ${slot}/${name}`);
    if (variable.valueFrom || typeof variable.value !== 'string') throw new Error(`Indirect reserved bundle control: ${slot}/${name}`);
  }
  for (const name of expected.keys()) {
    if (!name.endsWith('_AUTH_TOKEN') && !actual.has(name)) throw new Error(`Missing reserved bundle control: ${slot}/${name}`);
  }
}

function validateBundle(container, baseline, slot, receipt, requireBundle) {
  const actual = bundleVariables(container);
  const expected = bundleVariables(baseline);
  validateBundleVariableShape(actual, expected, slot);
  let consumers = 0;
  for (const name of ['CODE_BUNDLE_ENABLED', 'KUBECLAW_CODE_BUNDLE_ENABLED']) {
    if (!expected.has(name)) continue;
    const enabled = actual.get(name)?.value;
    if (!['true', 'false'].includes(enabled) || ((requireBundle || receipt.code) && enabled !== 'true')) throw new Error(`Canonical bundle consumer disabled: ${slot}/${name}`);
    const prefix = name.slice(0, -'ENABLED'.length);
    const commit = receipt.code?.commit ?? receipt.commit;
    const revision = actual.get(`${prefix}EXPECTED_COMMIT`)?.value;
    if ((enabled === 'true' || revision !== '') && revision !== commit) throw new Error(`Bundle commit differs from selected runtime: ${slot}`);
    if (actual.get(`${prefix}CONTRACT_VERSION`)?.value !== 'v2') throw new Error(`Unsupported bundle contract: ${slot}`);
    if (enabled === 'true' && receipt.code && prefix === 'CODE_BUNDLE_') {
      const url = actual.get(`${prefix}ARCHIVE_URL`)?.value;
      const bundle = Object.values(receipt.code.bundles).find(item => item.url === url);
      if (!bundle || actual.get(`${prefix}SHA256`)?.value !== bundle.sha256) throw new Error(`Unselected code bundle: ${slot}`);
      const role = container.env?.find(item => item.name === 'AGENT_NAME')?.value;
      if (!receipt.code.bundles[role] || receipt.code.bundles[role].url !== url) throw new Error(`Wrong code bundle role: ${slot}`);
    }
    consumers += 1;
  }
  return consumers;
}

export function validateRenderedRelease(baseline, rendered, receipt, requireBundle = false) {
  const expected = containerSlots(baseline);
  const actual = containerSlots(rendered);
  const refs = new Set(Object.values(receipt.images));
  for (const [slot, container] of expected) {
    if (refs.has(container.image) && actual.get(slot)?.image !== container.image) {
      throw new Error(`Selected release image slot changed or missing: ${slot}`);
    }
  }
  let bundleConsumers = 0;
  for (const [slot, container] of actual) {
    if (/\/kubeclaw-[^/]+(?:@|:)/u.test(container.image ?? '') && !refs.has(container.image)) {
      throw new Error(`Unselected first-party image: ${slot}`);
    }
    bundleConsumers += validateBundle(container, expected.get(slot), slot, receipt, requireBundle);
  }
  if (requireBundle && bundleConsumers === 0) throw new Error('Selected code bundle is missing from rendered workload');
}

function withDeploymentContext(args, role, run) {
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'release-registry-context-'));
  const context = [];
  try {
    for (let index = 0; index < args.length - 1; index += 1) {
      if (!['-f', '--values'].includes(args[index])) continue;
      const values = yaml.load(fs.readFileSync(args[++index], 'utf8'));
      const registry = values?.runtimeInfrastructure?.registry;
      const native = role === 'prism' ? values?.worker?.native : undefined;
      const binding = native && Object.fromEntries(['nodeName', 'namespace', 'policyDigest']
        .filter(key => native[key] !== undefined).map(key => [key, native[key]]));
      if (registry === undefined && (!binding || !Object.keys(binding).length)) continue;
      const file = path.join(temporary, `${index}.yaml`);
      fs.writeFileSync(file, yaml.dump({ ...(registry === undefined ? {} : { runtimeInfrastructure: { registry } }),
        ...(binding && Object.keys(binding).length ? { worker: { native: binding } } : {}) }), { mode: 0o600 });
      context.push('-f', file);
    }
    return run(context);
  } finally { fs.rmSync(temporary, { recursive: true, force: true }); }
}

function validateOverlays(args, root, role, baseline, render, receipt) {
  // Validate each explicit values overlay before a later override can conceal
  // a conflicting image or bundle choice. Helm performs the actual merge.
  let selectedSeen = false;
  for (let index = 0; index < args.length - 1; index += 1) {
    if (!['-f', '--values'].includes(args[index])) continue;
    const file = args[index + 1];
    const values = yaml.load(fs.readFileSync(file, 'utf8'));
    const commit = values?.codeBundle?.expectedCommit;
    if (commit && commit !== (receipt.code?.commit ?? receipt.commit)) throw new Error('Overlay bundle commit differs from selected runtime');
    if (selectedSeen) validateRenderedRelease(baseline, render(args.slice(0, index + 2)), receipt);
    selectedSeen ||= path.resolve(file) === path.join(root, `releases/values/${role}.yaml`);
    index += 1;
  }
  if (!selectedSeen) throw new Error('Selected release values are required');
}

if (process.argv[1] === import.meta.filename) {
  const [command, root, family, role, release, namespace, ...options] = process.argv.slice(2);
  const receipt = selectedRelease(root, family);
  if (command === 'verify') process.stdout.write(`${receipt.code?.commit ?? receipt.commit}\n`);
  else if (command === 'render') {
    const separator = options.indexOf('--');
    if (separator < 0) throw new Error('Helm values argument separator required');
    const control = options.slice(0, separator);
    const args = options.slice(separator + 1);
    if (!(family === 'ops' ? ['ops'] : ['nova', 'buster', 'prism-agent', 'prism']).includes(role)) throw new Error('Invalid release role');
    const chart = path.join(root, 'charts', role === 'ops' ? 'ops-pod' : role === 'prism' ? 'prism' : 'kubeclaw');
    const common = ['template', release, chart, '--namespace', namespace];
    const discovery = control.find(arg => arg.startsWith('--discovery='))?.slice('--discovery='.length);
    const baselineArgs = discovery ? ['-f', discovery] : [];
    baselineArgs.push('-f', path.join(root, `releases/values/${role}.yaml`));
    const render = values => execFileSync('helm', [...common, ...values], { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 });
    withDeploymentContext(args, role, context => {
      const baseline = render([...baselineArgs, ...context]);
      validateOverlays(args, root, role, baseline, values => render([...context, ...values]), receipt);
      const rendered = render(args);
      validateRenderedRelease(baseline, rendered, receipt, control.includes('--bundle'));
      process.stdout.write(rendered);
    });
  } else throw new Error('Unknown deployment release command');
}

