export interface BrowserLighthouseCapabilityInvokerOptions {
  readonly allowedOrigins: readonly string[];
  readonly chromeExecutable: string;
  readonly maximumRuns: number;
  readonly maximumExecutionMs: number;
  readonly maximumResultBytes: number;
}

function object(value: unknown, code: string): JsonObject {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(code);
  return value as JsonObject;
}

function integer(value: unknown, code: string, minimum: number, maximum: number): number {
  if (!Number.isSafeInteger(value) || Number(value) < minimum || Number(value) > maximum) throw new Error(code);
  return Number(value);
}

function finite(value: unknown, code: string, minimum: number, maximum: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < minimum || value > maximum) throw new Error(code);
  return value;
}

function origin(value: string, code: string): string {
  let parsed: URL;
  try { parsed = new URL(value); } catch { throw new Error(code); }
  if (!['http:', 'https:'].includes(parsed.protocol) || parsed.username || parsed.password
    || parsed.pathname !== '/' || parsed.search || parsed.hash) throw new Error(code);
  return parsed.origin;
}

function profile(raw: unknown): { name: string; settings: JsonObject } {
  const value = object(raw, 'BROWSER_LIGHTHOUSE_PROFILE_INVALID');
  if (typeof value.name !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/u.test(value.name)) {
    throw new Error('BROWSER_LIGHTHOUSE_PROFILE_INVALID');
  }
  if (!['mobile', 'desktop'].includes(String(value.formFactor))) throw new Error('BROWSER_LIGHTHOUSE_PROFILE_INVALID');
  const screen = object(value.screen, 'BROWSER_LIGHTHOUSE_PROFILE_INVALID');
  const throttling = object(value.throttling, 'BROWSER_LIGHTHOUSE_PROFILE_INVALID');
  const width = integer(screen.width, 'BROWSER_LIGHTHOUSE_PROFILE_INVALID', 240, 3840);
  const height = integer(screen.height, 'BROWSER_LIGHTHOUSE_PROFILE_INVALID', 240, 2160);
  const deviceScaleFactor = finite(screen.deviceScaleFactor, 'BROWSER_LIGHTHOUSE_PROFILE_INVALID', 0.5, 4);
  const mobile = screen.mobile;
  if (typeof mobile !== 'boolean') throw new Error('BROWSER_LIGHTHOUSE_PROFILE_INVALID');
  return { name: value.name, settings: {
    formFactor: value.formFactor,
    screenEmulation: { width, height, deviceScaleFactor, mobile, disabled: false },
    throttlingMethod: 'simulate',
    throttling: {
      rttMs: finite(throttling.rttMs, 'BROWSER_LIGHTHOUSE_PROFILE_INVALID', 0, 5000),
      throughputKbps: finite(throttling.throughputKbps, 'BROWSER_LIGHTHOUSE_PROFILE_INVALID', 1, 1_000_000),
      cpuSlowdownMultiplier: finite(throttling.cpuSlowdownMultiplier, 'BROWSER_LIGHTHOUSE_PROFILE_INVALID', 1, 32),
      requestLatencyMs: 0,
      downloadThroughputKbps: 0,
      uploadThroughputKbps: 0,
    },
  } };
}

async function exactOriginProxy(targetOrigin: string): Promise<{
  readonly port: number;
  readonly denied: Set<string>;
  close(): Promise<void>;
}> {
  const target = new URL(targetOrigin); const denied = new Set<string>();
  const connectAuthority = lighthouseConnectAuthority(target);
  const server = http.createServer((request, response) => {
    let destination: URL;
    try { destination = new URL(request.url ?? '/', targetOrigin); } catch {
      response.writeHead(400).end(); return;
    }
    if (destination.origin !== targetOrigin) {
      denied.add(destination.href); response.writeHead(403).end(); return;
    }
    const transport = destination.protocol === 'https:' ? https : http;
    const upstream = transport.request(destination, {
      method: request.method,
      headers: Object.fromEntries(Object.entries(request.headers).filter(([name]) => name.toLowerCase() !== 'proxy-connection')),
    }, (upstreamResponse) => {
      response.writeHead(upstreamResponse.statusCode ?? 502, upstreamResponse.headers);
      upstreamResponse.pipe(response);
    });
    upstream.on('error', () => { if (!response.headersSent) response.writeHead(502); response.end(); });
    request.pipe(upstream);
  });
  server.on('connect', (request, socket, head) => {
    if (request.url !== connectAuthority) {
      denied.add(`connect://${request.url}`); socket.write('HTTP/1.1 403 Forbidden\r\n\r\n'); socket.destroy(); return;
    }
    const upstream = net.connect(Number(target.port || 443), target.hostname, () => {
      socket.write('HTTP/1.1 200 Connection Established\r\n\r\n');
      if (head.length) upstream.write(head); socket.pipe(upstream); upstream.pipe(socket);
    });
    upstream.on('error', () => socket.destroy());
  });
  server.on('upgrade', (request, socket) => {
    denied.add(request.url ?? '<websocket>'); socket.destroy();
  });
  await new Promise<void>((resolve, reject) => {
    server.once('error', reject); server.listen(0, '127.0.0.1', resolve);
  });
  const address = server.address();
  if (!address || typeof address === 'string') throw new Error('BROWSER_LIGHTHOUSE_PROXY_FAILED');
  return { port: address.port, denied, close: () => new Promise<void>((resolve) => server.close(() => resolve())) };
}

export function lighthouseConnectAuthority(target: URL): string {
  const defaultPort = target.protocol === 'https:' ? '443' : '80';
  return `${target.hostname}:${target.port || defaultPort}`;
}

async function withTimeout<T>(promise: Promise<T>, milliseconds: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([promise, new Promise<never>((_resolve, reject) => {
      timer = setTimeout(() => reject(new Error('BROWSER_LIGHTHOUSE_TIMEOUT_EXCEEDED')), milliseconds);
    })]);
  } finally { if (timer !== undefined) clearTimeout(timer); }
}

function assertAuditedOrigin(log: unknown, targetOrigin: string): void {
  if (!Array.isArray(log) || log.length === 0) throw new Error('BROWSER_LIGHTHOUSE_NETWORK_EVIDENCE_MISSING');
  let observedTarget = false;
  for (const raw of log) {
    const event = object(raw, 'BROWSER_LIGHTHOUSE_NETWORK_EVIDENCE_INVALID');
    if (event.method === 'Network.webSocketCreated' || event.method === 'Network.webTransportCreated') {
      throw new Error('BROWSER_LIGHTHOUSE_SUBRESOURCE_ORIGIN_DENIED');
    }
    if (event.method !== 'Network.requestWillBeSent') continue;
    const params = object(event.params, 'BROWSER_LIGHTHOUSE_NETWORK_EVIDENCE_INVALID');
    const request = object(params.request, 'BROWSER_LIGHTHOUSE_NETWORK_EVIDENCE_INVALID');
    if (typeof request.url !== 'string') throw new Error('BROWSER_LIGHTHOUSE_NETWORK_EVIDENCE_INVALID');
    const destination = new URL(request.url);
    if (!['http:', 'https:'].includes(destination.protocol)) continue;
    if (destination.origin !== targetOrigin) throw new Error(`BROWSER_LIGHTHOUSE_SUBRESOURCE_ORIGIN_DENIED:${destination.origin}`);
    observedTarget = true;
  }
  if (!observedTarget) throw new Error('BROWSER_LIGHTHOUSE_NETWORK_EVIDENCE_MISSING');
}

export class BrowserLighthouseCapabilityInvoker implements TestProviderCapabilityInvoker {
  readonly #options: BrowserLighthouseCapabilityInvokerOptions;
  readonly #origins: ReadonlySet<string>;

  constructor(options: BrowserLighthouseCapabilityInvokerOptions) {
    this.#options = options;
    this.#origins = new Set(options.allowedOrigins.map((value) => origin(value, 'BROWSER_LIGHTHOUSE_ORIGIN_INVALID')));
    if (!fs.existsSync(options.chromeExecutable) || !pathIsExecutable(options.chromeExecutable)) {
      throw new Error('BROWSER_LIGHTHOUSE_EXECUTABLE_INVALID');
    }
    integer(options.maximumRuns, 'BROWSER_LIGHTHOUSE_RUN_LIMIT_INVALID', 1, 256);
    integer(options.maximumExecutionMs, 'BROWSER_LIGHTHOUSE_TIMEOUT_INVALID', 1000, 3_600_000);
    integer(options.maximumResultBytes, 'BROWSER_LIGHTHOUSE_RESULT_LIMIT_INVALID', 1024, 256 * 1024 * 1024);
  }

  async invoke(capability: string, request: TestProviderCapabilityRequest, signal: AbortSignal,
    inputs: readonly ResolvedInputV1[] = []): Promise<Readonly<Record<string, unknown>>> {
    signal = fixtureAuthoritySignal(inputs, signal);
    if (capability !== 'browser.lighthouse' || request.operation !== 'audit') throw new Error('BROWSER_LIGHTHOUSE_OPERATION_DENIED');
    if (request.resource.type !== 'network.url') throw new Error('BROWSER_LIGHTHOUSE_RESOURCE_INVALID');
    const target = new URL(request.resource.canonicalId); const allowed = new Set([...this.#origins, ...fixtureOrigins(inputs)]);
    if (!allowed.has(target.origin) || target.username || target.password) throw new Error('BROWSER_LIGHTHOUSE_ORIGIN_DENIED');
    const payload = object(request.payload, 'BROWSER_LIGHTHOUSE_REQUEST_INVALID');
    if (!Array.isArray(payload.runs) || payload.runs.length === 0 || payload.runs.length > this.#options.maximumRuns) {
      throw new Error('BROWSER_LIGHTHOUSE_RUN_LIMIT_EXCEEDED');
    }
    const timeoutMs = integer(payload.timeoutMs, 'BROWSER_LIGHTHOUSE_TIMEOUT_INVALID', 1000, this.#options.maximumExecutionMs);
    const runs = payload.runs.map((raw) => {
      const run = object(raw, 'BROWSER_LIGHTHOUSE_RUN_INVALID');
      if (typeof run.route !== 'string' || !run.route.startsWith('/') || run.route.startsWith('//')
        || /[?#\r\n]/u.test(run.route)) throw new Error('BROWSER_LIGHTHOUSE_ROUTE_INVALID');
      if (!['performance', 'seo', 'best-practices'].includes(String(run.purpose))) throw new Error('BROWSER_LIGHTHOUSE_PURPOSE_INVALID');
      return { route: run.route, purpose: run.purpose as Purpose, profile: profile(run.profile) };
    });
    const proxy = await exactOriginProxy(target.origin); let chrome: Launcher | undefined;
    const profileDirectory = fs.mkdtempSync(path.join(os.tmpdir(), 'kubeclaw-lighthouse-'));
    const abort = () => { try { chrome?.kill(); } catch { /* Best-effort abort cleanup. */ } };
    signal.addEventListener('abort', abort, { once: true });
    try {
      chrome = new Launcher({ userDataDir: profileDirectory, chromePath: this.#options.chromeExecutable, chromeFlags: [
        '--headless=new', '--disable-gpu', '--disable-dev-shm-usage',
        '--force-webrtc-ip-handling-policy=disable_non_proxied_udp',
        `--proxy-server=http://127.0.0.1:${proxy.port}`, '--proxy-bypass-list=<-loopback>',
        ...(process.getuid?.() === 0 ? ['--no-sandbox'] : []),
      ] });
      try { await chrome.launch(); }
      catch (error) {
        const log = path.join(profileDirectory, 'chrome-err.log');
        let diagnostic = '';
        if (fs.existsSync(log)) {
          const descriptor = fs.openSync(log, 'r');
          try { const bytes = Buffer.alloc(16384); diagnostic = bytes.subarray(0, fs.readSync(descriptor, bytes, 0, bytes.length, 0)).toString('utf8'); }
          finally { fs.closeSync(descriptor); }
        }
        throw new Error(`BROWSER_LIGHTHOUSE_LAUNCH_FAILED:${error instanceof Error ? error.message : String(error)}:${diagnostic}`);
      }
      const port = chrome.port;
      if (typeof port !== 'number' || !Number.isInteger(port) || port < 1) throw new Error('BROWSER_LIGHTHOUSE_DEBUG_PORT_INVALID');
      const results = [];
      for (const run of runs) {
        if (signal.aborted) throw new Error('BROWSER_LIGHTHOUSE_CANCELLED');
        const url = new URL(run.route, `${target.origin}/`);
        const startedAt = Date.now();
        const output = await withTimeout(lighthouse(url.href, {
          port, output: 'json', logLevel: 'silent', onlyCategories: [run.purpose],
        }, { extends: 'lighthouse:default', settings: run.profile.settings }), timeoutMs);
        if (!output) throw new Error('BROWSER_LIGHTHOUSE_RESULT_INVALID');
        // The proxy denies every other origin, including Chrome's background
        // services. Gate the audited page using its actual CDP network evidence;
        // an unrelated browser service must not be reported as a page defect.
        assertAuditedOrigin(output.artifacts.DevtoolsLog, target.origin);
        results.push({ route: run.route, purpose: run.purpose, profile: run.profile.name,
          durationMs: Date.now() - startedAt, report: output.lhr });
      }
      const response = { schemaVersion: 'browser-lighthouse-result.v1', results,
        blockedProxyOrigins: [...new Set([...proxy.denied].slice(0, 32).map(value => {
          const url = new URL(value, target.origin); return url.origin === 'null' ? `${url.protocol}//${url.host}` : url.origin;
        }))].sort() };
      if (Buffer.byteLength(JSON.stringify(response)) > this.#options.maximumResultBytes) {
        throw new Error('BROWSER_LIGHTHOUSE_RESULT_BYTES_EXCEEDED');
      }
      return response;
    } finally {
      signal.removeEventListener('abort', abort);
      try { chrome?.kill(); } catch { /* Best-effort final cleanup. */ }
      await proxy.close();
      fs.rmSync(profileDirectory, { recursive: true, force: true });
    }
  }
}

function pathIsExecutable(file: string): boolean {
  try { fs.accessSync(file, fs.constants.X_OK); return true; } catch { return false; }
}

skills/buster/plugins/security-providers.syntax:
export function object(value, code) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(code);
  return value;
}

export function integer(value, fallback, minimum, maximum, code) {
  const result = value ?? fallback;
  if (!Number.isSafeInteger(result) || result < minimum || result > maximum) throw new Error(code);
  return result;
}

function acceptances(value) {
  const list = value ?? [];
  if (!Array.isArray(list) || list.length > 128) throw new Error('SECURITY_POLICY_ACCEPTANCES_INVALID');
  const seen = new Set();
  return list.map((entry) => {
    const item = object(entry, 'SECURITY_POLICY_ACCEPTANCES_INVALID');
    if (typeof item.findingId !== 'string' || item.findingId.length < 1 || item.findingId.length > 256
      || !/^[A-Za-z0-9._:@/-]+$/u.test(item.findingId) || seen.has(item.findingId)
      || typeof item.reason !== 'string' || item.reason.trim().length < 8 || item.reason.length > 1024
      || typeof item.expiresAt !== 'string' || !Number.isFinite(Date.parse(item.expiresAt))) {
      throw new Error('SECURITY_POLICY_ACCEPTANCES_INVALID');
    }
    seen.add(item.findingId);
    return { findingId: item.findingId, reason: item.reason.trim(), expiresAt: new Date(item.expiresAt).toISOString() };
  });
}

export function policy(value) {
  const item = object(value, 'SECURITY_POLICY_INVALID');
  if (item.profile !== POLICY.profile || Object.keys(item).some((key) => !['profile', 'acceptances'].includes(key))) {
    throw new Error('SECURITY_POLICY_INVALID');
  }
  return { ...POLICY, acceptances: acceptances(item.acceptances) };
}

export function details(schemaId, values) {
  return { schemaId, schemaDigest: `sha256:${crypto.createHash('sha256').update(schemaId).digest('hex')}`, values };
}

export function result(invocation, scanner, rawFindings, resolvedPolicy, detailValues = {}) {
  if (!Array.isArray(rawFindings) || rawFindings.length > 4096) throw new Error('SECURITY_SCANNER_RESPONSE_INVALID');
  const accepted = new Map(resolvedPolicy.acceptances.map((item) => [item.findingId, item]));
  const now = Date.now();
  const findings = [];
  const normalizedFindings = [];
  const acceptedFindings = [];
  const blocking = [];
  const ids = new Set();
  for (const raw of rawFindings) {
    const finding = object(raw, 'SECURITY_SCANNER_RESPONSE_INVALID');
    if (typeof finding.id !== 'string' || finding.id.length < 1 || finding.id.length > 256 || ids.has(finding.id)
      || !SEVERITIES.includes(finding.severity) || typeof finding.message !== 'string'
      || finding.message.length < 1 || finding.message.length > 4096) {
      throw new Error('SECURITY_SCANNER_RESPONSE_INVALID');
    }
    ids.add(finding.id);
    const waiver = accepted.get(finding.id);
    const isAccepted = Boolean(waiver && Date.parse(waiver.expiresAt) > now);
    const isBlocking = resolvedPolicy.blockingSeverities.includes(finding.severity)
      || (resolvedPolicy.blockActiveThreats && finding.status === 'affected')
      || (resolvedPolicy.blockMissingFixes && finding.category === 'vulnerability' && !finding.fixedVersion);
    findings.push({ id: finding.id, severity: finding.severity, message: finding.message,
      ...(typeof finding.rule === 'string' ? { rule: finding.rule } : {}),
      ...(typeof finding.file === 'string' ? { file: finding.file } : {}),
      ...(Number.isSafeInteger(finding.line) ? { line: finding.line } : {}) });
    normalizedFindings.push({ id: finding.id, severity: finding.severity, message: finding.message,
      ...(typeof finding.category === 'string' ? { category: finding.category.slice(0, 128) } : {}),
      ...(typeof finding.package === 'string' ? { package: finding.package.slice(0, 512) } : {}),
      ...(typeof finding.installedVersion === 'string' ? { installedVersion: finding.installedVersion.slice(0, 512) } : {}),
      ...(typeof finding.fixedVersion === 'string' ? { fixedVersion: finding.fixedVersion.slice(0, 512) } : {}),
      ...(typeof finding.file === 'string' ? { sourceFile: finding.file } : {}),
      ...(finding.reachability === null || typeof finding.reachability === 'string'
        ? { reachability: finding.reachability === null ? null : finding.reachability.slice(0, 512) } : {}),
      ...(typeof finding.status === 'string' ? { status: finding.status.slice(0, 128) } : {}) });
    if (isAccepted) acceptedFindings.push({ findingId: finding.id, reason: waiver.reason, expiresAt: waiver.expiresAt });
    else if (isBlocking) blocking.push(finding.id);
  }
  const expiredAcceptances = resolvedPolicy.acceptances.filter((item) => Date.parse(item.expiresAt) <= now);
  const unusedAcceptances = resolvedPolicy.acceptances.filter((item) => !ids.has(item.findingId));
  const total = Math.max(1, findings.length);
  const failed = blocking.length;
  return { schemaVersion: 'provider-result.v1', outcome: failed > 0 ? 'failed' : 'passed',
    summary: failed > 0 ? `${failed} blocking security finding${failed === 1 ? '' : 's'} remain.`
      : findings.length > 0 ? `${findings.length} visible security finding${findings.length === 1 ? '' : 's'} do not block.`
        : 'No security finding was reported.',
    counts: { total, passed: total - failed, failed, skipped: 0 }, findings, metrics: [
      { name: 'security_findings', value: findings.length }, { name: 'security_blocking_findings', value: failed },
      { name: 'security_accepted_findings', value: acceptedFindings.length }],
    evidenceFiles: [], reports: [], outputs: [], exitCode: null, signal: null,
    providerDetails: details(`kubeclaw.${scanner}-security-details.v1`, { scanner, policy: resolvedPolicy,
      blockingFindingIds: blocking, acceptedFindings, expiredAcceptances, unusedAcceptances,
      normalizedFindings, ...detailValues }) };
}

export function safePart(value) {
  const normalized = String(value ?? 'unknown').replace(/[^A-Za-z0-9._:@/-]+/gu, '-');
  if (normalized.length <= 120) return normalized;
  return `${normalized.slice(0, 48)}:sha256:${crypto.createHash('sha256').update(normalized).digest('hex')}`;
}

export function findingId(...parts) {
  const full = parts.map(safePart).join(':');
  if (full.length <= 256) return full;
  return `${full.slice(0, 184)}:sha256:${crypto.createHash('sha256').update(full).digest('hex')}`;
}

