scripts/check-configuration-cli-drift.mj.syntax:
const check = spawnSync(process.execPath, ['scripts/docs-configuration-inventory.mjs', '--check'], {
  cwd: root,
  encoding: 'utf8',
});

if (check.status !== 0) {
  console.error('DOC_DRIFT_CLI: CLI and script-flag documentation inventory is stale.');
  process.stdout.write(check.stdout);
  process.stderr.write(check.stderr);
  process.exit(check.status ?? 1);
}

for (const flag of inventory.cliFlags) {
  assert.match(flag.name, /^(?:--[a-z][a-z0-9-]*|-[A-Za-z])$/, `invalid flag name: ${flag.name}`);
  assert.ok(['scripts/', 'my-values/', 'charts/', 'gitops/', 'skills/', 'docker/', 'ops/', 'tools/', 'cmd/', 'packaging/'].some((prefix) => flag.path.startsWith(prefix)), `flag is outside the registered runtime boundary: ${flag.path}`);
  assert.ok(Number.isInteger(flag.line) && flag.line > 0, `flag has no source line: ${flag.name}`);
  const identity = `${flag.path}:${flag.line}:${flag.name}`;
  assert.equal(identities.has(identity), false, `duplicate flag fact: ${identity}`);
  identities.add(identity);
  assert.equal(flag.classification, 'definition', `${identity}: external-command invocation leaked into the owned CLI inventory`);
  assert.ok(['operator-runtime', 'maintainer-verification', 'internal-or-invocation', 'documentation-internal'].includes(flag.surface), `${identity}: flag lacks surface taxonomy`);
  assert.ok(flag.valueTaking === null || typeof flag.valueTaking === 'boolean', `${identity}: flag has invalid value-taking semantics`);
  assert.ok(flag.ownerComponent && flag.runtimeOwner && flag.consumers.length > 0, `${identity}: flag lacks owner or consumer`);
  assert.ok(flag.precedence.length > 0 && flag.changeImpact && flag.failureMeaning, `${identity}: flag lacks operational semantics`);
  assert.ok(flag.unknownOptionBehavior && flag.duplicateOptionBehavior, `${identity}: flag lacks parser-specific unknown/duplicate semantics`);
  assert.ok(['authored-documentation', 'missing-authored-documentation', 'not-required-in-operator-handbook', 'not-applicable-invocation'].includes(flag.documentationStatus), `${identity}: flag lacks documentation status`);
}

const expectedValueSemantics = [
  ['skills/nova/project_setup/tools/progress-scaffold.ts', '--apply', false],
];

for (const [sourcePath, name, expected] of expectedValueSemantics) {
  const fact = inventory.cliFlags.find((item) => item.path === sourcePath && item.name === name);
  assert.ok(fact, `${sourcePath}:${name}: representative CLI fact is missing`);
  assert.equal(fact.valueTaking, expected, `${sourcePath}:${name}: value-taking semantics drifted`);
}

for (const [sourcePath, name, valueTaking, required, defaultValue] of expectedStructuredDefinitions) {
  const fact = inventory.cliFlags.find((item) => item.path === sourcePath && item.name === name);
  assert.ok(fact, `${sourcePath}:${name}: structured parser definition is missing`);
  assert.equal(fact.classification, 'definition', `${sourcePath}:${name}: structured parser was mistaken for an invocation`);
  assert.equal(fact.valueTaking, valueTaking, `${sourcePath}:${name}: structured arity drifted`);
  assert.equal(fact.required, required, `${sourcePath}:${name}: required semantics drifted`);
  assert.equal(fact.default, defaultValue, `${sourcePath}:${name}: default semantics drifted`);
}

for (const sourcePath of ['skills/nova/core/cli.ts', 'skills/nova/core/test-gates/remote-gate-cli.ts']) {
  const facts = definitions.filter((item) => item.path === sourcePath);
  assert.ok(facts.length > 0, `${sourcePath}: dynamic paired parser definitions are missing`);
  assert.ok(facts.every((item) => /accepted and ignored/u.test(item.unknownOptionBehavior)), `${sourcePath}: arbitrary paired options were falsely described as rejected`);
  assert.ok(facts.every((item) => /last value/u.test(item.duplicateOptionBehavior)), `${sourcePath}: last-duplicate-wins behavior is missing`);
  assert.ok(facts.every((item) => !/^Unknown, missing-value/u.test(item.failureMeaning)), `${sourcePath}: generic unknown-option failure claim remains`);
}

for (const name of ['--import-legacy', '--authoring', '--platform', '--output']) {
  const fact = definitions.find((item) => item.path === 'skills/nova/project/legacy-import-cli.ts' && item.name === name);
  assert.match(fact?.requiredReason ?? '', /Object\.keys\(args\)\.length !== 4/u, `${name}: legacy import requiredness is not tied to the four-key rejection`);
}

for (const [sourcePath, name] of [
  ['scripts/deploy.sh', '--namespace'],
  ['charts/prism/templates/postgresql.yaml', '--set'],
  ['scripts/pipeline-light-openclaw-notify.sh', '--account'],
  ['scripts/pipeline-light-openclaw-notify.sh', '--agent'],
  ['scripts/pipeline-light-openclaw-notify.sh', '--channel'],
  ['scripts/pipeline-light-openclaw-notify.sh', '--json'],
  ['docker/buster-runtime-entrypoint.sh', '--addr'],
]) {
  const fact = inventory.cliFlags.find((item) => item.path === sourcePath && item.name === name);
  assert.equal(fact, undefined, `${sourcePath}:${name}: external-command flag was mistaken for an owned KubeClaw definition`);
}

for (const item of inventory.derivedValues) {
  assert.ok(['analyzed', 'unsupported'].includes(item.analysisStatus), `${item.path}:${item.line}:${item.name}: derived value lacks analysis status`);
  if (item.analysisStatus === 'unsupported') {
    assert.equal(item.formula, '<unsupported shell syntax; inspect source>', `${item.path}:${item.line}:${item.name}: unsupported syntax published an inferred formula`);
    assert.ok(item.unsupportedReason, `${item.path}:${item.line}:${item.name}: unsupported syntax lacks its reason`);
  }
}

for (const assignment of namespaceAssignments) {
  assert.ok(assignment.consumers.some((item) => item.kind === 'shell-global-conditional-return-edge'),
    `NAMESPACE:${assignment.line}: assignment lacks its conditional function-return edge`);
  assert.ok(assignment.consumers.some((item) => item.kind === 'shell-global-conditional-post-call-use'),
    `NAMESPACE:${assignment.line}: assignment lacks an actual post-call use`);
  assert.equal(assignment.consumers.some((item) => item.kind === 'shell-global-derived-value-use'), false,
    `NAMESPACE:${assignment.line}: legacy whole-file flow overclaim remains`);
  assert.ok(assignment.consumers.length <= 10,
    `NAMESPACE:${assignment.line}: conditional flow fan-out is implausibly broad (${assignment.consumers.length})`);
}

for (const internal of inventory.cliFlags.filter((flag) => flag.surface === 'documentation-internal')) {
  assert.equal(publishedFlagRows.includes(`${internal.path}:`), false, `${internal.path}:${internal.name}: internal CLI definition was published`);
}

scripts/check-configuration-drift-mutati.syntax:
function copy(relativePath) {
  const source = path.join(repositoryRoot, relativePath);
  if (fs.existsSync(source)) fs.cpSync(source, path.join(temporaryRoot, relativePath), { recursive: true });
}

function runGenerator(...args) {
  return spawnSync(process.execPath, [generator, '--root', temporaryRoot, '--out-dir', outputDirectory, ...args], {
    cwd: repositoryRoot,
    encoding: 'utf8',
  });
}

function runPublisher(...args) {
  return spawnSync(process.execPath, [publisher, '--root', temporaryRoot, '--revision', sourceRevision, '--allow-detached-source-root', ...args], {
    cwd: repositoryRoot,
    encoding: 'utf8',
    env: { ...process.env, KUBECLAW_DOCS_ISOLATED_MUTATION: '1' },
  });
}

function published(relativePath) {
  return fs.readFileSync(path.join(temporaryRoot, relativePath), 'utf8');
}

function append(relativePath, text) {
  const target = path.join(temporaryRoot, relativePath);
  const original = fs.readFileSync(target, 'utf8');
  fs.writeFileSync(target, `${original.replace(/\s*$/, '')}\n${text}\n`);
  return () => fs.writeFileSync(target, original);
}

function createFile(relativePath, text) {
  const target = path.join(temporaryRoot, relativePath);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  assert.equal(fs.existsSync(target), false, `${relativePath}: mutation target already exists`);
  fs.writeFileSync(target, `${text.replace(/\s*$/u, '')}\n`);
  return () => fs.rmSync(target, { force: true });
}

function replaceOnce(relativePath, before, after) {
  const target = path.join(temporaryRoot, relativePath);
  const original = fs.readFileSync(target, 'utf8');
  assert.ok(original.includes(before), `${relativePath}: mutation source text is missing: ${before}`);
  fs.writeFileSync(target, original.replace(before, after));
  return () => fs.writeFileSync(target, original);
}

function combineMutations(...mutations) {
  const restores = mutations.map((mutation) => mutation());
  return () => restores.reverse().forEach((restore) => restore());
}

function mutateJson(relativePath, edit) {
  const target = path.join(temporaryRoot, relativePath);
  const original = fs.readFileSync(target, 'utf8');
  const value = JSON.parse(original);
  edit(value);
  fs.writeFileSync(target, `${JSON.stringify(value, null, 2)}\n`);
  return () => fs.writeFileSync(target, original);
}

function mutateSchemaRule(relativePath, edit, selectRule, example, expectedBefore, expectedAfter) {
  const ajv = new Ajv2020({ strict: false }); addFormats(ajv);
  const original = JSON.parse(fs.readFileSync(path.join(temporaryRoot, relativePath), 'utf8'));
  assert.equal(ajv.compile(selectRule(original))(example), expectedBefore, `${relativePath}: semantic mutation starting condition differs`);
  const restore = mutateJson(relativePath, edit);
  try {
    const changed = JSON.parse(fs.readFileSync(path.join(temporaryRoot, relativePath), 'utf8'));
    assert.equal(ajv.compile(selectRule(changed))(example), expectedAfter, `${relativePath}: mutation did not change the declared validation behavior`);
  } catch (error) { restore(); throw error; }
  return restore;
}

function mutateLineToken(relativePath, lineNumber, token) {
  const target = path.join(temporaryRoot, relativePath);
  const original = fs.readFileSync(target, 'utf8');
  const lines = original.split('\n');
  assert.ok(lines[lineNumber - 1]?.includes(token), `${relativePath}:${lineNumber}: mutation token is missing`);
  const pivot = Math.max(0, token.search(/[A-Za-z0-9](?![\s\S]*[A-Za-z0-9])/u));
  const replacement = token[pivot] === 'X' ? 'Y' : 'X';
  const changed = `${token.slice(0, pivot)}${replacement}${token.slice(pivot + 1)}`;
  lines[lineNumber - 1] = lines[lineNumber - 1].replace(token, changed);
  fs.writeFileSync(target, lines.join('\n'));
  return () => fs.writeFileSync(target, original);
}

function mutateFileByte(relativePath) {
  const target = path.join(temporaryRoot, relativePath);
  const original = fs.readFileSync(target);
  const changed = Buffer.from(original);
  assert(changed.length > 0, `${relativePath}: cannot mutate an empty authority file`);
  changed[Math.floor(changed.length / 2)] ^= 1;
  fs.writeFileSync(target, changed);
  return () => fs.writeFileSync(target, original);
}

function expectDetected(name, mutate, verifyPublication = null) {
  const restore = mutate();
  try {
    const result = name.startsWith('payload-edge:')
      ? runGenerator('--check-payload-delivery-only')
      : name.startsWith('environment-consumer:') ? runGenerator('--check-environment-coverage-only')
      : name.startsWith('schema-validation-rule:') ? runGenerator('--schemas-only', '--check') : runGenerator('--check');
    assert.notEqual(result.status, 0, `${name}: stale inventory was not detected`);
    const diagnostic = `${result.stdout}\n${result.stderr}`;
    assert.match(diagnostic, /(?:Configuration documentation inventory is stale|CONFIG_SEMANTIC_GAP|CONFIG_SCHEMA_UNSUPPORTED_(?:KEYWORD|REFERENCE)|CONFIG_YAML_AUTHORITY_DRIFT|CONFIG_YAML_(?:DOTTED_KEY|PATH_COLLISION|SEMANTIC_AUTHORITY|SEMANTIC_CONTRACT)|CONFIG_YAML_API_CONTRACT_GAP|CONFIG_YAML_LEAF_LINE_DRIFT|CONFIG_YAML_API_LEAF_(?:LINE|DIGEST)_DRIFT|CONFIG_PAYLOAD_(?:REQUEST_PATH|SWARM_READER)_BOUNDARY_CHANGED|schema logical regression|offline external Helm authority verification failed|external Helm authority lock bytes|external Helm extracted authority bytes|authority source bytes changed|indirect semantic contract|cannot extract vendored CRD authority|exact consumer line changed|consumer context changed|downstream receiver changed|consumer proof is not bound to this exact leaf|selected-value proof does not bind the exact source field|compressed bytes changed|manifest bytes changed|deployed config payload .* is missing|deployed config payload discovery differs|expected .* containing|mutation token is missing)/u, `${name}: failure did not identify inventory drift or a semantic authority gap`);
    const semanticRejected = /CONFIG_SEMANTIC_GAP|CONFIG_YAML_AUTHORITY_DRIFT|authority source bytes changed/u.test(diagnostic);
    if (name.startsWith('environment-consumer:')) assert.match(diagnostic, /CONFIG_SEMANTIC_GAP:.*(?:PRISM_CONTROL_URL|AP98_NEW_RUNTIME_VALUE|REDIS_HOST):(?:skills|charts)\//u, `${name}: exact missing pair was not reported`);
    if (name === 'environment-setting:add') {
      assert.match(diagnostic, /AP98_MUTATION_ENV/u, `${name}: diagnostic did not identify the new operator environment input`);
      assert.match(diagnostic, /purpose, accepted form, default and empty behavior, precedence, impact, and failure symptom/u, `${name}: diagnostic did not require the complete environment contract`);
    }
    if (name === 'secret-setting:add' || name === 'shell-secret-source:add') {
      assert.match(diagnostic, /ap98-mutation/u, `${name}: diagnostic did not identify the new Secret authority`);
      assert.match(diagnostic, /purpose, namespace, keys, optionality, producer, consumer, rotation owner and method, and failure symptom/u, `${name}: diagnostic did not require the complete Secret contract`);
    }
    if (['helm-secret-key-reference:add', 'helm-secret-volume:add', 'helm-secret-declaration:add', 'helm-secret-envfrom:add',
      'yaml-secret-declaration:add', 'yaml-secret-envfrom:add', 'yaml-secret-reference:add', 'yaml-image-pull-secret:add'].includes(name)) {
      if (/CONFIG_YAML_API_CONTRACT_GAP/u.test(diagnostic)) {
        assert.match(diagnostic, name === 'yaml-image-pull-secret:add' ? /imagePullSecrets/u : /secret(?:Key)?Ref/u,
          `${name}: API-contract diagnostic did not identify the new Secret field`);
      } else {
        assert.match(diagnostic, /ap98-(?:secret|helm|yaml)[a-z-]*/u, `${name}: diagnostic did not identify the new Secret declaration or binding`);
      }
      if (name.startsWith('helm-')) {
        assert.match(diagnostic, /purpose, namespace, keys, optionality, producer, consumer, rotation owner and method, and failure symptom/u,
          `${name}: diagnostic did not require the complete Helm Secret authority`);
      } else {
        assert.match(diagnostic, /(?:CONFIG_YAML_API_CONTRACT_GAP|exact source path \+ full field path|purpose, namespace, keys, optionality)/u,
          `${name}: diagnostic did not reject the new YAML Secret surface at an authority gate`);
      }
    }
    if (name === 'nova-cli-flag:add' || name === 'short-cli-alias:add') {
      const regenerate = runGenerator('--allow-semantic-gaps');
      assert.equal(regenerate.status, 0, `${name}: mutated inventory generation failed\n${regenerate.stdout}\n${regenerate.stderr}`);
      const cliGate = spawnSync(process.execPath, ['scripts/check-configuration-cli-drift.mjs'], { cwd: temporaryRoot, encoding: 'utf8' });
      assert.notEqual(cliGate.status, 0, `${name}: undocumented public CLI flag passed the CLI documentation gate`);
      assert.match(`${cliGate.stdout}\n${cliGate.stderr}`, /operator-runtime definitions lack authored documentation/u, `${name}: CLI gate did not name the missing authored authority`);
      console.log(`PASS ${name}: public CLI option rejected until authored documentation exists`);
    } else if (semanticRejected) {
      console.log(`PASS ${name}: public option rejected until qualified semantic authority exists`);
    } else if (verifyPublication) {
      const regenerate = runGenerator('--allow-semantic-gaps');
      assert.equal(regenerate.status, 0, `${name}: mutated inventory generation failed\n${regenerate.stdout}\n${regenerate.stderr}`);
      const publish = runPublisher();
      assert.equal(publish.status, 0, `${name}: mutated reference publication failed\n${publish.stdout}\n${publish.stderr}`);
      verifyPublication();
      console.log(`PASS ${name}: source -> inventory -> published semantics`);
    }
  } finally {
    restore();
    if (verifyPublication) {
      const recover = runGenerator('--allow-semantic-gaps');
      assert.equal(recover.status, 0, `${name}: baseline inventory recovery failed\n${recover.stdout}\n${recover.stderr}`);
    }
  }
  console.log(`PASS ${name}`);
}

function expectLocalHelmMaintenanceDetected(name, mutate, expectedDiagnostic) {
  const restore = mutate();
  try {
    const result = spawnSync(process.execPath, ['scripts/generate-local-helm-authorities.mjs', '--check'], {
      cwd: temporaryRoot,
      encoding: 'utf8',
    });
    assert.notEqual(result.status, 0, `${name}: local Helm semantic maintenance accepted the mutation`);
    assert.match(`${result.stdout}\n${result.stderr}`, expectedDiagnostic,
      `${name}: local Helm semantic maintenance did not explain the rejected mutation`);
  } finally {
    restore();
  }
  console.log(`PASS ${name}`);
}

try {
  ['charts', 'examples', 'gitops', 'my-values', 'releases', 'scripts', 'skills', 'contracts/agent-observability/v1/src', 'docker', 'ops', 'tools', 'cmd', 'packaging', 'versions.json', 'docs/generated/inventory', 'docs/site'].forEach(copy);
  fs.symlinkSync(path.join(repositoryRoot, 'node_modules'), path.join(temporaryRoot, 'node_modules'), 'dir');
  // Recreate the ignored observer contract from canonical source in this fixture.
  // Copied host-generated output must never substitute for that authority.
  const observerContractSync = spawnSync(process.execPath, ['skills/common/plugins/openclaw-agent-observer/scripts/sync-contract.mjs'], {
    cwd: temporaryRoot,
    encoding: 'utf8',
  });
  assert.ifError(observerContractSync.error);
  assert.equal(observerContractSync.status, 0, `isolated observer contract synchronization failed\n${observerContractSync.stdout}\n${observerContractSync.stderr}`);
  const runtimeSemantics = runGenerator('--check-runtime-consumer-semantics-only');
  assert.equal(runtimeSemantics.status, 0, `runtime consumer semantic checks failed\n${runtimeSemantics.stdout}\n${runtimeSemantics.stderr}`);
  console.log(runtimeSemantics.stdout.trim());
  if (consumerCoverageOnly) {
    const baseline = runGenerator('--check-environment-coverage-only');
    assert.equal(baseline.status, 0, `consumer coverage baseline failed\n${baseline.stdout}\n${baseline.stderr}`);
    console.log(baseline.stdout.trim());
    for (const [name, mutate] of consumerCoverageCases()) expectDetected(name, mutate);
    const recovered = runGenerator('--check-environment-coverage-only');
    assert.equal(recovered.status, 0, `consumer coverage recovery failed\n${recovered.stdout}\n${recovered.stderr}`);
    console.log('PASS focused environment consumer coverage mutations and baseline recovery');
    fs.rmSync(temporaryRoot, { recursive: true, force: true }); process.exit(0);
  }
  const semanticCheck = runGenerator('--check-schema-semantics-only');
  assert.equal(semanticCheck.status, 0, `configuration semantic checks failed\n${semanticCheck.stdout}\n${semanticCheck.stderr}`);
  console.log(semanticCheck.stdout.trim());
  if (schemaSemanticsOnly) { fs.rmSync(temporaryRoot, { recursive: true, force: true }); process.exit(0); }
  if (schemaRulesOnly) {
    const initial = runGenerator('--schemas-only');
    assert.equal(initial.status, 0, `schema mutation baseline failed\n${initial.stdout}\n${initial.stderr}`);
    const before = runGenerator('--schemas-only', '--check');
    assert.equal(before.status, 0, `schema mutation baseline check failed\n${before.stdout}\n${before.stderr}`);
    for (const [name, mutate] of schemaRuleCases()) expectDetected(name, mutate);
    const recovered = runGenerator('--schemas-only', '--check');
    assert.equal(recovered.status, 0, `schema mutation baseline recovery failed\n${recovered.stdout}\n${recovered.stderr}`);
    console.log('PASS focused schema validation-rule mutations and baseline recovery');
    fs.rmSync(temporaryRoot, { recursive: true, force: true }); process.exit(0);
  }

  const generated = runGenerator('--allow-semantic-gaps');
  assert.equal(generated.status, 0, `could not generate temporary baseline\n${generated.stdout}\n${generated.stderr}`);
  const baseline = runGenerator('--check');
  assert.equal(baseline.status, 0, `temporary baseline is stale\n${baseline.stdout}\n${baseline.stderr}`);
  const baselineValues = JSON.parse(fs.readFileSync(path.join(outputDirectory, 'configuration-values.json'), 'utf8'));
  const baselineSchemaInventory = JSON.parse(fs.readFileSync(path.join(outputDirectory, 'configuration-schemas.json'), 'utf8'));
  const baselineRuntime = JSON.parse(fs.readFileSync(path.join(outputDirectory, 'configuration-runtime-inputs.json'), 'utf8'));
  const schemaFields = baselineSchemaInventory.files.flatMap((file) => file.fields);
  for (const field of schemaFields.filter((candidate) => candidate.type.includes('string')
    && candidate.constraints.some((constraint) => constraint.name === 'format'))) {
    assert.doesNotMatch(field.meaning.emptyBehavior, /accepts an empty string/iu,
      `${field.meaning.authorityKey}: formatted string incorrectly accepts an empty value`);
  }
  for (const field of schemaFields) {
    assert.doesNotMatch(field.meaning.text, /Limits the complete the /u,
      `${field.meaning.authorityKey}: generated purpose contains duplicated grammar`);
    if (field.meaning.runtimeDefault !== null && field.meaning.runtimeDefault !== undefined) {
      const declaredTypes = field.type.split('|');
      const value = field.meaning.runtimeDefault;
      const typeMatches = declaredTypes.some((type) => (type === 'any' || type === 'unspecified')
        || (type === 'integer' && Number.isInteger(value))
        || (type === 'number' && typeof value === 'number' && Number.isFinite(value))
        || (type === 'string' && typeof value === 'string')
        || (type === 'boolean' && typeof value === 'boolean')
        || (type === 'array' && Array.isArray(value))
        || (type === 'object' && value !== null && typeof value === 'object' && !Array.isArray(value)));
      assert(typeMatches,
        `${field.meaning.authorityKey}: runtime default type does not match ${field.type}`);
    }
  }
  for (const testOnlyName of ['KUBECLAW_DEMO_AUTH_TEST_OUTPUT', 'PRODUCT_TS_EXPORTER']) {
    assert.equal(baselineRuntime.environment.some((item) => item.name === testOnlyName), false,
      `${testOnlyName}: Go test-only environment input leaked into the runtime inventory`);
