    operations: ['change'],
    source: 'charts/prism/templates/networkpolicy.yaml',
    apply(_operation, source) {
      return replaceOnce(source, 'metadata: { name: prism-default-deny }\n',
        'metadata: { name: prism-default-deny-source-mutation }\n');
