      if (operation === 'change') return replaceOnce(source, "'get_pod'", "'get_pod_ap97_source_mutation'");
      return replaceOnce(source, call, '');
    },
  },
};

function replaceOnce(source, needle, replacement) {
  const first = source.indexOf(needle);
  assert(first >= 0, `mutation anchor is absent: ${JSON.stringify(needle)}`);
  assert.equal(source.indexOf(needle, first + needle.length), -1,
    `mutation anchor is not unique: ${JSON.stringify(needle)}`);
  return `${source.slice(0, first)}${replacement}${source.slice(first + needle.length)}`;
}

function registrationCall(source, toolName) {
  const nameIndex = source.indexOf(`'${toolName}'`);
  assert(nameIndex >= 0, `Ops tool mutation anchor is absent: ${toolName}`);
  const start = source.lastIndexOf('server.registerTool(', nameIndex);
  assert(start >= 0, `Ops tool registration is absent: ${toolName}`);
  let depth = 0;
  let quote;
  let escaped = false;
  for (let index = start; index < source.length; index += 1) {
    const character = source[index];
    if (quote) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === quote) quote = undefined;
      continue;
    }
    if (character === "'" || character === '"' || character === '`') quote = character;
    else if (character === '(') depth += 1;
    else if (character === ')') {
      depth -= 1;
      if (depth === 0) {
        let end = index + 1;
        while (source[end] === ';' || source[end] === '\n') end += 1;
        return source.slice(start, end).trimEnd();
      }
    }
  }
  assert.fail(`Ops tool registration is incomplete: ${toolName}`);
}

function runInventory(sourceRoot, isolatedMutation = false, args = ['--check']) {
  return spawnSync(process.execPath, [inventoryScript, ...args], {
    cwd: root,
    encoding: 'utf8',
    env: isolatedMutation ? {
      ...process.env,
      KUBECLAW_DOCS_SOURCE_ROOT: sourceRoot,
      KUBECLAW_DOCS_ISOLATED_MUTATION: '1',
    } : process.env,
    maxBuffer: 64 * 1024 * 1024,
  });
}

function workspaceFiles() {
  const listed = spawnSync('git', ['ls-files', '--cached', '--others', '--exclude-standard', '-z'], {
    cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024,
  });
  assert.equal(listed.status, 0, `could not enumerate workspace files:\n${listed.stderr}`);
  return listed.stdout.split('\0').filter(Boolean).sort();
}

function copyWorkspace() {
  for (const relative of workspaceFiles()) {
    const source = path.join(root, relative);
    if (!fs.existsSync(source)) continue;
    const target = path.join(isolatedSourceRoot, relative);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.cpSync(source, target, { dereference: false, preserveTimestamps: true });
  }
  const dependencies = path.join(root, 'node_modules');
  assert(fs.existsSync(dependencies), 'node_modules is required for the isolated rendering checks');
  fs.symlinkSync(dependencies, path.join(isolatedSourceRoot, 'node_modules'), 'dir');
}

function cleanup() {
  if (cleaned) return;
  cleaned = true;
  fs.rmSync(temporaryParent, { recursive: true, force: true });
}

for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, () => {
  cleanup();
  process.exit(128 + os.constants.signals[signal]);
});

try {
  const baseline = runInventory(root);
  assert.equal(baseline.status, 0,
    `platform inventory baseline failed:\n${baseline.stderr || baseline.stdout}`);
  const baselineInventory = JSON.parse(fs.readFileSync(
    path.join(root, 'docs/generated/inventory/platform-surfaces.json'), 'utf8'));
  assert.deepEqual(
    baselineInventory.networkExposures
      .filter(({ kind }) => kind === 'Ingress')
      .map(({ namespace, name, routeKind, host, path: routePath, backendService, backendPort }) => [`${namespace}/${name}`, routeKind, host, routePath, backendService, backendPort]),
    [
      ['argocd/argocd', 'default-backend', null, null, 'argocd-server', 80],
      ['kubeclaw/agent-nova-archviewer', 'default-backend', null, null, 'agent-nova-archviewer', 3456],
      ['kubeclaw/prism-studio', 'default-backend', null, null, 'prism-studio', 80],
    ],
    'Ingress defaultBackend extraction changed or lost a published route');
  copyWorkspace();

  // An Ingress can declare rule paths and a default backend at the same time.
  // Both routes are effective and therefore both must remain in the inventory.
  const ingressFixturePath = path.join(isolatedSourceRoot, 'my-values/infra/argocd-tailscale-ingress.yaml');
  const ingressFixtureBefore = fs.readFileSync(ingressFixturePath, 'utf8');
  const ingressFixture = replaceOnce(ingressFixtureBefore, '  defaultBackend:\n', [
    '  rules:',
    '    - host: argocd.example.test',
    '      http:',
    '        paths:',
    '          - path: /api',
    '            pathType: Prefix',
    '            backend:',
    '              service:',
    '                name: argocd-api',
    '                port:',
    '                  number: 8080',
    '  defaultBackend:',
    '',
  ].join('\n'));
  fs.writeFileSync(ingressFixturePath, ingressFixture);
  const combinedIngressResult = runInventory(isolatedSourceRoot, true, ['--print-inventory']);
  assert.equal(combinedIngressResult.status, 0,
    `could not inspect the combined Ingress fixture:\n${combinedIngressResult.stderr}`);
  const combinedIngressInventory = JSON.parse(combinedIngressResult.stdout);
  assert.deepEqual(combinedIngressInventory.networkExposures
    .filter(({ kind, namespace, name }) => kind === 'Ingress' && namespace === 'argocd' && name === 'argocd')
    .map(({ routeKind, host, path: routePath, backendService, backendPort }) => [routeKind, host, routePath, backendService, backendPort]), [
    ['rule', 'argocd.example.test', '/api', 'argocd-api', 8080],
    ['default-backend', null, null, 'argocd-server', 80],
  ], 'Ingress with rules and defaultBackend did not publish both effective routes');
  fs.writeFileSync(ingressFixturePath, ingressFixtureBefore);

  const unsafeSync = runInventory(isolatedSourceRoot, true, ['--sync-map-identities']);
  assert.notEqual(unsafeSync.status, 0, 'the unsafe bulk identity synchronization option unexpectedly succeeded');
  assert.match(`${unsafeSync.stdout}\n${unsafeSync.stderr}`, /DOC_DRIFT_MAP_REVIEW/u,
    'the rejected bulk synchronization option lacks the map-review diagnostic');
  mapReviewResults.push('bulk-sync-rejected');

  for (const [kind, mutation] of Object.entries(mutations)) {
    for (const operation of mutation.operations ?? operations) {
      const relative = typeof mutation.source === 'function' ? mutation.source(operation) : mutation.source;
      const target = path.join(isolatedSourceRoot, relative);
      const before = fs.readFileSync(target, 'utf8');
      const after = mutation.apply(operation, before);
      assert.notEqual(after, before, `${kind}:${operation} did not change ${relative}`);
      fs.writeFileSync(target, after);

      const result = runInventory(isolatedSourceRoot, true);
      const output = `${result.stdout ?? ''}\n${result.stderr ?? ''}`;
      const diagnostics = [...new Set(output.match(/\bDOC_DRIFT_[A-Z_]+\b/gu) ?? [])];
      assert.notEqual(result.status, 0, `${kind}:${operation} unexpectedly passed the drift check`);
      assert.deepEqual(diagnostics, [mutation.diagnostic],
        `${kind}:${operation} produced the wrong drift diagnostic:\n${output}`);
      results.push({ kind, operation, diagnostic: mutation.diagnostic, source: relative });

      fs.writeFileSync(target, before);
    }
  }

  const dependencyMutation = mutations.dependency;
  const dependencyTarget = path.join(isolatedSourceRoot, dependencyMutation.source);
  const dependencyBefore = fs.readFileSync(dependencyTarget, 'utf8');
  const mappingPath = path.join(isolatedSourceRoot, 'docs/config/platform-surface-map.json');
  const mappingBefore = fs.readFileSync(mappingPath, 'utf8');
  fs.writeFileSync(dependencyTarget, dependencyMutation.apply('add', dependencyBefore));
  const printed = runInventory(isolatedSourceRoot, true, ['--print-inventory']);
  assert.equal(printed.status, 0, `could not inspect the isolated identity addition:\n${printed.stderr}`);
  const mutatedInventory = JSON.parse(printed.stdout);
  const mapping = JSON.parse(mappingBefore);
  mapping.dependencySignals.identities = [...new Set(mutatedInventory.dependencySignals.map((item) => item.value))].sort();
  fs.writeFileSync(mappingPath, `${JSON.stringify(mapping, null, 2)}\n`);
  const digestBypass = runInventory(isolatedSourceRoot, true);
  assert.notEqual(digestBypass.status, 0, 'adding an identity without independent review unexpectedly passed');
  assert.match(`${digestBypass.stdout}\n${digestBypass.stderr}`, /DOC_DRIFT_MAP_REVIEW/u,
    'an identity-only map edit did not fail at the independent review digest');
  mapReviewResults.push('identity-only-edit-rejected');
  fs.writeFileSync(dependencyTarget, dependencyBefore);
  fs.writeFileSync(mappingPath, mappingBefore);
} finally {
  cleanup();
}

assert.equal(results.length,
  Object.values(mutations).reduce((total, mutation) => total + (mutation.operations ?? operations).length, 0),
  'the complete platform mutation matrix was not executed');

scripts/check-prism-guides.mjs.syntax:
for (const specification of specifications) {
  const filePath = path.join(root, specification.file);
  const source = fs.readFileSync(filePath, 'utf8');
  const revisionMatch = source.match(/^Evidence revision: `([0-9a-f]{40})`$/mu);
  assert(revisionMatch, `${specification.file} lacks one explicit inspected evidence revision`);
  const revision = revisionMatch[1];
  for (const marker of specification.required) {
    assert(source.includes(marker), `${specification.file} lacks required content: ${marker}`);
  }

  if (specification.file.startsWith('docs/site/understand/')) {
    const blockLanguages = [...source.matchAll(/^```([^\n]*)$/gmu)]
      .map((match) => match[1].trim().toLowerCase()).filter(Boolean);
    assert(blockLanguages.every((language) => language === 'mermaid'),
      `${specification.file} copies maintained code instead of linking to source`);
  }

  const links = [...source.matchAll(
    /https:\/\/github\.com\/datrab\/kubeclaw\/blob\/([0-9a-f]{40})\/([^#)]+)(?:#L([0-9]+)(?:-L([0-9]+))?)?/gu,
  )];
  assert(links.length >= specification.minimumLinks,
    `${specification.file} has only ${links.length} pinned source links`);
  sourceLinks += links.length;

  for (const match of links) {
    const [, linkRevision, repositoryPath, firstValue, lastValue] = match;
    assert.equal(linkRevision, revision,
      `${specification.file} uses another revision for ${repositoryPath}`);
    const pinned = execFileSync('git', ['-C', root, 'show', `${revision}:${repositoryPath}`],
      { encoding: 'utf8' });
    if (!checkedSources.has(repositoryPath)) {
      const currentPath = path.join(root, repositoryPath);
      assert(fs.existsSync(currentPath), `linked source is absent: ${repositoryPath}`);
      assert.equal(fs.readFileSync(currentPath, 'utf8'), pinned,
        `${repositoryPath} changed after ${revision}; inspect and repin the Prism guides`);
      checkedSources.add(repositoryPath);
    }
    if (!firstValue) continue;
    const lineCount = pinned.split('\n').length;
    const first = Number(firstValue);
    const last = Number(lastValue ?? firstValue);
    assert(first >= 1 && last >= first && last <= lineCount,
      `${specification.file} has an invalid line range for ${repositoryPath}`);
  }
}

for (const setting of settings) {
  assert(runtimeInventory.environment.some((entry) => entry.name === setting),
    `canonical environment inventory lacks Prism runtime setting ${setting}`);
  assert(environmentReference.includes(`| \`${setting}\` |`),
    `canonical environment reference does not publish Prism runtime setting ${setting}`);
}

function leafValues(value, prefix = '$') {
  if (Array.isArray(value)) {
    return value.flatMap((item, index) => leafValues(item, `${prefix}[${index}]`));
  }
  if (value !== null && typeof value === 'object') {
    return Object.entries(value).flatMap(([key, child]) =>
      leafValues(child, `${prefix}.${key}`));
  }
  return [{ path: prefix, value }];
}

for (const file of ['charts/prism/values.yaml', 'my-values/prism-agent-values.yaml']) {
  const bytes = fs.readFileSync(path.join(root, file), 'utf8');
  const discovered = leafValues(parseYaml(bytes));
  const inventoryFile = valueInventory.files.find((entry) => entry.path === file);
  assert(inventoryFile, `canonical configuration inventory lacks ${file}`);
  assert.equal(inventoryFile.sourceDigest, crypto.createHash('sha256').update(bytes).digest('hex'),
    `${file} differs from the canonical inventory; regenerate and review its receiving semantics`);
  const fields = inventoryFile.documents.flatMap((document) => document.fields);
  const sectionStart = helmReference.indexOf(`<summary><code>${file}</code>`);
  assert(sectionStart >= 0, `canonical Helm reference lacks the ${file} section`);
  const sectionEnd = helmReference.indexOf('</details>', sectionStart);
  assert(sectionEnd > sectionStart, `canonical Helm reference has an incomplete ${file} section`);
  const section = helmReference.slice(sectionStart, sectionEnd);
  for (const leaf of discovered) {
    const field = fields.find((entry) => entry.path === leaf.path);
    assert(field, `canonical configuration inventory lacks ${file}:${leaf.path}`);
    // Credentials and private authority identities remain redacted. Their
    // source digest still binds changes; never print their unredacted value.
    const redacted = typeof field.value === 'string' && field.value.startsWith('<redacted:');
    if (!redacted) assert(Object.is(field.value, leaf.value),
      `canonical selected value differs for ${file}:${leaf.path}`);
    const row = section.split('\n').find((line) => line.startsWith(`| \`${leaf.path}\` |`));
    assert(row, `canonical Helm reference does not publish ${file}:${leaf.path}`);
    const displayValue = String(field.value ?? 'null').replaceAll('|', '&#124;')
      .replaceAll('`', '&#96;').replaceAll('\n', '<br>');
    assert(row.includes(`| \`${field.type}\`<br>\`${displayValue}\`<br>`),
      `canonical Helm reference has a stale type or selected value for ${file}:${leaf.path}`);
  }
  if (file === 'charts/prism/values.yaml') helmFields = discovered;
}

for (const setting of deploySettings) {
  assert(operator.includes(`\`${setting}\``),
    `Prism operator guide does not classify deploy identifier ${setting}`);
}

for (const migration of migrations) {
  assert(dataGuide.includes(`\`${migration}\``),
    `Prism data guide does not name migration ${migration}`);
}

for (const operation of ['generate', 'render', 'evaluate', 'ingest', 'publish']) {
  assert(allGuides.includes(`\`${operation}\``),
    `Prism guide set does not name engine operation ${operation}`);
}

for (const [file, target] of navigation) {
  assert(fs.readFileSync(path.join(root, file), 'utf8').includes(`](${target}`),
    `${file} does not link to ${target}`);
}

for (const id of ['SUR-SPC-03', 'SUR-DAT-04', 'SUR-DEP-06']) {
  const row = surfaces.split('\n').find((line) => line.startsWith(`| ${id} |`));
  assert(row?.endsWith('| Detailed |'), `${id} does not declare detailed coverage`);
}

const requirementMarkers = {
  'SPC-002': ['docs/site/understand/prism.md', '## The Product Boundary'],
  'SPC-003': ['docs/site/understand/prism-data.md', '## Projects and Design Requests'],
  'OPR-010': ['docs/site/use/prism-studio.md', '## The Complete Studio Journey'],
  'CDV-009': ['docs/site/extend/platform/prism.md', '## Start With the Smallest Owner'],
};

for (const [id, [file, marker]] of Object.entries(requirementMarkers)) {
  assert(fs.readFileSync(path.join(root, file), 'utf8').includes(marker),
    `${id} lost its maintained marker in ${file}`);
}

scripts/check-suite-migration-workflow.m.syntax:
function isContained(relative) {
  if (typeof relative !== 'string' || path.isAbsolute(relative)) return false;
  const resolved = path.resolve(root, relative);
  const fromRoot = path.relative(root, resolved);
  return fromRoot !== '' && fromRoot !== '..' && !fromRoot.startsWith(`..${path.sep}`) && !path.isAbsolute(fromRoot);
}

function realContained(relative) {
  if (!isContained(relative)) return false;
  try {
    const resolved = fs.realpathSync(path.resolve(root, relative));
    const fromRoot = path.relative(realRoot, resolved);
    return fromRoot !== '' && fromRoot !== '..' && !fromRoot.startsWith(`..${path.sep}`) && !path.isAbsolute(fromRoot);
  } catch {
    return false;
  }
}

function checkStatus() {
  if (status.schemaVersion !== 'suite-migration-status.v1') errors.push(`${statusPath}: invalid schemaVersion`);
  if (status.totalLegacySuites !== 13 || status.suites.length !== 13) errors.push(`${statusPath}: expected 13 legacy suites`);
  const ids = status.suites.map((suite) => suite.id);
  if (new Set(ids).size !== ids.length) errors.push(`${statusPath}: duplicate suite id`);
  const allSourceCutoversComplete = status.suites.every((suite) => suite.implementation === 'complete'
    && suite.sourceCutover === 'complete');
  for (const suite of status.suites) {
    for (const phase of ['implementation', 'parity', 'cutover']) {
      if (!allowedState.has(suite[phase])) errors.push(`${statusPath}: ${suite.id}.${phase} is invalid`);
    }
    if (!allowedState.has(suite.sourceCutover)) {
      errors.push(`${statusPath}: ${suite.id}.sourceCutover is invalid`);
    }
    if (suite.productionAcceptance !== undefined && !allowedAcceptanceState.has(suite.productionAcceptance)) {
      errors.push(`${statusPath}: ${suite.id}.productionAcceptance is invalid`);
    }
    if (productionRequiredSuites.has(suite.id) && suite.productionAcceptance === undefined) {
      errors.push(`${statusPath}: ${suite.id}.productionAcceptance is required`);
    }
    if (productionRequiredSuites.has(suite.id) && suite.parity === 'complete'
      && suite.productionAcceptance !== 'complete') {
      errors.push(`${statusPath}: ${suite.id} proves parity before production acceptance`);
    }
    if (suite.parity === 'complete' && suite.implementation !== 'complete') errors.push(`${statusPath}: ${suite.id} proves parity before implementation`);
    if (suite.cutover === 'complete' && suite.parity !== 'complete') errors.push(`${statusPath}: ${suite.id} cuts over before parity`);
    if (suite.cutover === 'complete' && suite.productionAcceptance !== undefined
      && suite.productionAcceptance !== 'complete') {
      errors.push(`${statusPath}: ${suite.id} cuts over before production acceptance`);
    }
    if (suite.sourceCutover === 'complete' && suite.implementation !== 'complete') {
      errors.push(`${statusPath}: ${suite.id} completes source cutover before implementation`);
    }
    if (suite.productionAcceptance === 'complete') {
      if (!allSourceCutoversComplete) {
        errors.push(`${statusPath}: ${suite.id} completes production acceptance before all source cutovers`);
      }
      if (!realContained(suite.productionReceipt)) {
        errors.push(`${statusPath}: ${suite.id} has no contained production receipt`);
      } else {
        const receipt = readJson(suite.productionReceipt);
        const expectedIdentity = productionReceiptIdentity.get(suite.id);
        if (!expectedIdentity || receipt.schemaVersion !== expectedIdentity.schemaVersion
          || receipt.suite !== expectedIdentity.suite) {
          errors.push(`${suite.productionReceipt}: receipt identity does not match ${suite.id}`);
        }
        const publicKeyPath = productionReceiptTrustedPublicKeyFile;
        if (!fs.existsSync(publicKeyPath)) {
          errors.push(`${suite.productionReceipt}: trusted production receipt public key is not installed`);
        } else if (!gitRevision.test(suite.productionRevision ?? '')) {
          errors.push(`${statusPath}: ${suite.id}.productionRevision is required`);
        } else if (!gitRevision.test(suite.productionBusterRevision ?? '')) {
          errors.push(`${statusPath}: ${suite.id}.productionBusterRevision is required`);
        } else if (!digest.test(suite.productionReceiptKeyFingerprint ?? '')) {
          errors.push(`${statusPath}: ${suite.id}.productionReceiptKeyFingerprint is required`);
        } else {
          const trustedKey = fs.realpathSync(publicKeyPath);
          const fromRoot = path.relative(realRoot, trustedKey);
          if (fromRoot === '' || (fromRoot !== '..' && !fromRoot.startsWith(`..${path.sep}`)
            && !path.isAbsolute(fromRoot))) {
            errors.push(`${suite.productionReceipt}: trusted public key must be outside the repository`);
          } else {
            const receiptErrors = verifyProductionReceipt(receipt, fs.readFileSync(trustedKey), {
              expectedRevision: suite.productionRevision,
              expectedBusterRevision: suite.productionBusterRevision,
              expectedPublicKeyFingerprint: suite.productionReceiptKeyFingerprint,
            });
            for (const error of receiptErrors) errors.push(`${suite.productionReceipt}: ${error}`);
          }
        }
        const ledger = suite.parityLedger && exists(suite.parityLedger) ? readJson(suite.parityLedger) : null;
        const acceptance = ledger?.entries?.['TSX-CUT-005'];
        if (suite.id === 'tailscale-preview' && (acceptance?.status !== 'proved'
          || !acceptance?.proof?.includes(suite.productionReceipt)
          || ledger?.acceptedDeferral?.status === 'open')) {
          errors.push(`${suite.parityLedger}: production acceptance does not cite the closed receipt`);
        } else if (suite.id !== 'tailscale-preview' && (ledger?.productionAcceptance?.status !== 'proved'
          || ledger?.productionAcceptance?.receipt !== suite.productionReceipt
          || ledger?.acceptedDeferral?.status === 'open')) {
          errors.push(`${suite.parityLedger}: production acceptance does not cite the closed receipt`);
        }
      }
    }
  }
  if (exists('contracts/pipeline-test-gate/v1/legacy-suite-bridge.json')) {
    errors.push('retired legacy suite bridge still exists');
  }
}

function selectedSuites(phase) {
  return status.suites.filter((suite) => (!suiteFilter || suite.id === suiteFilter) && suite[phase] === 'complete');
}

function checkBaseline() {
  for (const suite of selectedSuites('implementation')) {
    if (!suite.baseline || !exists(suite.baseline)) { errors.push(`${suite.id}: baseline record is missing`); continue; }
    const source = fs.readFileSync(path.join(root, suite.baseline), 'utf8');
    if (!source.trim()) { errors.push(`${suite.baseline}: baseline record is empty`); continue; }
    if (suite.baseline.endsWith('.json')) {
      const baseline = JSON.parse(source);
      if (baseline.legacySuite !== suite.id) errors.push(`${suite.baseline}: legacySuite does not match status`);
      if (baseline.successor !== suite.successor) errors.push(`${suite.baseline}: successor does not match status`);
      if (!Number.isSafeInteger(baseline.expectedItemCount) || baseline.expectedItemCount < 1) errors.push(`${suite.baseline}: expectedItemCount is invalid`);
      if (!Array.isArray(baseline.items) || baseline.items.length < 1) errors.push(`${suite.baseline}: baseline items are missing`);
      else {
        if (baseline.items.length !== baseline.expectedItemCount) errors.push(`${suite.baseline}: item count does not match expectedItemCount`);
        const ids = baseline.items.map((item) => item.id);
        if (new Set(ids).size !== ids.length) errors.push(`${suite.baseline}: duplicate item id`);
        for (const item of baseline.items) {
          for (const field of ['id', 'class', 'requirement', 'state']) {
            if (typeof item[field] !== 'string' || !item[field].trim()) errors.push(`${suite.baseline}: ${String(item.id)} has no ${field}`);
          }
        }
      }
    } else {
      for (const heading of ['## Current Execution Path', '## Current Configuration', '## Current Parity Inventory', '## Existing Proof Coverage', '## Unit Cutover Deletion Targets']) {
        if (!source.includes(heading)) errors.push(`${suite.baseline}: required section is missing: ${heading}`);
      }
      const ids = [...source.matchAll(/`([A-Z][A-Z0-9]+(?:-[A-Z0-9]+){2,})`/gu)].map((match) => match[1]);
      if (new Set(ids).size < 1) errors.push(`${suite.baseline}: stable baseline items are missing`);
    }
  }
}

function checkParity() {
  for (const suite of status.suites.filter((item) => (!suiteFilter || item.id === suiteFilter)
    && (item.parity === 'complete' || item.productionAcceptance !== undefined))) {
    const ledger = suite.parityLedger;
    if (!ledger) { errors.push(`${suite.id}: parity ledger is not declared`); continue; }
    if (!exists(ledger)) { errors.push(`${suite.id}: parity ledger is missing`); continue; }
    const value = readJson(ledger);
    const items = Array.isArray(value.items) ? value.items : Object.entries(value.entries ?? {}).map(([id, item]) => ({ id, ...item }));
    if (items.length < 1) errors.push(`${ledger}: items are missing`);
    const ids = items.map((item) => item.id);
    if (new Set(ids).size !== ids.length) errors.push(`${ledger}: duplicate item id`);
    const globalProof = Array.isArray(value.proof) && value.proof.length > 0 ? value.proof : null;
    const acceptedDeferral = value.acceptedDeferral?.status === 'open'
      && value.acceptedDeferral?.acceptedBy === 'project-owner'
      && typeof value.acceptedDeferral?.condition === 'string'
      && exists(value.acceptedDeferral?.proof);
    for (const item of items) {
      if (!allowedDisposition.has(item.disposition)) errors.push(`${ledger}: ${item.id} has invalid disposition`);
      if (item.disposition === 'blocked') errors.push(`${ledger}: ${item.id} remains blocked`);
      if (item.status !== undefined && item.status !== 'proved') {
        if (!(item.status === 'deferred' && item.disposition === 'deferred' && acceptedDeferral)) {
          errors.push(`${ledger}: ${item.id} is neither proved nor covered by an accepted deferral`);
        }
      }
      const itemProof = Array.isArray(item.proof) && item.proof.length > 0 ? item.proof : null;
      const proof = itemProof ?? globalProof;
      if (!proof) errors.push(`${ledger}: ${item.id} has no non-empty proof`);
      else for (const proofPath of proof) if (typeof proofPath !== 'string' || !exists(proofPath)) errors.push(`${ledger}: ${item.id} cites missing proof ${String(proofPath)}`);
    }
  }
}

function checkCutover() {
  for (const suite of status.suites.filter((item) => (!suiteFilter || item.id === suiteFilter)
    && (item.sourceCutover ?? item.cutover) === 'complete')) {
    const inventory = suite.cutoverInventory;
    if (!inventory) { errors.push(`${suite.id}: cutover inventory is not declared`); continue; }
    if (!exists(inventory)) { errors.push(`${suite.id}: cutover inventory is missing`); continue; }
    const value = readJson(inventory);
    if (value.suite !== suite.id) errors.push(`${inventory}: suite id does not match status`);
    const deleted = value.legacyFilesToDelete;
    if (!Array.isArray(deleted) || deleted.length < 1) errors.push(`${inventory}: concrete deletion targets are missing`);
    else for (const target of deleted) {
      if (!isContained(target)) errors.push(`${inventory}: invalid deletion target ${String(target)}`);
      else if (exists(target)) errors.push(`${inventory}: legacy deletion target still exists: ${target}`);
    }
    for (const replacement of value.replacementFilesRequired ?? []) {
      if (typeof replacement !== 'string' || !exists(replacement)) errors.push(`${inventory}: required replacement is missing: ${String(replacement)}`);
    }
    const verification = value.verification;
    const tests = new Set();
    for (const kind of ['solePathTests', 'dualAuthorityTests', 'absenceTests']) {
      if (!Array.isArray(verification?.[kind]) || verification[kind].length < 1) errors.push(`${inventory}: ${kind} are missing`);
      else for (const test of verification[kind]) {
        if (!realContained(test)) errors.push(`${inventory}: ${kind} cites unsafe test ${String(test)}`);
        else if (!exists(test)) errors.push(`${inventory}: ${kind} cites missing test ${String(test)}`);
        else tests.add(test);
      }
    }
    for (const test of tests) {
      const result = spawnSync(process.execPath, [fs.realpathSync(path.join(root, test))], {
        cwd: root,
        encoding: 'utf8',
        env: process.env,
      });
      if (result.status !== 0) {
        const detail = [result.stdout, result.stderr].filter(Boolean).join('\n').trim();
        errors.push(`${inventory}: cutover proof failed: ${test}${detail ? `\n${detail}` : ''}`);
      }
    }
    if (Number.isSafeInteger(value.parityItemCount)) {
      const ledger = readJson(suite.parityLedger);
      const count = Array.isArray(ledger.items) ? ledger.items.length : Object.keys(ledger.entries ?? {}).length;
      if (value.parityItemCount !== count) errors.push(`${inventory}: parity item count does not match ledger`);
    }
  }
}

function schemaLeafPaths(schema) {
  const out = new Set();
  function visit(value, prefix = '') {
    if (!value || typeof value !== 'object') return;
    if (value.properties) {
      for (const [name, child] of Object.entries(value.properties)) {
        const next = prefix ? `${prefix}.${name}` : name;
        if (child && typeof child === 'object' && (child.properties || child.oneOf)) visit(child, next);
        else out.add(next);
      }
    }
    for (const choice of value.oneOf ?? []) visit(choice, prefix);
  }
  visit(schema);
  return [...out];
}

function documentText(manifest, kind) {
  const relative = manifest.documents[kind];
  const text = fs.readFileSync(path.join(root, relative), 'utf8');
  if (relative !== 'docs/site/reference/buster-suites.md' || !manifest.suiteSection) return text;
  const marker = `## ${manifest.suiteSection}`;
  const start = text.indexOf(marker);
  if (start < 0) throw new Error(`${relative}: missing suite section ${marker}`);
  const next = text.indexOf('\n## ', start + marker.length);
  return text.slice(start, next < 0 ? text.length : next);
}

function checkSchemaDocumentation() {
  for (const manifestPath of documentationManifests()) {
    const manifest = readJson(manifestPath);
    for (const document of Object.values(manifest.documents)) if (!exists(document)) errors.push(`${manifestPath}: missing ${document}`);
    const projectSchemas = manifest.projectSchemas ?? [manifest.projectSchema];
    if (!Array.isArray(projectSchemas) || projectSchemas.length < 1 || projectSchemas.some((schema) => !exists(schema))) {
      errors.push(`${manifestPath}: project schema is missing`); continue;
    }
    const configurationReferences = [...new Set([
      manifest.documents.configurationReference,
      'docs/site/reference/buster-runtime-configuration.md',
      ...(manifest.canonicalConfigurationReferences ?? []),
    ])];
    for (const referencePath of configurationReferences) {
      if (!exists(referencePath)) errors.push(`${manifestPath}: missing canonical configuration reference ${referencePath}`);
    }
    const reference = configurationReferences.filter(exists)
      .map((referencePath) => referencePath === manifest.documents.configurationReference
        ? documentText(manifest, 'configurationReference')
        : fs.readFileSync(path.join(root, referencePath), 'utf8')).join('\n');
    const referenceLabel = configurationReferences.join(', ');
    for (const projectSchema of projectSchemas) for (const field of schemaLeafPaths(readJson(projectSchema))) {
      if (!reference.includes(`\`${field}\``)) errors.push(`${referenceLabel}: undocumented project field ${field}`);
    }
    for (const field of manifest.operatorFields ?? []) {
      const documented = reference.includes(`\`${field}\``) || reference.includes(`\`${field}[]\``);
      if (!documented) errors.push(`${referenceLabel}: undocumented operator field ${field}`);
    }
  }
}

function checkErrorDocumentation() {
  const nonErrorIdentifiers = new Set([
    'PLAYWRIGHT_BROWSERS_PATH', 'PLAYWRIGHT_JSON_OUTPUT_NAME', 'PLAYWRIGHT_TEST_BASE_URL',
  ]);
  for (const manifestPath of documentationManifests()) {
    const manifest = readJson(manifestPath);
    const source = manifest.sourceFilesWithErrors.map((relative) => fs.readFileSync(path.join(root, relative), 'utf8')).join('\n');
    const prefixes = manifest.errorPrefixes ?? [];
    const discovered = source.match(/[A-Z][A-Z0-9]+(?:_[A-Z0-9]+){2,}/gu) ?? [];
    const codes = [...new Set([
      ...discovered.filter((code) => prefixes.some((prefix) => code.startsWith(prefix))),
      ...(manifest.additionalErrors ?? []),
    ])].filter((code) => !nonErrorIdentifiers.has(code)).sort();
    const reference = [
      documentText(manifest, 'errorReference'),
      fs.readFileSync(path.join(root, 'docs/site/reference/nova-project.md'), 'utf8'),
      documentText(manifest, 'userGuide'),
    ].join('\n');
    for (const code of codes) if (!reference.includes(`\`${code}\``)) errors.push(`${manifest.documents.errorReference}: undocumented error ${code}`);
  }
}

function findConfigs(value, markers, out = []) {
  if (!value || typeof value !== 'object') return out;
  if (!Array.isArray(value) && markers.some((field) => value[field] !== undefined)) out.push(value);
  for (const child of Array.isArray(value) ? value : Object.values(value)) findConfigs(child, markers, out);
  return out;
}

function checkExamples() {
  for (const manifestPath of documentationManifests()) {
    const manifest = readJson(manifestPath);
    const markers = manifest.configurationMarkerFields ?? ['buildContext', 'definition'];
    if (!Array.isArray(markers) || markers.length < 1 || markers.some((field) => typeof field !== 'string' || !field)) {
      errors.push(`${manifestPath}: configurationMarkerFields are invalid`);
      continue;
    }
    const projectSchemas = manifest.projectSchemas ?? [manifest.projectSchema];
    const validators = projectSchemas.map((schema) => {
      const ajv = new Ajv2020({ allErrors: true, strict: true });
      addFormats(ajv);
      return ajv.compile(readJson(schema));
    });
    const validateConfig = (config, label) => {
      if (!validators.some((validate) => validate(config))) {
        const details = validators.flatMap((validate) => validate.errors ?? [])
          .map((error) => `${error.instancePath || '/'} ${error.message}`).join('; ');
        errors.push(`${label}: provider schema rejected example: ${details}`);
      }
    };
    for (const example of manifest.exampleFiles ?? []) {
      if (!exists(example)) { errors.push(`${manifestPath}: missing example ${example}`); continue; }
      const value = readJson(example);
      const configs = findConfigs(value, markers);
      if (configs.length < 1) errors.push(`${example}: no provider config found`);
      configs.forEach((config, index) => validateConfig(config, `${example}#${index + 1}`));
    }
    for (const [kind, document] of Object.entries(manifest.documents)) {
      const text = documentText(manifest, kind);
      const blocks = [...text.matchAll(/```json\n([\s\S]*?)\n```/gu)];
      for (const [index, block] of blocks.entries()) {
        try {
          const value = JSON.parse(block[1]);
          findConfigs(value, markers).forEach((config, configIndex) => validateConfig(config, `${document}:${kind}:block-${index + 1}.${configIndex + 1}`));
        } catch (error) { errors.push(`${document}: JSON block ${index + 1} does not parse: ${error.message}`); }
      }
    }
  }
}

function checkControlledLanguage() {
  const targets = [
    { label: 'docs/architecture/pipeline-test-gate-suite-migration-playbook.md', text: fs.readFileSync(path.join(root, 'docs/architecture/pipeline-test-gate-suite-migration-playbook.md'), 'utf8') },
    { label: 'docs/architecture/pipeline-test-gate-suite-migration-templates.md', text: fs.readFileSync(path.join(root, 'docs/architecture/pipeline-test-gate-suite-migration-templates.md'), 'utf8') },
    ...documentationManifests().flatMap((manifestPath) => {
      const manifest = readJson(manifestPath);
      return ['userGuide', 'operatorGuide', 'securityModel'].map((kind) => ({
        label: `${manifest.documents[kind]}#${manifest.suiteSection ?? kind}`,
        text: documentText(manifest, kind),
      }));
    }),
  ];
  const vague = /\b(simply|obviously|appropriate|properly|normally|just|easy|easily)\b/iu;
  const uniqueTargets = [...new Map(targets.map((target) => [target.label, target])).values()];
  for (const target of uniqueTargets) {
    const text = stripCode(target.text);
    if (vague.test(text)) errors.push(`${target.label}: contains vague controlled-language term "${vague.exec(text)?.[0]}"`);
    const statements = [];
    let prose = [];
    const flush = () => {
      if (prose.length) statements.push(...prose.join(' ').split(/(?<=[.!?])\s+/gu));
      prose = [];
    };
    for (const raw of text.split('\n')) {
      const line = raw.trim();
      if (!line || line.startsWith('#') || line.startsWith('|')) { flush(); continue; }
      if (/^(?:[-*]|\d+[.)])\s+/u.test(line)) { flush(); statements.push(line.replace(/^(?:[-*]|\d+[.)])\s+/u, '')); }
      else prose.push(line);
    }
    flush();
    for (const statement of statements) {
      const words = statement.match(/[A-Za-z0-9][A-Za-z0-9@._/-]*/gu) ?? [];
      if (words.length > 40) errors.push(`${target.label}: statement exceeds 40 words: ${statement.slice(0, 100)}...`);
    }
  }
}

const actions = {
  status: checkStatus,
  baseline: checkBaseline,
  parity: checkParity,
  cutover: checkCutover,
  'docs-schema': checkSchemaDocumentation,
  'docs-errors': checkErrorDocumentation,
  'docs-examples': checkExamples,
  'docs-language': checkControlledLanguage,
};

if (mode === 'all') for (const action of Object.values(actions)) action();
else if (actions[mode]) actions[mode]();
else errors.push(`unknown workflow check mode: ${mode}`);

if (errors.length) {
  console.error(`suite migration ${mode} check failed:`);
  for (const error of errors) console.error(`- ${error}`);
  process.exit(1);
}

