scripts/render-postgresql-recovery.mjs.syntax:
function validate(policy, namespace, postgres, application) {
  if (policy.schemaVersion !== 1 || !identifier(namespace) || !identifier(postgres.auth?.existingSecret)
    || typeof postgres.auth.secretKeys?.adminPasswordKey !== 'string' || !/^[a-zA-Z0-9._-]+$/.test(postgres.auth.secretKeys.adminPasswordKey)
    || postgres.auth.database !== 'litellm' || application?.metadata?.name !== 'litellm') throw new Error('POSTGRES_RECOVERY_CONFIGURATION_INVALID');
  for (const key of ['backupIntervalMinutes', 'verificationIntervalMinutes', 'maximumAgeSeconds', 'maximumDurationSeconds', 'verificationDeadlineSeconds', 'maximumBackupBytes', 'maximumRetainedBytes']) {
    if (!Number.isSafeInteger(policy[key]) || policy[key] < 1) throw new Error(`POSTGRES_RECOVERY_POLICY_INVALID:${key}`);
  }
  validateBudgets(policy);
  validateStorage(policy);
}

function validateBudgets(policy) {
  if (policy.maximumDurationSeconds >= policy.maximumAgeSeconds || policy.maximumBackupBytes + 67108864 > policy.maximumRetainedBytes) throw new Error('POSTGRES_RECOVERY_BUDGET_INVALID');
  if (policy.backupIntervalMinutes > 60 || policy.verificationIntervalMinutes > 30
    || policy.verificationIntervalMinutes > policy.backupIntervalMinutes
    || 2 * policy.maximumDurationSeconds + policy.verificationIntervalMinutes * 60 + policy.verificationDeadlineSeconds + 60 >= policy.maximumAgeSeconds) throw new Error('POSTGRES_RECOVERY_SCHEDULE_RPO_INVALID');
}

function validateStorage(policy) {
  if (!/^[1-9][0-9]*(?:Gi|Ti)$/.test(policy.persistence?.size)
    || (policy.persistence.storageClass !== null && !identifier(policy.persistence.storageClass))) throw new Error('POSTGRES_RECOVERY_STORAGE_INVALID');
  if (!policy.resources?.requests?.cpu || !policy.resources.requests.memory || !policy.resources.limits?.cpu || !policy.resources.limits.memory) throw new Error('POSTGRES_RECOVERY_RESOURCES_REQUIRED');
}

function applicationSecret(application) {
  const secrets = application.spec.template.spec.containers.find(container => container.name === 'litellm')?.envFrom?.filter(value => value.secretRef);
  if (secrets?.length !== 1 || secrets[0].prefix || !identifier(secrets[0].secretRef.name)) throw new Error('POSTGRES_RECOVERY_APPLICATION_SECRET_AMBIGUOUS');
  return secrets[0].secretRef.name;
}

function validateCredentialAuthority(application, applicationFile) {
  const config = load(fs.readFileSync(path.join(path.dirname(applicationFile), 'litellm-config.yaml'), 'utf8'));
  const environment = application.spec.template.spec.containers.find(container => container.name === 'litellm')?.env ?? [];
  if (config.general_settings?.master_key !== 'os.environ/LITELLM_MASTER_KEY'
    || environment.some(value => ['LITELLM_MASTER_KEY', 'LITELLM_SALT_KEY'].includes(value.name))) throw new Error('POSTGRES_RECOVERY_CREDENTIAL_AUTHORITY_UNSUPPORTED');
}

function configuration(policy, postgres, application, service, namespace) {
  const applicationImage = application.spec.template.spec.containers.find(container => container.name === 'litellm')?.image;
  if (!/^[a-zA-Z0-9._/-]+@sha256:[a-f0-9]{64}$/.test(applicationImage)) throw new Error('POSTGRES_RECOVERY_APPLICATION_PIN_REQUIRED');
  const [major, minor] = infrastructureChart('postgresql').appVersion.split('.').map(Number);
  return { PGHOST: service.name, PGPORT: String(service.port), PGDATABASE: postgres.auth.database, PGUSER: 'postgres',
    BACKUP_ROOT: '/backups/litellm', BACKUP_INTERVAL_SECONDS: String(policy.backupIntervalMinutes * 60), BACKUP_MAXIMUM_BYTES: String(policy.maximumBackupBytes),
    BACKUP_MAXIMUM_RETAINED_BYTES: String(policy.maximumRetainedBytes), BACKUP_MAXIMUM_AGE_SECONDS: String(policy.maximumAgeSeconds),
    BACKUP_MAXIMUM_DURATION_SECONDS: String(policy.maximumDurationSeconds), BACKUP_EXPECTED_SERVER_VERSION: String(major * 10000 + minor),
    BACKUP_CREDENTIAL_AUTHORITY_REF: `kubernetes-secret:${namespace}/${applicationSecret(application)}`,
    BACKUP_APPLICATION_IMAGE: applicationImage };
}

function cronJob(context) {
  const { policy, postgres, metadata, image, checksum, application } = context;
  const container = { name: 'backup', image, imagePullPolicy: 'IfNotPresent',
    command: ['bash', '/recovery/postgresql-recovery.sh', 'scheduled'],
    envFrom: [{ configMapRef: { name: `${name}-settings` } }], resources: policy.resources,
    securityContext: { allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: { drop: ['ALL'] } },
    volumeMounts: [{ name: 'backups', mountPath: '/backups', readOnly: false }, { name: 'script', mountPath: '/recovery', readOnly: true }, { name: 'tmp', mountPath: '/tmp' }] };
  container.env = [{ name: 'PGPASSWORD', valueFrom: { secretKeyRef: { name: postgres.auth.existingSecret, key: postgres.auth.secretKeys.adminPasswordKey } } },
    { name: 'LITELLM_MASTER_KEY', valueFrom: { secretKeyRef: { name: applicationSecret(application), key: 'LITELLM_MASTER_KEY' } } },
    { name: 'LITELLM_SALT_KEY', valueFrom: { secretKeyRef: { name: applicationSecret(application), key: 'LITELLM_SALT_KEY', optional: true } } }];
  return { apiVersion: 'batch/v1', kind: 'CronJob', metadata: { ...metadata, name }, spec: {
    schedule: `*/${policy.verificationIntervalMinutes} * * * *`, timeZone: 'Etc/UTC', concurrencyPolicy: 'Forbid',
    startingDeadlineSeconds: policy.verificationDeadlineSeconds, successfulJobsHistoryLimit: 3, failedJobsHistoryLimit: 10,
    jobTemplate: { spec: { backoffLimit: 0, activeDeadlineSeconds: policy.maximumDurationSeconds + 60,
      template: { metadata: { labels: metadata.labels, annotations: { 'checksum/recovery': checksum } }, spec: {
        automountServiceAccountToken: false, restartPolicy: 'Never',
        securityContext: { runAsNonRoot: true, runAsUser: 1001, runAsGroup: 1001, fsGroup: 1001, fsGroupChangePolicy: 'OnRootMismatch', seccompProfile: { type: 'RuntimeDefault' } },
        containers: [container], volumes: [{ name: 'backups', persistentVolumeClaim: { claimName: name } },
          { name: 'script', configMap: { name: `${name}-script`, defaultMode: 0o444 } }, { name: 'tmp', emptyDir: { sizeLimit: '256Mi' } }] },
      } } },
  } };
}

function networkPolicies(metadata, service) {
  const database = { matchLabels: { ...service.selector, 'k8s:io.kubernetes.pod.namespace': metadata.namespace } };
  const backup = { matchLabels: { app: name, 'k8s:io.kubernetes.pod.namespace': metadata.namespace } };
  const ports = [...new Set([service.port, service.targetPort])].map(port => ({ port: String(port), protocol: 'TCP' }));
  return [
    { apiVersion: 'cilium.io/v2', kind: 'CiliumNetworkPolicy', metadata: { ...metadata, name }, spec: { endpointSelector: backup, egress: [
      { toEndpoints: [{ matchLabels: { 'k8s:io.kubernetes.pod.namespace': 'kube-system', 'k8s:k8s-app': 'kube-dns' } }], toPorts: [{ ports: [{ port: '53', protocol: 'UDP' }, { port: '53', protocol: 'TCP' }], rules: { dns: [{ matchPattern: '*' }] } }] },
      { toEndpoints: [database], toPorts: [{ ports }] },
    ] } },
    { apiVersion: 'cilium.io/v2', kind: 'CiliumNetworkPolicy', metadata: { ...metadata, name: `${name}-database` }, spec: { endpointSelector: database, ingress: [{ fromEndpoints: [backup], toPorts: [{ ports: [{ port: String(service.targetPort), protocol: 'TCP' }] }] }] } },
  ];
}

export function renderPostgresqlRecovery(namespace, policyFile, postgresFile, applicationFile, helm = 'helm', release = 'postgresql') {
  const policy = load(fs.readFileSync(policyFile, 'utf8')); const postgres = load(fs.readFileSync(postgresFile, 'utf8'));
  const application = loadAll(fs.readFileSync(applicationFile, 'utf8')).find(value => value?.kind === 'Deployment' && value.metadata?.name === 'litellm');
  validate(policy, namespace, postgres, application);
  validateCredentialAuthority(application, applicationFile);
  const version = JSON.parse(fs.readFileSync(path.join(root, 'versions.json'), 'utf8'));
  const image = version.infrastructure.postgresql.replace(/:[^:@]+@/, '@');
  const script = fs.readFileSync(path.join(root, 'scripts/postgresql-recovery.sh'), 'utf8');
  if (!identifier(release) || release.length > 53) throw new Error('POSTGRES_RECOVERY_RELEASE_INVALID');
  const service = statefulDatabaseService('postgresql', release, namespace, postgresFile, helm);
  const data = configuration(policy, postgres, application, service, namespace);
  const checksum = createHash('sha256').update(script).update(JSON.stringify(data)).digest('hex');
  const metadata = { namespace, labels: { app: name, 'app.kubernetes.io/managed-by': 'kubeclaw-infrastructure' } };
  const storage = { accessModes: ['ReadWriteOnce'], resources: { requests: { storage: policy.persistence.size } },
    ...(policy.persistence.storageClass === null ? {} : { storageClassName: policy.persistence.storageClass }) };
  const context = { policy, postgres, metadata, image, checksum, application };
  return [{ apiVersion: 'v1', kind: 'ConfigMap', metadata: { ...metadata, name: `${name}-settings` }, data },
    { apiVersion: 'v1', kind: 'ConfigMap', metadata: { ...metadata, name: `${name}-script` }, data: { 'postgresql-recovery.sh': script } },
    { apiVersion: 'v1', kind: 'PersistentVolumeClaim', metadata: { ...metadata, name }, spec: storage },
    ...networkPolicies(metadata, service), cronJob(context)];
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const preflight = process.argv[2] === '--preflight';
  const args = process.argv.slice(preflight ? 3 : 2);
  if (![4, 5].includes(args.length)) throw new Error('Usage: render-postgresql-recovery.mjs [--preflight] NAMESPACE POLICY POSTGRES_VALUES LITELLM_DEPLOYMENT [RELEASE]');
  const documents = renderPostgresqlRecovery(...args.slice(0, 4), 'helm', args[4] ?? 'postgresql');
  if (preflight) preflightRecoveryVolume(args[0], documents);
  process.stdout.write(documents.map(value => dump(value, { noRefs: true, lineWidth: -1 })).join('---\n'));
}

scripts/render-registry-local.mjs.syntax:
function validateConfig(config) {
  if (!config || typeof config !== 'object' || Array.isArray(config)
    || Object.keys(config).some(key => !['capacity', 'storageClassName'].includes(key))
    || !/^[1-9][0-9]*(Mi|Gi|Ti)$/.test(config.capacity ?? '')
    || !/^[a-z0-9]([-a-z0-9.]*[a-z0-9])?$/.test(config.storageClassName ?? '')
    || config.storageClassName.length > 253) throw new Error('REGISTRY_STORAGE_CONFIG_INVALID');
}

function dataMount(pod) {
  return pod?.containers?.find(item => item.name === 'registry')?.volumeMounts?.find(item => item.mountPath === dataPath);
}

function validateDeployment(existing) {
  if (existing.kind !== 'Deployment' || existing.metadata?.name !== 'registry-local') throw new Error('REGISTRY_DEPLOYMENT_INVALID');
  const pod = existing.spec?.template?.spec;
  const mount = dataMount(pod);
  const volume = pod?.volumes?.find(item => item.name === mount?.name);
  if (!mount || mount.subPath || mount.subPathExpr || volume?.persistentVolumeClaim?.claimName !== claimName) {
    throw new Error('REGISTRY_EPHEMERAL_MIGRATION_REQUIRED');
  }
}

function validatePvc(pvc, config) {
  if (pvc.kind !== 'PersistentVolumeClaim' || pvc.metadata?.name !== claimName
    || pvc.spec?.accessModes?.length !== 1 || pvc.spec.accessModes[0] !== 'ReadWriteOncePod'
    || pvc.spec.storageClassName !== config.storageClassName
    || pvc.spec.resources?.requests?.storage !== config.capacity) throw new Error('REGISTRY_EXISTING_STORAGE_MISMATCH');
}

export function renderRegistryLocal(config, mode = 'serve', existing = null, existingPvc = null) {
  validateConfig(config);
  if (!['serve', 'gc-dry-run', 'gc'].includes(mode)) throw new Error('REGISTRY_MODE_INVALID');
  // Never replace an old writable container layer with an empty volume.
  // Absence is supplied only by kubectl --ignore-not-found; lookup errors abort.
  if (existing) validateDeployment(existing);
  else if (mode !== 'serve') throw new Error('REGISTRY_GC_EXISTING_DEPLOYMENT_REQUIRED');
  if (existingPvc) validatePvc(existingPvc, config);
  if (existing && !existingPvc) throw new Error('REGISTRY_EXISTING_STORAGE_MISSING');
  const docs = parseAllDocuments(fs.readFileSync(template, 'utf8')).map(doc => {
    if (doc.errors.length) throw new Error('REGISTRY_TEMPLATE_INVALID');
    return doc.toJS();
  });
  const pvc = docs.find(doc => doc.kind === 'PersistentVolumeClaim');
  pvc.spec.storageClassName = config.storageClassName;
  pvc.spec.resources.requests.storage = config.capacity;
  const deployment = docs.find(doc => doc.kind === 'Deployment');
  deployment.spec.replicas = mode === 'serve' ? 1 : 0;
  if (mode !== 'serve') {
    const spec = structuredClone(deployment.spec.template.spec);
    spec.restartPolicy = 'Never';
    const container = spec.containers[0];
    container.args = ['garbage-collect', ...(mode === 'gc-dry-run' ? ['--dry-run'] : []), configPath];
    delete container.ports;
    delete container.readinessProbe;
    delete container.livenessProbe;
    // RWOP prevents overlap even while the old writer Pod is terminating.
    // No delete-untagged: every manifest, including digest-only references, survives.
    docs.push({ apiVersion: 'batch/v1', kind: 'Job', metadata: { name: `registry-local-${mode}` },
      spec: { backoffLimit: 0, template: { metadata: { labels: { app: 'registry-local-gc' } }, spec } } });
  }
  return docs;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const [configFile, mode = 'serve', existingFile, pvcFile, ...extra] = process.argv.slice(2);
  if (!configFile || !existingFile || !pvcFile || extra.length) throw new Error('Usage: render-registry-local.mjs config.json serve|gc-dry-run|gc existing-deployment.json existing-pvc.json');
  const existingText = fs.readFileSync(existingFile, 'utf8').trim();
  const pvcText = fs.readFileSync(pvcFile, 'utf8').trim();
  const docs = renderRegistryLocal(JSON.parse(fs.readFileSync(configFile, 'utf8')), mode, existingText ? JSON.parse(existingText) : null, pvcText ? JSON.parse(pvcText) : null);
  process.stdout.write(docs.map(doc => stringify(doc)).join('---\n'));
}

scripts/render-stateful-network-policies.syntax:
function profile(selector) {
  const name = selector?.matchLabels?.['app.kubernetes.io/name'];
  return ['redis', 'postgresql'].includes(name) && selector.matchLabels['app.kubernetes.io/instance'] === name ? name : undefined;
}

function bindPorts(rule, original, ports) {
  if (rule.toPorts?.length !== 1 || rule.toPorts[0].ports?.length !== original.length
    || rule.toPorts[0].ports.some((port, index) => port.port !== String(original[index]) || port.protocol !== 'TCP')) {
    throw new Error('STATEFUL_NETWORK_PORT_CONTRACT_INVALID');
  }
  rule.toPorts[0].ports = [...new Set(ports)].map(port => ({ port: String(port), protocol: 'TCP' }));
}

function bindEgress(rule, services) {
  const selections = (rule.toEndpoints ?? []).map(selector => ({ selector, name: profile(selector) })).filter(item => item.name);
  if (!selections.length) return undefined;
  if (selections.length !== 1 || rule.toEndpoints.length !== 1) throw new Error('STATEFUL_NETWORK_DESTINATION_AMBIGUOUS');
  const { selector, name } = selections[0];
  bindSelector(selector, services[name]);
  bindPorts(rule, defaultPorts(name), services[name].ports.flatMap(port => [port.port, port.targetPort]));
  return name;
}

export function renderStatefulNetworkPolicies(file, namespace, selections, helm = 'helm') {
  const documents = loadAll(fs.readFileSync(file, 'utf8')).filter(Boolean);
  const services = Object.fromEntries(['redis', 'postgresql'].map(name =>
    [name, statefulDatabaseService(name, selections[name].release, namespace, selections[name].values, helm)]));
  const seen = Object.fromEntries(Object.keys(services).map(name => [name, { ingress: 0, egress: 0 }]));
  for (const document of documents) {
    if (document.kind !== 'CiliumNetworkPolicy') continue;
    const owner = profile(document.spec.endpointSelector);
    if (owner) {
      bindSelector(document.spec.endpointSelector, services[owner]);
      for (const rule of document.spec.ingress ?? []) bindPorts(rule, defaultPorts(owner), services[owner].ports.map(port => port.targetPort));
      seen[owner].ingress++;
    }
    for (const rule of document.spec.egress ?? []) {
      const name = bindEgress(rule, services);
      if (name) seen[name].egress++;
    }
  }
  for (const counts of Object.values(seen)) {
    if (!counts.ingress || !counts.egress) throw new Error('STATEFUL_NETWORK_POLICY_MISSING');
  }
  return documents;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 8) throw new Error('Usage: render-stateful-network-policies.mjs POLICY NAMESPACE REDIS_RELEASE REDIS_VALUES POSTGRESQL_RELEASE POSTGRESQL_VALUES');
  const [file, namespace, redisRelease, redisValues, postgresRelease, postgresValues] = process.argv.slice(2);
  const documents = renderStatefulNetworkPolicies(file, namespace, {
    redis: { release: redisRelease, values: redisValues }, postgresql: { release: postgresRelease, values: postgresValues },
  });
  process.stdout.write(documents.map(value => dump(value, { noRefs: true, lineWidth: -1 })).join('---\n'));
}

scripts/runtime-tool-locks.mjs.syntax:
function identities(directory, names) {
  return Object.fromEntries(names.map(name => [name, digest(fs.readFileSync(path.join(directory, name)))]));
}

export function checkRuntimeToolLocks(directory = root) {
  const receipt = JSON.parse(fs.readFileSync(path.join(directory, receiptFile), 'utf8'));
  if (receipt.schemaVersion !== 'runtime-tool-locks.v1'
    || JSON.stringify(receipt.inputs) !== JSON.stringify(identities(directory, inputs))
    || JSON.stringify(receipt.outputs) !== JSON.stringify(identities(directory, outputs))) {
    throw new Error('RUNTIME_TOOL_LOCK_DRIFT: run npm run versions:sync and review the resolved lock changes');
  }
  for (const group of groups) {
    const requirements = fs.readFileSync(path.join(directory, `docker/python-tools/${group}.in`), 'utf8');
    const locked = fs.readFileSync(path.join(directory, `docker/python-tools/${group}.txt`), 'utf8');
    for (const line of requirements.split('\n').filter(line => line && !line.startsWith('#'))) {
      if (!locked.split('\n').some(lockedLine => lockedLine.startsWith(`${line} `))) throw new Error('RUNTIME_PYTHON_ROOT_NOT_LOCKED');
    }
  }
  return { inputs: inputs.length, locks: outputs.length };
}

function run(command, args, cwd) {
  const executable = command === 'go' ? 'env' : command;
  const arguments_ = command === 'go' ? ['GOTOOLCHAIN=local', 'go', ...args] : args;
  return execFileSync(executable, arguments_, { cwd, encoding: 'utf8', timeout: 600000,
    maxBuffer: 16 * 1024 * 1024, stdio: ['ignore', 'pipe', 'inherit'] });
}

function resolvePython(directory, temporary) {
  for (const group of groups) {
    const source = `docker/python-tools/${group}.in`, output = `docker/python-tools/${group}.txt`;
    const common = ['pip', 'compile', '--python-version', '3.11', '--generate-hashes', '--only-binary', ':all:',
      '--no-annotate', '--no-header', '--no-strip-extras', '--default-index', 'https://pypi.org/simple'];
    run('uv', [...common, '--python-platform', 'x86_64-manylinux_2_36', source, '-o', output], directory);
    // Keep extras in install requirements; constraints must contain bare package pins.
    const constraints = path.join(temporary, `${group}-constraints.txt`);
    fs.writeFileSync(constraints, fs.readFileSync(path.join(directory, output), 'utf8')
      .replace(/^(\S+?)\[[^\]]+\](==)/gmu, '$1$2'));
    const arm = path.join(temporary, `${group}-arm64.txt`);
    run('uv', [...common, '--python-platform', 'aarch64-manylinux_2_36', '--constraints', constraints, source, '-o', arm], directory);
    if (!fs.readFileSync(path.join(directory, output)).equals(fs.readFileSync(arm))) throw new Error('RUNTIME_PYTHON_ARCHITECTURE_LOCK_MISMATCH');
  }
}

function resolveGo(directory) {
  const cwd = path.join(directory, 'docker/go-tools');
  const requirements = JSON.parse(fs.readFileSync(path.join(cwd, 'requirements.json'), 'utf8'));
  if (!run('go', ['version'], cwd).startsWith(`go version go${requirements.GO_VERSION} `)) throw new Error('RUNTIME_GO_TOOLCHAIN_NOT_SELECTED');
  if (!fs.existsSync(path.join(cwd, 'go.mod'))) run('go', ['mod', 'init', 'kubeclaw.local/runtime-tools'], cwd);
  run('go', ['get', '-tool', `honnef.co/go/tools/cmd/staticcheck@${requirements.STATICCHECK_VERSION}`,
    `golang.org/x/vuln/cmd/govulncheck@${requirements.GOVULNCHECK_VERSION}`,
    `github.com/fzipp/gocyclo/cmd/gocyclo@${requirements.GOCYCLO_VERSION}`], cwd);
  run('go', ['mod', 'tidy'], cwd);
  run('go', ['mod', 'download', 'all'], cwd);
  run('go', ['mod', 'verify'], cwd);
}

export function updateRuntimeToolLocks(directory = root) {
  try { return checkRuntimeToolLocks(directory); }
  catch (error) {
    if (error.code !== 'ENOENT' && !error.message.startsWith('RUNTIME_')) throw error;
    console.error(`Refreshing runtime tool locks: ${error.message}`);
  }
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'kubeclaw-tool-locks-'));
  try {
    resolvePython(directory, temporary);
    resolveGo(directory);
    // A failed resolution cannot publish a receipt certifying partial outputs.
    fs.writeFileSync(path.join(directory, receiptFile), JSON.stringify({ schemaVersion: 'runtime-tool-locks.v1',
      inputs: identities(directory, inputs), outputs: identities(directory, outputs) }, null, 2) + '\n');
    return checkRuntimeToolLocks(directory);
  } finally { fs.rmSync(temporary, { recursive: true, force: true }); }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 3 || !['--check', '--update'].includes(process.argv[2])) throw new Error('Usage: runtime-tool-locks.mjs --check|--update');
  console.log(JSON.stringify(process.argv[2] === '--check' ? checkRuntimeToolLocks() : updateRuntimeToolLocks()));
}

scripts/stateful-database-service.mjs.syntax:
export function statefulDatabaseService(profile, release, namespace, values, helm = 'helm') {
  if (!['redis', 'postgresql'].includes(profile)) throw new Error('STATEFUL_SERVICE_PROFILE_INVALID');
  for (const [value, maximum] of [[release, 53], [namespace, 63]]) {
    if (!/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(value) || value.length > maximum) throw new Error('STATEFUL_SERVICE_IDENTITY_INVALID');
  }
  const portName = `tcp-${profile}`;
  const archive = stageInfrastructureChart(profile);
  const rendered = loadAll(renderInfrastructureChart(profile, release, namespace, archive, values, helm, true));
  const services = rendered.filter(value => value?.kind === 'Service' && value.spec.clusterIP !== 'None'
    && value.spec.ports?.some(port => port.name === portName));
  if (services.length !== 1) throw new Error('STATEFUL_SERVICE_AMBIGUOUS');
  const service = services[0]; const port = service.spec.ports.find(value => value.name === portName);
  const workloads = rendered.filter(value => value?.kind === 'StatefulSet'
    && Object.entries(service.spec.selector).every(([key, label]) => value.spec.template.metadata.labels[key] === label));
  if (workloads.length !== 1) throw new Error('STATEFUL_SERVICE_WORKLOAD_AMBIGUOUS');
  const names = [portName];
  const ports = names.map(name => {
    const selected = service.spec.ports.filter(port => port.name === name);
    if (selected.length !== 1) throw new Error('STATEFUL_SERVICE_PORT_AMBIGUOUS');
    return { port: selected[0].port, targetPort: targetPort(workloads[0], selected[0].targetPort) };
  });
  if (ports.some(item => [item.port, item.targetPort].some(value => !Number.isInteger(value) || value < 1 || value > 65535))) throw new Error('STATEFUL_SERVICE_PORT_INVALID');
  return { name: service.metadata.name, selector: service.spec.selector, port: port.port, targetPort: ports[0].targetPort, ports };
}

function targetPort(workload, target) {
  if (typeof target === 'number') return target;
  const ports = workload.spec.template.spec.containers.flatMap(container => container.ports ?? []).filter(port => port.name === target);
  if (ports.length !== 1) throw new Error('STATEFUL_SERVICE_PORT_AMBIGUOUS');
  return ports[0].containerPort;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 6) throw new Error('Usage: stateful-database-service.mjs PROFILE RELEASE NAMESPACE VALUES');
  console.log(statefulDatabaseService(...process.argv.slice(2)).name);
}

scripts/suite-parity-report.mjs.syntax:
const entries = Object.entries(ledger.entries).sort(([left], [right]) => (
  left < right ? -1 : left > right ? 1 : 0
));

if (process.argv.includes('--check')) {
  if (!fs.existsSync(targetPath) || fs.readFileSync(targetPath, 'utf8') !== output) {
    console.error(`${targetPath} is stale; regenerate it with suite-parity-report.mjs`);
    process.exit(1);
  }
  console.log(`verified ${targetPath} (${entries.length} items)`);
} else {
  fs.writeFileSync(targetPath, output);
  console.log(`generated ${targetPath} (${entries.length} items)`);
}

scripts/updates/refresh-versions.mjs.syntax:
async function get(url, headers = {}) {
  if (new URL(url).hostname === 'api.github.com' && process.env.RENOVATE_TOKEN) headers = { ...headers, Authorization: `Bearer ${process.env.RENOVATE_TOKEN}` };
  return fetchUpstream(url, { headers });
}

async function checksum(url, name) {
  const lines = (await text(url)).split('\n');
  const matches = lines.filter(line => line.trim().split(/\s+/).at(-1)?.replace(/^\*/, '') === name);
  if (matches.length !== 1 || !/^[a-f0-9]{64}\s/.test(matches[0])) throw new Error(`Missing or ambiguous checksum: ${name}`);
  return matches[0].split(/\s+/)[0];
}

async function verified(url, expected) {
  if (!/^[a-f0-9]{64}$/.test(expected)) throw new Error(`Invalid checksum: ${url}`);
  const bytes = Buffer.from(await (await get(url)).arrayBuffer());
  if (sha(bytes) !== expected) throw new Error(`Checksum mismatch: ${url}`);
  return expected;
}

async function imageDigest(reference) {
  const tag = reference.split('@')[0];
  const slash = tag.indexOf('/');
  const explicit = slash >= 0 && /[.:]/.test(tag.slice(0, slash));
  let host = explicit ? tag.slice(0, slash) : 'registry-1.docker.io';
  let image = explicit ? tag.slice(slash + 1) : tag;
  if (host === 'docker.io') host = 'registry-1.docker.io';
  if (!image.includes('/')) image = `library/${image}`;
  const colon = image.lastIndexOf(':');
  if (colon < 0) throw new Error('Image tag required');
  const url = `https://${host}/v2/${image.slice(0, colon)}/manifests/${image.slice(colon + 1)}`;
  const headers = { Accept: 'application/vnd.oci.image.index.v1+json, application/vnd.docker.distribution.manifest.list.v2+json, application/vnd.oci.image.manifest.v1+json, application/vnd.docker.distribution.manifest.v2+json' };
  let response = await fetch(url, { headers, signal: AbortSignal.timeout(60000) });
  if (response.status === 401) {
    const challenge = response.headers.get('www-authenticate') ?? '';
    const fields = Object.fromEntries([...challenge.matchAll(/(realm|service|scope)="([^"]+)"/g)].map(m => [m[1], m[2]]));
    const tokenUrl = new URL(fields.realm);
    if (tokenUrl.protocol !== 'https:') throw new Error('HTTPS registry authentication required');
    for (const key of ['service', 'scope']) if (fields[key]) tokenUrl.searchParams.set(key, fields[key]);
    const token = await (await get(tokenUrl)).json();
    headers.Authorization = `Bearer ${token.token ?? token.access_token}`;
    response = await get(url, headers);
  }
  if (!response.ok) throw new Error(`Cannot resolve image: ${tag}`);
  const digest = `sha256:${sha(Buffer.from(await response.arrayBuffer()))}`;
  if (digest !== response.headers.get('docker-content-digest')) throw new Error(`Registry digest mismatch: ${tag}`);
  return digest;
}

if (next.openclaw.version !== before.openclaw.version) {
  for (const plugin of ['acpx', 'discord']) await get(`https://registry.npmjs.org/@openclaw%2f${plugin}/${next.openclaw.version}`);
  next.openclaw.digest = await imageDigest(`ghcr.io/openclaw/openclaw:${next.openclaw.version}`);
}

for (const section of ['buildArgs', 'infrastructure', 'automation']) {
  for (const [key, value] of Object.entries(next[section] ?? {})) {
    if (typeof value !== 'string' || !value.includes('@sha256:') || value === before[section]?.[key]) continue;
    const digest = await imageDigest(value);
    if (value.split('@')[1] !== digest) throw new Error(`Updater supplied stale digest: ${key}`);
  }
}

async function releaseArtifact(tool, version, arch) {
let url, digest;
if (tool === 'GO') {
  const releases = await (await get('https://go.dev/dl/?mode=json&include=all')).json();
  const artifact = releases.find(r => r.version === `go${version}`)?.files.find(f => f.os === 'linux' && f.arch === arch && f.kind === 'archive');
  if (!artifact) throw new Error(`Go release unavailable: ${version}/${arch}`);
  url = `https://go.dev/dl/${artifact.filename}`; digest = artifact.sha256;
} else if (tool === 'SHFMT') {
  const release = await (await get(`https://api.github.com/repos/mvdan/sh/releases/tags/v${version}`)).json();
  const asset = release.assets?.find(a => a.name === `shfmt_v${version}_linux_${arch}`);
  if (!/^sha256:[a-f0-9]{64}$/.test(asset?.digest)) throw new Error(`Missing published shfmt digest: ${version}/${arch}`);
  url = asset.browser_download_url; digest = asset.digest.slice(7);
} else if (tool === 'HADOLINT') {
  url = `https://github.com/hadolint/hadolint/releases/download/v${version}/hadolint-Linux-${arch === 'amd64' ? 'x86_64' : 'arm64'}`;
  digest = (await text(`${url}.sha256`)).trim().split(/\s+/)[0];
} else if (tool === 'HELM') {
  url = `https://get.helm.sh/helm-v${version}-linux-${arch}.tar.gz`;
  digest = (await text(`${url}.sha256sum`)).trim().split(/\s+/)[0];
} else if (tool === 'KUBECONFORM') {
  const name = `kubeconform-linux-${arch}.tar.gz`;
  const base = `https://github.com/yannh/kubeconform/releases/download/v${version}`;
  url = `${base}/${name}`; digest = await checksum(`${base}/CHECKSUMS`, name);
} else if (tool === 'KUBECTL') {
  url = `https://dl.k8s.io/release/v${version}/bin/linux/${arch}/kubectl`; digest = (await text(`${url}.sha256`)).trim();
} else {
  const names = { TERRAFORM: `terraform_${version}_linux_${arch}.zip`, TFLINT: `tflint_linux_${arch}.zip`, TRIVY: `trivy_${version}_Linux-${arch === 'amd64' ? '64bit' : 'ARM64'}.tar.gz` };
  const bases = { TERRAFORM: `https://releases.hashicorp.com/terraform/${version}`, TFLINT: `https://github.com/terraform-linters/tflint/releases/download/v${version}`, TRIVY: `https://github.com/aquasecurity/trivy/releases/download/v${version}` };
  const lists = { TERRAFORM: `terraform_${version}_SHA256SUMS`, TFLINT: 'checksums.txt', TRIVY: `trivy_${version}_checksums.txt` };
  url = `${bases[tool]}/${names[tool]}`; digest = await checksum(`${bases[tool]}/${lists[tool]}`, names[tool]);
}
  return { url, digest };
}

for (const [args, previous] of [[next.buildArgs, before.buildArgs],
  [next.imageOverrides['ops-pod'], before.imageOverrides['ops-pod']]]) {
for (const tool of ['GO', 'SHFMT', 'TERRAFORM', 'TFLINT', 'TRIVY', 'KUBECTL', 'HADOLINT', 'HELM', 'KUBECONFORM']) {
  if (!args[`${tool}_VERSION`] || args[`${tool}_VERSION`] === previous[`${tool}_VERSION`]) continue;
  const version = args[`${tool}_VERSION`].replace(/^v/, '');
  if (tool === 'KUBECTL' && args === next.imageOverrides['ops-pod']) {
    const moduleVersion = `v0.${version.split('.').slice(1).join('.')}`;
    if (!fs.readFileSync('ops/pod/kubectl-build/go.mod', 'utf8').includes(`k8s.io/kubectl ${moduleVersion}`)) {
      throw new Error('Update the Ops kubectl source module locks before changing its version');
    }
    continue;
  }
  for (const arch of ['amd64', 'arm64']) {
    console.log(`Verifying upstream ${tool} ${version} linux/${arch}`);
    const { url, digest } = await releaseArtifact(tool, version, arch);
    args[`${tool}_SHA256_${arch.toUpperCase()}`] = await verified(url, digest);
  }
}
}

if (next.buildArgs.GH_VERSION !== before.buildArgs.GH_VERSION) {
  const source = await get(`https://codeload.github.com/cli/cli/tar.gz/refs/tags/v${next.buildArgs.GH_VERSION}`);
  next.buildArgs.GH_SOURCE_SHA256 = sha(Buffer.from(await source.arrayBuffer()));
}

try {
  fs.writeFileSync(file, `${JSON.stringify(next, null, 2)}\n`);
  console.log(JSON.stringify(syncVersions(root, false)));
  console.log(JSON.stringify(updateRuntimeToolLocks(root)));
} catch (error) { fs.writeFileSync(file, original); throw error; }

scripts/vendor-external-helm-authorities.syntax:
function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right)).map(([key, item]) => [key, stable(item)]));
  return value;
}

function valueAt(value, tokens) {
  return tokens.reduce((current, token) => current?.[token], value);
}

function nearestValue(value, tokens) {
  for (let length = tokens.length; length >= 0; length -= 1) {
    const selected = valueAt(value, tokens.slice(0, length));
    if (selected !== undefined) {
      const encoded = JSON.stringify(stable(selected));
      return {
        path: tokens.slice(0, length),
        valueKind: Array.isArray(selected) ? 'array' : selected === null ? 'null' : typeof selected,
        valueSha256: sha256(encoded),
        value: encoded.length <= 1000 ? selected : undefined,
        topLevelKeys: encoded.length > 1000 && selected && typeof selected === 'object' ? Object.keys(selected).sort() : undefined,
      };
    }
  }
  throw new Error(`values.yaml has no ancestor for ${tokens.join('.')}`);
}

function schemaAt(schema, tokens) {
  let current = schema;
  const resolved = [];
  for (const token of tokens) {
    if (!current) break;
    if (typeof token === 'number') current = current.items;
    else current = current.properties?.[token] ?? (typeof current.additionalProperties === 'object' ? current.additionalProperties : null);
    if (!current) break;
    resolved.push(token);
  }
  if (!current) return null;
  const selected = Object.fromEntries(['type', 'description', 'default', 'enum', 'minimum', 'maximum', 'pattern', 'format', 'required']
    .filter((key) => current[key] !== undefined).map((key) => [key, current[key]]));
  return { path: resolved, contract: selected };
}

function walk(directory) {
  if (!fs.existsSync(directory)) return [];
  return fs.readdirSync(directory, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => path.join(entry.parentPath, entry.name));
}

function templateEvidence(chartDirectory, tokens) {
  const stringTokens = tokens.filter((token) => typeof token === 'string');
  const candidates = [];
  for (let length = stringTokens.length; length > 0; length -= 1) candidates.push(`.Values.${stringTokens.slice(0, length).join('.')}`);
  const result = [];
  for (const absolute of walk(path.join(chartDirectory, 'templates'))) {
    const lines = fs.readFileSync(absolute, 'utf8').split('\n');
    lines.forEach((line, index) => {
      const matchedPrefix = candidates.find((candidate) => line.includes(candidate));
      if (!matchedPrefix) return;
      const context = lines.slice(Math.max(0, index - 2), Math.min(lines.length, index + 3)).join('\n');
      result.push({
        path: path.relative(chartDirectory, absolute).replaceAll(path.sep, '/'),
        line: index + 1,
        matchedPrefix,
        context,
        contextSha256: sha256(context),
      });
    });
  }
  const mostSpecific = Math.max(0, ...result.map((item) => item.matchedPrefix.split('.').length));
  return result.filter((item) => item.matchedPrefix.split('.').length === mostSpecific)
    .sort((left, right) => `${left.path}:${left.line}`.localeCompare(`${right.path}:${right.line}`));
}

function extractChart(key, chart, archive, directory) {
  const archiveBytes = fs.readFileSync(archive);
  assert.equal(sha256(archiveBytes), chart.archiveSha256, `${key}: archive digest differs from the checked-in lock`);
  const extracted = path.join(directory, 'extracted');
  fs.mkdirSync(extracted);
  const untarred = spawnSync('tar', ['-xzf', archive, '-C', extracted], { encoding: 'utf8' });
  if (untarred.status !== 0) throw new Error(`${key}: chart extraction failed: ${untarred.stderr}`);
  const children = fs.readdirSync(extracted).map((name) => path.join(extracted, name)).filter((candidate) => fs.statSync(candidate).isDirectory());
  assert.equal(children.length, 1, `${key}: archive does not contain one chart directory`);
  return children[0];
}

function pullChart(key, chart, directory) {
  const isOci = !chart.repository.startsWith('http');
  const reference = isOci ? `oci://${chart.repository}/${chart.chart}` : chart.chart;
  const args = ['pull', reference, '--version', chart.version, '--destination', directory];
  if (!isOci) args.push('--repo', chart.repository);
  const pulled = spawnSync('helm', args, { cwd: root, encoding: 'utf8' });
  if (pulled.status !== 0) throw new Error(`failed to pull ${key}: ${pulled.stderr || pulled.stdout}`);
  const archives = fs.readdirSync(directory).filter((name) => name.endsWith('.tgz'));
  assert.equal(archives.length, 1, `${key}: expected one chart archive`);
  const archive = path.join(directory, archives[0]);
  const archiveBytes = fs.readFileSync(archive);
  assert.equal(sha256(archiveBytes), chart.archiveSha256, `${key}: archive digest differs from the checked-in lock`);
  return archive;
}

function inventoryExternalFields() {
  const inventory = JSON.parse(fs.readFileSync(inventoryPath, 'utf8'));
  const result = [];
  for (const file of inventory.files) for (const document of file.documents) for (const field of document.fields ?? []) {
    if (field.meaning?.status !== 'external-chart-authority') continue;
    result.push({ sourcePath: file.path, fieldPath: field.path, selectedValue: field.value, externalChart: field.meaning.externalChart });
  }
  return result;
}

function deriveArtifact(archiveManifest) {
  const fields = inventoryExternalFields();
  const output = { version: 2, generatedBy: 'scripts/vendor-external-helm-authorities.mjs', lockSha256: sha256(fs.readFileSync(lockPath)), archiveManifestSha256: sha256(fs.readFileSync(archiveManifestPath)), charts: {}, templateContexts: {}, fields: {} };
  const temporaryRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kubeclaw-external-helm-authority-'));
  try {
    for (const [key, chart] of Object.entries(lock.charts)) {
      const directory = path.join(temporaryRoot, key);
      fs.mkdirSync(directory);
      const archiveEntry = archiveManifest.charts[key];
      assert(archiveEntry, `${key}: vendored chart archive manifest entry is missing`);
      assert.equal(archiveEntry.sha256, chart.archiveSha256, `${key}: vendored archive manifest differs from chart lock`);
      const archive = path.join(root, archiveEntry.path);
      assert(fs.existsSync(archive), `${key}: vendored chart archive is missing: ${archiveEntry.path}`);
      const archiveBytes = fs.readFileSync(archive);
      assert.equal(archiveBytes.length, archiveEntry.size, `${key}: vendored archive byte count changed`);
      assert.equal(sha256(archiveBytes), archiveEntry.sha256, `${key}: vendored archive bytes changed`);
      const chartDirectory = extractChart(key, chart, archive, directory);
      const valuesBytes = fs.readFileSync(path.join(chartDirectory, 'values.yaml'));
      assert.equal(sha256(valuesBytes), chart.valuesSha256, `${key}: extracted values.yaml digest differs from the checked-in lock`);
      const schemaPath = path.join(chartDirectory, 'values.schema.json');
      const schemaBytes = fs.existsSync(schemaPath) ? fs.readFileSync(schemaPath) : null;
      if (chart.schemaSha256) {
        assert(schemaBytes, `${key}: locked schema is missing from archive`);
        assert.equal(sha256(schemaBytes), chart.schemaSha256, `${key}: extracted schema digest differs from the checked-in lock`);
      }
      const values = YAML.parse(valuesBytes.toString('utf8'));
      const schema = schemaBytes ? JSON.parse(schemaBytes) : null;
      output.charts[key] = { ...chart, extractedValuesSha256: sha256(valuesBytes), extractedSchemaSha256: schemaBytes ? sha256(schemaBytes) : null };
      for (const field of fields.filter((item) => item.externalChart.chart === chart.chart && item.externalChart.version === chart.version
        && item.externalChart.archiveSha256 === chart.archiveSha256)) {
        const tokens = yamlFieldPathTokens(field.fieldPath);
        const upstream = nearestValue(values, tokens);
        const schemaContract = schemaAt(schema, tokens);
        const templates = templateEvidence(chartDirectory, tokens);
        const templateContextIds = templates.map((template) => {
          const id = sha256(JSON.stringify(stable(template)));
          output.templateContexts[id] ??= template;
          return id;
        });
        const keyName = `${field.sourcePath}#${field.fieldPath}`;
        output.fields[keyName] = {
          chartKey: key,
          selectedValue: field.selectedValue,
          upstreamValue: upstream,
          schema: schemaContract,
          templateContextIds,
          authorityMode: templateContextIds.length ? 'extracted-template-and-values' : schemaContract ? 'extracted-schema-and-values' : 'extracted-values-nearest-ancestor',
        };
      }
    }
  } finally {
    fs.rmSync(temporaryRoot, { recursive: true, force: true });
  }
  return `${JSON.stringify(stable(output), null, 2)}\n`;
}

function refreshArtifact() {
  fs.mkdirSync(archiveDirectory, { recursive: true });
  const temporaryRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kubeclaw-external-helm-download-'));
  const manifest = { version: 1, generatedBy: 'scripts/vendor-external-helm-authorities.mjs --refresh', charts: {} };
  try {
    for (const [key, chart] of Object.entries(lock.charts)) {
      const directory = path.join(temporaryRoot, key);
      fs.mkdirSync(directory);
      const downloaded = pullChart(key, chart, directory);
      const fileName = `${chart.archiveSha256}.tgz`;
      const destination = path.join(archiveDirectory, fileName);
      fs.copyFileSync(downloaded, destination);
      const bytes = fs.readFileSync(destination);
      manifest.charts[key] = {
        chart: chart.chart,
        version: chart.version,
        repository: chart.repository,
        path: path.relative(root, destination).replaceAll(path.sep, '/'),
        sha256: sha256(bytes),
        size: bytes.length,
      };
    }
  } finally {
    fs.rmSync(temporaryRoot, { recursive: true, force: true });
  }
  const manifestBytes = `${JSON.stringify(stable(manifest), null, 2)}\n`;
  fs.writeFileSync(archiveManifestPath, manifestBytes);
  fs.writeFileSync(archiveManifestChecksumPath, `${sha256(manifestBytes)}  ${path.basename(archiveManifestPath)}\n`);
  const bytes = deriveArtifact(manifest);
  fs.writeFileSync(artifactPath, bytes);
  fs.writeFileSync(checksumPath, `${sha256(bytes)}  ${path.basename(artifactPath)}\n`);
}

function checkArtifact() {
  assert(fs.existsSync(artifactPath) && fs.existsSync(checksumPath), 'external Helm extracted authority artifact is missing; run with --refresh');
  assert(fs.existsSync(archiveManifestPath) && fs.existsSync(archiveManifestChecksumPath), 'vendored external Helm archive manifest is missing; run with --refresh');
  const manifestBytes = fs.readFileSync(archiveManifestPath);
  const [manifestExpected, manifestName] = fs.readFileSync(archiveManifestChecksumPath, 'utf8').trim().split(/\s+/u);
  assert.equal(manifestName, path.basename(archiveManifestPath), 'external Helm archive checksum names the wrong manifest');
  assert.equal(sha256(manifestBytes), manifestExpected, 'external Helm archive manifest bytes changed');
  const archiveManifest = JSON.parse(manifestBytes);
  const bytes = fs.readFileSync(artifactPath);
  const artifact = JSON.parse(bytes);
  const [expected, name] = fs.readFileSync(checksumPath, 'utf8').trim().split(/\s+/u);
  assert.equal(name, path.basename(artifactPath), 'external Helm snapshot checksum names the wrong file');
  assert.equal(sha256(bytes), expected, 'external Helm extracted authority bytes changed');
  const recomputedBytes = deriveArtifact(archiveManifest);
  assert.equal(bytes.toString('utf8'), recomputedBytes, 'external Helm authority snapshot does not match a fresh offline extraction from vendored chart archives');
  assert.equal(artifact.lockSha256, sha256(fs.readFileSync(lockPath)), 'external Helm extracted authority uses a different chart lock');
  const inventoryFields = inventoryExternalFields();
  assert.equal(Object.keys(artifact.fields).length, inventoryFields.length, 'external Helm extracted field count differs from the inventory');
  for (const field of inventoryFields) {
    const key = `${field.sourcePath}#${field.fieldPath}`;
    const proof = artifact.fields[key];
    assert(proof, `${key}: extracted external Helm authority is missing`);
    assert(proof.templateContextIds.length || proof.schema || proof.upstreamValue, `${key}: extracted authority has no vendored input`);
    assert.match(proof.upstreamValue?.valueSha256 ?? '', /^[a-f0-9]{64}$/u, `${key}: extracted upstream values evidence has no content digest`);
    for (const id of proof.templateContextIds) {
      const template = artifact.templateContexts[id];
      assert(template, `${key}: extracted template context ${id} is missing`);
      assert.equal(sha256(JSON.stringify(stable(template))), id, `${key}: extracted template context identity changed`);
      assert.equal(sha256(template.context), template.contextSha256, `${key}: extracted template context changed`);
    }
  }
  for (const [key, chart] of Object.entries(lock.charts)) assert.deepEqual(artifact.charts[key], {
    ...chart,
    extractedValuesSha256: chart.valuesSha256,
    extractedSchemaSha256: chart.schemaSha256 ?? null,
  }, `${key}: extracted chart coordinate or content digest differs from the lock`);
  console.log(`external Helm authority snapshots are current (${inventoryFields.length} exact fields across ${Object.keys(lock.charts).length} charts)`);
}

scripts/versions.mjs.syntax:
function validateVersionEntries(entries) {
    for (const [key, value] of Object.entries(entries)) {
      if (!/^[A-Z][A-Z0-9_]+$/.test(key) || typeof value !== 'string' || !/^[a-zA-Z0-9.:/@_-]+$/.test(value))
        throw new Error(`Invalid version field: ${key}`);
      if (key.includes('SHA256') && !/^[a-f0-9]{64}$/.test(value)) throw new Error(`Invalid checksum: ${key}`);
      if (key.endsWith('_BASE') && !/@sha256:[a-f0-9]{64}$/.test(value)) throw new Error(`Unpinned base image: ${key}`);
    }
}

function versionArguments(manifest) {
  if (manifest.schemaVersion !== 1 || !/^\d{4}\.\d+\.\d+(?:-\d+)?$/.test(manifest.openclaw?.version)
    || !/^sha256:[a-f0-9]{64}$/.test(manifest.openclaw?.digest)) throw new Error('Invalid OpenClaw version manifest');
  for (const key of ['OPENCLAW_BASE', 'OPENCLAW_PLUGIN_VERSION']) {
    if (Object.hasOwn(manifest.buildArgs, key)) throw new Error(`OpenClaw must have one authority: ${key}`);
  }
  const args = { ...manifest.buildArgs,
    OPENCLAW_BASE: `ghcr.io/openclaw/openclaw:${manifest.openclaw.version}@${manifest.openclaw.digest}`,
    OPENCLAW_PLUGIN_VERSION: manifest.openclaw.version };
  validateVersionEntries(args);
  return args;
}

function dockerfileVersions(name, source, args, overrides, used) {
    const usedOverrides = new Set();
    const content = source.replace(/^ARG ([A-Z0-9_]+)=(\S+)$/gm, (line, key) => {
      if (['KUBECLAW_BUILD_REVISION', 'TARGETARCH'].includes(key)) return line;
      if (name === 'docker/Dockerfile.buster-runtime' && key === 'TRIVY_DATABASE_REFRESH') return line;
      if (!Object.hasOwn(args, key)) throw new Error(`${name}: unmanaged version argument ${key}`);
      used.add(key);
      if (Object.hasOwn(overrides, key)) usedOverrides.add(key);
      return `ARG ${key}=${overrides[key] ?? args[key]}`;
    });
    for (const key of Object.keys(overrides)) if (!usedOverrides.has(key)) throw new Error(`${name}: unused override ${key}`);
    for (const match of content.matchAll(/^FROM (\S+)/gm)) {
      if (!/^\$\{[A-Z0-9_]+\}$/.test(match[1])) throw new Error(`${name}: base must reference a managed ARG`);
      if (!Object.hasOwn(args, match[1].slice(2, -1))) throw new Error(`${name}: unknown base argument`);
    }
  return content;
}

function bindDockerVersions(root, manifest, args, read, outputs) {
  const used = new Set();
  const dockerfiles = new Map(fs.readdirSync(path.join(root, 'docker')).filter(file => file.startsWith('Dockerfile.')).sort()
    .map(file => [file.slice('Dockerfile.'.length), `docker/${file}`]));
  dockerfiles.set('ops-pod', 'ops/pod/Dockerfile');
  dockerfiles.set('ops-mcp', 'tools/ops-mcp/Dockerfile');
  for (const [image, overrides] of Object.entries(manifest.imageOverrides ?? {})) {
    if (!dockerfiles.has(image)) throw new Error(`Unknown image override: ${image}`);
    if (Object.keys(overrides).some(key => key.startsWith('OPENCLAW_'))) throw new Error('OpenClaw versions must match across roles');
    validateVersionEntries(overrides);
  }
  for (const [image, name] of dockerfiles) {
    outputs.set(name, dockerfileVersions(name, read(name), args, manifest.imageOverrides?.[image] ?? {}, used));
  }
  for (const key of Object.keys(args)) if (!used.has(key)) throw new Error(`Unused central version: ${key}`);
}

function bindInfrastructureVersions(manifest, replaceOne) {
  for (const name of ['spire', 'spire-crds', 'csi-driver-smb']) {
    const version = manifest.platformCharts?.[name]?.version;
    if (!/^\d+\.\d+\.\d+$/.test(version ?? '')) throw new Error('Invalid platform chart version: ' + name);
    replaceOne('gitops/platform/bootstrap/' + name + '.yaml', new RegExp('chart: ' + name + '\\n      targetRevision: [^\\n]+'),
      'chart: ' + name + '\n      targetRevision: ' + version);
  }
  if (!/^ghcr\.io\/berriai\/litellm:[a-zA-Z0-9._-]+@sha256:[a-f0-9]{64}$/.test(manifest.litellmProduction?.image ?? '')) throw new Error('Invalid production LiteLLM image');
  replaceOne('gitops/platform/litellm/resources.yaml', /^          image: [^\n]+$/m, '          image: ' + manifest.litellmProduction.image);

  for (const [name, chart] of Object.entries({ prometheus: 'kube-prometheus-stack', loki: 'loki', alloy: 'alloy', promtail: 'promtail' })) {
    const version = manifest.monitoringCharts?.[name]?.version;
    if (!/^\d+\.\d+\.\d+$/.test(version ?? '')) throw new Error(`Invalid monitoring chart version: ${name}`);
    replaceOne(`gitops/platform/bootstrap/${name}.yaml`, new RegExp(`chart: ${chart}\\n      targetRevision: [^\\n]+`),
      `chart: ${chart}\n      targetRevision: ${version}`);
  }

  for (const name of ['redis', 'postgresql']) {
    const selected = manifest[`${name}Production`];
    const image = selected?.image?.match(/^(registry-1\.docker\.io)\/(bitnami\/(?:redis|postgresql)):([a-zA-Z0-9._-]+)@(sha256:[a-f0-9]{64})$/);
    if (!image || image[2] !== `bitnami/${name}` || !/^\d+\.\d+\.\d+$/.test(selected?.chartVersion ?? '')) throw new Error(`Invalid production ${name} chart version or image digest`);
    replaceOne(`gitops/platform/values/${name}.yaml`, /^image:\n  registry: [^\n]+\n  repository: [^\n]+\n  tag: [^\n]+\n  digest: [^\n]+/m,
      `image:\n  registry: ${image[1]}\n  repository: ${image[2]}\n  tag: ${image[3]}\n  digest: ${image[4]}`);
    replaceOne(`gitops/platform/bootstrap/${name}.yaml`, new RegExp(`chart: ${name}\\n      targetRevision: [^\\n]+`),
      `chart: ${name}\n      targetRevision: ${selected.chartVersion}`);
  }

  for (const reference of [...Object.values(manifest.infrastructure ?? {}), ...Object.values(manifest.automation ?? {})]) {
    if (typeof reference !== 'string' || !/^[a-z0-9./_-]+:[a-zA-Z0-9._-]+@sha256:[a-f0-9]{64}$/.test(reference))
      throw new Error('Infrastructure and automation images require exact tags and digests');
  }
  for (const name of ['tailscale', 'redis', 'postgresql']) validateInfrastructureChartLock(manifest.infrastructureCharts?.[name]);
  for (const name of ['redis', 'postgresql']) {
    const reference = manifest.infrastructure[name].match(/^([^/]+)\/(.+):([^:@]+)@(sha256:[a-f0-9]{64})$/);
    replaceOne(`my-values/infra/${name}-values.yaml`, /^image:\n  registry: [^\n]+\n  repository: [^\n]+\n  tag: [^\n]+\n  digest: [^\n]+/m,
      `image:\n  registry: ${reference[1]}\n  repository: ${reference[2]}\n  tag: ${reference[3]}\n  digest: ${reference[4]}`);
  }
  for (const [section, key] of [['operatorConfig', 'tailscaleOperator'], ['proxyConfig', 'tailscaleProxy']]) {
    const reference = manifest.infrastructure[key].match(/^(.+):([^:@]+)@(sha256:[a-f0-9]{64})$/);
    replaceOne('my-values/infra/tailscale-operator-values.yaml',
      new RegExp(`^${section}:\\n  image:\\n    repository: [^\\n]+\\n    digest: [^\\n]+`, 'm'),
      `${section}:\n  image:\n    repository: ${reference[1]}\n    digest: ${reference[3]}`);
  }
  replaceOne('my-values/infra/registry-mirror.yaml', /^          image: [^\n]+$/m,
    `          image: ${manifest.infrastructure.registryMirror}`);
  const envoy = manifest.infrastructure.envoy.match(/^(.+):([^:@]+)@(sha256:[a-f0-9]{64})$/);
  for (const file of ['charts/kubeclaw/values.yaml', 'charts/prism/values.yaml']) {
    replaceOne(file, /^      repository: envoyproxy\/envoy$/m, `      repository: ${envoy[1]}`);
    replaceOne(file, /^      tag: v[0-9.]+$/m, `      tag: ${envoy[2]}`);
    replaceOne(file, /^      digest: "[^"]*"$/m, `      digest: "${envoy[3]}"`);
  }
}

function bindApplicationVersions(manifest, args, replaceOne) {
  replaceOne('charts/kubeclaw/Chart.yaml', /^appVersion:.*$/m, `appVersion: "${manifest.openclaw.version}"`);
  for (const plugin of ['acpx', 'discord']) replaceOne('charts/kubeclaw/values.yaml',
    new RegExp(`^    - "npm:@openclaw/${plugin}@[^"\\n]+"$`, 'm'), `    - "npm:@openclaw/${plugin}@${manifest.openclaw.version}"`);
  replaceOne('charts/kubeclaw/files/config/lint-policy.json', /"kubernetes_version": "[^"]+"/,
    `"kubernetes_version": "${args.KUBECTL_VERSION}"`);
  replaceOne('charts/kubeclaw/files/config/lint-policy.json', /"schema_location": "[^"]+"/,
    `"schema_location": "/opt/kubeclaw-kubernetes-schemas/v${args.KUBECTL_VERSION}-standalone-strict/{{.ResourceKind}}{{.KindSuffix}}.json"`);
  replaceOne('skills/common/plugins/openclaw-agent-observer/package.json', /"openclawVersion": "[^"]+"/,
    `"openclawVersion": "${manifest.openclaw.version}"`);
  replaceOne('.github/workflows/build-ops-mcp.yaml', /^          version: v\d+\.\d+\.\d+$/m,
    `          version: ${manifest.imageOverrides['ops-pod'].HELM_VERSION}`, 2);
  replaceOne('.github/workflows/update-checks.yaml', /^          version: v\d+\.\d+\.\d+$/m,
    `          version: v${args.HELM_VERSION}`);
  replaceOne('.github/workflows/pipeline-reliability.yaml', /^          version: v\d+\.\d+\.\d+$/m,
    `          version: v${args.HELM_VERSION}`);
  for (const [shellKey, key] of [['TRIVY_VERSION', 'TRIVY_VERSION'], ['TRIVY_AMD64_SHA256', 'TRIVY_SHA256_AMD64'], ['TRIVY_ARM64_SHA256', 'TRIVY_SHA256_ARM64']])
    replaceOne('scripts/scan-runtime-images.sh', new RegExp(`^readonly ${shellKey}="[^"]+"$`, 'm'), `readonly ${shellKey}="${args[key]}"`);
}

function bindRuntimeToolInputs(manifest, args, outputs) {
  const tools = [['RUFF_VERSION', 'ruff'], ['MYPY_VERSION', 'mypy'], ['PIP_AUDIT_VERSION', 'pip-audit']];
  const requirements = entries => '# Generated from versions.json; use scripts/versions.mjs\n'
    + entries.map(([name, version]) => `${name}==${version}\n`).join('');
  const common = tools.map(([key, name]) => [name, args[key]]);
  outputs.set('docker/python-tools/common.in', requirements(common));
  outputs.set('docker/python-tools/semgrep-nova.in', requirements([['semgrep', args.SEMGREP_VERSION]]));
  outputs.set('docker/python-tools/buster.in', requirements([...common,
    ['semgrep', manifest.imageOverrides['buster-runtime'].SEMGREP_VERSION ?? args.SEMGREP_VERSION]]));
  outputs.set('docker/go-tools/requirements.json', JSON.stringify(Object.fromEntries(
    ['GO_VERSION', 'STATICCHECK_VERSION', 'GOVULNCHECK_VERSION', 'GOCYCLO_VERSION'].map(key => [key, args[key]])), null, 2) + '\n');
}

export function versionOutputs(root) {
  const read = file => fs.readFileSync(path.join(root, file), 'utf8');
  const manifest = JSON.parse(read('versions.json'));
  const args = versionArguments(manifest);
  const outputs = new Map();
  bindDockerVersions(root, manifest, args, read, outputs);
  const replaceOne = (file, regex, replacement, expectedCount = 1) => {
    const source = outputs.get(file) ?? read(file);
    if ([...source.matchAll(new RegExp(regex.source, 'gm'))].length !== expectedCount) throw new Error(`${file}: version field missing or ambiguous`);
    outputs.set(file, source.replace(new RegExp(regex.source, 'gm'), replacement));
  };
  replaceOne('scripts/deploy.sh', /^BUILDKIT_ROOTLESS_PREFLIGHT_IMAGE="[^"\n]+"$/m,
    `BUILDKIT_ROOTLESS_PREFLIGHT_IMAGE="${'${BUILDKIT_ROOTLESS_PREFLIGHT_IMAGE:-'}${manifest.imageOverrides?.['buster-runtime']?.BUILDKIT_BASE ?? args.BUILDKIT_BASE}}"`);
  bindInfrastructureVersions(manifest, replaceOne);
  bindApplicationVersions(manifest, args, replaceOne);
  bindRuntimeToolInputs(manifest, args, outputs);
  return outputs;
}

export function syncVersions(root, check = true) {
  const outputs = versionOutputs(root);
  const changed = [...outputs].filter(([file, content]) => fs.readFileSync(path.join(root, file), 'utf8') !== content);
  if (check && changed.length) throw new Error(`Version drift; run npm run versions:sync:\n${changed.map(([file]) => file).join('\n')}`);
  if (!check) for (const [file, content] of changed) fs.writeFileSync(path.join(root, file), content);
  return { checked: outputs.size, changed: changed.map(([file]) => file) };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 3 || !['--check', '--write'].includes(process.argv[2])) throw new Error('Usage: node scripts/versions.mjs --check|--write');
  console.log(JSON.stringify(syncVersions(fileURLToPath(new URL('../', import.meta.url)), process.argv[2] === '--check')));
  if (process.argv[2] === '--check') console.log(JSON.stringify(checkRuntimeToolLocks()));
}

