const TEMPLATES = Object.freeze({
  'node-static@1': Object.freeze({
    id: 'node-static',
    version: '1',
    dockerfile: [
      'FROM docker.io/library/node@sha256:752ea8a2f758c34002a0461bd9f1cee4f9a3c36d48494586f60ffce1fc708e0e AS build',
      'WORKDIR /src',
