      'RUN npm ci',
      'COPY . .',
      'RUN npm run build',
      'FROM docker.io/library/nginx@sha256:65645c7bb6a0661892a8b03b89d0743208a18dd2f3f17a54ef4b76fb8e2f2a10',
      'COPY --from=build /src/dist/ /usr/share/nginx/html/',
