    const entry = object(raw, 'VISUAL_MANIFEST_INVALID'); exact(entry, ['id', 'route', 'profile', 'baselineFile', 'sha256', 'browser', 'browserVersion', 'viewport', 'pageConditions'], 'VISUAL_MANIFEST_INVALID');
