function issueMessage(issue: any) {
  if (issue.Message) return issue.Message;
  if (issue.Title) return issue.Title;
  return 'Kubernetes security misconfiguration';
}

function unquote(value: any) {
  return value?.trim().replace(/^['"]|['"]$/g, '') || null;
}

function documentAtLine(rendered: any, lineNumber: any) {
  const lines = rendered.split('\n');
  const lineIndex = Math.max(0, Math.min(lines.length - 1, Number(lineNumber || 1) - 1));
  let start = lineIndex;
  while (start > 0 && lines[start].trim() !== '---') start -= 1;
  if (lines[start].trim() === '---') start += 1;
  let end = lineIndex + 1;
  while (end < lines.length && lines[end].trim() !== '---') end += 1;
  return lines.slice(start, end);
}

function metadataLines(document: any) {
  const metadataIndex = document.findIndex((line: any) => /^metadata:\s*$/.test(line));
  if (metadataIndex < 0) return [];
  const lines: any[] = [];
  for (const line of document.slice(metadataIndex + 1)) {
    if (line.trim() && !/^\s/.test(line)) break;
    lines.push(line);
  }
  return lines;
}

function resourceIdentity(rendered: any, lineNumber: any) {
  const document = documentAtLine(rendered, lineNumber);
  const kind = unquote(document.find((line: any) => /^kind:\s*\S+/.test(line))?.replace(/^kind:\s*/, ''));
  const metadata = metadataLines(document);
  const name = unquote(metadata.find((line: any) => /^\s+name:\s*\S+/.test(line))?.replace(/^\s+name:\s*/, ''));
  const namespace = unquote(metadata.find((line: any) => /^\s+namespace:\s*\S+/.test(line))?.replace(/^\s+namespace:\s*/, '')) || 'default';
  return kind && name ? `${kind}:${namespace}:${name}` : 'unresolved-resource';
}

function trivyFinding(ctx: any, chartDir: any, rendered: any, issue: any, occurrence: any) {
  const code = issue.ID || 'trivy-kubernetes';
  const message = issueMessage(issue);
  const resource = resourceIdentity(rendered, issue.CauseMetadata?.StartLine);
  return {
    file: chartDir,
    line: issue.CauseMetadata?.StartLine ?? null,
    column: null,
    severity: 'error',
    code,
    message,
    fingerprint_seed: { chart: path.relative(ctx.repoRoot, chartDir).split(path.sep).join('/'), resource, code, message, occurrence },
  };
}

function trivyFindings(ctx: any, chartDir: any, rendered: any, issues: any) {
  const occurrences = new Map();
  return issues.map((issue: any) => {
    const resource = resourceIdentity(rendered, issue.CauseMetadata?.StartLine);
    const identity = JSON.stringify({ resource, code: issue.ID, message: issueMessage(issue) });
    const occurrence = (occurrences.get(identity) || 0) + 1;
    occurrences.set(identity, occurrence);
    return trivyFinding(ctx, chartDir, rendered, issue, occurrence);
  });
}

async function runTrivyKubernetes(ctx: any) {
  const findings: any[] = [];
  for (const chartDir of configuredMarkerDirectories(ctx, 'Chart.yaml')) {
    const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'kubeclaw-trivy-kubernetes-'));
    const manifestPath = path.join(tempDir, 'rendered.yaml');
    try {
      const rendered = await renderChart(ctx, chartDir);
      fs.writeFileSync(manifestPath, rendered);
      const args = ['config', '--quiet', '--format', 'json', '--misconfig-scanners', 'kubernetes', '--severity', 'HIGH,CRITICAL', '--skip-check-update', '--skip-version-check', '--exit-code', '1', ...ctx.tool.arguments, manifestPath];
      const result = requireToolExecution(await safeExec('trivy', args, { signal: ctx.signal, cwd: ctx.repoRoot, timeout: ctx.tool.timeout_ms }), 'trivy-kubernetes');
      const parsed = tryParseJson(result.stdout);
      if (!parsed.ok) return failParse(ctx, 'trivy-kubernetes', parsed, result, chartDir);
      if (result.exitCode !== 0 && result.exitCode !== 1) return failParse(ctx, 'trivy-kubernetes', { error: `unexpected exit code ${result.exitCode}` }, result, chartDir);
      const results = Array.isArray(parsed.data?.Results) ? parsed.data.Results : [];
      const issues = results.flatMap((entry: any) => Array.isArray(entry.Misconfigurations) ? entry.Misconfigurations : []);
      findings.push(...trivyFindings(ctx, chartDir, rendered, issues));
      if (result.exitCode !== 0 && issues.length === 0) return failParse(ctx, 'trivy-kubernetes', { error: 'non-zero exit without misconfigurations' }, result, chartDir);
    } finally {
      fs.rmSync(tempDir, { recursive: true, force: true });
    }
  }
  return { errors: findings.length, warnings: 0, findings };
}

function registerKubernetesSecurityTools(registerTool: any) {
  registerTool({
    id: 'trivy-kubernetes',
    name: 'Trivy Kubernetes',
    binary: 'trivy',
    tier: 'full',
    detect: (ctx: any) => ctx.projectTypes.has('helm'),
    run: runTrivyKubernetes,
  });
}

skills/nova/project_setup/tools/progress.syntax:
import {
  errorMessage,
  readJsonIfExists,
  relFromRepo,
  writeJson,
} from './progress-scaffold-values.ts';

function requireValue(argv: string[], index: number, flag: string) {
  const value = argv[index];
  if (!value || value.startsWith('--')) throw new Error(`${flag} requires a value.`);
  return value;
}

function parseArgs(argv: string[]): Args {
  const args: Args = {
    apply: false,
    check: false,
    print: false,
    help: false,
    project: null,
    repo: null,
    swarm: null,
    scaffold: null,
  };
  const valueFlags: Record<string, keyof Pick<Args, 'project' | 'repo' | 'swarm' | 'scaffold'>> = {
    '--project': 'project',
    '--repo': 'repo',
    '--swarm': 'swarm',
    '--scaffold': 'scaffold',
  };
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === '--apply') args.apply = true;
    else if (argument === '--check') args.check = true;
    else if (argument === '--print') args.print = true;
    else if (argument === '--help' || argument === '-h') args.help = true;
    else if (argument && valueFlags[argument]) args[valueFlags[argument]] = requireValue(argv, ++index, argument);
    else throw new Error(`Unknown argument: ${argument}`);
  }
  if (args.apply && args.check) throw new Error('Use either --apply or --check, not both.');
  if (!args.help && !args.project && !args.swarm) throw new Error('Provide --project <name> or --swarm <path>.');
  return args;
}

function findRepoRoot(startDir = process.cwd()) {
  let current = path.resolve(startDir);
  for (;;) {
    if (fs.existsSync(path.join(current, '.git'))) return current;
    const parent = path.dirname(current);
    if (parent === current) throw new Error('Cannot find repository root. Pass --repo <path>.');
    current = parent;
  }
}

function safeProject(value: unknown) {
  if (typeof value !== 'string' || !value.trim()) throw new Error('project must be a non-empty string.');
  if (!/^[A-Za-z0-9._-]+$/.test(value) || value.includes('..')) throw new Error(`project must be a safe path segment: ${value}`);
  return value;
}

function inferProject(swarmDir: string) {
  const parts = swarmDir.split(path.sep);
  const projectsIndex = parts.lastIndexOf('Projects');
  return projectsIndex >= 0 ? parts[projectsIndex + 1] : null;
}

function resolveContext(args: Args): Context {
  const repoRoot = path.resolve(args.repo ?? findRepoRoot());
  if (!fs.existsSync(path.join(repoRoot, '.git'))) throw new Error(`Repo root is not a git repository: ${repoRoot}`);
  const swarmDir = args.swarm
    ? path.resolve(args.swarm)
    : path.join(repoRoot, 'Projects', safeProject(args.project), 'src', '.swarm');
  const project = args.project ?? inferProject(swarmDir);
  if (!project) throw new Error('Cannot infer project name from --swarm; pass --project too.');
  return {
    repoRoot,
    project,
    swarmDir,
    scaffoldFile: args.scaffold ? path.resolve(args.scaffold) : path.join(swarmDir, DEFAULT_SCAFFOLD_FILE),
    progressFile: path.join(swarmDir, 'progress.json'),
    pipelineFile: path.join(swarmDir, 'pipeline.json'),
  };
}

function printDiagnostics(diagnostics: Diagnostic[]) {
  if (!diagnostics.length) {
    console.log('progress scaffold validation passed');
    return;
  }
  console.log(`progress scaffold diagnostics (${diagnostics.length}):`);
  diagnostics.forEach((item) => console.log(`- [${item.kind}] ${item.field}: ${item.message}`));
}

function diffSummary(existing: unknown, next: unknown) {
  if (!existing) return 'progress.json will be created';
  const before = JSON.stringify(existing, null, 2);
  const after = JSON.stringify(next, null, 2);
  if (before === after) return 'progress.json is already current';
  return `progress.json will change (${before.split('\n').length} -> ${after.split('\n').length} JSON lines)`;
}

async function applyScaffold(args: Args, context: Context) {
  const scaffold = readJsonIfExists(context.scaffoldFile);
  if (!scaffold) throw new Error(`Scaffold file not found. Run without --apply first: ${context.scaffoldFile}`);
  const { progress, pipeline, diagnostics } = scaffoldToProgress(scaffold, context);
  printDiagnostics(diagnostics);
  if (args.check) return 0;
  if (args.print) {
    console.log(JSON.stringify({ progress, pipeline }, null, 2));
    return 0;
  }
  console.log(diffSummary(readJsonIfExists(context.progressFile), progress));
  await publishJsonPair(context.swarmDir,['progress.json','pipeline.json'],[progress,pipeline]);
  console.log(`wrote ${relFromRepo(context.repoRoot, context.progressFile)}`);
  console.log(`wrote ${relFromRepo(context.repoRoot, context.pipelineFile)}`);
  return 0;
}

export async function run(argv: string[] = process.argv.slice(2)): Promise<number> {
  const args = parseArgs(argv);
  if (args.help) {
    console.log(usage());
    return 0;
  }
  const context = resolveContext(args);
  if (!fs.existsSync(context.swarmDir)) throw new Error(`.swarm directory not found: ${context.swarmDir}`);
  if (args.apply || args.check || args.print) return applyScaffold(args, context);
  const scaffold = buildScaffold(context);
  writeJson(context.scaffoldFile, scaffold);
  console.log(`wrote ${relFromRepo(context.repoRoot, context.scaffoldFile)}`);
  printDiagnostics(validateScaffold(scaffold, context));
  console.log('Next: fill the progress and provider-plan gaps, then rerun with --apply.');
  return 0;
}

if (isCli) {
  try {
    process.exitCode = await run();
  } catch (error) {
    const scaffoldError = error as Error & { diagnostics?: Diagnostic[] };
    console.error(errorMessage(error));
    if (scaffoldError.diagnostics) printDiagnostics(scaffoldError.diagnostics);
    process.exitCode = 1;
  }
}

