export function inputDigest(root, revision, predicate) {
  if (!/^[a-f0-9]{40}$/u.test(revision)) throw new Error('INPUT_REVISION_REQUIRED');
  const entries = execFileSync('git', ['-C', root, 'ls-tree', '-rz', revision], { encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 })
    .split('\0').filter(Boolean).filter(entry => predicate(entry.slice(entry.indexOf('\t') + 1))).map(entry => {
      if (!entry.endsWith('\tversions.json')) return entry;
      const versions = JSON.parse(execFileSync('git', ['-C', root, 'show', `${revision}:versions.json`], { encoding: 'utf8' }));
      // Infra-only chart bumps do not change the agent environment.
      return `versions.json\t${JSON.stringify({ openclaw: versions.openclaw, buildArgs: versions.buildArgs, imageOverrides: versions.imageOverrides })}`;
    }).sort();
  return createHash('sha256').update(entries.join('\0')).digest('hex');
}

if (process.argv[1] === import.meta.filename) {
  const root = process.cwd(), head = process.env.GITHUB_SHA;
  const event = JSON.parse(fs.readFileSync(process.env.GITHUB_EVENT_PATH, 'utf8'));
  const before = event.pull_request?.base.sha ?? event.before;
  const manual = process.env.GITHUB_EVENT_NAME === 'workflow_dispatch';
  const changed = predicate => manual || !before || /^0+$/u.test(before)
    || inputDigest(root, before, predicate) !== inputDigest(root, head, predicate);
  const deployment = changed(isDeploymentInput);
  const selection = 'releases/runtime-images.json';
  // Compare production builds with the selected image, not just the last push:
  // a preceding build may have failed or been superseded before selection.
  const selectedCommit = fs.existsSync(selection) ? JSON.parse(fs.readFileSync(selection, 'utf8')).commit : undefined;
  const images = deployment && (changed(isImageInput) || (process.env.GITHUB_EVENT_NAME !== 'pull_request'
    && (!selectedCommit || inputDigest(root, selectedCommit, isImageInput) !== inputDigest(root, head, isImageInput))));
  fs.appendFileSync(process.env.GITHUB_OUTPUT, `image_inputs=${images}\ndeployment_inputs=${deployment}\n`);
}

skills/buster/engine/test-gates/fixture-.syntax:
function fixtures(inputs: readonly ResolvedInputV1[]): Record<string, unknown>[] {
  return inputs.filter(input => input.kind === 'value' && FIXTURES.has(input.schemaId)).map(input => {
    if (input.kind !== 'value' || !input.value || typeof input.value !== 'object' || Array.isArray(input.value)) throw new Error('FIXTURE_AUTHORITY_INVALID');
    const value = input.value as Record<string, unknown>;
    if (value.schemaVersion !== FIXTURES.get(input.schemaId) || typeof value.expiresAt !== 'string'
      || !Number.isFinite(Date.parse(value.expiresAt))) throw new Error('FIXTURE_AUTHORITY_INVALID');
    if (Date.parse(value.expiresAt) <= Date.now()) throw new Error('FIXTURE_AUTHORITY_EXPIRED');
    return value;
  });
}

export function fixtureAuthoritySignal(inputs: readonly ResolvedInputV1[], signal: AbortSignal): AbortSignal {
  if (signal.aborted) return signal;
  const values = fixtures(inputs);
  if (!values.length) return signal;
  const remaining = Math.min(...values.map(value => Date.parse(value.expiresAt as string))) - Date.now();
  if (remaining <= 0) throw new Error('FIXTURE_AUTHORITY_EXPIRED');
  return AbortSignal.any([signal, AbortSignal.timeout(Math.min(remaining, 2_147_483_647))]);
}

export function fixtureOrigins(inputs: readonly ResolvedInputV1[]): Set<string> {
  const origins = new Set<string>();
  for (const value of fixtures(inputs)) {
    const urls = value.schemaVersion === 'public-endpoint-fixture.v1' ? [value.url]
      : Array.isArray(value.endpoints) && value.endpoints.length > 0 && value.endpoints.length <= 64
        ? value.endpoints.map(endpoint => endpoint?.url) : [];
    if (!urls.length) throw new Error('FIXTURE_AUTHORITY_INVALID');
    for (const raw of urls) {
      if (typeof raw !== 'string') throw new Error('FIXTURE_AUTHORITY_INVALID');
      const url = new URL(raw);
      if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash || url.search) throw new Error('FIXTURE_AUTHORITY_INVALID');
      origins.add(url.origin);
    }
  }
  return origins;
}

