export async function agentAttempt(job:{id:string;fence:string;expires_at:string|Date;request_digest:string;request:Record<string,unknown>},runnerId:string):Promise<WorkerAttemptEnvelopeV2> {
  const files=['agent-process.ts','agent-attempt.ts','agent-job-runner.mjs','agent-prompt.mjs','preference-prompt.mjs'];
  const content=await Promise.all(files.map(async file=>({file,digest:sha256Text(await readFile(new URL(file,import.meta.url),'utf8'))})));
  const unsignedProfile={schemaVersion:'worker-profile.v2' as const,profileId:'prism-openclaw-launcher-v2',workerType:'prism-agent',coreContractId:'kubeclaw.pipeline-worker-core@2',
    engine:{engineId:'prism-openclaw-launcher',contractId:'kubeclaw.prism-agent-launcher@1',engineVersion:'2.0.0',contentDigest:sha256Digest(content)},capabilities:['openclaw.agent','artifacts.write'],resourceCapabilities:{
      schemaVersion:'worker-resource-capabilities.v1' as const,
      cpuTimeMs:unavailable('milliseconds'),maximumMemoryBytes:unavailable('bytes'),maximumProcesses:unavailable('processes'),
    }};
  const profile:WorkerProfileV2={...unsignedProfile,profileDigest:workerProfileDigest(unsignedProfile)};
  const expiresAt=new Date(job.expires_at).toISOString();const now=new Date().toISOString();
  const unsigned={schemaVersion:'worker-attempt-envelope.v2' as const,protocolVersion:'worker-protocol.v1' as const,
    pipelineRunId:`prism-${job.id}`,moduleId:null,gateId:null,planId:`prism-${job.id}`,nodeId:'openclaw-agent',executionId:job.id,
    attemptId:job.fence,attemptNumber:1,claim:{schemaVersion:'attempt-claim.v1' as const,claimId:job.fence,attemptId:job.fence,generation:1,workerId:runnerId,claimedAt:now,expiresAt},profile,packages:[],grantedCapabilities:[...profile.capabilities],
    limits:{timeoutMs:900_000,cleanupTimeoutMs:10_000,logBytes:1_048_576,resultBytes:1_048_576,evidenceBytes:2_097_152,evidenceFiles:2},
    resourceBudgets:{schemaVersion:'worker-resource-budgets.v1' as const,cpuTimeMs:{state:'unrequested' as const},maximumMemoryBytes:{state:'unrequested' as const},maximumProcesses:{state:'unrequested' as const}},
    inputs:[],operation:{contractId:'kubeclaw.prism-agent-launcher@1',inputSchemaId:'prism-agent-job.v1',inputSchemaDigest:sha256Digest({type:'object',required:['jobId','requestDigest','request']}),values:{jobId:job.id,requestDigest:job.request_digest,request:job.request as JsonValue}},
    cancellationId:job.fence,issuedAt:now,queueDeadline:expiresAt};
  return {...unsigned,attemptSpecDigest:workerAttemptSpecDigest(unsigned)};
}

skills/prism/server/agent-process.ts.syntax:
export class AgentProcess implements WorkerAttemptOperation<WorkerAttemptEnvelopeV2> {
  private child:ChildProcess|undefined;
  private closed:Promise<void>|undefined;
  private streamsClosed=false;
  private readonly executable:string;
  private readonly args:string[];
  constructor(executable:string,args:string[]) {this.executable=executable;this.args=args;}
  prepare(_limits:WorkerAttemptLimitsV2){return undefined;}
  execute(context:WorkerAttemptContext<WorkerAttemptEnvelopeV2>) {
    if(this.child)throw new Error('Prism external action has already been started');
    context.signal.throwIfAborted();
    const child=spawn(this.executable,this.args,{stdio:['ignore','pipe','pipe'],detached:true});
    this.child=child;
    this.closed=new Promise(resolve=>child.once('close',()=>{this.streamsClosed=true;resolve();}));
    child.stdout!.on('data',(chunk:Buffer)=>context.log('stdout',chunk));
    child.stderr!.on('data',(chunk:Buffer)=>context.log('stderr',chunk));
    return new Promise<{summary:string;specialistResult:{schemaId:string;schemaDigest:string;values:{localProcessClosed:boolean}};evidence:[];exitCode:number|null;signal:string|null}>((resolve,reject)=>{
      child.once('error',reject);
      child.once('close',(code,signal)=>{
        if(code!==0)return reject(new Error(`OpenClaw CLI closed with code ${code}, signal ${signal}; gateway action requires reconciliation`));
        resolve({summary:'OpenClaw CLI closed; authoritative success requires the fenced Control receipt',specialistResult:{schemaId:'prism-agent-launcher-result.v1',schemaDigest:sha256Digest({type:'object',required:['localProcessClosed']}),values:{localProcessClosed:true}},evidence:[],exitCode:code,signal});
      });
    });
  }
  async terminate() {
    if(!this.child || this.streamsClosed)return;
    const kill=(signal:NodeJS.Signals)=>{try{if(this.child?.pid)process.kill(-this.child.pid,signal);}catch(error){if((error as NodeJS.ErrnoException).code!=='ESRCH')throw error;}};
    kill('SIGTERM');const timer=setTimeout(()=>kill('SIGKILL'),1000);
    try{await this.closed;}finally{clearTimeout(timer);}
  }
  async measure():Promise<WorkerResourceObservations> {
    const unavailable={status:'unavailable' as const,reason:'Complete local CLI child-tree resource accounting is unavailable; bridge parent counters are not child observations'};
    return {cpuTimeMs:{...unavailable},maximumMemoryBytes:{...unavailable},maximumProcesses:{...unavailable}};
  }
}

skills/prism/server/worker-artifacts.ts.syntax:
export function artifactLocation(artifact: WorkerArtifactRefV1, origin: URL): URL {
  const url = new URL(artifact.storageUrl);
  if (url.origin !== origin.origin || url.pathname !== `/v1/internal/artifacts/${artifact.contentDigest}`
    || url.search || url.hash || url.username || url.password || artifact.artifactId !== `artifact:${artifact.contentDigest}`) {
    throw new Error('Prism artifact location or identity is not allowed');
  }
  return url;
}

async function responseBytes(response: Response, maximum: number): Promise<Buffer> {
  if (Number(response.headers.get('content-length')) > maximum) {
    await response.body?.cancel(); throw new Error('Prism artifact response exceeds its byte limit');
  }
  const reader = response.body?.getReader(); if (!reader) throw new Error('Prism artifact response is empty');
  const chunks: Uint8Array[] = []; let size = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read(); if (done) break;
      size += value.byteLength;
      if (size > maximum) throw new Error('Prism artifact response exceeds its byte limit');
      chunks.push(value);
    }
  } finally { try { await reader.cancel(); } finally { reader.releaseLock(); } }
  return Buffer.concat(chunks, size);
}

export class WorkerArtifactClient {
  readonly origin: URL;
  readonly #headers: Record<string, string>;
  constructor(origin: URL, secret: string, spiffeEnabled: boolean) {
    this.origin = new URL(origin);
    this.#headers = spiffeEnabled ? {} : { authorization: `Bearer ${secret}` };
  }
  async read(artifact: WorkerArtifactRefV1, signal: AbortSignal): Promise<Buffer> {
    const response = await fetch(artifactLocation(artifact, this.origin), { headers: this.#headers, signal, redirect: 'error' });
    if (!response.ok) { await response.body?.cancel(); throw new Error(`Prism artifact read failed: ${response.status}`); }
    const bytes = await responseBytes(response, artifact.sizeBytes);
    if (bytes.byteLength !== artifact.sizeBytes || digest(bytes) !== artifact.contentDigest) throw new Error('Prism artifact failed integrity validation');
    return bytes;
  }
  async upload(id: string, type: string, mediaType: string, content: Uint8Array, signal: AbortSignal): Promise<WorkerEvidenceRefV1> {
    const bytes = Buffer.from(content); const contentDigest = digest(bytes);
    const storageUrl = new URL(`/v1/internal/artifacts/${contentDigest}`, this.origin).toString();
    const response = await fetch(storageUrl, { method: 'POST', headers: { ...this.#headers, 'content-type': 'application/octet-stream' },
      body: new Uint8Array(bytes), signal, redirect: 'error' });
    const acknowledgment = await responseBytes(response, 8192);
    if (!response.ok) throw new Error(`Prism artifact upload failed: ${response.status}: ${acknowledgment.toString('utf8')}`);
    const stored = JSON.parse(acknowledgment.toString('utf8')) as { artifactId?: string; digest?: string; sizeBytes?: number };
    if (stored.artifactId !== `artifact:${contentDigest}` || stored.digest !== contentDigest || stored.sizeBytes !== bytes.byteLength) {
      throw new Error('Prism artifact upload acknowledgment failed integrity validation');
    }
    return { evidenceId: id, type, artifact: { artifactId: stored.artifactId, type, mediaType, contentDigest, sizeBytes: bytes.byteLength, storageUrl } };
  }
}

