skills/prism/control/agent-jobs.ts.syntax:
export type AgentJob = Record<string,unknown> & {
  id:string; project_id:string; operation:'design-set'|'revise'; session_key:string;
  request_digest:string; request:Record<string,unknown>; state:'accepted'|'running'|'completed'|'needs_nova'|'superseded';
  attempt_envelope:WorkerAttemptEnvelopeV2|null; fence:string|null; result:unknown; result_digest:string|null;
};

export async function enqueueAgentJob(db: Database, namespace:string, projectId:string, operation:AgentJob['operation'], input:Record<string,unknown> & {preferences:{generationId:string}}) {
  return inTransaction(db,connection=>insertAgentJob(connection,namespace,projectId,operation,input));
}

export async function insertAgentJob(connection:Queryable,namespace:string,projectId:string,operation:AgentJob['operation'],input:Record<string,unknown> & {preferences:{generationId:string}}) {
    const generation=await connection.query<{project_id:string}>("SELECT g.project_id FROM prism.preference_generation g JOIN prism.project p ON p.id=g.project_id WHERE g.id=$1 AND p.external_id=$2 FOR SHARE OF g",[input.preferences.generationId,projectId]);
    if(!generation.rows[0])throw new Error('agent job generation does not belong to project');
    input={...input,preferences:Object.fromEntries(Object.entries(input.preferences).filter(([key])=>key!=='result')) as {generationId:string}};
    const requestDigest=sha256Digest({operation,input});
    await connection.query("INSERT INTO prism.agent_job(id,project_id,operation,session_namespace,session_key,request_digest,request) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb) ON CONFLICT(id) DO NOTHING",[input.preferences.generationId,generation.rows[0].project_id,operation,namespace,agentSessionKey(namespace,projectId),requestDigest,JSON.stringify(input)]);
    const job=await agentJob(connection,input.preferences.generationId);
    if(job.request_digest!==requestDigest)throw new Error('agent job generation conflicts with recorded request');
    return job;
}

export async function agentJob(db:Queryable,id:string):Promise<AgentJob> {
  await db.query("UPDATE prism.agent_job SET state='needs_nova',outcome=jsonb_build_object('reason','external agent outcome unresolved after claim expiry'),updated_at=clock_timestamp() WHERE state='running' AND expires_at<=clock_timestamp() AND session_key=(SELECT session_key FROM prism.agent_job WHERE id=$1)",[id]);
  const row=await db.query<AgentJob>("SELECT j.*,(SELECT blocked.id FROM prism.agent_job blocked WHERE blocked.session_key=j.session_key AND blocked.state='needs_nova' ORDER BY blocked.created_at,blocked.id LIMIT 1) AS blocked_by FROM prism.agent_job j WHERE j.id=$1",[id]);
  if(!row.rows[0])throw new Error('persisted Prism agent job not found');
  return row.rows[0];
}

export async function claimAgentJob(db:Database,runnerId:string) {
  if(!runnerId || runnerId.length>160)throw new Error('agent runner identity is required');
  return inTransaction(db,async connection=>{
    await connection.query("SELECT pg_advisory_xact_lock(hashtextextended('prism-agent-admission',0))");
    await connection.query("UPDATE prism.agent_job SET state='needs_nova',outcome=jsonb_build_object('reason','external agent outcome unresolved after claim expiry'),updated_at=clock_timestamp() WHERE state='running' AND expires_at<=clock_timestamp()");
    await connection.query("UPDATE prism.agent_job j SET state='superseded',outcome=jsonb_build_object('reason','source changed before external action started'),updated_at=clock_timestamp() WHERE j.state='accepted' AND ((j.operation='design-set' AND NOT EXISTS (SELECT 1 FROM prism.design_round round JOIN prism.design_request request ON request.id=round.design_request_id WHERE round.id=j.id AND request.status='active' AND request.current_round_id=round.id)) OR (j.operation='revise' AND NOT EXISTS (SELECT 1 FROM prism.design_document document JOIN prism.design_revision revision ON revision.id=document.current_revision_id WHERE document.id::text=j.request->>'documentId' AND revision.revision::text=j.request->>'expectedRevision'))) ");
    const rows=await connection.query<AgentJob>("SELECT j.* FROM prism.agent_job j WHERE j.state='accepted' AND NOT EXISTS (SELECT 1 FROM prism.agent_job active WHERE active.session_key=j.session_key AND active.state IN ('running','needs_nova')) ORDER BY j.created_at,j.id LIMIT 1 FOR UPDATE OF j");
    if(!rows.rows[0])return null;
    const source=rows.rows[0];const fence=randomUUID();
    const deadline=await connection.query<{expires_at:Date|string}>("SELECT clock_timestamp()+interval '16 minutes' AS expires_at");
    const expiresAt=deadline.rows[0]!.expires_at;
    const envelope=await agentAttempt({...source,fence,expires_at:expiresAt},runnerId);
    const claimed=await connection.query<AgentJob>("UPDATE prism.agent_job SET state='running',fence=$2,runner_id=$3,expires_at=$4,attempt_envelope=$5::jsonb,updated_at=clock_timestamp() WHERE id=$1 AND state='accepted' RETURNING *",[source.id,fence,runnerId,expiresAt,JSON.stringify(envelope)]);
    return claimed.rows[0]!;
  });
}

export async function finishAgentRun(db:Database,id:string,fence:string,outcome:Record<string,unknown>) {
  return inTransaction(db,async connection=>{
    const rows=await connection.query<AgentJob>('SELECT * FROM prism.agent_job WHERE id=$1 FOR UPDATE',[id]);
    const job=rows.rows[0];
    if(!job || job.fence!==fence)throw new Error('agent job fence conflict');
    validateAgentOutcome(job,outcome);
    if(job.state==='completed' || job.state==='needs_nova')return job;
    const completed=outcome.schemaVersion==='worker-attempt-result.v2' && outcome.state==='completed' && job.result!==null;
    await connection.query("UPDATE prism.agent_job SET state=$2,outcome=$3::jsonb,updated_at=clock_timestamp() WHERE id=$1",[id,completed?'completed':'needs_nova',JSON.stringify(outcome)]);
    return agentJob(connection,id);
  });
}

function validateAgentOutcome(job:AgentJob,outcome:Record<string,unknown>) {
  if(!job.attempt_envelope)throw new Error('agent accepted attempt envelope is missing');
  const accepted=job.attempt_envelope;
  if(accepted.attemptId!==job.fence || accepted.claim.claimId!==job.fence || accepted.executionId!==job.id)throw new Error('agent persisted attempt identity conflict');
  if(outcome.schemaVersion==='worker-attempt-result.v2'){
    const checked=checkWorkerResourceResultBinding(accepted,outcome as unknown as WorkerAttemptResultV2);
    if(!checked.ok)throw new Error(`agent outcome binding failed: ${checked.errors.join('; ')}`);
    return;
  }
  if(outcome.state==='errored' && typeof outcome.error==='string' && outcome.error.length>0
    && Object.keys(outcome).every(key=>key==='state' || key==='error'))return;
  throw new Error('agent outcome requires a bound V2 receipt; startup diagnostics may only report errored');
}

export async function lockAgentResult(db:Queryable,identity:AgentCompletion,generationId:string) {
  if(identity.jobId!==generationId || !identity.fence)throw new Error('agent result job identity is required');
  const rows=await db.query<AgentJob & {live:boolean}>('SELECT *,expires_at>clock_timestamp() AS live FROM prism.agent_job WHERE id=$1 FOR UPDATE',[identity.jobId]);
  const job=rows.rows[0];
  if(!job || job.fence!==identity.fence)throw new Error('agent result fence conflict');
  if(job.result_digest){
    if(job.result_digest!==sha256Digest(identity.payload))throw new Error('agent result conflicts with committed payload');
    return job.result;
  }
  if(job.state!=='running'||!job.live)throw new Error('agent action is unresolved; NeedsNova reconciliation is required');
  return null;
}

export async function recordAgentResult(db:Queryable,identity:AgentCompletion,result:unknown) {
  await db.query('UPDATE prism.agent_job SET result_digest=$2,result=$3::jsonb,updated_at=clock_timestamp() WHERE id=$1',[identity.jobId,sha256Digest(identity.payload),JSON.stringify(result)]);
}

skills/prism/storage/index.ts.syntax:
export type Queryable = {
  query<T extends Record<string, unknown> = Record<string, unknown>>(
    sql: string,
    params?: unknown[],
  ): Promise<{ rows: T[] }>;
  exec?(sql: string): Promise<unknown>;
};

export async function migrate(
  db: Queryable & { connect?: () => Promise<Queryable & { release(): void }> },
  options: { infrastructure?: "embedded" | "preprovisioned" } = {},
): Promise<void> {
  const root = new URL("./migrations/", import.meta.url);
  const files = (await readdir(root))
    .filter((name) => /^\d{3}_[a-z0-9_]+\.sql$/u.test(name))
    .sort();
  const connection = db.connect ? await db.connect() : db;
  try {
    await connection.query("BEGIN");
    try {
      await connection.query(
        "SELECT pg_advisory_xact_lock(hashtextextended('prism-schema-migrations',0))",
      );
      if (options.infrastructure === "preprovisioned") {
        const schema = await connection.query(
          "SELECT n.nspname FROM pg_namespace n JOIN pg_roles r ON r.oid=n.nspowner WHERE n.nspname='prism' AND r.rolname=current_user",
        );
        if (!schema.rows[0]) {
          throw new Error("Prism schema bootstrap is missing or prism_migrator is not its owner");
        }
      } else {
        await connection.query("CREATE EXTENSION IF NOT EXISTS vector");
        await connection.query("DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'prism_migrator') THEN CREATE ROLE prism_migrator; END IF; IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'prism_runtime') THEN CREATE ROLE prism_runtime; END IF; IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'prism_readonly') THEN CREATE ROLE prism_readonly; END IF; END $$");
        await connection.query("CREATE SCHEMA IF NOT EXISTS prism");
      }
      await connection.query(
        "CREATE TABLE IF NOT EXISTS prism.schema_migration(name text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now())",
      );
      for (const name of files) {
        const sql = await readFile(new URL(name, root), "utf8");
        const applied = await connection.query(
          "SELECT name FROM prism.schema_migration WHERE name=$1",
          [name],
        );
        if (!applied.rows[0]) {
          if (connection.exec) await connection.exec(sql);
          else await connection.query(sql);
          await connection.query(
            "INSERT INTO prism.schema_migration(name) VALUES($1)",
            [name],
          );
        }
      }
      await connection.query("COMMIT");
    } catch (error) {
      await connection.query("ROLLBACK");
      throw error;
    }
  } finally {
    if ("release" in connection && typeof connection.release === "function")
      connection.release();
  }
}

export async function inTransaction<T>(db: Database, execute: (connection: Queryable) => Promise<T>): Promise<T> {
  const connection = db.connect ? await db.connect() : db;
  try {
    await connection.query("BEGIN");
    try {
      const result = await execute(connection);
      await connection.query("COMMIT");
      return result;
    } catch (error) {
      await connection.query("ROLLBACK");
      throw error;
    }
  } finally {
    if ("release" in connection && typeof connection.release === "function") connection.release();
  }
}

async function insertDocument(connection: Queryable, projectId: string, key: string, document: PrismDocument, user: string, designRequestId?: string): Promise<string> {
    const documentId = randomUUID();
    const revisionId = randomUUID();
    const content = JSON.stringify(document);
    const contentDigest = digest(content);
      await connection.query("SELECT id FROM prism.project WHERE id=$1 FOR SHARE",[projectId]);
      if(designRequestId){const active=await connection.query("SELECT id FROM prism.design_request WHERE id=$1 AND project_id=$2 AND status='active'",[designRequestId,projectId]);if(!active.rows[0])throw new Error("active Prism design request changed before document creation");}
      await connection.query(
        "INSERT INTO prism.design_document(id,project_id,document_key,design_request_id) VALUES($1,$2,$3,$4)",
        [documentId, projectId, key, designRequestId ?? null],
      );
      await connection.query(
        "INSERT INTO prism.design_revision(id,document_id,revision,schema_id,content,content_digest,created_by) VALUES($1,$2,$3,$4,$5::jsonb,$6,$7)",
        [
          revisionId,
          documentId,
          document.meta.revision,
          document.meta.schema,
          content,
          contentDigest,
          user,
        ],
      );
      await connection.query(
        "UPDATE prism.design_document SET current_revision_id=$1 WHERE id=$2",
        [revisionId, documentId],
      );
    return documentId;
}

export class RevisionRepository {
  private readonly db: Database;
  constructor(db: Database) {
    this.db = db;
  }
  async createProject(externalId: string, name: string): Promise<string> {
    const id = randomUUID();
    await this.db.query(
      "INSERT INTO prism.project(id,external_id,name) VALUES($1,$2,$3)",
      [id, externalId, name],
    );
    return id;
  }
  async createDocument(
    projectId: string,
    key: string,
    document: PrismDocument,
    user: string,
    designRequestId?: string,
  ): Promise<string> {
    return inTransaction(this.db, connection => insertDocument(connection, projectId, key, document, user, designRequestId));
  }

  async createDirectionSet(projectKey: string, generationId: string, designs: readonly { key: string; title: string; summary: string; document: PrismDocument; evidence?: Record<string, unknown> }[], agent?:AgentCompletion) {
    if (designs.length !== 3 || new Set(designs.map(item => item.key)).size !== 3
      || designs.some(item => !item.key || !item.title || !item.summary || item.document.meta.projectId !== projectKey)) throw new Error("invalid Prism design set");
    return inTransaction(this.db, async connection => {
      const project = await connection.query<{ id: string }>("SELECT id FROM prism.project WHERE external_id=$1 FOR UPDATE", [projectKey]);
      if (!project.rows[0]) throw new Error("active Prism project not found");
      const projectId = project.rows[0].id;
      if(agent){const replay=await lockAgentResult(connection,agent,generationId);if(replay)return replay as {status:string;projectId:string;documentId:string;directions:Array<{directionId:string;documentId:string;key:string}>};}
      const resultDigest = digest(JSON.stringify(designs));
      const bound = await boundDesignRound(connection,projectId,generationId,resultDigest);
      if (bound.replay) return bound.replay as {status: string; projectId: string; documentId: string; directions: Array<{directionId:string;documentId:string;key:string}>};
      const requestId = bound.requestId;
      const directions = [];
      for (const item of designs) {
        const documentId = await insertDocument(connection, projectId, `direction-${generationId}-${item.key}`, item.document, 'agent:prism', requestId);
        await connection.query("UPDATE prism.design_document SET design_round_id=$2 WHERE id=$1",[documentId,generationId]);
        const current = await new RevisionRepository(connection).current(documentId);
        const directionId = randomUUID();
        const content = JSON.stringify(item.document);
        await connection.query("INSERT INTO prism.direction(id,project_id,source_document_id,source_revision_id,direction_key,title,summary,proposal,content_digest,state,evidence) VALUES($1,$2,$3,$4,$5,$6,$7,$8::jsonb,$9,'proposed',$10::jsonb)",
          [directionId, projectId, documentId, current.id, item.key, item.title, item.summary, content, digest(content), JSON.stringify(item.evidence ?? {})]);
        directions.push({ directionId, documentId, key: item.key });
      }
      const result = { status: 'created', generationId, projectId, documentId: directions[0]!.documentId, directions };
      await connection.query("UPDATE prism.design_round SET result_digest=$2,result=$3::jsonb WHERE id=$1",[generationId,resultDigest,JSON.stringify(result)]);
      if(agent)await recordAgentResult(connection,agent,result);
      return result;
    });
  }
  async current(
    documentId: string,
  ): Promise<{ id: string; document: PrismDocument }> {
    const result = await this.db.query<{ id: string; content: PrismDocument }>(
      "SELECT r.id,r.content FROM prism.design_document d JOIN prism.design_revision r ON r.id=d.current_revision_id WHERE d.id=$1",
      [documentId],
    );
    if (!result.rows[0]) throw new Error("document not found");
    return { id: result.rows[0].id, document: result.rows[0].content };
  }
  async revision(
    documentId: string,
    revision: number,
  ): Promise<{ id: string; document: PrismDocument }> {
    const result = await this.db.query<{ id: string; content: PrismDocument }>(
      "SELECT id,content FROM prism.design_revision WHERE document_id=$1 AND revision=$2",
      [documentId, revision],
    );
    if (!result.rows[0]) throw new Error("design revision not found");
    return { id: result.rows[0].id, document: result.rows[0].content };
  }
  async includesOperation(
    documentId: string,
    idempotencyKey: string,
  ): Promise<boolean> {
    const result = await this.db.query(
      "SELECT id FROM prism.design_revision WHERE document_id=$1 AND operation->>'idempotencyKey'=$2 LIMIT 1",
      [documentId, idempotencyKey],
    );
    return Boolean(result.rows[0]);
  }
  async history(
    documentId: string,
  ): Promise<
    Array<{
      id: string;
      revision: number;
      createdAt: string;
      createdBy: string;
      operation: Record<string, unknown> | null;
    }>
  > {
    const result = await this.db.query<{
      id: string;
      revision: number;
      created_at: string;
      created_by: string;
      operation: Record<string, unknown> | null;
    }>(
      "SELECT id,revision,created_at::text,created_by,operation FROM prism.design_revision WHERE document_id=$1 ORDER BY created_at DESC,id DESC",
      [documentId],
    );
    return result.rows.map((row) => ({
      id: row.id,
      revision: row.revision,
      createdAt: row.created_at,
      createdBy: row.created_by,
      operation: row.operation,
    }));
  }
  async restore(
    documentId: string,
    revisionId: string,
    user: string,
  ): Promise<PrismDocument> {
    const source = await this.db.query<{ content: PrismDocument }>(
      "SELECT content FROM prism.design_revision WHERE id=$1 AND document_id=$2",
      [revisionId, documentId],
    );
    if (!source.rows[0]) throw new Error("revision not found");
    const current = await this.current(documentId);
    const next = structuredClone(source.rows[0].content);
    next.meta.revision = current.document.meta.revision + 1;
    next.meta.updatedAt = new Date().toISOString();
    return this.replace(
      documentId,
      current.id,
      next,
      { type: "revision.restored", sourceRevisionId: revisionId },
      user,
    );
  }
  async apply(
    documentId: string,
    operation: PrismOperation,
    user: string,
  ): Promise<PrismDocument> {
    return inTransaction(this.db, async (connection) => {
      const current = await new RevisionRepository(connection).current(documentId);
      const next = applyOperation(current.document, operation);
      const id = randomUUID();
      const content = JSON.stringify(next);
      await connection.query(
        "INSERT INTO prism.design_revision(id,document_id,revision,schema_id,content,content_digest,parent_revision_id,operation,created_by) VALUES($1,$2,$3,$4,$5::jsonb,$6,$7,$8::jsonb,$9)",
        [
          id,
          documentId,
          next.meta.revision,
          next.meta.schema,
          content,
          digest(content),
          current.id,
          JSON.stringify(operation),
          user,
        ],
      );
      const updated = await connection.query(
        "UPDATE prism.design_document SET current_revision_id=$1 WHERE id=$2 AND current_revision_id=$3 RETURNING id",
        [id, documentId, current.id],
      );
      if (!updated.rows[0]) throw new Error("revision conflict");
      return next;
    });
  }
  async replace(
    documentId: string,
    expectedRevisionId: string,
    document: PrismDocument,
    operation: Record<string, unknown>,
    user: string,
    agent?:AgentCompletion,
  ): Promise<PrismDocument> {
    return inTransaction(this.db, async (connection) => {
      if(agent){const replay=await lockAgentResult(connection,agent,String(operation.generationId));if(replay)return replay as PrismDocument;}
      const current = await new RevisionRepository(connection).current(documentId);
      if (current.id !== expectedRevisionId)
        throw new Error("revision conflict");
      const id = randomUUID();
      const content = JSON.stringify(document);
      await connection.query(
        "INSERT INTO prism.design_revision(id,document_id,revision,schema_id,content,content_digest,parent_revision_id,operation,created_by) VALUES($1,$2,$3,$4,$5::jsonb,$6,$7,$8::jsonb,$9)",
        [
          id,
          documentId,
          document.meta.revision,
          document.meta.schema,
          content,
          digest(content),
          current.id,
          JSON.stringify(operation),
          user,
        ],
      );
      const updated = await connection.query(
        "UPDATE prism.design_document SET current_revision_id=$1 WHERE id=$2 AND current_revision_id=$3 RETURNING id",
        [id, documentId, current.id],
      );
      if (!updated.rows[0]) throw new Error("revision conflict");
      if(agent)await recordAgentResult(connection,agent,document);
      return document;
    });
  }
}

