export type PrismOperation =
  | { type: "node.insert"; baseRevision: number; parentId: string; index: number; node: PrismNode }
  | { type: "node.remove"; baseRevision: number; nodeId: string }
  | { type: "node.duplicate"; baseRevision: number; nodeId: string; newNodeId: string }
  | { type: "node.move"; baseRevision: number; nodeId: string; parentId: string; index: number }
  | { type: "node.props.set"; baseRevision: number; nodeId: string; props: Record<string, unknown> }
  | { type: "responsive.props.set"; baseRevision: number; nodeId: string; viewport: Viewport; props: Record<string, unknown> }
  | { type: "operation.batch"; baseRevision: number; operations: PrismOperation[] };

function nodes(document: PrismDocument): PrismNode[] {
  return Object.values(document.views).flatMap((view) => {
    const result: PrismNode[] = [];
    const visit = (node: PrismNode): void => { result.push(node); node.children?.forEach(visit); };
    visit(view.root);
    return result;
  });
}

function findNode(document: PrismDocument, id: string): PrismNode {
  const matches = nodes(document).filter((node) => node.id === id);
  if (matches.length !== 1) throw new Error(matches.length ? `duplicate node ID: ${id}` : `missing node: ${id}`);
  return matches[0]!;
}

function findParent(document: PrismDocument, id: string): PrismNode | undefined {
  return nodes(document).find((node) => node.children?.some((child) => child.id === id));
}

function ensureUnique(document: PrismDocument): void {
  const seen = new Set<string>();
  for (const node of nodes(document)) {
    if (seen.has(node.id)) throw new Error(`duplicate node ID: ${node.id}`);
    seen.add(node.id);
  }
}

function containsNode(root: PrismNode, id: string): boolean {
  return root.id === id || Boolean(root.children?.some((child) => containsNode(child, id)));
}

function moveNode(document: PrismDocument, node: PrismNode, parent: PrismNode, operation: Extract<PrismOperation, { type: "node.move" }>): void {
  const target = findNode(document, operation.parentId);
  if (containsNode(node, target.id)) throw new Error("node cannot move into itself or its descendant");
  const targetLength = (target.children?.length ?? 0) - (target === parent ? 1 : 0);
  if (operation.index > targetLength) throw new Error("move index out of range");
  const sourceIndex = parent.children!.findIndex((child) => child.id === node.id);
  parent.children!.splice(sourceIndex, 1);
  target.children ??= [];
  target.children.splice(operation.index, 0, node);
  ensureUnique(document);
}

function setResponsiveProps(document: PrismDocument, operation: Extract<PrismOperation, { type: "responsive.props.set" }>): void {
  const view = Object.values(document.views).find((candidate) => containsNode(candidate.root, operation.nodeId));
  if (!view) throw new Error(`missing node: ${operation.nodeId}`);
  const patches = view.responsive[operation.viewport]!.patches;
  patches[operation.nodeId] = { ...(patches[operation.nodeId] ?? {}), ...operation.props };
}

function applyMutable(document: PrismDocument, operation: PrismOperation): void {
  if (operation.type === "operation.batch") {
    for (const child of operation.operations) {
      if (child.baseRevision !== operation.baseRevision) throw new Error("batch revision mismatch");
      applyMutable(document, child);
    }
    return;
  }
  if (operation.type === "responsive.props.set") {
    setResponsiveProps(document, operation);
    return;
  }
  if (operation.type === "node.props.set") {
    const node = findNode(document, operation.nodeId);
    node.props = { ...(node.props ?? {}), ...operation.props };
    return;
  }
  if (operation.type === "node.insert") {
    const parent = findNode(document, operation.parentId);
    parent.children ??= [];
    if (operation.index > parent.children.length) throw new Error("insert index out of range");
    parent.children.splice(operation.index, 0, clone(operation.node));
    ensureUnique(document);
    return;
  }
  const node = findNode(document, operation.nodeId);
  const parent = findParent(document, operation.nodeId);
  if (!parent?.children) throw new Error("root node cannot be moved or removed");
  const sourceIndex = parent.children.findIndex((child) => child.id === operation.nodeId);
  if (operation.type === "node.remove") { parent.children.splice(sourceIndex, 1); return; }
  if (operation.type === "node.duplicate") {
    const copy = duplicateSubtree(document, node, operation.newNodeId);
    parent.children.splice(sourceIndex + 1, 0, copy); ensureUnique(document); return;
  }
  moveNode(document, node, parent, operation);
}

export function applyOperation(source: PrismDocument, input: PrismOperation): PrismDocument {
  validatePrism("operation", input);
  if (source.meta.revision !== input.baseRevision) throw new Error(`revision conflict: expected ${source.meta.revision}`);
  const next = clone(source);
  applyMutable(next, input);
  next.meta.revision += 1;
  next.meta.updatedAt = new Date(Date.parse(source.meta.updatedAt) + 1).toISOString();
  ensureUnique(next);
  return validatePrism<PrismDocument>("designDocument", next);
}

export function resolveView(document: PrismDocument, viewId: string, state = "default", viewport: Viewport = "wide"): PrismNode {
  const view = document.views[viewId];
  if (!view) throw new Error(`missing view: ${viewId}`);
  const root = clone(view.root);
  const statePatches = view.states[state]?.patches ?? {};
  const viewportPatches = view.responsive[viewport]?.patches ?? {};
  const visit = (node: PrismNode): void => {
    if (statePatches[node.id] || viewportPatches[node.id]) {
      node.props = { ...(node.props ?? {}), ...statePatches[node.id], ...viewportPatches[node.id] };
    }
    node.children?.forEach(visit);
  };
  visit(root);
  return root;
}

export function transition(document: PrismDocument, flowId: string, current: { view: string; state: string }, action: string): { view: string; state: string } {
  const flow = document.flows[flowId] as { transitions?: Array<{ from: { view: string; state: string }; trigger: { action: string }; to: { view: string; state: string } }> } | undefined;
  const match = flow?.transitions?.find((item) => item.from.view === current.view && item.from.state === current.state && item.trigger.action === action);
  if (!match) throw new Error(`undeclared transition: ${action}`);
  return clone(match.to);
}

skills/prism/domain/duplicate.ts.syntax:
type FlowTransition = {
  id: string;
  from: { view: string; state: string };
  trigger: { actor: string; action: string; node?: string };
};

function allocateId(seed: string, occupied: Set<string>, ordinal: number): string {
  let counter = ordinal;
  let id: string;
  do {
    const suffix = `-${counter++}`;
    id = `${seed.slice(0, 80 - suffix.length)}${suffix}`;
  } while (occupied.has(id));
  occupied.add(id);
  return id;
}

function copyPatches(view: PrismDocument["views"][string], remap: Map<string, string>): void {
  for (const group of [...Object.values(view.states), ...Object.values(view.responsive)]) {
    for (const [oldId, newId] of remap) {
      if (Object.hasOwn(group.patches, oldId)) group.patches[newId] = structuredClone(group.patches[oldId]!);
    }
  }
}

function copyTransitions(document: PrismDocument, viewId: string, remap: Map<string, string>, seed: string): void {
  for (const raw of Object.values(document.flows)) {
    const flow = raw as { transitions: FlowTransition[] };
    const occupied = new Set(flow.transitions.map((transition) => transition.id));
    const copies: FlowTransition[] = [];
    for (const transition of flow.transitions) {
      const newId = transition.trigger.node && remap.get(transition.trigger.node);
      if (transition.from.view !== viewId || !newId) continue;
      const copy = structuredClone(transition);
      copy.id = allocateId(seed, occupied, copies.length + 1);
      copy.trigger.node = newId;
      copies.push(copy);
    }
    flow.transitions.push(...copies);
  }
}

export function duplicateSubtree(document: PrismDocument, node: PrismNode, newNodeId: string): PrismNode {
  const views = Object.entries(document.views);
  const occupied = new Set(views.flatMap(([, view]) => collect(view.root).map((item) => item.id)));
  if (occupied.has(newNodeId)) throw new Error(`duplicate node ID: ${newNodeId}`);
  occupied.add(newNodeId);
  const copy = structuredClone(node);
  const remap = new Map<string, string>();
  collect(copy).forEach((item, index) => {
    const id = index === 0 ? newNodeId : allocateId(newNodeId, occupied, index);
    remap.set(item.id, id);
    item.id = id;
  });
  const [viewId, view] = views.find(([, candidate]) => collect(candidate.root).some((item) => item === node))!;
  copyPatches(view, remap);
  copyTransitions(document, viewId, remap, newNodeId);
  // Action names, component IDs and component-local override keys are separate
  // identities, not view node references, and therefore remain unchanged.
  return copy;
}

skills/prism/storage/artifacts.ts.syntax:
async function syncDirectory(directory: string): Promise<void> {
  const handle = await open(directory, constants.O_RDONLY | constants.O_DIRECTORY);
  try { await handle.sync(); } finally { await handle.close(); }
}

async function ensureDurableDirectory(directory: string): Promise<void> {
  await mkdir(directory, { recursive: true });
  // Also cover another concurrent creator that has not yet synced its parent.
  for (let current = resolve(directory);;) {
    await syncDirectory(current);
    const parent = dirname(current); if (parent === current) return; current = parent;
  }
}

async function verifiedBytes(file: string, expectedDigest: string, durable = false): Promise<Buffer> {
  const handle = await open(file, constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
  try {
    if (!(await handle.stat()).isFile()) throw new Error('PRISM_ARTIFACT_NOT_REGULAR');
    const bytes = await handle.readFile();
    if (digest(bytes) !== expectedDigest) throw new Error(`PRISM_ARTIFACT_CORRUPT:${expectedDigest}`);
    // An existing object's presence alone is not a durable acknowledgement.
    if (durable) await handle.sync(); return bytes;
  } finally { await handle.close(); }
}

async function removePending(pending: string, directory: string, failure: unknown): Promise<void> {
  try { await unlink(pending); await syncDirectory(directory); }
  catch (error) {
    if (failure) throw new AggregateError([failure, error], 'PRISM_ARTIFACT_PENDING_CLEANUP_FAILED', { cause: failure });
    throw error;
  }
}

export class ContentAddressedArtifactStore {
  readonly #root: string;
  constructor(root: string) { this.#root = resolve(root); }

  async put(content: Uint8Array): Promise<{ artifactId: string; digest: string; sizeBytes: number }> {
    // Take ownership before the first await; callers may reuse their buffer.
    const bytes = Buffer.from(content); const contentDigest = digest(bytes); const hex = contentDigest.slice(7);
    const file = join(this.#root, hex.slice(0, 2), hex); const directory = dirname(file);
    await ensureDurableDirectory(directory);
    const pending = `${file}.${randomUUID()}.pending`; let created = false; let failure: unknown;
    try {
      const handle = await open(pending, 'wx', 0o600); created = true;
      try { await handle.writeFile(bytes); await handle.sync(); } finally { await handle.close(); }
      try { await link(pending, file); }
      catch (error) {
        if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;
        await verifiedBytes(file, contentDigest, true);
      }
      await syncDirectory(directory);
      return { artifactId: `artifact:${contentDigest}`, digest: contentDigest, sizeBytes: bytes.byteLength };
    } catch (error) { failure = error; throw error; }
    finally { if (created) await removePending(pending, directory, failure); }
  }

  async get(artifactId: string): Promise<Uint8Array> {
    const match = /^artifact:sha256:([a-f0-9]{64})$/u.exec(artifactId);
    if (!match) throw new Error('invalid artifact ID');
    return verifiedBytes(join(this.#root, match[1]!.slice(0, 2), match[1]!), `sha256:${match[1]}`);
  }
}

skills/prism/server/agent-session.ts.syntax:
export function agentSessionKey(namespace:string, projectId:string) {
  if (typeof namespace !== 'string' || !namespace || typeof projectId !== 'string' || !projectId) {
    throw new Error('Prism agent session namespace and full project identity are required');
  }
  const identity = createHash('sha256').update(JSON.stringify([namespace, projectId])).digest('hex');
  return `prism-v2-${identity}`;
}

scripts/check-runtime-role-manifests.mjs.syntax:
for (let index = 0; index < process.argv.slice(2).length; index += 2) {
  const option = process.argv.slice(2)[index];
  const value = process.argv.slice(2)[index + 1];
  if (!value || !['--additional-plugin', '--role-addition'].includes(option)) {
    throw new Error('Usage: check-runtime-role-manifests.mjs [--additional-plugin <role=manifest>] [--role-addition <role=plugin-id>]');
  }
  const separator = value.indexOf('=');
  const role = value.slice(0, separator);
  const item = value.slice(separator + 1);
  if (separator < 1 || !roleNames.has(role) || !item) throw new Error(`Invalid ${option} value: ${value}`);
  if (option === '--additional-plugin') additionalPlugins.push({ role, manifestPath: item });
  else roleAdditions.set(role, [...(roleAdditions.get(role) ?? []), item]);
}

for (const [role, additions] of roleAdditions) {
  assert.equal(new Set(additions).size, additions.length, `${role} has duplicate role additions`);
}

function pluginCatalog() {
  const roots = [
    ['shared', 'skills/common/plugins'],
    ['nova', 'skills/nova/plugins'],
    ['buster', 'skills/buster/plugins'],
    ['prism', 'skills/prism/plugins'],
  ];
  const result = new Map();
  for (const [owner, relativeRoot] of roots) {
    const directory = path.join(root, relativeRoot);
    if (!fs.existsSync(directory)) continue;
    for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const manifestPath = path.join(directory, entry.name, 'plugin.json');
      if (!fs.existsSync(manifestPath)) continue;
      const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
      assert(!result.has(manifest.id), `duplicate plugin ID: ${manifest.id}`);
      result.set(manifest.id, { owner, root: path.dirname(manifestPath), manifest });
    }
  }
  for (const entry of additionalPlugins) {
    const manifestPath = path.resolve(root, entry.manifestPath);
    assert(fs.existsSync(manifestPath), `additional plugin manifest is missing: ${entry.manifestPath}`);
    const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
    assert(!result.has(manifest.id), `duplicate plugin ID: ${manifest.id}`);
    result.set(manifest.id, { owner: entry.role, root: path.dirname(manifestPath), manifest });
  }
  return result;
}

const extensionCatalog = new Map([
  ['kubeclaw-agent-observer', { owner: 'shared', root: 'skills/common/plugins/openclaw-agent-observer' }],
]);

for (const entry of ownership.packages) {
  const manifestPath = path.join(root, entry.source, 'package.json');
  if (!fs.existsSync(manifestPath)) continue;
  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  if (manifest.name) packageNames.set(manifest.name, entry.id);
}

for (const [pluginId, plugin] of plugins) {
  const manifestPath = path.join(plugin.root, 'package.json');
  if (!fs.existsSync(manifestPath)) continue;
  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  if (!manifest.name) continue;
  assert(!pluginPackageNames.has(manifest.name), `duplicate plugin package name: ${manifest.name}`);
  pluginPackageNames.set(manifest.name, pluginId);
}

for (const role of ['nova', 'buster', 'prism']) {
  const manifestPath = path.join(root, `packaging/runtime/roles/${role}.json`);
  const sourceManifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  const manifest = { ...sourceManifest, plugins: [...sourceManifest.plugins, ...(roleAdditions.get(role) ?? [])] };
  assert.equal(manifest.schemaVersion, 'pipeline-runtime-role.v1');
  assert.equal(manifest.role, role);
  for (const field of ['packages', 'plugins', 'extensions', 'externalCapabilities']) {
    assert(Array.isArray(manifest[field]), `${role} ${field} must be an array`);
  }
  assert.equal(new Set(manifest.packages).size, manifest.packages.length, `${role} has duplicate packages`);
  assert.equal(new Set(manifest.plugins).size, manifest.plugins.length, `${role} has duplicate plugins`);
  assert.equal(new Set(manifest.extensions).size, manifest.extensions.length, `${role} has duplicate extensions`);
  assert(manifest.packages.includes(manifest.entrypoint.package), `${role} entrypoint package is not selected`);
  const entrypointPackage = packages.get(manifest.entrypoint.package);
  assert(entrypointPackage, `${role} entrypoint package is unknown`);
  const entrypointRoot = path.resolve(root, entrypointPackage.source);
  const entrypoint = path.resolve(entrypointRoot, manifest.entrypoint.path);
  assert(entrypoint.startsWith(`${entrypointRoot}${path.sep}`), `${role} entrypoint escapes its package`);
  assert(fs.existsSync(entrypoint), `${role} entrypoint is missing`);

  for (const packageId of manifest.packages) {
    const entry = packages.get(packageId);
    assert(entry, `${role} selects unknown package: ${packageId}`);
    assert(entry.roles.includes(role), `${role} cannot select package ${packageId}`);
    const packageManifestPath = path.join(root, entry.source, 'package.json');
    if (!fs.existsSync(packageManifestPath)) continue;
    const packageManifest = JSON.parse(fs.readFileSync(packageManifestPath, 'utf8'));
    for (const dependency of Object.keys(packageManifest.dependencies ?? {})) {
      const dependencyId = packageNames.get(dependency);
      const dependencyPluginId = pluginPackageNames.get(dependency);
      if (dependency.startsWith('@kubeclaw/')) assert(dependencyId || dependencyPluginId,
        `${role} package ${packageId} has unregistered internal dependency ${dependency}`);
      if (dependencyId) assert(manifest.packages.includes(dependencyId), `${role} package closure misses ${dependencyId} required by ${packageId}`);
      if (dependencyPluginId) assert(manifest.plugins.includes(dependencyPluginId),
        `${role} plugin closure misses ${dependencyPluginId} required by ${packageId}`);
    }
    for (const assetId of packageManifest.kubeclawRuntimeAssets ?? []) {
      assert(packages.has(assetId), `${role} package ${packageId} has unknown runtime asset ${assetId}`);
      assert(manifest.packages.includes(assetId), `${role} package closure misses asset ${assetId} required by ${packageId}`);
    }
  }

  const requiredCapabilities = new Set();
  const providedCapabilities = new Set();
  for (const pluginId of manifest.plugins) {
    const plugin = plugins.get(pluginId);
    assert(plugin, `${role} selects unknown plugin: ${pluginId}`);
    assert(plugin.owner === 'shared' || plugin.owner === role, `${role} cannot select ${plugin.owner} plugin ${pluginId}`);
    for (const registration of [...(plugin.manifest.stages ?? []), ...(plugin.manifest.observers ?? []), ...(plugin.manifest.adapters ?? [])]) {
      for (const capability of registration.requiredCapabilities ?? []) requiredCapabilities.add(capability);
    }
    for (const adapter of plugin.manifest.adapters ?? []) {
      for (const capability of adapter.providesCapabilities ?? []) providedCapabilities.add(capability);
    }
  }
  for (const extensionId of manifest.extensions) {
    const extension = extensionCatalog.get(extensionId);
    assert(extension, `${role} selects unknown extension: ${extensionId}`);
    assert(extension.owner === 'shared' || extension.owner === role, `${role} cannot select extension ${extensionId}`);
    assert(fs.existsSync(path.join(root, extension.root, 'package.json')), `${role} extension is missing: ${extensionId}`);
  }
  selectedByRole.set(role, new Set([...manifest.plugins, ...manifest.extensions]));
  const externalCapabilities = new Set();
  for (const capability of manifest.externalCapabilities) {
    assert.equal(typeof capability.id, 'string');
    assert.equal(typeof capability.source, 'string');
    assert(capability.reason.length >= 20, `${role} external capability needs a clear reason: ${capability.id}`);
    assert(!externalCapabilities.has(capability.id), `${role} has duplicate external capability: ${capability.id}`);
    externalCapabilities.add(capability.id);
    const source = externalSources.get(capability.source);
    assert(source, `${role} uses unknown external capability source: ${capability.source}`);
    assert(source.roles.includes(role), `${capability.source} is not available to ${role}`);
    assert(source.capabilities.includes(capability.id), `${capability.source} does not provide ${capability.id}`);
  }
  for (const capability of requiredCapabilities) {
    assert(providedCapabilities.has(capability) || externalCapabilities.has(capability), `${role} has no provider for ${capability}`);
  }

  const rolePluginRoot = path.join(root, `skills/${role}/plugins`);
  if (!fs.existsSync(rolePluginRoot)) continue;
  const ownedPluginIds = fs.readdirSync(rolePluginRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && fs.existsSync(path.join(rolePluginRoot, entry.name, 'plugin.json')))
    .flatMap((entry) => {
      const plugin = JSON.parse(fs.readFileSync(path.join(rolePluginRoot, entry.name, 'plugin.json'), 'utf8'));
      const registrationCount = ['stages', 'observers', 'adapters', 'testProviders']
        .reduce((count, field) => count + (Array.isArray(plugin[field]) ? plugin[field].length : 0), 0);
      return registrationCount > 0 ? [plugin.id] : [];
    });
  for (const pluginId of ownedPluginIds) assert(manifest.plugins.includes(pluginId), `${role} omits its plugin: ${pluginId}`);
}

for (const [directory, expectedRoles] of Object.entries(ownership.sharedPlugins)) {
  const pipelinePlugin = [...plugins.entries()].find(([, entry]) => path.basename(entry.root) === directory)?.[0];
  const extension = [...extensionCatalog.entries()].find(([, entry]) => path.basename(entry.root) === directory)?.[0];
  const runtimeId = pipelinePlugin ?? extension;
  if (!runtimeId) {
    assert.deepEqual(expectedRoles, [], `unclassified shared package use: ${directory}`);
    continue;
  }
  const actualRoles = [...selectedByRole].filter(([, selected]) => selected.has(runtimeId)).map(([role]) => role).sort();
  assert.deepEqual([...expectedRoles].sort(), actualRoles, `role manifests disagree with shared package inventory: ${directory}`);
}

for (const entry of additionalPlugins) {
  const manifest = JSON.parse(fs.readFileSync(path.resolve(root, entry.manifestPath), 'utf8'));
  assert(roleAdditions.get(entry.role)?.includes(manifest.id), `${entry.role} omits its plugin: ${manifest.id}`);
}

