function nestedMap(value: Readonly<Record<string, Readonly<Record<string, Readonly<Record<string, unknown>>>>>>): ReadonlyMap<string, ReadonlyMap<string, Readonly<Record<string, unknown>>>> {
  return new Map(Object.entries(value).map(([id, grants]) => [id, new Map(Object.entries(grants))]));
}

export interface PreparedRuntime {
  readonly configuration: Readonly<Record<string, unknown>>;
  readonly snapshot: ReturnType<typeof buildRegistry>; readonly granted: ReturnType<typeof resolveCapabilityGrants>;
  readonly activated: Awaited<ReturnType<typeof activateRegistry>>;
}

export async function prepareRuntime(platform: PlatformConfig, definition: PipelineDefinition): Promise<PreparedRuntime> {
  validateContractValue('pipelineDefinition', definition);
  const packages = discoverPackages({ installationRoots: platform.installationRoots, trustPolicy: {
    trustedBuiltinRoots: platform.trustedBuiltinRoots, allowedSourceDigests: new Map(Object.entries(platform.externalTrust.allowedSourceDigests)),
    verifiedAttestations: new Map(Object.entries(platform.externalTrust.verifiedAttestations)), verifierId: 'kubeclaw-platform-v2',
  } });
  const snapshot = buildRegistry(packages); const enabled = enabledRegistrations(platform, definition, snapshot);
  const policy: CapabilityPolicy = { enabledRegistrations: enabled, grants: nestedMap(platform.grants), providers: new Map(Object.entries(platform.providers)) };
  const granted = resolveCapabilityGrants(snapshot, policy);
  validateRuntimeRegistrationConfiguration(snapshot, granted.enabledRegistrations, {
    stages: definition.stages.map((stage) => ({ type: stage.type, config: stage.config })), observers: objectMap(platform.observers), adapters: objectMap(platform.adapters),
  });
  return { configuration: { providers: platform.providers, grants: platform.grants, adapters: platform.adapters, activeAdapters: platform.activeAdapters, observers: platform.observers, ...(platform.isolation ? { isolation: platform.isolation } : {}) }, snapshot, granted, activated: await activateRegistry(snapshot, new Set(granted.grants.keys()), platform.isolation) };
}

function enabledRegistrations(platform: PlatformConfig, definition: PipelineDefinition, snapshot: ReturnType<typeof buildRegistry>): Set<string> {
  const enabled = new Set<string>(Object.keys(platform.observers)); platform.activeAdapters.forEach((id) => enabled.add(id));
  for (const stage of definition.stages) {
    const owner = snapshot.stages.get(stage.type); if (!owner) throw new Error(`PIPELINE_STAGE_OWNER_MISSING:${stage.type}`);
    enabled.add(`${owner.package.manifest.id}:${owner.registration.id}`);
  }
  return enabled;
}

function effectAppender(events: FileJournal<LifecycleEvent | PluginDomainEvent>): (type: 'effect.requested' | 'effect.accepted' | 'effect.completed' | 'effect.failed', request: EffectRequest, payload: Readonly<Record<string, unknown>>) => void {
  return (type, request, payload) => {
    if (request.attempt.attemptId.startsWith('observer:')) return;
    events.appendSequenced((sequence) => ({ schemaVersion: 'lifecycle-event.v2', eventId: `event:${crypto.randomUUID()}`, sequence,
      type, identity: { runId: request.attempt.runId, stageId: request.attempt.stageId, attemptId: request.attempt.attemptId, effectId: request.effectId },
      occurredAt: new Date().toISOString(), causationId: request.attempt.attemptId, payload }));
  };
}

function auditResult(result: Readonly<Record<string, unknown>>): Readonly<Record<string, unknown>> {
  const serialized = Buffer.from(JSON.stringify(result));
  if (serialized.length <= 16 * 1024) return result;
  const contentDigest = `sha256:${crypto.createHash('sha256').update(serialized).digest('hex')}`;
  return Object.freeze({
    schemaVersion: 'effect-result-summary.v1',
    contentDigest,
    artifactRef: `effect-result:${contentDigest}`,
    bytes: serialized.length,
    externalized: true,
  });
}

export function createAdapterRuntime(platform: PlatformConfig, runRoot: string, runtime: PreparedRuntime, events: FileJournal<LifecycleEvent | PluginDomainEvent>): AdapterRuntime {
  const append = effectAppender(events);
  const effects = new EffectCoordinator(new FileEffectJournal(path.join(runRoot, 'effects.jsonl')), () => new Date(), {
    requested: (request, executionMode) => append('effect.requested', request, { executionMode, capability: request.capability, operation: request.operation, resource: request.resource }),
    accepted: (request, executionMode) => append('effect.accepted', request, { executionMode }),
    completed: (request, receipt, executionMode) => append(receipt.status === 'completed' ? 'effect.completed' : 'effect.failed', request,
      receipt.status === 'completed' ? { executionMode, adapter: receipt.adapter, result: auditResult(receipt.result ?? {}) } : { executionMode, adapter: receipt.adapter, error: receipt.error ?? {} }),
  }, new FileResourceLockManager(path.join(platform.storageRoot, 'resource-locks')), platform.effectLockTtlMs ?? 300_000);
  return new AdapterRuntime({ granted: runtime.granted, activated: runtime.activated, configs: objectMap(platform.adapters), effects,
    shutdownTimeoutMs: platform.shutdownTimeoutMs, emitDomainEvent: async (registration, type, identity, payload) => { events.appendSequenced((sequence) => ({
      schemaVersion: 'plugin-domain-event.v2', eventId: `event:${crypto.randomUUID()}`, sequence, type,
      producer: registration, identity, occurredAt: new Date().toISOString(), causationId: null, payload,
    })); } });
}

export async function drainObservers(platform: PlatformConfig, runRoot: string, runtime: PreparedRuntime, adapters: AdapterRuntime, events: FileJournal<LifecycleEvent | PluginDomainEvent>): Promise<void> {
  const observers = new ObserverRuntime({ registry: runtime.granted, activated: runtime.activated, adapters, events,
    checkpoints: new FileJournal<ObserverCheckpoint>(path.join(runRoot, 'observer-checkpoints.jsonl')),
    deliveries: new FileJournal<ObserverDeliveryRecord>(path.join(runRoot, 'observer-deliveries.jsonl')), configs: objectMap(platform.observers) });
  await observers.drain();
}

export function serializedObserverDrainer(platform: PlatformConfig, runRoot: string, runtime: PreparedRuntime, adapters: AdapterRuntime, events: FileJournal<LifecycleEvent | PluginDomainEvent>): () => Promise<void> {
  let pending = Promise.resolve(); return () => { pending = pending.then(() => drainObservers(platform, runRoot, runtime, adapters, events)); return pending; };
}

skills/nova/core/state/journal.ts.syntax:
export interface JournalRecord<T> {
  readonly sequence: number;
  readonly previousHash: string | null;
  readonly hash: string;
  readonly entry: T;
}

export function parseJournalRecords<T>(buffer: Buffer, records: JournalRecord<T>[], file: string): void {
    for (const record of parseHashJournal<T>(buffer,file,records.length,records.at(-1)?.hash??null)) {
      records.push(snapshotJson(record));
    }
  }

export class FileJournal<T> {
  readonly #file: string;
  readonly #mutex: FileMutex;
  #records: JournalRecord<T>[];
  #offset: number;
  #identity: string | undefined;
  #mtimeMs: number | undefined;
  #ctimeMs: number | undefined;

  constructor(file: string, appendLockTimeoutMs = 5_000) {
    if (!Number.isSafeInteger(appendLockTimeoutMs) || appendLockTimeoutMs < 1) {
      throw new Error('JOURNAL_APPEND_LOCK_TIMEOUT_INVALID');
    }
    this.#file = path.resolve(file);
    fs.mkdirSync(path.dirname(this.#file), { recursive: true });
    this.#mutex = new FileMutex(`${this.#file}.append-lock`, appendLockTimeoutMs, `JOURNAL_APPEND_LOCK_TIMEOUT:${this.#file}`);
    const loaded = this.#mutex.withLock(() => this.#load());
    this.#records = loaded.records;
    this.#offset = loaded.offset;
    this.#identity = loaded.identity;
    this.#mtimeMs = loaded.mtimeMs;
    this.#ctimeMs = loaded.ctimeMs;
  }

  #fileState(): { identity: string; size: number; mtimeMs: number; ctimeMs: number } | undefined {
    try {
      const stat = fs.statSync(this.#file);
      return { identity: `${stat.dev}:${stat.ino}`, size: stat.size, mtimeMs: stat.mtimeMs, ctimeMs: stat.ctimeMs };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined;
      throw error;
    }
  }

  #parse(buffer: Buffer, records: JournalRecord<T>[]): void {
    parseJournalRecords(buffer, records, this.#file);
  }

  #recoverIncompleteTail(buffer: Buffer): Buffer {
    if (buffer.length === 0 || buffer.at(-1) === 0x0a) return buffer;
    const committedBytes = buffer.lastIndexOf(0x0a) + 1;
    const descriptor = fs.openSync(this.#file, 'r+');
    try {
      fs.ftruncateSync(descriptor, committedBytes);
      fs.fsyncSync(descriptor);
    } finally {
      fs.closeSync(descriptor);
    }
    return buffer.subarray(0, committedBytes);
  }

  #load(): { records: JournalRecord<T>[]; offset: number; identity: string | undefined; mtimeMs: number | undefined; ctimeMs: number | undefined } {
    if (!fs.existsSync(this.#file)) return { records: [], offset: 0, identity: undefined, mtimeMs: undefined, ctimeMs: undefined };
    const buffer = this.#recoverIncompleteTail(fs.readFileSync(this.#file));
    const records: JournalRecord<T>[] = [];
    this.#parse(buffer, records);
    const state = this.#fileState();
    if (!state || state.size !== buffer.length) throw new Error(`JOURNAL_CHANGED_DURING_READ:${this.#file}`);
    return { records, offset: buffer.length, identity: state.identity, mtimeMs: state.mtimeMs, ctimeMs: state.ctimeMs };
  }

  #adoptReloaded(loaded: { records: JournalRecord<T>[]; offset: number; identity: string | undefined; mtimeMs: number | undefined; ctimeMs: number | undefined }): void {
    if (loaded.records.length < this.#records.length
      || this.#records.some((record, index) => loaded.records[index]?.hash !== record.hash)) {
      throw new Error(`JOURNAL_REWIND_OR_DIVERGENCE:${this.#file}`);
    }
    this.#records = loaded.records;
    this.#offset = loaded.offset;
    this.#identity = loaded.identity;
    this.#mtimeMs = loaded.mtimeMs;
    this.#ctimeMs = loaded.ctimeMs;
  }

  #synchronize(): void {
    const state = this.#fileState();
    if (state === undefined) {
      if (this.#offset !== 0 || this.#records.length !== 0) throw new Error(`JOURNAL_REMOVED:${this.#file}`);
      return;
    }
    if (state.identity !== this.#identity || state.size < this.#offset
      || (state.size === this.#offset && (state.mtimeMs !== this.#mtimeMs || state.ctimeMs !== this.#ctimeMs))) {
      this.#adoptReloaded(this.#load());
      return;
    }
    if (state.size === this.#offset) return;
    const length = state.size - this.#offset;
    const descriptor = fs.openSync(this.#file, 'r');
    try {
      const buffer = Buffer.allocUnsafe(length);
      const read = fs.readSync(descriptor, buffer, 0, length, this.#offset);
      if (read !== length) throw new Error(`JOURNAL_TAIL_READ_INCOMPLETE:${this.#file}`);
      if (buffer.at(-1) !== 0x0a) {
        this.#adoptReloaded(this.#load());
        return;
      }
      this.#parse(buffer, this.#records);
      this.#offset = state.size;
      this.#mtimeMs = state.mtimeMs;
      this.#ctimeMs = state.ctimeMs;
    } finally {
      fs.closeSync(descriptor);
    }
  }

  #appendUnlocked(entry: T): JournalRecord<T> {
    entry = snapshotJson(entry);
    const sequence = this.#records.length + 1;
    const previousHash = this.#records.at(-1)?.hash ?? null;
    const record: JournalRecord<T> = Object.freeze({
      sequence,
      previousHash,
      hash: recordHash(sequence, previousHash, entry),
      entry,
    });
    const serialized = Buffer.from(`${JSON.stringify(record)}\n`);
    const descriptor = fs.openSync(this.#file, 'a');
    try {
      let written = 0;
      while (written < serialized.length) {
        const count = fs.writeSync(descriptor, serialized, written, serialized.length - written);
        if (count < 1) throw new Error(`JOURNAL_APPEND_WRITE_INCOMPLETE:${this.#file}`);
        written += count;
      }
      fs.fsyncSync(descriptor);
    } finally {
      fs.closeSync(descriptor);
    }
    this.#records.push(record);
    this.#offset += serialized.length;
    const state = this.#fileState();
    if (!state || state.size !== this.#offset) throw new Error(`JOURNAL_APPEND_SIZE_MISMATCH:${this.#file}`);
    this.#identity = state.identity;
    this.#mtimeMs = state.mtimeMs;
    this.#ctimeMs = state.ctimeMs;
    return record;
  }

  transact<R>(
    operation: (
      records: readonly JournalRecord<T>[],
      append: (entry: T) => JournalRecord<T>,
    ) => R,
  ): R {
    return this.#mutex.withLock(() => {
      this.#synchronize();
      let active = true;
      try {
        return operation(
          Object.freeze([...this.#records]),
          (entry) => {
            if (!active) throw new Error('JOURNAL_TRANSACTION_CLOSED');
            return this.#appendUnlocked(entry);
          },
        );
      } finally { active = false; }
    });
  }

  append(entry: T): JournalRecord<T> {
    return this.transact((_records, append) => append(entry));
  }

  appendSequenced<U extends T>(create: (sequence: number) => U): JournalRecord<U> {
    return this.transact((records, append) => append(create(records.length + 1))) as JournalRecord<U>;
  }

  records(): readonly JournalRecord<T>[] {
    return Object.freeze([...this.#records]);
  }

  refresh(): readonly JournalRecord<T>[] {
    return this.#mutex.withLock(() => {
      this.#synchronize();
      return this.records();
    });
  }
}

