function objectProperties(input: object, output: object, array: boolean): CopyTask[] {
  const properties: CopyTask[] = [];
  for (const key of Reflect.ownKeys(input)) {
    if (array && key === 'length') continue;
    const property = Object.getOwnPropertyDescriptor(input, key)!;
    if (typeof key !== 'string' || !property.enumerable || !('value' in property)) throw new Error('JOURNAL_VALUE_NOT_JSON');
    if (array && (!/^(0|[1-9]\d*)$/.test(key) || Number(key) >= (input as unknown[]).length)) throw new Error('JOURNAL_VALUE_NOT_JSON');
    if (!array && property.value === undefined) continue;
    properties.push({ input: property.value, target: output, key });
  }
  if (array && properties.length !== (input as unknown[]).length) throw new Error('JOURNAL_VALUE_NOT_JSON');
  return properties;
}

function copyObject(input: unknown, ancestors: Set<object>, pending: Task[]): object {
  if (typeof input !== 'object' || input === null || types.isProxy(input)) throw new Error('JOURNAL_VALUE_NOT_JSON');
  if (ancestors.has(input)) throw new Error('JOURNAL_VALUE_CIRCULAR');
  const array = Array.isArray(input);
  const prototype = Object.getPrototypeOf(input);
  if (!array && prototype !== Object.prototype && prototype !== null) throw new Error('JOURNAL_VALUE_NOT_JSON');
  const output: object = array ? [] : {};
  const properties = objectProperties(input, output, array);
  ancestors.add(input);
  pending.push({ finish: output, source: input });
  // Reverse work order so object key insertion order and journal hashes stay stable.
  for (let index = properties.length - 1; index >= 0; index--) pending.push(properties[index]!);
  return output;
}

export function snapshotJson<T>(value: T): T {
  const ancestors = new Set<object>();
  const root: { value?: unknown } = {};
  const pending: Task[] = [{ input: value, target: root, key: 'value' }];
  while (pending.length) {
    const task = pending.pop()!;
    if ('finish' in task) { Object.freeze(task.finish); ancestors.delete(task.source); continue; }
    const { input, target, key } = task;
    let result: unknown;
    if (input === null || typeof input === 'string' || typeof input === 'boolean') result = input;
    else if (typeof input === 'number' && Number.isFinite(input)) result = Object.is(input, -0) ? 0 : input;
    else result = copyObject(input, ancestors, pending);
    Object.defineProperty(target, key, { value: result, enumerable: true, writable: true, configurable: true });
  }
  return root.value as T;
}

skills/nova/core/effects/dependency-jour.syntax:
export function dependencySubject(request: DependencySubject) {
  return {attempt: request.attempt, capability: request.capability, operation: request.operation,
    resource: request.resource, payload: request.payload, ...runtimeDispatchProfileFields(request), ...(request.deliveryId === undefined ? {} : {deliveryId: request.deliveryId})};
}

function ownedKey(key: string, query: DependencyQuery): boolean {
  return (key.startsWith(query.prefix) && (query.suffix ? key.endsWith(query.suffix) : !key.includes(':parent:')))
    || (key.startsWith('adapter-dep:') && key.split(':')[2] === query.scope);
}

function ownerScope(key: string): string | undefined {
  if (key.startsWith('adapter-dep:')) return `portable:${key.split(':')[2]}`;
  const parts = key.split(':');
  if (parts[0] !== 'adapter' || parts.length < 5) return undefined;
  const suffix = parts.at(-2) === 'parent' ? `:parent:${parts.at(-1)}` : '';
  return `legacy:${parts.slice(0, 4).join(':')}:${suffix}`;
}

export class DependencyRequestIndex {
  readonly #facts = new Map<string, Facts>();
  readonly #subjects = new Map<string, Set<string>>();
  readonly #invalidKeys = new Set<string>();
  readonly #ownerAttempts = new Map<string, Set<string>>();
  #position = 0;
  #entry(key: string): Facts {
    let facts = this.#facts.get(key);
    if (!facts) {facts = {accepted: false, completed: false, invalid: false}; this.#facts.set(key, facts);}
    return facts;
  }
  requested(request: EffectRequest): void {
    const position = this.#position++;
    const facts = this.#entry(request.idempotencyKey);
    if (facts.request) facts.invalid = true;
    else {facts.request = structuredClone(request); facts.position = position;}
    if (facts.invalid) this.#invalidKeys.add(request.idempotencyKey);
    try {
      portableJson(request); validateContractValue('effectRequest', request);
      if (request.attempt.stageId === 'adapter-activation' && request.attempt.runId.startsWith('adapter:')
        && (request.attempt.runId !== request.attempt.attemptId || request.attempt.attemptNumber !== 1)) throw new Error('ADAPTER_DEPENDENCY_ACTIVATION_OWNER_INVALID');
      const scope = ownerScope(request.idempotencyKey);
      if (scope) {
        const attempts = this.#ownerAttempts.get(scope) ?? new Set<string>();
        attempts.add(sha256Text(portableJson(request.attempt))); this.#ownerAttempts.set(scope, attempts);
        if (request.idempotencyKey.startsWith('adapter-dep:') && !/^adapter-dep:utf16-v1:[a-f0-9]{64}:[a-f0-9]{64}$/u.test(request.idempotencyKey)) throw new Error('ADAPTER_DEPENDENCY_IDENTITY_UNSUPPORTED');
      }
    }
    catch {facts.invalid = true; this.#invalidKeys.add(request.idempotencyKey); return;}
    const hash = digest(request), keys = this.#subjects.get(hash) ?? new Set<string>();
    keys.add(request.idempotencyKey); this.#subjects.set(hash, keys);
  }
  accepted(request: EffectRequest): void {
    const position = this.#position++;
    const facts = this.#entry(request.idempotencyKey);
    if (!facts.request || facts.accepted || facts.completed || !same(facts.request, request)) facts.invalid = true;
    if (facts.invalid) this.#invalidKeys.add(request.idempotencyKey);
    facts.accepted = true;
    facts.acceptedPosition ??= position;
  }
  completed(receipt: EffectReceipt): void {
    this.#position++;
    const facts = this.#entry(receipt.idempotencyKey);
    try {portableJson(receipt); validateContractValue('effectReceipt', receipt);}
    catch {facts.invalid = true;}
    if (!facts.request || !facts.accepted || facts.completed || facts.request.effectId !== receipt.effectId) facts.invalid = true;
    if (facts.invalid) this.#invalidKeys.add(receipt.idempotencyKey);
    facts.completed = true;
  }
  #parent(request: EffectRequest | undefined): Facts | undefined {
    if (!request) return undefined;
    const parent = this.#facts.get(request.idempotencyKey);
    if (!parent?.request || parent.invalid || !parent.accepted || !same(parent.request, request)) throw new Error('ADAPTER_DEPENDENCY_PARENT_UNBOUND');
    return parent;
  }
  matches(query: DependencyQuery): readonly EffectRequest[] {
    for (const key of this.#invalidKeys) {
      if (ownedKey(key, query)) throw new Error('ADAPTER_DEPENDENCY_HISTORY_INVALID');
    }
    for (const scope of [`legacy:${query.prefix}${query.suffix}`, `portable:${query.scope}`]) {
      const attempts = this.#ownerAttempts.get(scope);
      if (attempts && (attempts.size !== 1 || !attempts.has(sha256Text(portableJson(query.subject.attempt))))) throw new Error('ADAPTER_DEPENDENCY_HISTORY_OWNER_MISMATCH');
    }
    const parent = this.#parent(query.parent);
    const result: EffectRequest[] = [];
    for (const key of this.#subjects.get(digest(query.subject)) ?? []) {
      if (!ownedKey(key, query)) continue;
      const facts = this.#facts.get(key)!;
      if (!facts.request || facts.invalid || (parent && facts.position! <= parent.acceptedPosition!)) throw new Error('ADAPTER_DEPENDENCY_HISTORY_INVALID');
      result.push(structuredClone(facts.request));
    }
    return result;
  }
}

skills/nova/core/effects/coordinator.ts.syntax:
export class EffectCoordinator {
  readonly #journal: EffectJournal; readonly #now: () => Date; readonly #audit: EffectModeAuditSink | undefined;
  readonly #locks: EffectLockManager; readonly #lockTtlMs: number;

  constructor(journal: EffectJournal, now: () => Date = () => new Date(), audit?: EffectModeAuditSink, locks?: EffectLockManager, lockTtlMs = 300_000) {
    if (!locks) throw new Error('EFFECT_RESOURCE_LOCK_MANAGER_REQUIRED');
    this.#journal = journal; this.#now = now; this.#audit = audit; this.#locks = locks; this.#lockTtlMs = lockTtlMs;
  }

  async invoke(adapter: AdapterInstance, adapterOwner: PackageResolution, invocation: EffectInvocation, signal: AbortSignal): Promise<EffectReceipt> {
    return invokeDurableEffect({
      journal: this.#journal,
      now: this.#now,
      ...(this.#audit ? { audit: {
        requested: (request: EffectRequest) => this.#audit!.requested(request, 'durable'),
        accepted: (request: EffectRequest) => this.#audit!.accepted(request, 'durable'),
        completed: (request: EffectRequest, receipt: EffectReceipt) => this.#audit!.completed(request, receipt, 'durable'),
      } } : {}),
      locks: this.#locks,
      lockTtlMs: this.#lockTtlMs,
    }, adapter, adapterOwner, invocation, signal);
  }

  async invokeConfidential(
    adapter: AdapterInstance,
    adapterOwner: PackageResolution,
    invocation: EffectInvocation,
    signal: AbortSignal,
  ): Promise<Readonly<Record<string, unknown>>> {
    if (signal.aborted) throw new Error('ADAPTER_CANCELLED');
    const request = this.#confidentialRequest(invocation);
    if (Object.hasOwn(request, 'runtimeDispatchProfile')) validateContractValue('effectRequest', request);
    const auditRequest: EffectRequest = { ...request, resource: { type: request.resource.type, canonicalId: '[confidential]' }, payload: { confidential: true } };
    this.#audit?.requested(auditRequest, 'confidential'); this.#audit?.accepted(auditRequest, 'confidential');
    try {
      const result = await adapter.invoke({ request, signal, confidential: true });
      this.#audit?.completed(auditRequest, this.#confidentialReceipt(request, adapterOwner, 'completed'), 'confidential');
      return result;
    } catch (error) {
      this.#audit?.completed(auditRequest, this.#confidentialReceipt(request, adapterOwner, 'failed'), 'confidential');
      throw error;
    }
  }

  #confidentialRequest(invocation: EffectInvocation): EffectRequest {
    return {
      schemaVersion: 'effect-request.v2', effectId: `effect:${crypto.randomUUID()}`, idempotencyKey: invocation.idempotencyKey,
      ...(invocation.deliveryId === undefined ? {} : { deliveryId: invocation.deliveryId }),
      attempt: invocation.attempt, capability: invocation.capability, operation: invocation.operation, resource: invocation.resource,
      payload: invocation.payload, ...runtimeDispatchProfileFields(invocation, invocation.capability), requestedAt: this.#now().toISOString(),
    };
  }

  #confidentialReceipt(request: EffectRequest, adapter: PackageResolution, status: 'completed' | 'failed'): EffectReceipt {
    return {
      schemaVersion: 'effect-receipt.v2', effectId: request.effectId, idempotencyKey: request.idempotencyKey, adapter, status,
      ...(status === 'completed'
        ? { result: { confidential: true } }
        : { error: { code: 'adapter.confidential_effect_failed', message: 'Confidential adapter operation failed' } }),
      recordedAt: this.#now().toISOString(),
    };
  }
}

skills/nova/core/effects/contracts.ts.syntax:
export interface EffectInvocation {
  readonly runtimeDispatchProfile?: RuntimeDispatchProfile;
  readonly dependencyIdentity?: DependencyIdentity;
  readonly idempotencyKey: string;
  readonly deliveryId?: string;
  readonly attempt: AttemptIdentity;
  readonly capability: string;
  readonly operation: string;
  readonly resource: { readonly type: string; readonly canonicalId: string };
  readonly payload: Readonly<Record<string, unknown>>;
}

export interface EffectAuditSink {
  requested(request: EffectRequest): void;
  accepted(request: EffectRequest): void;
  completed(request: EffectRequest, receipt: EffectReceipt): void;
}

export interface EffectModeAuditSink {
  requested(request: EffectRequest, mode: 'durable' | 'confidential'): void;
  accepted(request: EffectRequest, mode: 'durable' | 'confidential'): void;
  completed(request: EffectRequest, receipt: EffectReceipt, mode: 'durable' | 'confidential'): void;
}

export interface EffectLockManager {
  acquire(resource: ResourceLock['resource'], ownerLeaseId: string, ttlMs: number): ResourceLock;
  renew(lockId: string, ownerLeaseId: string, ttlMs: number): ResourceLock;
  release(lockId: string, ownerLeaseId: string): ResourceLock;
  assertCurrent(lockId: string, ownerLeaseId: string): ResourceLock;
}

skills/nova/core/effects/dependency-iden.syntax:
export interface DependencyIdentity {
  readonly prefix: string;
  readonly suffix: string;
  readonly currentKey: string;
  readonly scope: string;
  readonly parent?: {readonly request: EffectRequest; readonly confidential: boolean};
}

export function portableDependencyKey(adapterId: string, capability: string, request: CapabilityInvocation,
  parent: DependencyIdentity['parent'], deliveryId: string | undefined): {key: string; scope: string} {
  const scope = sha256Text(portableJson({adapterId, capability,
    ...(parent ? {parent: {executionKey: parent.request.idempotencyKey, attempt: parent.request.attempt}} : {activation: adapterId})})).slice(7);
  const subject = {schemaVersion: 'adapter-dependency-identity.utf16.v1', adapterId, capability, request,
    ...(parent ? {parent: {executionKey: parent.request.idempotencyKey, attempt: parent.request.attempt}} : {activation: adapterId}),
    ...(deliveryId === undefined ? {} : {deliveryId})};
  return {key: `adapter-dep:utf16-v1:${scope}:${sha256Text(portableJson(subject)).slice(7)}`, scope};
}

function validateParent(identity: DependencyIdentity): void {
  if (!identity.parent) return;
  portableJson(identity.parent.request); validateContractValue('effectRequest', identity.parent.request);
  if (!identity.parent.confidential && !validEffectIdentity(identity.parent.request)) throw new Error('ADAPTER_DEPENDENCY_PARENT_UNBOUND');
}

function validateCandidate(request: EffectRequest, identity: DependencyIdentity): void {
  portableJson(request); validateContractValue('effectRequest', request);
  const inner = request.idempotencyKey.slice(identity.prefix.length, identity.suffix ? -identity.suffix.length : undefined);
  const legacy = request.idempotencyKey.startsWith(identity.prefix) && request.idempotencyKey.endsWith(identity.suffix) && /^[a-f0-9]{64}$/u.test(inner);
  if (!legacy && request.idempotencyKey !== identity.currentKey) throw new Error('ADAPTER_DEPENDENCY_IDENTITY_UNSUPPORTED');
  if (!validEffectIdentity(request)) throw new Error('ADAPTER_DEPENDENCY_HISTORY_INVALID');
}

export async function resolveDependencyInvocation(journal: Partial<DependencyJournal>, invocation: EffectInvocation): Promise<EffectInvocation> {
  const identity = invocation.dependencyIdentity;
  if (!identity) return invocation;
  validateParent(identity);
  if (typeof journal.dependencyRequests !== 'function') throw new Error('ADAPTER_DEPENDENCY_JOURNAL_LOOKUP_REQUIRED');
  const query: DependencyQuery = {subject: invocation, prefix: identity.prefix, suffix: identity.suffix, scope: identity.scope,
    ...(identity.parent && !identity.parent.confidential ? {parent: identity.parent.request} : {})};
  const matches = await journal.dependencyRequests(query);
  matches.forEach(request => validateCandidate(request, identity));
  if (matches.length > 1) throw new Error('ADAPTER_DEPENDENCY_HISTORY_AMBIGUOUS');
  return {...invocation, idempotencyKey: matches[0]?.idempotencyKey ?? identity.currentKey};
}

skills/nova/core/effects/identity.ts.syntax:
function subject(invocation: EffectInvocation) {
  return {
    idempotencyKey: invocation.idempotencyKey,
    ...(invocation.deliveryId === undefined ? {} : { deliveryId: invocation.deliveryId }),
    attempt: invocation.attempt,
    capability: invocation.capability,
    operation: invocation.operation,
    resource: invocation.resource,
    ...runtimeDispatchProfileFields(invocation, invocation.capability),
  };
}

export function stableEffectId(invocation: EffectInvocation): string {
  return `${PORTABLE_PREFIX}${hash(portableJson({ schemaVersion: 'effect-identity.utf16.v1', ...subject(invocation) }))}`;
}

function matchesIdentity(effectId: string, invocation: EffectInvocation): boolean {
  if (/^effect:json-utf16-v1:[a-f0-9]{64}$/u.test(effectId)) return effectId === stableEffectId(invocation);
  // This is the exact old producer algorithm, not an inferred/fallback collator.
  if (/^effect:[a-f0-9]{64}$/u.test(effectId)) return effectId === `effect:${hash(canonicalJson(subject(invocation)))}`;
  return false;
}

export function validEffectIdentity(request: EffectRequest): boolean {
  return matchesIdentity(request.effectId, request);
}

export function assertMatchingRequest(prior: EffectRequest | undefined, invocation: EffectInvocation): void {
  if (!prior) return;
  if (prior.deliveryId !== invocation.deliveryId || !matchesIdentity(prior.effectId, prior) || !matchesIdentity(prior.effectId, invocation)) {
    throw new Error(`EFFECT_IDEMPOTENCY_CONFLICT:${invocation.idempotencyKey}`);
  }
  const serialize = prior.effectId.startsWith(PORTABLE_PREFIX) ? portableJson : canonicalJson;
  if (serialize(prior.payload) !== serialize(invocation.payload)) {
    throw new Error(`EFFECT_IDEMPOTENCY_CONFLICT:${invocation.idempotencyKey}`);
  }
}

skills/nova/core/effects/durable-invocat.syntax:
interface Dependencies {
  readonly journal: EffectJournal;
  readonly now: () => Date;
  readonly audit?: EffectAuditSink;
  readonly locks: EffectLockManager;
  readonly lockTtlMs: number;
}

function lockResource(invocation: EffectInvocation, prior?: EffectRequest): ResourceLock['resource'] {
  if (invocation.capability !== 'runtime.dispatch') return invocation.resource;
  return Object.freeze({ type: 'runtime.invocation', canonicalId: prior?.effectId ?? stableEffectId(invocation) });
}

export async function invokeDurableEffect(
  dependencies: Dependencies,
  adapter: AdapterInstance,
  adapterOwner: PackageResolution,
  invocation: EffectInvocation,
  signal: AbortSignal,
): Promise<EffectReceipt> {
  return new DurableInvocation(dependencies, adapter, adapterOwner, invocation, signal).execute();
}

class DurableInvocation {
  readonly #dependencies: Dependencies; readonly #adapter: AdapterInstance; readonly #adapterOwner: PackageResolution;
  #invocation: EffectInvocation; readonly #signal: AbortSignal; #lock: ResourceLock | undefined;
  constructor(dependencies: Dependencies, adapter: AdapterInstance, adapterOwner: PackageResolution, invocation: EffectInvocation, signal: AbortSignal) {
    this.#dependencies = dependencies; this.#adapter = adapter; this.#adapterOwner = adapterOwner; this.#invocation = invocation; this.#signal = signal;
  }

  async execute(): Promise<EffectReceipt> {
    if (this.#invocation.dependencyIdentity) this.#invocation = await resolveDependencyInvocation(this.#dependencies.journal, this.#invocation);
    let prior = await this.#dependencies.journal.request(this.#invocation.idempotencyKey);
    assertMatchingRequest(prior, this.#invocation);
    const existing = await this.#existingReceipt(prior);
    if (existing) return existing;
    this.#lock = await acquireResource(this.#dependencies.locks, lockResource(this.#invocation, prior), this.#invocation.attempt.attemptId, this.#dependencies.lockTtlMs, this.#signal);
    let failed = false;
    let failure: unknown;
    try {
      if (this.#invocation.dependencyIdentity) this.#invocation = await resolveDependencyInvocation(this.#dependencies.journal, this.#invocation);
      prior = await this.#dependencies.journal.request(this.#invocation.idempotencyKey);
      assertMatchingRequest(prior, this.#invocation);
      const lockedExisting = await this.#existingReceipt(prior);
      if (lockedExisting) return lockedExisting;
      if (this.#lock.resource.canonicalId !== lockResource(this.#invocation, prior).canonicalId) {
        throw new Error(`EFFECT_IDENTITY_CHANGED_DURING_ADMISSION:${this.#invocation.idempotencyKey}`);
      }
      return await this.#executeLocked(prior);
    } catch (error) {
      failed = true; failure = error; throw error;
    } finally {
      try { this.#release(); }
      catch (releaseError) {
        if (failed) throw new AggregateError([failure, releaseError], 'EFFECT_FAILED_AND_LOCK_RELEASE_FAILED', { cause: failure });
        throw releaseError;
      }
    }
  }

  async #existingReceipt(prior: EffectRequest | undefined): Promise<EffectReceipt | undefined> {
    const receipt = await this.#dependencies.journal.receipt(this.#invocation.idempotencyKey);
    if (receipt && (!prior || receipt.effectId !== prior.effectId)) throw new Error(`EFFECT_RECEIPT_ORPHANED:${this.#invocation.idempotencyKey}`);
    if (receipt && this.#invocation.dependencyIdentity) {
      validateContractValue('effectReceipt', receipt);
      if (portableJson(receipt.adapter) !== portableJson(this.#adapterOwner)) throw new Error('ADAPTER_DEPENDENCY_RECEIPT_OWNER_MISMATCH');
    }
    return receipt;
  }

  #request(prior: EffectRequest | undefined): EffectRequest {
    return prior ?? {
      schemaVersion: 'effect-request.v2', effectId: stableEffectId(this.#invocation), idempotencyKey: this.#invocation.idempotencyKey,
      ...(this.#invocation.deliveryId === undefined ? {} : { deliveryId: this.#invocation.deliveryId }),
      attempt: this.#invocation.attempt, capability: this.#invocation.capability, operation: this.#invocation.operation,
      resource: this.#invocation.resource, payload: this.#invocation.payload, ...runtimeDispatchProfileFields(this.#invocation), requestedAt: this.#dependencies.now().toISOString(),
    };
  }

  async #executeLocked(prior: EffectRequest | undefined): Promise<EffectReceipt> {
    const request = this.#request(prior);
    if (this.#invocation.dependencyIdentity || Object.hasOwn(request, 'runtimeDispatchProfile')) validateContractValue('effectRequest', request);
    const controller = new AbortController();
    const timer = this.#renew(controller);
    try {
      await this.#dependencies.journal.requested(request);
      if (!prior) this.#dependencies.audit?.requested(request);
      const accepted = await this.#dependencies.journal.accepted(request);
      return accepted ? await this.#invokeAdapter(request, controller.signal) : await this.#recover(request);
    } finally {
      if (timer) clearInterval(timer);
    }
  }

  #renew(controller: AbortController): NodeJS.Timeout | undefined {
    if (!this.#lock) return undefined;
    const timer = setInterval(() => {
      try { this.#lock = this.#dependencies.locks.renew(this.#lock!.lockId, this.#invocation.attempt.attemptId, this.#dependencies.lockTtlMs); }
      catch (error) { controller.abort(error); }
    }, Math.max(1, Math.floor(this.#dependencies.lockTtlMs / 3)));
    timer.unref(); return timer;
  }

  async #recover(request: EffectRequest): Promise<EffectReceipt> {
    if (!this.#adapter.receipt) throw new Error(`EFFECT_RECOVERY_RECEIPT_UNAVAILABLE:${request.effectId}`);
    const result = await this.#adapter.receipt(request);
    if (result === undefined) throw new Error(`EFFECT_RECOVERY_RECEIPT_MISSING:${request.effectId}`);
    return this.#complete(request, { status: 'completed', result });
  }

  async #invokeAdapter(request: EffectRequest, renewalSignal: AbortSignal): Promise<EffectReceipt> {
    this.#dependencies.audit?.accepted(request);
    this.#lock = this.#dependencies.locks.renew(
      this.#lock!.lockId,
      this.#invocation.attempt.attemptId,
      this.#dependencies.lockTtlMs,
    );
    const lock = this.#lock;
    let asserted = false;
    const invocation = this;
    const fence = {
      get contract(): ResourceLock { return invocation.#lock!; },
      assertCurrent: (): ResourceLock => { asserted = true; return this.#assertCurrent(); },
    };
    try {
      const result = await this.#adapter.invoke({ request, signal: AbortSignal.any([this.#signal, renewalSignal]), confidential: false, lock, fence });
      if (!asserted) throw new Error(`ADAPTER_FENCE_NOT_ASSERTED:${request.effectId}`);
      this.#assertCurrent();
      return this.#complete(request, { status: 'completed', result });
    } catch (error) {
      return this.#complete(request, { status: 'failed', error: { code: 'adapter.effect_failed', message: error instanceof Error ? error.message : String(error) } });
    }
  }

  #assertCurrent(): ResourceLock {
    return this.#dependencies.locks.assertCurrent(this.#lock!.lockId, this.#invocation.attempt.attemptId);
  }

  #complete(request: EffectRequest, outcome: Pick<EffectReceipt, 'status' | 'result' | 'error'>): Promise<EffectReceipt> {
    const receipt: EffectReceipt = {
      schemaVersion: 'effect-receipt.v2', effectId: request.effectId, idempotencyKey: this.#invocation.idempotencyKey,
      adapter: this.#adapterOwner, ...outcome, recordedAt: this.#dependencies.now().toISOString(),
    };
    if (this.#invocation.dependencyIdentity) {portableJson(receipt); validateContractValue('effectReceipt', receipt);}
    return this.#persistReceipt(request, receipt);
  }

  async #persistReceipt(request: EffectRequest, receipt: EffectReceipt): Promise<EffectReceipt> {
    await this.#dependencies.journal.completed(receipt); this.#dependencies.audit?.completed(request, receipt); return receipt;
  }

  #release(): void {
    if (!this.#lock) return;
    this.#dependencies.locks.release(this.#lock.lockId, this.#invocation.attempt.attemptId); this.#lock = undefined;
  }
}

skills/nova/core/effects/resource-acquis.syntax:
export async function acquireResource(
  locks: EffectLockManager, resource: ResourceLock['resource'], owner: string,
  ttlMs: number, signal: AbortSignal,
): Promise<ResourceLock> {
  const deadline = performance.now() + Math.min(ttlMs, 30_000);
  let contention: Error | undefined;
  for (;;) {
    if (signal.aborted) throw new Error('EFFECT_RESOURCE_WAIT_CANCELLED', { cause: signal.reason });
    if (contention && performance.now() >= deadline) throw new Error('EFFECT_RESOURCE_WAIT_TIMEOUT', { cause: contention });
    try { return locks.acquire(resource, owner, ttlMs); }
    catch (error) {
      if (!(error instanceof Error) || !/^RESOURCE_LOCK(?:ED|_PROVISIONING):/u.test(error.message)) throw error;
      contention = error;
    }
    await waitForResource(signal, Math.min(10, Math.max(1, deadline - performance.now())));
  }
}

function waitForResource(signal: AbortSignal, delayMs: number): Promise<void> {
  return new Promise((resolve, reject) => {
    const done = (): void => { signal.removeEventListener('abort', abort); resolve(); };
    const timer = setTimeout(done, delayMs);
    const abort = (): void => {
      clearTimeout(timer); signal.removeEventListener('abort', abort);
      reject(new Error('EFFECT_RESOURCE_WAIT_CANCELLED', { cause: signal.reason }));
    };
    signal.addEventListener('abort', abort, { once: true });
    if (signal.aborted) abort();
  });
}

skills/nova/core/effects/memory-locks.ts.syntax:
export class MemoryResourceLockManager implements EffectLockManager {
  readonly #locks = new Map<string, ResourceLock>();
  #fencingToken = 0;

  acquire(resource: ResourceLock['resource'], ownerLeaseId: string, ttlMs: number): ResourceLock {
    const key = canonical(resource);
    const current = this.#locks.get(key);
    if (current && Date.parse(current.expiresAt) > Date.now()) throw new Error(`RESOURCE_LOCKED:${resource.canonicalId}`);
    const acquiredAt = new Date();
    const lock: ResourceLock = Object.freeze({
      schemaVersion: 'resource-lock.v2', lockId: `lock:${crypto.randomUUID()}`, resource, ownerLeaseId,
      fencingToken: ++this.#fencingToken, status: 'active', acquiredAt: acquiredAt.toISOString(),
      expiresAt: new Date(acquiredAt.getTime() + ttlMs).toISOString(),
    });
    this.#locks.set(key, lock);
    return lock;
  }

  renew(lockId: string, ownerLeaseId: string, ttlMs: number): ResourceLock {
    const active = this.assertCurrent(lockId, ownerLeaseId);
    const renewed: ResourceLock = Object.freeze({ ...active, expiresAt: new Date(Date.now() + ttlMs).toISOString() });
    this.#locks.set(canonical(active.resource), renewed);
    return renewed;
  }

  release(lockId: string, ownerLeaseId: string): ResourceLock {
    const active = this.assertCurrent(lockId, ownerLeaseId);
    const released: ResourceLock = Object.freeze({ ...active, status: 'released', releasedAt: new Date().toISOString() });
    this.#locks.delete(canonical(active.resource));
    return released;
  }

  assertCurrent(lockId: string, ownerLeaseId: string): ResourceLock {
    const active = [...this.#locks.values()].find((lock) => lock.lockId === lockId);
    if (!active) throw new Error(`RESOURCE_LOCK_UNKNOWN:${lockId}`);
    if (active.ownerLeaseId !== ownerLeaseId) throw new Error(`RESOURCE_LOCK_OWNER_DENIED:${lockId}`);
    if (Date.parse(active.expiresAt) <= Date.now()) throw new Error(`RESOURCE_LOCK_EXPIRED:${lockId}`);
    return active;
  }
}

