import type {
  StageDefinition,
  StageResult,
  WaitRequest,
} from '@kubeclaw/plugin-sdk';

export interface StageRuntimeState {
  readonly stageId: string;
  readonly status: StageStatus;
  readonly attemptNumber: number;
  readonly attemptsUsed: number;
  readonly remediationCyclesUsed: number;
  readonly technicalRetriesUsed?: number;
  readonly repairLedger?: readonly RepairOrder[];
  readonly pendingRepair?: PendingRepair;
  readonly continuationGuidance?: Readonly<Record<string, unknown>>;
  readonly facts?: Readonly<Record<string, string | number | boolean | null>>;
  readonly wait?: WaitRequest;
  readonly retryAt?: string;
  readonly remediationReturnTo?: string;
  readonly remediationTarget?: string;
}

export type LifecycleAction =
  | { readonly type: 'complete' }
  | { readonly type: 'schedule_attempt' }
  | { readonly type: 'schedule_remediation'; readonly stageId: string; readonly repairRequest?: RepairRequest }
  | { readonly type: 'request_repair_authorization'; readonly pending: PendingRepair }
  | { readonly type: 'persist_wait'; readonly wait: WaitRequest }
  | { readonly type: 'pause_for_orchestrator'; readonly wait: WaitRequest }
  | { readonly type: 'request_orchestrator'; readonly afterAttempt: number }
  | { readonly type: 'stop' }
  | { readonly type: 'cooldown'; readonly retryAt: string };

export interface LifecycleDecision {
  readonly state: StageRuntimeState;
  readonly action: LifecycleAction;
}

function frozenFacts(
  facts: Readonly<Record<string, string | number | boolean | null>>,
): Readonly<Record<string, string | number | boolean | null>> {
  return Object.freeze({ ...facts });
}

function requiredReason(result: StageResult): void {
  if (result.outcome !== 'passed' && !result.reason) {
    throw new Error(`STAGE_RESULT_REASON_REQUIRED:${result.outcome}`);
  }
}

function stopWhenExhausted(definition: StageDefinition, attempted: AttemptedState): LifecycleDecision | undefined {
  return attempted.attemptsUsed >= definition.execution.maxAttempts
    ? { state: { ...attempted, status: 'blocked' }, action: { type: 'stop' } }
    : undefined;
}

const pass: ResultHandler = (_definition, _current, attempted, result) => ({
  state: { ...attempted, status: 'succeeded', ...(result.outcome === 'passed' && result.facts ? { facts: frozenFacts(result.facts) } : {}) },
  action: { type: 'complete' },
});

const retry: ResultHandler = (definition, _current, attempted) => stopWhenExhausted(definition, attempted) ?? (
  definition.execution.orchestratorAfterAttempt === attempted.attemptsUsed
    ? { state: { ...attempted, status: 'waiting' }, action: { type: 'request_orchestrator', afterAttempt: attempted.attemptsUsed } }
    : { state: { ...attempted, status: 'retrying' }, action: { type: 'schedule_attempt' } }
);

const requestFix: ResultHandler = (definition, current, attempted) => {
  const remediationCyclesUsed = current.remediationCyclesUsed + 1;
  const target = definition.on?.request_fix;
  if (!target) throw new Error(`STAGE_REMEDIATION_UNDECLARED:${definition.id}`);
  const exhausted = attempted.attemptsUsed >= definition.execution.maxAttempts
    || (!definition.execution.repairCategory && remediationCyclesUsed > definition.execution.maxRemediationCycles);
  if (exhausted) return { state: { ...attempted, remediationCyclesUsed, status: 'blocked' }, action: { type: 'stop' } };
  return { state: { ...attempted, remediationCyclesUsed, status: 'waiting', remediationTarget: target }, action: { type: 'schedule_remediation', stageId: target } };
};

const wait: ResultHandler = (definition, _current, attempted, result) => stopWhenExhausted(definition, attempted) ?? (
  result.outcome === 'wait'
    ? { state: { ...attempted, status: 'waiting', wait: result.wait }, action: { type: 'persist_wait', wait: result.wait } }
    : result.outcome === 'orchestrator_required'
      ? { state: { ...attempted, status: 'waiting', wait: result.wait }, action: { type: 'pause_for_orchestrator', wait: result.wait } }
      : { state: { ...attempted, status: 'waiting', retryAt: result.outcome === 'rate_limited' ? result.retryAt : '' }, action: { type: 'cooldown', retryAt: result.outcome === 'rate_limited' ? result.retryAt : '' } }
);

const handlers: Record<StageResult['outcome'], ResultHandler> = {
  passed: pass, retry, request_fix: requestFix, wait, orchestrator_required: wait, rate_limited: wait,
  blocked: stopped('blocked'), failed: stopped('failed'), timed_out: stopped('failed'), cancelled: stopped('cancelled'),
};

export function applyStageResult(
  definition: StageDefinition,
  current: StageRuntimeState,
  result: StageResult,
): LifecycleDecision {
  if (current.status !== 'running') throw new Error(`STAGE_RESULT_ILLEGAL_STATE:${current.status}`);
  requiredReason(result);
  const {
    wait: _wait,
    retryAt: _retryAt,
    pendingRepair: _pendingRepair,
    ...activeState
  } = current;
  const attempted = {
    ...activeState,
    attemptNumber: current.attemptNumber + 1,
    attemptsUsed: current.attemptsUsed + 1,
  };
  if (definition.execution.maxTechnicalRetries !== undefined && ['retry', 'rate_limited'].includes(result.outcome)) {
    const technicalRetriesUsed = (current.technicalRetriesUsed ?? 0) + 1;
    const technical = { ...attempted, technicalRetriesUsed };
    if (technicalRetriesUsed > definition.execution.maxTechnicalRetries) return { state: { ...attempted, status: 'blocked' }, action: { type: 'stop' } };
    return handlers[result.outcome](definition, current, technical, result);
  }
  return handlers[result.outcome](definition, current, attempted, result);
}

skills/nova/core/lifecycle/repair-budget.syntax:
export interface RepairOrder {
  readonly repairIdentityEncoding?: typeof PORTABLE_JSON_ENCODING;
  readonly id: string;
  readonly category: string;
  readonly requesterStageId: string;
  readonly requesterAttempt: number;
  readonly requestDigest: string;
  readonly request: RepairRequest;
  readonly sourceFacts: Readonly<Record<string, string | number | boolean | null>>;
  readonly authorization?: Readonly<{ signalId: string; reason: string }>;
}

export interface PendingRepair {
  readonly repairIdentityEncoding?: typeof PORTABLE_JSON_ENCODING;
  readonly digest: string;
  readonly category: string;
  readonly request: RepairRequest;
  readonly history: readonly RepairOrder[];
  readonly sourceFacts: Readonly<Record<string, string | number | boolean | null>>;
}

export function repairOrder(pending: PendingRepair, attempt: number): RepairOrder {
  return { ...(pending.repairIdentityEncoding ? { repairIdentityEncoding: pending.repairIdentityEncoding } : {}),
    id: pending.digest, category: pending.category, requesterStageId: pending.request.requesterStageId,
    requesterAttempt: attempt, requestDigest: pending.digest, request: pending.request, sourceFacts: pending.sourceFacts };
}

export function pendingRepair(
  stages: readonly StageDefinition[], states: ReadonlyMap<string, StageRuntimeState>,
  requester: StageDefinition, state: StageRuntimeState, result: StageResult, runId: string,
  repairIdentityEncoding?: typeof PORTABLE_JSON_ENCODING,
): PendingRepair {
  const target = requester.on!.request_fix!;
  const request = repairRequest(stages, requester.id, target, state.remediationCyclesUsed, result);
  const category = requester.execution.repairCategory!;
  const history = states.get(target)?.repairLedger ?? [];
  const sourceFacts = states.get(target)?.facts ?? {};
  const identity = { ...(repairIdentityEncoding ? { repairIdentityEncoding } : {}), category, request, history, sourceFacts };
  const serialize = repairIdentityEncoding ? portableJson : canonicalJson;
  return { digest: sha256Text(serialize({ runId, ...identity })), ...identity };
}

export function repairDisposition(stages: readonly StageDefinition[], pending: PendingRepair): 'allowed' | 'authorize' | 'blocked' {
  const policy = stages.find(stage => stage.id === pending.request.targetStageId)?.execution.repairBudget;
  if (!policy || policy.categories[pending.category] === undefined) throw new Error('REPAIR_BUDGET_UNDECLARED');
  const authorized = pending.history.filter(order => order.authorization).length;
  // Once an extra order was issued, any later repair requires operator action.
  if (authorized > 0) return 'blocked';
  if (pending.history.filter(order => order.category === pending.category).length < policy.categories[pending.category]!) return 'allowed';
  return authorized < policy.maximumOrchestratorOrders ? 'authorize' : 'blocked';
}

function extraOrderUsed(states: ReadonlyMap<string, StageRuntimeState>, requester: StageDefinition): boolean {
  const owner = requester.execution.repairBudget ? requester.id : requester.on?.request_fix;
  return Boolean(owner && states.get(owner)?.repairLedger?.some(order => order.authorization));
}

export function budgetedRepairDecision(
  stages: readonly StageDefinition[], states: ReadonlyMap<string, StageRuntimeState>, requester: StageDefinition,
  decision: LifecycleDecision, result: StageResult, runId: string,
  identity: RepairIdentityContext = {},
): LifecycleDecision {
  if (identity.projection && (!requester.execution.repairCategory || decision.action.type !== 'schedule_remediation')) {
    throw new Error('REPAIR_PROJECTION_DISPOSITION_INVALID');
  }
  if (decision.state.status === 'failed' && extraOrderUsed(states, requester)) {
    return { state: { ...decision.state, status: 'blocked' }, action: { type: 'stop' } };
  }
  if (!requester.execution.repairCategory || decision.action.type !== 'schedule_remediation') return decision;
  const calculated = pendingRepair(stages, states, requester, decision.state, result, runId, identity.encoding);
  const disposition = repairDisposition(stages, calculated);
  const pending = reconcileRepairProjection(calculated, identity, decision.state.attemptNumber, disposition);
  if (disposition === 'allowed') return { ...decision, action: { ...decision.action,
    repairRequest: { ...pending.request, budgetOrder: repairOrder(pending, decision.state.attemptNumber) } } };
  const { remediationTarget: _target, ...withoutTarget } = decision.state;
  return { state: { ...withoutTarget, status: disposition === 'authorize' ? 'waiting' : 'blocked', pendingRepair: pending },
    action: disposition === 'authorize' ? { type: 'request_repair_authorization', pending } : { type: 'stop' } };
}

export function recordRepairOrder(states: Map<string, StageRuntimeState>, request: RepairRequest): void {
  if (!request.budgetOrder) return;
  const target = states.get(request.targetStageId)!;
  const ledger = target.repairLedger ?? [];
  const existing = ledger.find(order => order.id === request.budgetOrder!.id);
  if (existing) {
    if (canonicalJson(existing) !== canonicalJson(request.budgetOrder)) throw new Error('REPAIR_ORDER_IDENTITY_CONFLICT');
    return;
  }
  states.set(request.targetStageId, { ...target, repairLedger: [...ledger, request.budgetOrder] });
}

export function validateAdministrativeRepairProjection(stages: readonly StageDefinition[], states: ReadonlyMap<string, StageRuntimeState>,
  state: StageRuntimeState, event: LifecycleEvent, identity: RepairIdentityContext): void {
  const completion = identity.administrativeCompletion;
  if (!completion) return;
  const requester = stages.find(stage => stage.id === state.stageId)!;
  const result = completion.payload.result as StageResult;
  const calculated = pendingRepair(stages, states, requester, { ...state, remediationCyclesUsed: state.remediationCyclesUsed + 1 },
    result, event.identity.runId, identity.encoding);
  const disposition = repairDisposition(stages, calculated);
  if (disposition !== 'allowed') throw new Error('REPAIR_PROJECTION_ADMINISTRATIVE_BUDGET_EXHAUSTED');
  const pending = reconcileRepairProjection(calculated, identity, state.attemptNumber, disposition);
  const expected = { ...pending.request, budgetOrder: repairOrder(pending, state.attemptNumber) };
  if (event.payload.remediationCyclesUsed !== state.remediationCyclesUsed + 1 || event.payload.attemptsUsed !== state.attemptsUsed
    || portableJson(event.payload.repairRequest) !== portableJson(expected)) throw new Error('REPAIR_PROJECTION_ADMINISTRATIVE_SEMANTICS_INVALID');
}

skills/nova/core/lifecycle/repair-projec.syntax:
export interface RepairIdentityContext {
  readonly encoding?: typeof PORTABLE_JSON_ENCODING | undefined;
  readonly projection?: Readonly<{ kind: 'pending' | 'order'; value: unknown }>;
  readonly administrativeCompletion?: LifecycleEvent;
}

export function repairIdentityEncoding(value: unknown): typeof PORTABLE_JSON_ENCODING | undefined {
  if (value !== undefined && value !== PORTABLE_JSON_ENCODING) throw new Error('REPAIR_IDENTITY_ENCODING_UNSUPPORTED');
  return value;
}

function isAdministrativeProjection(event: LifecycleEvent, administrative: ReadonlyMap<string, unknown>): boolean {
  if (!event.payload.administrativeDecision || !event.causationId || !administrative.has(event.causationId)) return false;
  const decision = administrative.get(event.causationId) as AdministrativeReopenDecision;
  semanticMatch(event.payload.administrativeDecision, decision);
  if (decision.decisionId !== event.causationId || decision.runId !== event.identity.runId
    || decision.stageId !== event.identity.stageId || decision.continuation !== 'remediation'
    || decision.remediationStageId !== event.payload.remediationStageId) throw new Error('REPAIR_PROJECTION_ADMINISTRATIVE_INVALID');
  return true;
}

function projected(event: LifecycleEvent): RepairIdentityContext['projection'] {
  if (event.type === 'stage.waiting' && event.payload.repairRequest) {
    const request = event.payload.repairRequest as Record<string, unknown>;
    if (request.budgetOrder) {
      if (request.requesterStageId !== event.identity.stageId) throw new Error('REPAIR_PROJECTION_STAGE_INVALID');
      const order = request.budgetOrder as RepairOrder;
      semanticMatch(request, { ...order.request, budgetOrder: order });
      return { kind: 'order', value: order };
    }
  }
  if (event.type === 'orchestrator.required' && event.payload.wait) {
    const wait = event.payload.wait as { request?: { repairAuthorization?: unknown } };
    if (wait.request?.repairAuthorization) {
      const pending = wait.request.repairAuthorization as PendingRepair;
      if (pending.request?.requesterStageId !== event.identity.stageId) throw new Error('REPAIR_PROJECTION_STAGE_INVALID');
      return { kind: 'pending', value: pending };
    }
  }
  return undefined;
}

class ProjectionIndex {
  readonly contexts = new Map<LifecycleEvent, RepairIdentityContext>();
  readonly #latest = new Map<string, LifecycleEvent>();
  readonly #administrative = new Map<string, unknown>();
  readonly #administrativeProjections = new Set<string>();

  record(entry: LifecycleEvent): void {
    this.#recordAdministrative(entry);
    if (!entry.identity.stageId) return;
    if (completions.has(entry.type)) {
      this.contexts.set(entry, { encoding: repairIdentityEncoding(entry.payload.repairIdentityEncoding) });
      this.#latest.set(entry.identity.stageId, entry);
      return;
    }
    const projection = projected(entry);
    if (projection) this.#associate(entry, projection);
  }

  #recordAdministrative(entry: LifecycleEvent): void {
    if (entry.type !== 'run.resumed' || !entry.causationId || !entry.payload.administrativeDecision) return;
    if (this.#administrative.has(entry.causationId)) throw new Error('REPAIR_PROJECTION_ADMINISTRATIVE_AMBIGUOUS');
    this.#administrative.set(entry.causationId, entry.payload.administrativeDecision);
  }

  #associate(entry: LifecycleEvent, projection: NonNullable<RepairIdentityContext['projection']>): void {
    const completion = this.#latest.get(entry.identity.stageId!);
    if (isAdministrativeProjection(entry, this.#administrative)) {
      if (!completion || this.#administrativeProjections.has(entry.causationId!)) throw new Error('REPAIR_PROJECTION_ADMINISTRATIVE_AMBIGUOUS');
      this.#administrativeProjections.add(entry.causationId!);
      this.contexts.set(entry, { encoding: repairIdentityEncoding(completion.payload.repairIdentityEncoding), projection,
        administrativeCompletion: completion });
      return;
    }
    if (!completion || completion.causationId !== entry.causationId) throw new Error('REPAIR_PROJECTION_CAUSATION_INVALID');
    const prior = this.contexts.get(completion)!;
    if (prior.projection) throw new Error('REPAIR_PROJECTION_AMBIGUOUS');
    this.contexts.set(completion, { ...prior, projection });
  }
}

export function repairIdentityContexts(records: readonly JournalRecord<LifecycleEvent | PluginDomainEvent>[],
  runId: string): ReadonlyMap<LifecycleEvent, RepairIdentityContext> {
  const index = new ProjectionIndex();
  for (const { entry } of records) {
    if (entry.schemaVersion === 'lifecycle-event.v2' && entry.identity.runId === runId) index.record(entry);
  }
  return index.contexts;
}

function digest(value: unknown): string {
  if (typeof value !== 'string' || !/^sha256:[a-f0-9]{64}$/u.test(value)) throw new Error('REPAIR_PROJECTION_DIGEST_INVALID');
  return value;
}

function semanticMatch(actual: unknown, expected: unknown): void {
  if (portableJson(actual) !== portableJson(expected)) throw new Error('REPAIR_PROJECTION_SEMANTICS_INVALID');
}

export function reconcileRepairProjection(pending: PendingRepair, identity: RepairIdentityContext,
  attempt: number, disposition: 'allowed' | 'authorize' | 'blocked'): PendingRepair {
  const projection = identity.projection;
  if (!projection) return pending; // Existing completion-only legacy crash prefixes remain supported.
  if (projection.kind === 'pending') {
    if (disposition !== 'authorize') throw new Error('REPAIR_PROJECTION_DISPOSITION_INVALID');
    const { digest: storedDigest, ...body } = projection.value as PendingRepair;
    const { digest: calculatedDigest, ...expected } = pending;
    semanticMatch(body, expected);
    const stored = digest(storedDigest);
    if (identity.encoding && stored !== calculatedDigest) throw new Error('REPAIR_PROJECTION_DIGEST_INVALID');
    return { ...pending, digest: stored };
  }
  if (disposition !== 'allowed') throw new Error('REPAIR_PROJECTION_DISPOSITION_INVALID');
  const { id, requestDigest, ...body } = projection.value as RepairOrder;
  const expected = { ...(pending.repairIdentityEncoding ? { repairIdentityEncoding: pending.repairIdentityEncoding } : {}),
    category: pending.category, requesterStageId: pending.request.requesterStageId, requesterAttempt: attempt,
    request: pending.request, sourceFacts: pending.sourceFacts };
  semanticMatch(body, expected);
  const stored = digest(id);
  if (stored !== requestDigest || (identity.encoding && stored !== pending.digest)) throw new Error('REPAIR_PROJECTION_DIGEST_INVALID');
  return { ...pending, digest: stored };
}

