export function administrativeRepairRequest(definition: PipelineDefinition, decision: AdministrativeReopenDecision,
  events: FileJournal<LifecycleEvent | PluginDomainEvent>, generation: number, states?: ReadonlyMap<string, StageRuntimeState>): RepairRequest {
  if (decision.continuation !== 'remediation') throw new Error('ADMIN_REMEDIATION_DECISION_REQUIRED');
  const completion = [...events.records()].reverse().find(({ entry }) => entry.schemaVersion === 'lifecycle-event.v2'
    && entry.identity.runId === decision.runId && entry.identity.stageId === decision.stageId
    && ['attempt.completed', 'attempt.cancelled', 'attempt.timed_out'].includes(entry.type));
  const result = completion?.entry.payload.result;
  if (!result) throw new Error(`ADMIN_REMEDIATION_EVIDENCE_MISSING:${decision.stageId}`);
  validateContractValue('stageResult', result);
  const stage = definition.stages.find(candidate => candidate.id === decision.stageId)!;
  if (stage.execution.repairCategory) {
    const current = states?.get(stage.id);
    if (!current) throw new Error('ADMIN_REPAIR_STATE_REQUIRED');
    const pending = pendingRepair(definition.stages, states!, stage, { ...current, remediationCyclesUsed: generation }, result as StageResult, decision.runId,
      repairIdentityEncoding(completion!.entry.payload.repairIdentityEncoding));
    if (repairDisposition(definition.stages, pending) !== 'allowed') throw new Error('ADMIN_REPAIR_BUDGET_EXHAUSTED');
    return { ...pending.request, budgetOrder: repairOrder(pending, current.attemptNumber) };
  }
  return repairRequest(definition.stages, decision.stageId, decision.remediationStageId, generation, result as StageResult);
}

skills/nova/core/lifecycle/recovery.ts.syntax:
import type {
  LifecycleEvent,
  PipelineDefinition,
  PluginDomainEvent,
} from '@kubeclaw/plugin-sdk';

function deepFreeze<T>(value: T): T {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
  return Object.freeze(value);
}

export function recoverStageStates(
  definition: PipelineDefinition,
  records: readonly JournalRecord<LifecycleEvent | PluginDomainEvent>[],
  runId: string,
  orchestratorIssuerId: string,
): ReadonlyMap<string, StageRuntimeState> {
  const states = initialStageStates(definition);
  const identities = repairIdentityContexts(records, runId);
  for (const record of records) {
    const event = record.entry;
    if (event.schemaVersion !== 'lifecycle-event.v2' || event.identity.runId !== runId) continue;
    applyRecoveryEvent(definition, states, event, orchestratorIssuerId, identities.get(event));
  }
  resetInterruptedStages(states);
  return new FrozenMap(
    [...states].map(([stageId, state]) => [stageId, deepFreeze(structuredClone(state))]),
  );
}

export function recoverWaitCreation(
  definition: PipelineDefinition,
  records: readonly JournalRecord<LifecycleEvent | PluginDomainEvent>[],
  runId: string,
  orchestratorIssuerId: string,
  waitId: string,
): JournalRecord<LifecycleEvent | PluginDomainEvent> | undefined {
  const states = initialStageStates(definition);
  const identities = repairIdentityContexts(records, runId);
  let created: JournalRecord<LifecycleEvent | PluginDomainEvent> | undefined;
  for (const record of records) {
    const event = record.entry;
    if (event.schemaVersion !== 'lifecycle-event.v2' || event.identity.runId !== runId) continue;
    const stageId = event.identity.stageId;
    const previous = stageId ? states.get(stageId)?.wait?.waitId : undefined;
    applyRecoveryEvent(definition, states, event, orchestratorIssuerId, identities.get(event));
    if (stageId && previous !== waitId && states.get(stageId)?.wait?.waitId === waitId) created = record;
  }
  return created;
}

skills/nova/core/lifecycle/recovery-stat.syntax:
import type {
  LifecycleEvent,
  PipelineDefinition,
  StageResult,
  WaitRequest,
  ResumeSignal,
} from '@kubeclaw/plugin-sdk';

function count(value: unknown): number {
  return typeof value === 'number' && Number.isInteger(value) && value >= 0 ? value : 0;
}

function budgets(event: LifecycleEvent, current: StageRuntimeState): Pick<StageRuntimeState, 'attemptsUsed' | 'remediationCyclesUsed'> {
  return {
    attemptsUsed: event.payload.attemptsUsed === undefined ? current.attemptsUsed : count(event.payload.attemptsUsed),
    remediationCyclesUsed: event.payload.remediationCyclesUsed === undefined
      ? current.remediationCyclesUsed
      : count(event.payload.remediationCyclesUsed),
  };
}

export function initialStageStates(definition: PipelineDefinition): StateMap {
  return new Map([...definition.stages]
    .sort((left, right) => left.id.localeCompare(right.id))
    .map((stage) => [stage.id, {
      stageId: stage.id,
      status: 'pending' as const,
      attemptNumber: 0,
      attemptsUsed: 0,
      remediationCyclesUsed: 0,
    }]));
}

function recoverAttemptResult(
  definition: PipelineDefinition,
  event: LifecycleEvent,
  current: StageRuntimeState,
  orchestratorIssuerId: string,
  states: StateMap,
  identity: RepairIdentityContext,
): StageRuntimeState | undefined {
  if (!['attempt.completed', 'attempt.cancelled', 'attempt.timed_out'].includes(event.type)) return undefined;
  if (identity.projection && current.status !== 'running') throw new Error('REPAIR_PROJECTION_COMPLETION_STATE_INVALID');
  if (!event.payload.result || typeof event.payload.result !== 'object' || current.status !== 'running') return undefined;
  const stage = definition.stages.find(({ id }) => id === current.stageId);
  if (!stage) return undefined;
  const result = event.payload.result as StageResult;
  const original = applyStageResult(stage, {
    ...current,
    attemptNumber: Math.max(0, current.attemptNumber - 1),
    attemptsUsed: Math.max(0, current.attemptsUsed - 1),
  }, result);
  const decision = budgetedRepairDecision(definition.stages, states, stage, original, result, event.identity.runId, identity);
  const wait = decisionWait(decision, event.identity.runId, orchestratorIssuerId);
  const state = wait ? { ...decision.state, wait } : decision.state;
  if (decision.action.type === 'schedule_remediation') {
    states.set(stage.id, state);
    applyRepair(states, decision.action.repairRequest ?? repairRequest(definition.stages, stage.id,
      decision.action.stageId, state.remediationCyclesUsed, result));
    return states.get(stage.id);
  }
  return decision.action.type === 'schedule_attempt' ? { ...state, status: 'pending' } : state;
}

function scheduleState(event: LifecycleEvent, current: StageRuntimeState, states: StateMap): StageRuntimeState {
  if (typeof event.payload.remediationReturnTo === 'string') {
    return { ...current, status: 'pending', remediationReturnTo: event.payload.remediationReturnTo };
  }
  const { remediationTarget: _target, ...withoutTarget } = current;
  const remediationStageId = event.payload.remediationStageId;
  if (typeof remediationStageId === 'string') {
    const remediation = states.get(remediationStageId);
    if (remediation) {
      const { remediationReturnTo: _returnTo, ...withoutReturn } = remediation;
      states.set(remediationStageId, withoutReturn);
    }
  }
  return { ...withoutTarget, status: 'pending' };
}

function waitingState(event: LifecycleEvent, current: StageRuntimeState): StageRuntimeState {
  const wait = event.payload.wait;
  return {
    ...current,
    ...budgets(event, current),
    status: 'waiting',
    ...(wait && typeof wait === 'object' ? { wait: wait as WaitRequest } : {}),
    ...(typeof event.payload.retryAt === 'string' ? { retryAt: event.payload.retryAt } : {}),
    ...(typeof event.payload.remediationStageId === 'string'
      ? { remediationTarget: event.payload.remediationStageId }
      : {}),
  };
}

function succeededState(event: LifecycleEvent, current: StageRuntimeState): StageRuntimeState {
  const facts = event.payload.facts;
  return {
    ...current,
    ...budgets(event, current),
    status: 'succeeded',
    ...(facts && typeof facts === 'object' && !Array.isArray(facts)
      ? { facts: Object.freeze({ ...(facts as Record<string, string | number | boolean | null>) }) }
      : {}),
    ...(typeof event.payload.remediationReturnTo === 'string'
      ? { remediationReturnTo: event.payload.remediationReturnTo }
      : {}),
  };
}

const terminalStatus = new Map<string, StageRuntimeState['status']>([
  ['stage.skipped', 'skipped'],
  ['stage.blocked', 'blocked'],
  ['stage.failed', 'failed'],
  ['stage.cancelled', 'cancelled'],
]);

function stageEventState(event: LifecycleEvent, current: StageRuntimeState, states: StateMap): StageRuntimeState | undefined {
  if (event.type === 'stage.scheduled') return scheduleState(event, current, states);
  if (event.type === 'stage.started') return { ...current, status: 'running' };
  if (event.type === 'stage.retrying') return { ...current, ...budgets(event, current), status: 'pending' };
  if (event.type === 'stage.waiting' || event.type === 'orchestrator.required') return waitingState(event, current);
  if (event.type === 'stage.succeeded') return succeededState(event, current);
  const status = terminalStatus.get(event.type);
  return status ? { ...current, ...budgets(event, current), status } : undefined;
}

function resolvedWaitState(event: LifecycleEvent, current: StageRuntimeState): StageRuntimeState {
  const { wait: _wait, ...withoutWait } = current;
  const signal = event.payload.signal as ResumeSignal;
  if (!signal || signal.waitId !== event.identity.waitId) throw new Error('RECOVERY_WAIT_SIGNAL_INVALID');
  return { ...withoutWait, status: 'pending', continuationGuidance: signal.payload };
}

export function applyRecoveryEvent(
  definition: PipelineDefinition,
  states: StateMap,
  event: LifecycleEvent,
  orchestratorIssuerId: string,
  identity: RepairIdentityContext = { encoding: repairIdentityEncoding(event.payload.repairIdentityEncoding) },
): void {
  const stageId = event.identity.stageId;
  if (!stageId) return;
  const current = states.get(stageId);
  if (!current) return;
  if (event.type === 'stage.waiting' && event.payload.repairRequest) {
    validateAdministrativeRepairProjection(definition.stages, states, current, event, identity);
    states.set(stageId, { ...current, ...budgets(event, current) });
    applyRepair(states, event.payload.repairRequest as unknown as RepairRequest); return;
  }
  if (event.type === 'attempt.created') {
    const attemptNumber = count(event.payload.attemptNumber);
    states.set(stageId, { ...current, attemptNumber: Math.max(current.attemptNumber, attemptNumber), attemptsUsed: Math.max(current.attemptsUsed, attemptNumber) });
    return;
  }
  if (event.type === 'wait.resolved') {
    const repair = authorizedRepair(definition.stages, states, current, event.payload.signal as ResumeSignal);
    if (repair) { applyRepair(states, repair); return; }
    states.set(stageId, resolvedWaitState(event, current));
    return;
  }
  const recovered = recoverAttemptResult(definition, event, current, orchestratorIssuerId, states, identity)
    ?? stageEventState(event, current, states);
  if (recovered) {
    states.set(stageId, recovered);
  }
}

export function resetInterruptedStages(states: StateMap): void {
  for (const [stageId, state] of states) {
    if (state.status === 'running') states.set(stageId, { ...state, status: 'pending' });
  }
}

skills/nova/core/lifecycle/wait-request..syntax:
export function decisionWait(decision: LifecycleDecision, runId: string, issuer: string): WaitRequest | undefined {
  const action = decision.action;
  if (action.type === 'persist_wait') return action.wait;
  if (action.type !== 'pause_for_orchestrator' && action.type !== 'request_orchestrator' && action.type !== 'request_repair_authorization') return undefined;
  const request = action.type === 'request_repair_authorization' ? { repairAuthorization: action.pending }
    : action.type === 'request_orchestrator' ? { afterAttempt: action.afterAttempt } : action.wait.request;
  const identity = canonicalJson([runId, decision.state.stageId, decision.state.attemptNumber]);
  return {
    schemaVersion: 'wait-request.v2',
    waitId: `wait:orchestrator:${sha256Text(identity).slice('sha256:'.length)}`,
    kind: 'orchestrator', signalType: 'core.orchestrator.resume',
    authorizedIssuer: { type: 'orchestrator', id: issuer }, expiresAt: null,
    ...(request ? { request } : {}),
  };
}

skills/nova/core/lifecycle/repair-author.syntax:
function authorizationReason(signal: ResumeSignal, digest: string): string {
  const value = signal.payload.repairAuthorization;
  if (Object.keys(signal.payload).length !== 1 || !value || typeof value !== 'object' || Array.isArray(value)) throw new Error('REPAIR_AUTHORIZATION_INVALID');
  const authorization = value as Record<string, unknown>;
  if (Object.keys(authorization).sort().join(',') !== 'pendingDigest,reason'
    || authorization.pendingDigest !== digest || typeof authorization.reason !== 'string'
    || !authorization.reason.trim() || authorization.reason.length > 8192) throw new Error('REPAIR_AUTHORIZATION_INVALID');
  return authorization.reason;
}

export function authorizedRepair(
  stages: readonly StageDefinition[], states: ReadonlyMap<string, StageRuntimeState>,
  waiting: StageRuntimeState, signal: ResumeSignal,
): RepairRequest | undefined {
  const pending = waiting.pendingRepair;
  if (!pending) return undefined;
  const reason = authorizationReason(signal, pending.digest);
  if (canonicalJson(states.get(pending.request.targetStageId)?.repairLedger ?? []) !== canonicalJson(pending.history)) throw new Error('REPAIR_AUTHORIZATION_STALE');
  if (repairDisposition(stages, pending) !== 'authorize') throw new Error('REPAIR_AUTHORIZATION_EXHAUSTED');
  if (signal.signalType !== 'core.orchestrator.resume' || signal.issuer.type !== 'orchestrator'
    || waiting.wait?.waitId !== signal.waitId || waiting.wait.authorizedIssuer.id !== signal.issuer.id) throw new Error('REPAIR_AUTHORIZATION_ISSUER_INVALID');
  return { ...pending.request, budgetOrder: { ...repairOrder(pending, waiting.attemptNumber),
    authorization: { signalId: signal.signalId, reason } } };
}

skills/nova/core/execution/engine-run.ts.syntax:
export async function executePrepared(context: ExecutionContext, options: Omit<PipelineRunnerOptions, 'definition' | 'registry' | 'activated' | 'adapters' | 'journal' | 'orchestratorIssuerId' | 'signal' | 'onEventsCommitted' | 'runtimeDispatchProfile' | 'reviewCacheProfile'>): Promise<PipelineRunResult> {
  const pinnedGraph = verifyPinnedGraph(context.runRoot, context.definition);
  const snapshot = readRunSnapshot(context.runRoot);
  const runtimeDispatchProfile = snapshot.schemaVersion === 'run-snapshot.v3' || snapshot.schemaVersion === 'run-snapshot.v4' ? snapshot.runtimeDispatchProfile : undefined;
  const reviewCacheProfile = snapshot.schemaVersion === 'run-snapshot.v4' ? snapshot.reviewCacheProfile : undefined;
  await assertEffectRecoverySafe(context.runRoot, context.runId, context.definition, context.events);
  const adapters = createAdapterRuntime(context.platform, context.runRoot, context.runtime, context.events); await adapters.start();
  const flush = serializedObserverDrainer(context.platform, context.runRoot, context.runtime, adapters, context.events);
  try { return await new PipelineRunner({ definition: context.definition, registry: context.runtime.granted, activated: context.runtime.activated,
    adapters, journal: context.events, orchestratorIssuerId: context.platform.orchestratorIssuerId, signal: context.leaseSignal,
    onEventsCommitted: flush, ...options, graphSnapshotVersion: pinnedGraph.schemaVersion,
    runtimeDispatchProfile, reviewCacheProfile }).run(context.runId); }
  finally { try { await flush(); } finally { await adapters.shutdown(); } }
}

export async function runNewPipeline(platform: PlatformConfig, definitionInput: PipelineDefinition, runId?: string, signal?: AbortSignal): Promise<PipelineRunResult> {
  const definition = deepFreeze(structuredClone(definitionInput)); const runtime = await prepareRuntime(platform, definition);
  const effectiveRunId = runId ?? `run:${crypto.randomUUID()}`; const runRoot = resolveRunRoot(platform.storageRoot, effectiveRunId);
  return withRunMutationLock(runRoot, async (leaseSignal) => {
    fs.mkdirSync(runRoot, { recursive: true }); const graph = graphSnapshot(definition); writeRunSnapshots(runRoot, graph, frozenRegistryRecord(runtime, definition, graph));
    const events = new FileJournal<LifecycleEvent | PluginDomainEvent>(path.join(runRoot, 'events.jsonl'));
    return executePrepared({ platform, definition, runtime, runId: effectiveRunId, runRoot, leaseSignal: signal ? AbortSignal.any([signal, leaseSignal]) : leaseSignal, events }, {});
  });
}

function assertRecoverableRun(events: FileJournal<LifecycleEvent | PluginDomainEvent>, runId: string, prefix: 'RECOVERY' | 'WAIT'): void {
  const boundary = [...events.records()].reverse().find(({ entry }) => entry.schemaVersion === 'lifecycle-event.v2' && entry.identity.runId === runId
    && ['run.resumed', 'run.succeeded', 'run.failed', 'run.blocked', 'run.cancelled'].includes(entry.type));
  if (boundary && boundary.entry.type !== 'run.resumed') throw new Error(`${prefix}_RUN_TERMINAL:${runId}:${boundary.entry.type}`);
}

function recoveryStates(definition: PipelineDefinition, events: FileJournal<LifecycleEvent | PluginDomainEvent>, runId: string, issuer: string): Map<string, StageRuntimeState> {
  return new Map(recoverStageStates(definition, events.records(), runId, issuer));
}

export async function recoverPipeline(platform: PlatformConfig, definitionInput: PipelineDefinition, runId: string): Promise<PipelineRunResult> {
  const definition = deepFreeze(structuredClone(definitionInput)); const runtime = await prepareRuntime(platform, definition);
  const runRoot = resolveRunRoot(platform.storageRoot, runId);
  return withRunMutationLock(runRoot, async (leaseSignal) => {
    const decisions = new FileJournal<AdministrativeReopenDecision>(path.join(runRoot, 'administrative-decisions.jsonl'));
    verifyPinnedPackages(runRoot, runtime, recordedPackageUpgrades(decisions.records().map(({ entry }) => entry))); verifyPinnedGraph(runRoot, definition);
    const events = new FileJournal<LifecycleEvent | PluginDomainEvent>(path.join(runRoot, 'events.jsonl')); assertRecoverableRun(events, runId, 'RECOVERY');
    // Phase 7 persists this run's test-attempt reconciliation plan before
    // dispatch. The recovery hook is active now; it is a no-op for legacy runs.
    await reconcileNovaObservabilityOnRecovery(runRoot, runId);
    const initialStates = dueRecoveryStates(recoveryStates(definition, events, runId, platform.orchestratorIssuerId));
    const wait = [...initialStates.values()].find((state) => state.wait)?.wait; if (wait) throw new Error(`RECOVERY_SIGNAL_REQUIRED:${wait.waitId}`);
    return executePrepared({ platform, definition, runtime, runId, runRoot, leaseSignal, events }, { initialStates, resume: true, resumePayload: { recovery: 'journal' } });
  });
}

function dueRecoveryStates(recovered: ReadonlyMap<string, StageRuntimeState>): Map<string, StageRuntimeState> {
  const states = new Map<string, StageRuntimeState>();
  for (const [stageId, state] of recovered) {
    if (!state.retryAt) { states.set(stageId, state); continue; }
    if (Date.now() < Date.parse(state.retryAt)) throw new Error(`RECOVERY_COOLDOWN_NOT_DUE:${stageId}:${state.retryAt}`);
    const { retryAt: _retryAt, ...withoutCooldown } = state; states.set(stageId, { ...withoutCooldown, status: 'pending' });
  }
  return states;
}

export async function resumePipeline(platform: PlatformConfig, definitionInput: PipelineDefinition, runId: string, signal: ResumeSignal): Promise<PipelineRunResult> {
  const definition = deepFreeze(structuredClone(definitionInput)); const runtime = await prepareRuntime(platform, definition);
  const runRoot = resolveRunRoot(platform.storageRoot, runId);
  return withRunMutationLock(runRoot, async (leaseSignal) => {
    const decisions = new FileJournal<AdministrativeReopenDecision>(path.join(runRoot, 'administrative-decisions.jsonl'));
    verifyPinnedPackages(runRoot, runtime, recordedPackageUpgrades(decisions.records().map(({ entry }) => entry))); verifyPinnedGraph(runRoot, definition);
    const events = new FileJournal<LifecycleEvent | PluginDomainEvent>(path.join(runRoot, 'events.jsonl')); assertRecoverableRun(events, runId, 'WAIT');
    const recovered = recoveryStates(definition, events, runId, platform.orchestratorIssuerId); const waiting = recoveredWait(recovered, signal.waitId);
    const created = validateWaitHistory(events, runId, signal.waitId, definition, platform.orchestratorIssuerId); validateSignal(waiting.wait!, signal, created.entry.occurredAt); leaseSignal.throwIfAborted();
    authorizedRepair(definition.stages, recovered, waiting, signal);
    recordSignal(runRoot, signal); recordWaitResolution(events, runId, waiting, signal, leaseSignal);
    const initialStates = recoveryStates(definition, events, runId, platform.orchestratorIssuerId);
    return executePrepared({ platform, definition, runtime, runId, runRoot, leaseSignal, events }, { initialStates,
      resumeGuidance: new Map([[waiting.stageId, signal.payload]]), resume: true });
  });
}

function recoveredWait(states: ReadonlyMap<string, StageRuntimeState>, waitId: string): StageRuntimeState {
  const waiting = [...states.values()].find((state) => state.wait?.waitId === waitId); if (!waiting?.wait) throw new Error(`WAIT_UNKNOWN_OR_STALE:${waitId}`); return waiting;
}

function validateWaitHistory(events: FileJournal<LifecycleEvent | PluginDomainEvent>, runId: string, waitId: string, definition: PipelineDefinition, issuer: string) {
  const terminal = [...events.records()].reverse().find(({ entry }) => entry.schemaVersion === 'lifecycle-event.v2' && entry.identity.runId === runId
    && ['run.succeeded', 'run.failed', 'run.blocked', 'run.cancelled'].includes(entry.type));
  const created = recoverWaitCreation(definition, events.records(), runId, issuer, waitId);
  if (terminal && (!created || created.sequence <= terminal.sequence)) throw new Error(`WAIT_INVALIDATED_BY_TERMINAL_RUN:${waitId}`);
  if (!created) throw new Error(`WAIT_CREATION_RECORD_MISSING:${waitId}`); return created;
}

function recordSignal(runRoot: string, signal: ResumeSignal): void {
  new FileJournal<ResumeSignal>(path.join(runRoot, 'signals.jsonl')).transact((records, append) => {
    const duplicate = records.find(({ entry }) => entry.idempotencyKey === signal.idempotencyKey)?.entry;
    if (duplicate) { if (canonicalJson(duplicate) !== canonicalJson(signal)) throw new Error(`WAIT_SIGNAL_CONFLICT:${signal.idempotencyKey}`); return; }
    if (records.some(({ entry }) => entry.waitId === signal.waitId)) throw new Error(`WAIT_ALREADY_RESOLVED:${signal.waitId}`); append(signal);
  });
}

function recordWaitResolution(events: FileJournal<LifecycleEvent | PluginDomainEvent>, runId: string, waiting: StageRuntimeState, signal: ResumeSignal, lease: AbortSignal): void {
  const exists = events.records().some(({ entry }) => entry.schemaVersion === 'lifecycle-event.v2' && entry.type === 'wait.resolved'
    && entry.identity.runId === runId && entry.identity.waitId === signal.waitId && entry.causationId === signal.signalId);
  if (exists) return; lease.throwIfAborted(); events.appendSequenced((sequence) => ({ schemaVersion: 'lifecycle-event.v2', eventId: `event:${crypto.randomUUID()}`,
    sequence, type: 'wait.resolved', identity: { runId, stageId: waiting.stageId, waitId: signal.waitId },
    occurredAt: new Date().toISOString(), causationId: signal.signalId, payload: { signal } }));
}

skills/nova/core/execution/runner.ts.syntax:
export interface PipelineRunResult {
  readonly runId: string; readonly identity: PipelineRunIdentity;
  readonly status: 'succeeded' | 'failed' | 'blocked' | 'waiting' | 'cancelled'; readonly stages: ReadonlyMap<string, StageRuntimeState>;
}

export interface PipelineRunnerOptions {
  readonly runtimeDispatchProfile?: RuntimeDispatchProfile | undefined;
  readonly reviewCacheProfile?: ReviewCacheProfile | undefined;
  readonly graphSnapshotVersion?: ExecutionGraphSnapshot['schemaVersion'];
  readonly definition: PipelineDefinition; readonly registry: GrantedRegistry; readonly activated: ActivatedRegistry; readonly adapters: AdapterRuntime;
  readonly journal: FileJournal<LifecycleEvent | PluginDomainEvent>; readonly initialStates?: ReadonlyMap<string, StageRuntimeState>;
  readonly resumeGuidance?: ReadonlyMap<string, Readonly<Record<string, unknown>>>; readonly orchestratorIssuerId: string;
  readonly resume?: boolean; readonly resumePayload?: Readonly<Record<string, unknown>>; readonly resumeCausationId?: string;
  readonly resumeEventAlreadyRecorded?: boolean; readonly administrativeAttemptOverrides?: ReadonlySet<string>; readonly signal?: AbortSignal;
  readonly now?: () => Date; readonly onEventsCommitted?: () => Promise<void>;
}

function deepFreeze<T>(value: T): T {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
  return Object.freeze(value);
}

export function validatePipelineDefinitionAgainstRegistry(definition: PipelineDefinition, registry: GrantedRegistry): void {
  ExecutionGraph.fromDefinition(definition);
  for (const stage of definition.stages) {
    const owner = registry.snapshot.stages.get(stage.type); if (!owner) throw new Error(`PIPELINE_STAGE_OWNER_MISSING:${stage.type}`);
    validateReferencedValue(fs.realpathSync(path.join(owner.package.root, owner.registration.configSchema)), stage.config, registry.snapshot.schemas);
    validateReferencedValue(fs.realpathSync(path.join(owner.package.root, owner.registration.inputSchema)), stage.input, registry.snapshot.schemas);
  }
}

export class PipelineRunner {
  readonly #options: PipelineRunnerOptions; readonly #graph: ExecutionGraph; readonly #snapshot: ExecutionGraphSnapshot; readonly #now: () => Date;
  constructor(options: PipelineRunnerOptions) {
    this.#options = {
      ...options, ...(options.runtimeDispatchProfile === undefined ? {} : {runtimeDispatchProfile: parseRuntimeDispatchProfile(options.runtimeDispatchProfile)}),
      ...(options.reviewCacheProfile === undefined ? {} : {reviewCacheProfile: parseReviewCacheProfile(options.reviewCacheProfile)}),
    }; validatePipelineDefinitionAgainstRegistry(options.definition, options.registry);
    this.#graph = ExecutionGraph.fromDefinition(options.definition); this.#snapshot = this.#graph.snapshot(options.definition.id, options.definition.maxConcurrency, options.graphSnapshotVersion);
    this.#now = options.now ?? (() => new Date());
  }
  graphSnapshot(): ExecutionGraphSnapshot { return this.#snapshot; }
  async run(runId = `run:${crypto.randomUUID()}`): Promise<PipelineRunResult> {
    const identity = Object.freeze({ runId, pipelineId: this.#snapshot.pipelineId, graphDigest: this.#snapshot.digest });
    const append = (type: LifecycleEvent['type'], eventIdentity: LifecycleEvent['identity'], payload: Readonly<Record<string, unknown>> = {}, causationId: string | null = this.#options.resumeCausationId ?? null): LifecycleEvent => {
      return this.#options.journal.appendSequenced((sequence): LifecycleEvent => ({ schemaVersion: 'lifecycle-event.v2', eventId: `event:${crypto.randomUUID()}`, sequence,
        type, identity: eventIdentity, occurredAt: this.#now().toISOString(), causationId, payload })).entry;
    };
    const checkpoints = new ArtifactCheckpointRecorder(this.#options.journal, append);
    const executor = new StageExecutor({ graph: this.#graph, registry: this.#options.registry, activated: this.#options.activated,
      adapters: this.#options.adapters, journal: this.#options.journal, checkpoints,
      ...(this.#options.runtimeDispatchProfile ? { runtimeDispatchProfile: this.#options.runtimeDispatchProfile } : {}),
      ...(this.#options.reviewCacheProfile ? { reviewCacheProfile: this.#options.reviewCacheProfile } : {}),
      ...(this.#options.signal ? { signal: this.#options.signal } : {}), now: this.#now, append });
    const loop = new PipelineLoop({ options: this.#options, graph: this.#graph, maxConcurrency: this.#options.definition.maxConcurrency,
      overrides: new Set(this.#options.administrativeAttemptOverrides), append, checkpoints,
      flush: async () => this.#options.onEventsCommitted?.(), executor,
      result: (runIdentity, status, states) => Object.freeze({ runId: runIdentity.runId, identity: runIdentity, status,
        stages: new FrozenMap([...states].map(([stageId, state]) => [stageId, deepFreeze(structuredClone(state))])) }),
    });
    return loop.run(identity);
  }
}

skills/nova/core/execution/pipeline-loop.syntax:
interface LoopServices {
  readonly options: PipelineRunnerOptions; readonly graph: ExecutionGraph; readonly maxConcurrency: number;
  readonly overrides: Set<string>; readonly append: AppendLifecycleEvent; readonly flush: () => Promise<void>;
  readonly checkpoints: ArtifactCheckpointRecorder;
  readonly executor: StageExecutor; readonly result: (identity: PipelineRunIdentity, status: PipelineRunResult['status'], states: ReadonlyMap<string, StageRuntimeState>) => PipelineRunResult;
}

export class PipelineLoop {
  readonly #services: LoopServices; readonly #states: Map<string, StageRuntimeState>; readonly #forced: string[] = []; readonly #forcedIds = new Set<string>();
  constructor(services: LoopServices) { this.#services = services; this.#states = this.#initialStates(); }

  async run(identity: PipelineRunIdentity): Promise<PipelineRunResult> {
    this.#recordRunStart(identity); await this.#services.flush(); this.#restoreRemediation();
    for (;;) {
      const cancelled = await this.#cancelled(identity); if (cancelled) return cancelled;
      const selection = await this.#selectReady(identity.runId); if (selection === 'continue') continue;
      if (selection.length === 0) break;
      const decisions = await Promise.all(selection.slice(0, this.#services.maxConcurrency).map((stage) => this.#execute(identity.runId, stage)));
      const recorder = new DecisionRecorder(this.#states, this.#services.append, this.#services.options.orchestratorIssuerId,
        (id) => this.#force(id), this.#services.checkpoints, this.#services.graph);
      // Record completed siblings before repair invalidation so their old results
      // cannot overwrite a newly pending evaluation in this batch.
      decisions.sort((a, b) => Number(a.decision.action.type === 'schedule_remediation') - Number(b.decision.action.type === 'schedule_remediation'));
      decisions.forEach((decision) => recorder.record(identity.runId, decision)); await this.#services.flush();
      const outcome = recorder.outcome();
      if (outcome.terminal) return this.#terminal(identity, outcome.terminal);
      if (outcome.paused) return this.#services.result(identity, 'waiting', this.#states);
    }
    return this.#finalize(identity);
  }

  #initialStates(): Map<string, StageRuntimeState> {
    return new Map(this.#services.options.initialStates ?? this.#services.graph.stages().map((stage) => [stage.id, {
      stageId: stage.id, status: 'pending' as const, attemptNumber: 0, attemptsUsed: 0, remediationCyclesUsed: 0,
    }] as const));
  }

  #recordRunStart(identity: PipelineRunIdentity): void {
    const options = this.#services.options;
    if (options.resume) {
      if (!options.resumeEventAlreadyRecorded) this.#services.append('run.resumed', { runId: identity.runId }, { runIdentity: identity, ...(options.resumePayload ?? {}) });
      return;
    }
    this.#services.append('run.created', { runId: identity.runId }, { runIdentity: identity }); this.#services.append('run.started', { runId: identity.runId });
  }

  #restoreRemediation(): void {
    for (const [stageId, state] of this.#states) {
      if (state.status !== 'waiting' || !state.remediationTarget) continue;
      const target = this.#states.get(state.remediationTarget);
      if (!target) throw new Error(`GRAPH_REMEDIATION_MISSING:${stageId}:${state.remediationTarget}`);
      if (!target.remediationReturnTo) this.#states.set(state.remediationTarget, { ...target, status: 'pending', remediationReturnTo: stageId });
    }
    for (const [stageId, state] of this.#states) this.#restoreReturn(stageId, state);
  }

  #restoreReturn(stageId: string, state: StageRuntimeState): void {
    if (!state.remediationReturnTo) return;
    if (state.status === 'pending') { this.#force(stageId); return; }
    if (state.status !== 'succeeded') return;
    const requester = this.#states.get(state.remediationReturnTo); if (!requester) return;
    const { remediationTarget: _target, ...requesterWithoutTarget } = requester;
    const { remediationReturnTo, ...stageWithoutReturn } = state;
    this.#states.set(remediationReturnTo, { ...requesterWithoutTarget, status: 'pending' }); this.#states.set(stageId, stageWithoutReturn);
  }

  async #cancelled(identity: PipelineRunIdentity): Promise<PipelineRunResult | undefined> {
    if (!this.#services.options.signal?.aborted) return undefined;
    for (const [stageId, state] of this.#states) {
      if (['skipped', 'succeeded', 'failed', 'blocked', 'cancelled'].includes(state.status)) continue;
      this.#states.set(stageId, { ...state, status: 'cancelled' });
      this.#services.append('stage.cancelled', { runId: identity.runId, stageId }, { attemptsUsed: state.attemptsUsed, remediationCyclesUsed: state.remediationCyclesUsed });
    }
    this.#services.append('run.cancelled', { runId: identity.runId }); await this.#services.flush();
    return this.#services.result(identity, 'cancelled', this.#states);
  }

  async #selectReady(runId: string): Promise<readonly StageDefinition[] | 'continue'> {
    const completed = new Set([...this.#states].filter(([, state]) => state.status === 'succeeded' || state.status === 'skipped').map(([id]) => id));
    const active = new Set([...this.#states].filter(([, state]) => !['pending', 'skipped', 'succeeded'].includes(state.status)).map(([id]) => id));
    let ready = this.#forcedReady(completed, active);
    const skipped = ready.filter((stage) => this.#shouldSkip(stage));
    skipped.forEach((stage) => this.#skip(runId, stage));
    if (skipped.length === 0) return ready;
    const skippedIds = new Set(skipped.map(({ id }) => id)); ready = ready.filter(({ id }) => !skippedIds.has(id)); await this.#services.flush();
    return ready.length === 0 ? 'continue' : ready;
  }

  #forcedReady(completed: ReadonlySet<string>, active: ReadonlySet<string>): readonly StageDefinition[] {
    const forced = this.#nextForced(); if (!forced) return this.#services.graph.ready(completed, active);
    const definition = this.#services.graph.stage(forced); const returnTo = this.#states.get(forced)?.remediationReturnTo;
    const dependenciesReady = definition.dependsOn.every((dependency) => dependency === returnTo || completed.has(dependency));
    if (dependenciesReady) return [definition];
    this.#force(forced); return this.#services.graph.ready(completed, active);
  }

  #shouldSkip(definition: StageDefinition): boolean {
    const activation = this.#services.graph.activation(definition.id); if (!activation) return false;
    const source = this.#states.get(activation.sourceStage); return !source?.facts || !Object.is(source.facts[activation.fact], activation.equals);
  }

  #skip(runId: string, definition: StageDefinition): void {
    const current = this.#states.get(definition.id)!; const activation = this.#services.graph.activation(definition.id)!;
    const observed = this.#states.get(activation.sourceStage)?.facts?.[activation.fact]; this.#states.set(definition.id, { ...current, status: 'skipped' });
    this.#services.append('stage.skipped', { runId, stageId: definition.id }, { stageType: definition.type, reason: { code: 'core.activation_condition_not_met', details: {
      sourceStage: activation.sourceStage, fact: activation.fact, equals: activation.equals, factPresent: observed !== undefined, ...(observed !== undefined ? { observed } : {}),
    } }, attemptsUsed: current.attemptsUsed, remediationCyclesUsed: current.remediationCyclesUsed });
  }

  async #execute(runId: string, definition: StageDefinition): Promise<CompletedStageDecision> {
    const current = this.#states.get(definition.id)!; const override = this.#services.overrides.delete(definition.id);
    if (current.attemptsUsed >= definition.execution.maxAttempts && !override) return { definition, administrativeOverride: false, decision: {
      state: { ...current, status: 'blocked' }, action: { type: 'stop' }, result: { schemaVersion: 'stage-result.v2', outcome: 'blocked',
        reason: { code: 'core.attempt_budget_exhausted', message: `Attempt budget exhausted for ${definition.id}` }, artifacts: [] },
    } };
    this.#states.set(definition.id, { ...current, status: 'running' });
    this.#services.append('stage.started', { runId, stageId: definition.id }, { stageType: definition.type,
      ...(typeof definition.config.agentRole === 'string' ? { agentRole: definition.config.agentRole } : {}), ...(override ? { administrativeOverride: true } : {}) });
    await this.#services.flush();
    const decision = await this.#services.executor.execute(runId, current, current.continuationGuidance ?? this.#services.options.resumeGuidance?.get(definition.id));
    return { definition, decision, administrativeOverride: override };
  }

  async #terminal(identity: PipelineRunIdentity, status: 'failed' | 'blocked' | 'cancelled'): Promise<PipelineRunResult> {
    this.#services.append(`run.${status}` as LifecycleEvent['type'], { runId: identity.runId }); await this.#services.flush();
    return this.#services.result(identity, status, this.#states);
  }

  async #finalize(identity: PipelineRunIdentity): Promise<PipelineRunResult> {
    const statuses = [...this.#states.values()].map(({ status }) => status);
    const complete = [...this.#states].every(([id, state]) => state.status === 'succeeded' || state.status === 'skipped'
      || (state.status === 'pending' && this.#services.graph.isRemediationOnlyTarget(id) && !state.remediationReturnTo));
    const status: PipelineRunResult['status'] = complete ? 'succeeded' : ['failed', 'blocked', 'cancelled', 'waiting'].find((candidate) => statuses.includes(candidate as StageRuntimeState['status'])) as PipelineRunResult['status'] ?? 'failed';
    if (status !== 'waiting') this.#services.append(`run.${status}` as LifecycleEvent['type'], { runId: identity.runId });
    await this.#services.flush(); return this.#services.result(identity, status, this.#states);
  }

  #force(stageId: string): void { if (!this.#forcedIds.has(stageId)) { this.#forcedIds.add(stageId); this.#forced.push(stageId); } }
  #nextForced(): string | undefined { const id = this.#forced.shift(); if (id) this.#forcedIds.delete(id); return id; }
}

skills/nova/core/execution/run-decisions.syntax:
export interface CompletedStageDecision {
  readonly definition: StageDefinition;
  readonly decision: LifecycleDecision & { readonly result: StageResult };
  readonly administrativeOverride: boolean;
}

export class DecisionRecorder {
  readonly #graph: ExecutionGraph;
  readonly #states: Map<string, StageRuntimeState>; readonly #append: AppendLifecycleEvent; readonly #issuer: string;
  readonly #force: (stageId: string) => void; readonly #checkpoints: ArtifactCheckpointRecorder;
  #terminal: TerminalStatus | undefined; #paused = false;
  constructor(states: Map<string, StageRuntimeState>, append: AppendLifecycleEvent, issuer: string,
    force: (stageId: string) => void, checkpoints: ArtifactCheckpointRecorder, graph: ExecutionGraph) {
    this.#graph = graph; this.#states = states; this.#append = append; this.#issuer = issuer; this.#force = force; this.#checkpoints = checkpoints;
  }

  record(runId: string, completed: CompletedStageDecision): void {
    const { definition, administrativeOverride } = completed;
    const decision = { ...budgetedRepairDecision(this.#graph.stages(), this.#states, definition, completed.decision, completed.decision.result, runId,
      { encoding: 'kubeclaw-json.utf16.v1' }), result: completed.decision.result };
    completed = { ...completed, decision };
    this.#states.set(definition.id, decision.state); this.#artifacts(runId, definition.id, decision.result);
    if (administrativeOverride && !['complete', 'stop'].includes(decision.action.type)) { this.#administrativeBlocked(runId, definition.id, decision.state); return; }
    const handler = this.#handlers()[decision.action.type]; handler(runId, completed);
  }

  outcome(): BatchOutcome { return { ...(this.#terminal ? { terminal: this.#terminal } : {}), paused: this.#paused }; }

  #handlers(): Record<LifecycleDecision['action']['type'], (runId: string, completed: CompletedStageDecision) => void> {
    return {
      schedule_attempt: (runId, completed) => this.#retry(runId, completed),
      schedule_remediation: (runId, completed) => this.#remediate(runId, completed),
      request_orchestrator: (runId, completed) => this.#orchestrator(runId, completed),
      pause_for_orchestrator: (runId, completed) => this.#orchestrator(runId, completed),
      request_repair_authorization: (runId, completed) => this.#orchestrator(runId, completed),
      persist_wait: (runId, completed) => this.#wait(runId, completed), cooldown: (runId, completed) => this.#wait(runId, completed),
      stop: (runId, completed) => this.#stop(runId, completed), complete: (runId, completed) => this.#complete(runId, completed),
    };
  }

  #artifacts(runId: string, stageId: string, result: StageResult): void {
    this.#checkpoints.completedResult(runId, stageId, result);
  }

  #administrativeBlocked(runId: string, stageId: string, state: StageRuntimeState): void {
    const blocked = { ...state, status: 'blocked' as const }; this.#states.set(stageId, blocked);
    this.#append('stage.blocked', { runId, stageId }, { attemptsUsed: blocked.attemptsUsed, remediationCyclesUsed: blocked.remediationCyclesUsed, reason: 'administrative_attempt_consumed' });
    this.#recordTerminal('blocked');
  }

  #retry(runId: string, { definition, decision }: CompletedStageDecision): void {
    this.#states.set(definition.id, { ...decision.state, status: 'pending' });
    this.#append('stage.retrying', { runId, stageId: definition.id }, { attemptsUsed: decision.state.attemptsUsed, remediationCyclesUsed: decision.state.remediationCyclesUsed });
    this.#force(definition.id);
  }

  #remediate(runId: string, { definition, decision }: CompletedStageDecision): void {
    if (decision.action.type !== 'schedule_remediation') return;
    const targetId = decision.action.stageId; const remediation = this.#states.get(targetId)!;
    if (['blocked', 'failed', 'cancelled'].includes(remediation.status)) { this.#terminalRemediation(runId, definition.id, targetId, decision.state, remediation.status); return; }
    const request = decision.action.repairRequest ?? repairRequest(this.#graph.stages(), definition.id, targetId, decision.state.remediationCyclesUsed, decision.result);
    if (remediation.remediationReturnTo && remediation.remediationReturnTo !== definition.id) {
      this.#terminalRemediation(runId, definition.id, targetId, decision.state, 'blocked'); return;
    }
    this.#append('stage.waiting', { runId, stageId: definition.id }, { attemptsUsed: decision.state.attemptsUsed,
      remediationCyclesUsed: decision.state.remediationCyclesUsed, remediationStageId: targetId, repairRequest: request });
    applyRepair(this.#states, request); this.#force(targetId);
  }

  #terminalRemediation(runId: string, stageId: string, targetId: string, state: StageRuntimeState, targetStatus: StageRuntimeState['status']): void {
    const blocked = { ...state, status: 'blocked' as const }; this.#states.set(stageId, blocked);
    this.#append('stage.blocked', { runId, stageId }, { attemptsUsed: blocked.attemptsUsed, remediationCyclesUsed: blocked.remediationCyclesUsed, remediationStageId: targetId, reason: 'remediation_target_terminal' });
    this.#recordTerminal(targetStatus === 'failed' ? 'failed' : targetStatus === 'cancelled' ? 'cancelled' : 'blocked');
  }

  #orchestrator(runId: string, { definition, decision }: CompletedStageDecision): void {
    const action = decision.action;
    if (action.type !== 'request_orchestrator' && action.type !== 'pause_for_orchestrator' && action.type !== 'request_repair_authorization') return;
    const wait = decisionWait(decision, runId, this.#issuer)!;
    this.#states.set(definition.id, { ...decision.state, wait });
    this.#append('orchestrator.required', { runId, stageId: definition.id }, { ...(action.type === 'request_orchestrator' ? { afterAttempt: action.afterAttempt } : {}),
      attemptsUsed: decision.state.attemptsUsed, remediationCyclesUsed: decision.state.remediationCyclesUsed, wait }); this.#paused = true;
  }

  #wait(runId: string, { definition, decision }: CompletedStageDecision): void {
    const action = decision.action;
    if (action.type !== 'persist_wait' && action.type !== 'cooldown') return;
    this.#append('stage.waiting', { runId, stageId: definition.id }, { attemptsUsed: decision.state.attemptsUsed,
      remediationCyclesUsed: decision.state.remediationCyclesUsed, ...(action.type === 'persist_wait' ? { wait: action.wait } : { retryAt: action.retryAt }) });
    this.#paused = true;
  }

  #stop(runId: string, { definition, decision }: CompletedStageDecision): void {
    const status: TerminalStatus = decision.state.status === 'blocked' ? 'blocked' : decision.state.status === 'cancelled' ? 'cancelled' : 'failed';
    this.#append(`stage.${status}` as LifecycleEvent['type'], { runId, stageId: definition.id }, { stageType: definition.type,
      ...(typeof definition.config.agentRole === 'string' ? { agentRole: definition.config.agentRole } : {}), outcome: decision.result.outcome,
      reason: decision.result.reason, attemptsUsed: decision.state.attemptsUsed, remediationCyclesUsed: decision.state.remediationCyclesUsed });
    this.#recordTerminal(status);
  }

  #complete(runId: string, { definition, decision }: CompletedStageDecision): void {
    this.#append('stage.succeeded', { runId, stageId: definition.id }, { stageType: definition.type,
      ...(typeof definition.config.agentRole === 'string' ? { agentRole: definition.config.agentRole } : {}), outcome: decision.result.outcome,
      attemptsUsed: decision.state.attemptsUsed, remediationCyclesUsed: decision.state.remediationCyclesUsed,
      ...(decision.state.facts ? { facts: decision.state.facts } : {}), ...(decision.state.remediationReturnTo ? { remediationReturnTo: decision.state.remediationReturnTo } : {}) });
    if (decision.state.remediationReturnTo) this.#completeRemediation(runId, definition.id, decision.state);
  }

  #completeRemediation(runId: string, stageId: string, state: StageRuntimeState): void {
    const returnTo = state.remediationReturnTo!; const requester = this.#states.get(returnTo);
    if (!requester) throw new Error(`GRAPH_REMEDIATION_RETURN_MISSING:${returnTo}`);
    const { remediationReturnTo: _returnTo, ...withoutReturn } = state; const { remediationTarget: _target, ...requesterWithoutTarget } = requester;
    this.#states.set(stageId, withoutReturn); this.#states.set(returnTo, { ...requesterWithoutTarget, status: 'pending' });
    this.#append('stage.scheduled', { runId, stageId: returnTo }, { reason: 'remediation_completed', remediationStageId: stageId });
  }

  #recordTerminal(status: TerminalStatus): void {
    const priority = { cancelled: 1, blocked: 2, failed: 3 } as const;
    if (!this.#terminal || priority[status] > priority[this.#terminal]) this.#terminal = status;
  }
}

skills/nova/core/execution/artifact-chec.syntax:
import { canonicalJson, portableJson, PORTABLE_JSON_ENCODING, sha256Text,
  type ArtifactRef, type AttemptIdentity, type CapabilityInvocation,
  type LifecycleEvent, type PluginDomainEvent, type StageResult } from '@kubeclaw/plugin-sdk';

function record(value: unknown): Readonly<Record<string, unknown>> | undefined {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as Readonly<Record<string, unknown>>
    : undefined;
}

function sameAttempt(left: AttemptIdentity, right: AttemptIdentity): boolean {
  return left.runId === right.runId && left.stageId === right.stageId
    && left.attemptId === right.attemptId && left.attemptNumber === right.attemptNumber;
}

function validDigest(value: unknown): value is `sha256:${string}` {
  return typeof value === 'string' && /^sha256:[a-f0-9]{64}$/u.test(value);
}

function assertEncoding(encoding: unknown): void {
  if (encoding !== undefined && encoding !== PORTABLE_JSON_ENCODING) {
    throw new Error('ARTIFACT_CHECKPOINT_ENCODING_INVALID');
  }
}

function checkpointJson(payload: Readonly<Record<string, unknown>>): string {
  assertEncoding(payload.encoding);
  return payload.encoding === PORTABLE_JSON_ENCODING
    ? portableJson(payload.value) : canonicalJson(payload.value);
}

export function artifactFromWrite(
  attempt: AttemptIdentity,
  request: CapabilityInvocation,
  response: Readonly<Record<string, unknown>>,
): ArtifactRef | undefined {
  if (request.payload.checkpoint !== true) return undefined;
  if (request.operation !== 'put_json') throw new Error('ARTIFACT_CHECKPOINT_OPERATION_INVALID');
  const artifact = record(response.artifact), producer = record(artifact?.producer);
  const encoding = request.payload.encoding;
  const serialized = checkpointJson(request.payload);
  if (!artifact || !producer
    || artifact.artifactId !== request.resource.canonicalId
    || artifact.namespace !== request.payload.namespace || artifact.mediaType !== request.payload.mediaType
    || artifact.encoding !== encoding
    || !validDigest(artifact.digest) || artifact.digest !== sha256Text(serialized)
    || !Number.isSafeInteger(artifact.sizeBytes) || artifact.sizeBytes !== Buffer.byteLength(serialized)) {
    throw new Error(`ARTIFACT_CHECKPOINT_RESPONSE_INVALID:${request.resource.canonicalId}`);
  }
  const candidate = artifact as unknown as ArtifactRef;
  if (!sameAttempt(candidate.producer, attempt)) {
    throw new Error(`ARTIFACT_CHECKPOINT_PRODUCER_INVALID:${request.resource.canonicalId}`);
  }
  return candidate;
}

function exactArtifact(left: ArtifactRef, right: ArtifactRef): boolean {
  return left.artifactId === right.artifactId && left.namespace === right.namespace
    && left.mediaType === right.mediaType && left.digest === right.digest && left.sizeBytes === right.sizeBytes
    && left.encoding === right.encoding
    && sameAttempt(left.producer, right.producer);
}

function conflictingArtifact(left: ArtifactRef, right: ArtifactRef): boolean {
  return left.artifactId === right.artifactId && sameAttempt(left.producer, right.producer)
    && !exactArtifact(left, right);
}

export class ArtifactCheckpointRecorder {
  readonly #append: AppendLifecycleEvent;
  readonly #recorded: ArtifactRef[];

  constructor(journal: FileJournal<LifecycleEvent | PluginDomainEvent>, append: AppendLifecycleEvent) {
    // Pipeline runners are created only inside withRunMutationLock. Its renewable
    // cross-process lease leaves one mutable owner for a run journal, while this
    // in-memory index serializes concurrent checkpoint completions in that owner.
    this.#append = append; this.#recorded = this.#read(journal);
    // Attempt completion is durable before its derived artifact.created rows.
    // Restore the same projection before dependent stages receive their index.
    for (const { entry } of journal.records()) {
      if (entry.schemaVersion !== 'lifecycle-event.v2' || !['attempt.completed', 'attempt.cancelled', 'attempt.timed_out'].includes(entry.type)) continue;
      if (!entry.payload.result) continue;
      this.completedResult(entry.identity.runId, entry.identity.stageId!, entry.payload.result as StageResult);
    }
  }

  checkpoint(artifact: ArtifactRef): void { this.#record(artifact, true); }

  result(artifact: ArtifactRef): void { this.#record(artifact, false); }

  completedResult(runId: string, stageId: string, result: StageResult): void {
    validateContractValue('stageResult', result);
    for (const artifact of result.artifacts) {
      if (artifact.producer.runId !== runId || artifact.producer.stageId !== stageId) {
        throw new Error(`ARTIFACT_PRODUCER_MISMATCH:${runId}:${stageId}:${artifact.artifactId}`);
      }
      this.result(artifact);
    }
  }

  #record(artifact: ArtifactRef, checkpoint: boolean): void {
    assertEncoding(artifact.encoding);
    if (this.#recorded.some((candidate) => exactArtifact(candidate, artifact))) return;
    if (this.#recorded.some((candidate) => conflictingArtifact(candidate, artifact))) {
      throw new Error(`ARTIFACT_CHECKPOINT_CONFLICT:${artifact.producer.runId}:${artifact.producer.stageId}:${artifact.artifactId}`);
    }
    this.#append('artifact.created', {
      runId: artifact.producer.runId,
      stageId: artifact.producer.stageId,
      artifactId: artifact.artifactId,
    }, {
      namespace: artifact.namespace,
      mediaType: artifact.mediaType,
      digest: artifact.digest,
      sizeBytes: artifact.sizeBytes,
      artifact: structuredClone(artifact),
      ...(checkpoint ? { checkpoint: true } : {}),
    }, artifact.producer.attemptId);
    this.#recorded.push(structuredClone(artifact));
  }

  artifacts(runId?: string, stageId?: string): ArtifactRef[] {
    return this.#recorded.filter((artifact) => (
      (runId === undefined || artifact.producer.runId === runId)
      && (stageId === undefined || artifact.producer.stageId === stageId)
    )).map((artifact) => structuredClone(artifact));
  }

  #read(journal: FileJournal<LifecycleEvent | PluginDomainEvent>): ArtifactRef[] {
    const artifacts: ArtifactRef[] = [];
    for (const { entry } of journal.records()) {
      if (entry.schemaVersion !== 'lifecycle-event.v2' || entry.type !== 'artifact.created') continue;
      const artifact = record(entry.payload.artifact);
      if (!artifact) continue;
      assertEncoding(artifact.encoding);
      artifacts.push(structuredClone(artifact) as unknown as ArtifactRef);
    }
    return artifacts;
  }
}

