        templateExpression: lineText.trim().slice(0, 240),
        exactValuePath: canonicalPath,
        bindingKind: details.bindingKind ?? 'exact-leaf-access',
        bindingProof: details.bindingProof ?? `the expression reads .Values.${canonicalPath}`,
