      const tokenIndex = (match.index ?? 0) + match[0].lastIndexOf(token) + parsed.offset;
      const found = runtime === 'node' ? nodeEnvironmentReads(`${file}#node-inline-${lineAt(text, match.index ?? 0)}`, parsed.code)
