    /\bos\.getenv\(\s*['"]([A-Z][A-Z0-9_]*)['"]/gu,
    /\bos\.environ\.get\(\s*['"]([A-Z][A-Z0-9_]*)['"]/gu,
    /\bos\.environ\[\s*['"]([A-Z][A-Z0-9_]*)['"]\s*\]/gu,
