    const body = lines.slice(bodyStartLine, endIndex).join('\n');
    for (const readFact of nodeEnvironmentReads(`${file}#node-heredoc-${lineIndex + 1}`, body)) {
      reads.push({
        ...readFact,
        index: offsets[bodyStartLine] + readFact.index,
        kind: `embedded-${readFact.kind}`,
