        name: readFact.name,
        kind: readFact.kind,
        path: file,
        line: lineAt(text, readFact.index),
        defaultOperator: null,
        sourceValueRole: 'none',
        default: '<none>',
        secretProvenance: false,
        filePathProvenance: false,
