    const evidenceLine = read(fact.path).split('\n')[fact.line - 1] ?? '';
    const expectedToken = typeof fact.name === 'string' && !fact.name.startsWith('<') ? fact.name
      : typeof fact.key === 'string' && !fact.key.startsWith('<') ? fact.key : null;
