export function yamlAuthorityFile(sourcePath) {
  return files.get(sourcePath) ?? null;
}

export function yamlFieldAuthority(sourcePath, fieldPath) {
  const declaration = files.get(sourcePath);
  const registered = fieldAuthorities.get(`${sourcePath}#${fieldPath}`);
  if (!declaration || !registered) return null;
  const expanded = registered.profile ? { ...profiles[registered.profile](registered), ...registered } : { ...registered };
  delete expanded.profile;
  delete expanded.semanticContractProofTokens;
  return { ...expanded, sourceFileSha256: declaration.sourceSha256, externalChart: declaration.externalChart };
}

export function yamlAuthorityStats() {
  return { files: files.size, fields: fieldAuthorities.size };
}

export function yamlAuthorityPaths(sourcePath) {
  const prefix = `${sourcePath}#`;
  return [...fieldAuthorities.keys()].filter((key) => key.startsWith(prefix)).map((key) => key.slice(prefix.length)).sort();
}

export function assertYamlAuthorityRegistry(repositoryRoot = process.cwd(), { verifyBytes = true } = {}) {
  assert.equal(externalChartLockName, 'docs-external-helm-authority-lock.json', 'external Helm lock checksum names the wrong artifact');
  assert.match(externalChartLockSha256, /^[a-f0-9]{64}$/u, 'external Helm lock checksum is invalid');
  assert.equal(crypto.createHash('sha256').update(externalChartLockBytes).digest('hex'), externalChartLockSha256,
    'external Helm authority lock bytes do not match the checked-in checksum');
  assert.equal(externalSnapshotName, 'external-helm-authority-snapshots.json', 'external Helm snapshot checksum names the wrong artifact');
  assert.match(externalSnapshotSha256, /^[a-f0-9]{64}$/u, 'external Helm snapshot checksum is invalid');
  assert.equal(crypto.createHash('sha256').update(externalSnapshotBytes).digest('hex'), externalSnapshotSha256,
    'external Helm extracted authority bytes do not match the checked-in checksum');
  assert.equal(externalSnapshots.lockSha256, crypto.createHash('sha256').update(externalChartLockBytes).digest('hex'),
    'external Helm extracted authority was not produced from the checked-in lock');
  assert.equal(externalChartLock.version, 1, 'unsupported external Helm authority lock version');
  assert(typeof externalChartLock.captureMethod === 'string' && externalChartLock.captureMethod.length >= 80,
    'external Helm authority lock does not explain its reproducible capture method');
  assert.deepEqual(Object.keys(charts).sort(), ['alloy', 'argocd', 'cilium', 'csi', 'loki', 'postgresql', 'postgresqlDirect', 'prometheus', 'promtail', 'redis', 'spire', 'tailscale'],
    'external Helm authority lock chart set changed');
  let externalFieldCount = 0;
  let indirectContractCount = 0;
  for (const [key, entry] of fieldAuthorities) {
    const registration = entry.semanticAuthorityEvidence;
    const contractEvidence = entry.semanticContractEvidence;
    assert(registration?.path === semanticAuthorityPath && registration.line > 1,
      `${key}: exact semantic authority registration line is missing`);
    assert.equal(crypto.createHash('sha256').update(semanticAuthorityLines[registration.line - 1] ?? '').digest('hex'), registration.sourceLineSha256,
      `${key}: semantic authority registration line changed`);
    assert(contractEvidence?.path === semanticAuthorityPath && contractEvidence.line > 1
      && contractEvidence.endLine >= contractEvidence.line,
    `${key}: semantic contract source range is missing`);
    assert.equal(crypto.createHash('sha256').update(semanticAuthorityLines.slice(contractEvidence.line - 1, contractEvidence.endLine).join('\n')).digest('hex'), contractEvidence.sourceRangeSha256,
      `${key}: semantic contract source range changed`);
    if (entry.semanticContractBinding === 'indirect-field-contract') {
      indirectContractCount += 1;
      const contractText = semanticAuthorityLines.slice(contractEvidence.line - 1, contractEvidence.endLine).join('\n');
      assert(entry.semanticContractProofTokens.length >= 2,
        `${key}: indirect semantic contract has no field-specific proof tokens`);
      for (const token of entry.semanticContractProofTokens) {
        assert(contractText.includes(token), `${key}: indirect semantic contract no longer contains ${JSON.stringify(token)}`);
      }
    }
    for (const name of ['purpose', 'acceptedValues', 'emptyBehavior', 'impact', 'failure']) {
      const value = entry.profile ? profiles[entry.profile](entry)[name] : entry[name];
      const minimum = name === 'acceptedValues' ? 8 : 20;
      assert(typeof value === 'string' && value.length >= minimum, `incomplete YAML authority ${name}: ${key}`);
    }
    const fieldSourcePath = key.slice(0, key.indexOf('#'));
    const externalChart = files.get(fieldSourcePath)?.externalChart;
    if (externalChart && entry.collectionOnly === true) {
      const proof = entry.upstreamTemplateProof;
      assert(proof && proof.archiveSha256 === externalChart.archiveSha256, `${key}: collection upstream archive differs from pinned chart`);
      const archive = path.join(repositoryRoot, proof.archivePath);
      assert.equal(crypto.createHash('sha256').update(fs.readFileSync(archive)).digest('hex'), proof.archiveSha256, `${key}: collection archive bytes changed`);
      const extracted = spawnSync('tar', ['-xOzf', archive, proof.member], { encoding: 'utf8' });
      assert.equal(extracted.status, 0, `${key}: collection upstream template cannot be extracted`);
      assert.equal(crypto.createHash('sha256').update(extracted.stdout).digest('hex'), proof.memberSha256, `${key}: collection template bytes changed`);
      for (const token of ['dig "namespaceSelector"', 'merge $namespaceSelector', 'append $namespaceSelector.matchExpressions', 'with $namespaceSelector']) assert(extracted.stdout.includes(token), `${key}: collection receiver contract changed`);
    } else if (externalChart) {
      externalFieldCount += 1;
      const extracted = externalSnapshots.fields[key];
      assert(extracted, `${key}: content-addressed external Helm authority input is missing`);
      const locked = externalSnapshots.charts[extracted.chartKey];
      assert(locked, `${key}: extracted chart coordinate is missing`);
      assert.equal(locked.chart, externalChart.chart, `${key}: extracted chart name differs`);
      assert.equal(locked.version, externalChart.version, `${key}: extracted chart version differs`);
      assert.equal(locked.archiveSha256, externalChart.archiveSha256, `${key}: extracted archive digest differs`);
      assert.equal(locked.extractedValuesSha256, externalChart.valuesSha256, `${key}: extracted values digest differs`);
      assert.match(extracted.upstreamValue?.valueSha256 ?? '', /^[a-f0-9]{64}$/u, `${key}: upstream values fragment is not content-addressed`);
      assert(extracted.templateContextIds.length || extracted.schema || extracted.upstreamValue, `${key}: no extracted upstream contract remains`);
      for (const id of extracted.templateContextIds) {
        const template = externalSnapshots.templateContexts[id];
        assert(template, `${key}: extracted template context ${id} is missing`);
        assert.equal(crypto.createHash('sha256').update(JSON.stringify(stableObject(template))).digest('hex'), id,
          `${key}: extracted template context identity changed`);
        assert.equal(crypto.createHash('sha256').update(template.context).digest('hex'), template.contextSha256,
          `${key}: extracted template context bytes changed`);
      }
    }
  }
  assert.equal(Object.keys(externalSnapshots.fields).length, externalFieldCount,
    'external Helm extracted authority contains stale or missing field inputs');
  assert.equal(indirectContractCount, 38,
    'indirect YAML semantic contract coverage changed; bind every generated field to its contract definition range');
  for (const declaration of files.values()) {
    if (verifyBytes) {
      const absoluteSource = path.join(repositoryRoot, declaration.path);
      assert(fs.existsSync(absoluteSource), `${declaration.path}: YAML authority source is missing`);
      const actual = crypto.createHash('sha256').update(fs.readFileSync(absoluteSource)).digest('hex');
      assert.equal(actual, declaration.sourceSha256, `${declaration.path}: YAML authority source bytes changed`);
    }
    if (!declaration.externalChart) continue;
    assert.match(declaration.externalChart.archiveSha256, /^[a-f0-9]{64}$/u);
    assert.match(declaration.externalChart.valuesSha256, /^[a-f0-9]{64}$/u);
    assert(declaration.externalChart.chart && declaration.externalChart.version && declaration.externalChart.repository);
    const locked = Object.values(charts).find((candidate) => candidate === declaration.externalChart);
    assert(locked, `${declaration.path}: external chart metadata is not the checked-in lock object`);
  }
}

scripts/docs-local-helm-authorities.mjs.syntax:
const registryEvidence = (sourcePath, fieldPath) => {
  const cacheKey = `${sourcePath}#${fieldPath}`;
  if (registryEvidenceCache.has(cacheKey)) return registryEvidenceCache.get(cacheKey);
  const fileLine = registryLines.findIndex((line) => line === `    ${JSON.stringify(sourcePath)}: {`);
  assert(fileLine >= 0, `${sourcePath}: local Helm authority file block has no exact JSON line`);
  const nextFileLine = registryLines.findIndex((line, index) => index > fileLine && /^    "[^"]+": \{$/u.test(line));
  const fieldLine = registryLines.findIndex((line, index) => index > fileLine
    && (nextFileLine < 0 || index < nextFileLine)
    && line === `        ${JSON.stringify(fieldPath)}: {`);
  assert(fieldLine >= 0, `${sourcePath}#${fieldPath}: local Helm authority object has no exact JSON line`);
  let objectEnd = registryLines.findIndex((line, index) => index > fieldLine
    && ((nextFileLine < 0 || index < nextFileLine) && /^        "(?:\\.|[^"])+": \{$/u.test(line)));
  const fieldsEnd = registryLines.findIndex((line, index) => index > fieldLine && line === '      }');
  if (objectEnd < 0 || (fieldsEnd >= 0 && fieldsEnd < objectEnd)) objectEnd = fieldsEnd;
  assert(objectEnd > fieldLine, `${sourcePath}#${fieldPath}: local Helm authority object range has no end`);
  const failureLine = registryLines.findIndex((line, index) => index > fieldLine && index < objectEnd
    && /^          "failure":/u.test(line));
  assert(failureLine > fieldLine, `${sourcePath}#${fieldPath}: semantic contract has no exact failure line`);
  const endLine = failureLine + 1;
  const registration = {
    path: 'scripts/docs-local-helm-field-authorities.json',
    line: fieldLine + 1,
    sourceLineSha256: crypto.createHash('sha256').update(registryLines[fieldLine]).digest('hex'),
  };
  const contract = {
    path: registration.path,
    line: registration.line,
    endLine,
    sourceRangeSha256: crypto.createHash('sha256').update(registryLines.slice(fieldLine, endLine).join('\n')).digest('hex'),
  };
  const result = { registration, contract };
  registryEvidenceCache.set(cacheKey, result);
  return result;
};

export function localHelmAuthorityFile(sourcePath) {
  return registry.files[sourcePath] ?? null;
}

export function localHelmFieldAuthority(sourcePath, fieldPath) {
  const declaration = localHelmAuthorityFile(sourcePath);
  const authority = declaration?.fields[fieldPath];
  const evidence = authority ? registryEvidence(sourcePath, fieldPath) : null;
  return authority ? {
    ...authority,
    sourceFileSha256: declaration.sourceSha256,
    chartRoot: declaration.chartRoot,
    semanticAuthorityEvidence: evidence.registration,
    semanticContractEvidence: evidence.contract,
  } : null;
}

export function localHelmChartAuthority(chartRoot) {
  return registry.charts[chartRoot] ?? null;
}

export function localHelmAuthorityStats() {
  return {
    files: Object.keys(registry.files).length,
    fields: Object.values(registry.files).reduce((sum, file) => sum + Object.keys(file.fields).length, 0),
    templates: Object.values(registry.charts).reduce((sum, chart) => sum + Object.keys(chart.templates).length, 0),
  };
}

export function assertLocalHelmAuthorityRegistry(repositoryRoot = process.cwd(), { verifyBytes = true } = {}) {
  assert.equal(registry.version, 2);
  assert.match(registry.semanticPolicy ?? '', /explicit field contract/u);
  for (const [sourcePath, declaration] of Object.entries(registry.files)) {
    assert.match(declaration.sourceSha256, /^[a-f0-9]{64}$/u, `${sourcePath}: invalid source digest`);
    if (verifyBytes) {
      const absoluteSource = path.join(repositoryRoot, sourcePath);
      assert(fs.existsSync(absoluteSource), `${sourcePath}: authority source is missing`);
      assert.equal(sha256(fs.readFileSync(absoluteSource)), declaration.sourceSha256,
        `${sourcePath}: authority source bytes changed`);
    }
    assert(registry.charts[declaration.chartRoot], `${sourcePath}: missing chart contract ${declaration.chartRoot}`);
    for (const [fieldPath, authority] of Object.entries(declaration.fields)) {
      const { registration: semanticEvidence, contract: semanticContract } = registryEvidence(sourcePath, fieldPath);
      assert(semanticEvidence.line > 1, `${sourcePath}#${fieldPath}: semantic authority points to line 1`);
      assert.equal(sha256(registryLines[semanticEvidence.line - 1]), semanticEvidence.sourceLineSha256,
        `${sourcePath}#${fieldPath}: semantic authority line digest changed`);
      assert(semanticContract.endLine >= semanticContract.line,
        `${sourcePath}#${fieldPath}: semantic authority object range is invalid`);
      assert.equal(sha256(registryLines.slice(semanticContract.line - 1, semanticContract.endLine).join('\n')), semanticContract.sourceRangeSha256,
        `${sourcePath}#${fieldPath}: semantic authority object range changed`);
      assert(fieldPath.startsWith('$.'), `${sourcePath}#${fieldPath}: field path is not exact`);
      assert(!['typed-rendered-value', 'bounded-integer', 'container-path', 'duration', 'kubernetes-or-runtime-name', 'network-or-source-url', 'numeric-security-mode', 'protocol-selector'].includes(authority.group),
        `${sourcePath}#${fieldPath}: mechanical or conflated fallback authority is forbidden`);
      assert(Object.hasOwn(authority, 'selectedBaseline'), `${sourcePath}#${fieldPath}: selected baseline is missing`);
      assert.equal(authority.semanticAuthority, 'explicit-field-contract', `${sourcePath}#${fieldPath}: semantic authority was not explicitly approved`);
      for (const name of ['purpose', 'acceptedValues', 'emptyBehavior', 'impact', 'failure']) {
        assert(typeof authority[name] === 'string' && authority[name].length >= 20, `${sourcePath}#${fieldPath}: incomplete ${name}`);
      }
      if (authority.apiSchemaAuthority) {
        const proof = authority.apiSchemaAuthority;
        assert.deepEqual(proof, apiFieldSchemaAuthority(proof.apiVersion, proof.kind, proof.fieldPath), `${sourcePath}#${fieldPath}: pinned collection API schema changed`);
      }
      if (authority.chartSchemaContract) {
        const proof = authority.chartSchemaContract;
        assert.equal(proof.path, `${declaration.chartRoot}/values.schema.json`, `${sourcePath}#${fieldPath}: chart schema is outside the selected chart`);
        assert.equal(proof.fieldPath, fieldPath, `${sourcePath}#${fieldPath}: schema contract belongs to another field`);
        assert.match(proof.sourceSha256, /^[a-f0-9]{64}$/u, `${sourcePath}#${fieldPath}: chart schema digest is missing`);
        assert(proof.schema && typeof proof.schema === 'object', `${sourcePath}#${fieldPath}: exact collection schema is missing`);
        if (verifyBytes) assert.equal(sha256(fs.readFileSync(path.join(repositoryRoot, proof.path))), proof.sourceSha256, `${sourcePath}#${fieldPath}: chart schema bytes changed`);
      }
      assert(Array.isArray(authority.consumerProof) && authority.consumerProof.length > 0,
        `${sourcePath}#${fieldPath}: exact consumer proof is missing`);
      for (const consumer of authority.consumerProof) {
        assert(consumer.path.startsWith(`${declaration.chartRoot}/templates/`), `${sourcePath}#${fieldPath}: consumer is outside the selected chart`);
        assert(consumer.kind?.startsWith('helm-template'), `${sourcePath}#${fieldPath}: consumer is not an exact Helm template binding`);
        assert(typeof consumer.templateExpression === 'string' && consumer.templateExpression.length > 0,
          `${sourcePath}#${fieldPath}: consumer expression is missing`);
        assert.equal(consumer.exactValuePath, fieldPath.replace(/^\$\.?/u, ''),
          `${sourcePath}#${fieldPath}: consumer proof is not bound to this exact leaf`);
        assert(typeof consumer.bindingKind === 'string' && consumer.bindingKind.length > 0,
          `${sourcePath}#${fieldPath}: Helm binding kind is missing`);
        assert(typeof consumer.bindingProof === 'string' && consumer.bindingProof.length >= 20,
          `${sourcePath}#${fieldPath}: leaf-to-expression binding proof is incomplete`);
        assert(Number.isSafeInteger(consumer.line) && consumer.line > 0,
          `${sourcePath}#${fieldPath}: consumer line is missing`);
        assert.match(consumer.sourceLineSha256 ?? '', /^[a-f0-9]{64}$/u,
          `${sourcePath}#${fieldPath}: consumer line digest is missing`);
        assert.match(consumer.contextSha256 ?? '', /^[a-f0-9]{64}$/u,
          `${sourcePath}#${fieldPath}: consumer context digest is missing`);
        assert(typeof consumer.receiver === 'string' && consumer.receiver.length > 0,
          `${sourcePath}#${fieldPath}: rendered receiver is missing`);
        assert(typeof consumer.condition === 'string' && consumer.condition.length > 0,
          `${sourcePath}#${fieldPath}: render condition is missing`);
        assert(typeof consumer.defaultProof === 'string' && consumer.defaultProof.length > 0,
          `${sourcePath}#${fieldPath}: default selection proof is missing`);
        assert(Array.isArray(consumer.receiverProof) && consumer.receiverProof.length > 0,
          `${sourcePath}#${fieldPath}: receiver proof list is empty`);
        assert.doesNotMatch(consumer.receiver, /^(?:exact template output|render branch|dynamic rendered value)/u,
          `${sourcePath}#${fieldPath}: receiver description is generic`);
        assert(Array.isArray(consumer.conditionProof), `${sourcePath}#${fieldPath}: condition proof list is missing`);
        if (consumer.condition !== 'unconditional in the linked template branch') {
          assert(consumer.conditionProof.length > 0,
            `${sourcePath}#${fieldPath}: conditional consumption has no branch proof`);
        }
        assert(consumer.defaultProofEvidence?.path === sourcePath && consumer.defaultProofEvidence?.fieldPath === fieldPath,
          `${sourcePath}#${fieldPath}: selected-value proof does not bind the exact source field`);
        assert.equal(consumer.defaultProofEvidence.sourceSha256, declaration.sourceSha256,
          `${sourcePath}#${fieldPath}: selected-value proof has the wrong source digest`);
        if (consumer.defaultClauseProof) {
          assert(['primary', 'fallback'].includes(consumer.defaultClauseProof.role),
            `${sourcePath}#${fieldPath}: nested default role is invalid`);
          assert(consumer.defaultClauseProof.left && consumer.defaultClauseProof.fallback,
            `${sourcePath}#${fieldPath}: nested default operands are incomplete`);
          assert.equal(consumer.defaultClauseProof.sourceLineSha256, consumer.sourceLineSha256,
            `${sourcePath}#${fieldPath}: nested default proof is not bound to the consumer line`);
        }
        assert(Array.isArray(consumer.defaultClauseProofs),
          `${sourcePath}#${fieldPath}: complete default-clause proof list is missing`);
        for (const proof of consumer.defaultClauseProofs) {
          assert(['primary', 'fallback'].includes(proof.role),
            `${sourcePath}#${fieldPath}: default-clause role is invalid`);
          assert(proof.left && proof.fallback,
            `${sourcePath}#${fieldPath}: default-clause operands are incomplete`);
          assert.equal(proof.sourceLineSha256, consumer.sourceLineSha256,
            `${sourcePath}#${fieldPath}: default-clause proof is not bound to the consumer line`);
        }
        if (verifyBytes) {
          const templateText = fs.readFileSync(path.join(repositoryRoot, consumer.path), 'utf8');
          const lines = templateText.split('\n');
          assert.equal(sha256(lines[consumer.line - 1] ?? ''), consumer.sourceLineSha256,
            `${sourcePath}#${fieldPath}: exact consumer line changed`);
          const start = Math.max(0, consumer.line - 4);
          const end = Math.min(lines.length, consumer.line + 3);
          assert.equal(sha256(lines.slice(start, end).join('\n')), consumer.contextSha256,
            `${sourcePath}#${fieldPath}: consumer context changed while its value expression may be unchanged`);
          if (/\{\{-?\s*define\s+"[^"]+"/u.test(lines.slice(0, consumer.line).join('\n'))) {
            assert(consumer.receiverProof.some((receiver) => /exact (?:transitive )?call site for Helm helper .* (?:with root-context argument|with \.Values\.)/u.test(receiver.relation ?? '')),
              `${sourcePath}#${fieldPath}: helper value has no exact parameter/root include/template call-site proof`);
          }
          for (const receiver of consumer.receiverProof) {
            assert(Number.isSafeInteger(receiver.line) && receiver.line > 0,
              `${sourcePath}#${fieldPath}: receiver line is invalid`);
            assert(typeof receiver.relation === 'string' && receiver.relation.length >= 12,
              `${sourcePath}#${fieldPath}: receiver relationship is not explained`);
            const receiverPath = receiver.path ?? consumer.path;
            assert(receiverPath.startsWith(`${declaration.chartRoot}/templates/`),
              `${sourcePath}#${fieldPath}: receiver is outside the selected chart`);
            const receiverLines = fs.readFileSync(path.join(repositoryRoot, receiverPath), 'utf8').split('\n');
            assert.equal(sha256(receiverLines[receiver.line - 1] ?? ''), receiver.sourceLineSha256,
              `${sourcePath}#${fieldPath}: downstream receiver changed`);
          }
          for (const condition of consumer.conditionProof) {
            assert(condition.path === consumer.path && Number.isSafeInteger(condition.line) && condition.line > 0,
              `${sourcePath}#${fieldPath}: branch proof is outside the consumer template`);
            assert.equal(sha256(lines[condition.line - 1] ?? ''), condition.sourceLineSha256,
              `${sourcePath}#${fieldPath}: branch condition changed`);
          }
        }
      }
      assert.doesNotMatch(authority.purpose, /^Sets .+ in the rendered .+ resources\.$/u, `${sourcePath}#${fieldPath}: tautological render-only purpose`);
      assert(!/-unresolved$/u.test(authority.group), `${sourcePath}#${fieldPath}: unresolved semantic proposal was accepted`);
      assert(Array.isArray(authority.runtimeConsumerProof), `${sourcePath}#${fieldPath}: runtime proof list is missing`);
      for (const proof of authority.runtimeConsumerProof) {
        assert(typeof proof.path === 'string' && Number.isSafeInteger(proof.line) && proof.line > 0,
          `${sourcePath}#${fieldPath}: runtime proof location is invalid`);
        assert((typeof proof.authority === 'string' && proof.authority.length >= 20)
          || (typeof proof.access === 'string' && typeof proof.environment === 'string'),
          `${sourcePath}#${fieldPath}: runtime proof relationship is not explained`);
        if (proof.sourceLineSha256) {
          const proofLines = fs.readFileSync(path.join(repositoryRoot, proof.path), 'utf8').split('\n');
          assert.equal(sha256(proofLines[proof.line - 1] ?? ''), proof.sourceLineSha256,
            `${sourcePath}#${fieldPath}: runtime consumer line changed`);
        }
      }
      if (authority.group === 'environment-runtime-contract') {
        assert(Array.isArray(authority.runtimeConsumerProof) && authority.runtimeConsumerProof.length > 0,
          `${sourcePath}#${fieldPath}: environment delivery has no runtime-boundary proof`);
      }
    }
  }
  for (const [chartRoot, chart] of Object.entries(registry.charts)) {
    assert(Object.keys(chart.templates).length > 0, `${chartRoot}: empty template authority set`);
    for (const [templatePath, sha256] of Object.entries(chart.templates)) {
      assert(templatePath.startsWith(`${chartRoot}/templates/`), `${templatePath}: template is outside ${chartRoot}`);
      assert.match(sha256, /^[a-f0-9]{64}$/u, `${templatePath}: invalid template digest`);
      if (verifyBytes) {
        const absoluteTemplate = path.join(repositoryRoot, templatePath);
        assert(fs.existsSync(absoluteTemplate), `${templatePath}: pinned template is missing`);
        assert.equal(crypto.createHash('sha256').update(fs.readFileSync(absoluteTemplate)).digest('hex'), sha256,
          `${templatePath}: pinned template bytes changed`);
      }
    }
  }
}

if (!process.argv.includes('--allow-local-helm-authority-maintenance')) {
  // Import-time validation proves the registry structure. The inventory calls
  // this function again with its selected --root to prove the actual bytes.
  assertLocalHelmAuthorityRegistry(process.cwd(), { verifyBytes: false });
}

scripts/docs-api-schema-authorities.mjs.syntax:
const stable = (value) => {
  if (Array.isArray(value)) return value.map(stable);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right)).map(([key, item]) => [key, stable(item)]));
  return value;
};

if (process.argv.includes('--refresh-api-authorities')) {
  const response = await fetch(kubernetesUrl);
  assert(response.ok, `failed to download Kubernetes OpenAPI authority: ${response.status}`);
  const bytes = Buffer.from(await response.arrayBuffer());
  const contentSha256 = sha256(bytes);
  const compressed = gzipSync(bytes, { level: 9, mtime: 0 });
  fs.mkdirSync(authorityDirectory, { recursive: true });
  const relative = `scripts/vendor/api-authorities/${contentSha256}.json.gz`;
  fs.writeFileSync(path.join(repositoryRoot, relative), compressed);
  const ciliumCrds = {};
  for (const [kind, fileName] of Object.entries({
    CiliumNetworkPolicy: 'ciliumnetworkpolicies.yaml',
    CiliumClusterwideNetworkPolicy: 'ciliumclusterwidenetworkpolicies.yaml',
  })) {
    const source = `https://raw.githubusercontent.com/cilium/cilium/v1.20.1/pkg/k8s/apis/cilium.io/client/crds/v2/${fileName}`;
    const crdResponse = await fetch(source);
    assert(crdResponse.ok, `failed to download ${kind} CRD authority: ${crdResponse.status}`);
    const crdBytes = Buffer.from(await crdResponse.arrayBuffer());
    const crdSha256 = sha256(crdBytes);
    const crdCompressed = gzipSync(crdBytes, { level: 9, mtime: 0 });
    const crdRelative = `scripts/vendor/api-authorities/${crdSha256}.yaml.gz`;
    fs.writeFileSync(path.join(repositoryRoot, crdRelative), crdCompressed);
    ciliumCrds[kind] = {
      source,
      contentSha256: crdSha256,
      compressedSha256: sha256(crdCompressed),
      compressedSize: crdCompressed.length,
      path: crdRelative,
    };
  }
  const manifest = {
    version: 1,
    kubernetes: {
      version: kubernetesVersion,
      source: kubernetesUrl,
      contentSha256,
      compressedSha256: sha256(compressed),
      compressedSize: compressed.length,
      path: relative,
    },
    customResources: {
      argoproj: { chartKey: 'argocd', chart: 'argo-cd', version: '10.8.0' },
      cilium: { chartKey: 'cilium', chart: 'cilium', version: '1.20.1', crds: ciliumCrds },
    },
  };
  const manifestBytes = `${JSON.stringify(stable(manifest), null, 2)}\n`;
  fs.writeFileSync(manifestPath, manifestBytes);
  fs.writeFileSync(checksumPath, `${sha256(manifestBytes)}  ${path.basename(manifestPath)}\n`);
}

for (const [definition, schema] of Object.entries(kubernetesOpenApi.definitions)) {
  for (const gvk of schema['x-kubernetes-group-version-kind'] ?? []) {
    const apiVersion = gvk.group ? `${gvk.group}/${gvk.version}` : gvk.version;
    const key = `${apiVersion}/${gvk.kind}`;
    assert(!builtinDefinitions.has(key) || builtinDefinitions.get(key) === definition,
      `API_SCHEMA_GVK_DUPLICATE: ${key}`);
    builtinDefinitions.set(key, definition);
  }
}

function loadCustomResourceSchemas() {
  if (customResourceSchemas) return customResourceSchemas;
  customResourceSchemas = new Map();
  const archiveManifest = JSON.parse(fs.readFileSync(path.join(repositoryRoot, 'scripts/external-helm-archives.json')));
  for (const authority of Object.values(manifest.customResources)) {
    const archive = archiveManifest.charts[authority.chartKey];
    assert(archive && archive.chart === authority.chart && archive.version === authority.version,
      `CONFIG_YAML_AUTHORITY_DRIFT: scripts/external-helm-archives.json#charts.${authority.chartKey}: custom-resource authority ${authority.chart}@${authority.version} does not match the vendored chart`);
    const archiveIdentity = `${authority.chartKey} ${authority.chart}@${authority.version} (${archive.path})`;
    const archiveBytes = fs.readFileSync(path.join(repositoryRoot, archive.path));
    assert.equal(archiveBytes.length, archive.size, `CONFIG_YAML_AUTHORITY_DRIFT: ${archiveIdentity}: chart archive byte count changed`);
    assert.equal(sha256(archiveBytes), archive.sha256, `CONFIG_YAML_AUTHORITY_DRIFT: ${archiveIdentity}: chart archive bytes changed`);
    const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'kubeclaw-api-crd-'));
    try {
      const unpack = spawnSync('tar', ['-xzf', path.join(repositoryRoot, archive.path), '-C', temporary], { encoding: 'utf8' });
      assert.equal(unpack.status, 0, `${authority.chartKey}: cannot extract vendored CRD authority`);
      const documents = [];
      if (authority.crds) {
        for (const [kind, crd] of Object.entries(authority.crds)) {
          const crdIdentity = `${authority.chartKey} ${authority.chart}@${authority.version} ${kind} ${crd.source} (${crd.path})`;
          const compressed = fs.readFileSync(path.join(repositoryRoot, crd.path));
          assert.equal(compressed.length, crd.compressedSize, `CONFIG_YAML_AUTHORITY_DRIFT: ${crdIdentity}: compressed CRD byte count changed`);
          assert.equal(sha256(compressed), crd.compressedSha256, `CONFIG_YAML_AUTHORITY_DRIFT: ${crdIdentity}: compressed CRD bytes changed`);
          const bytes = gunzipSync(compressed);
          assert.equal(sha256(bytes), crd.contentSha256, `CONFIG_YAML_AUTHORITY_DRIFT: ${crdIdentity}: CRD source bytes changed`);
          documents.push(...YAML.parseAllDocuments(bytes.toString('utf8'), { prettyErrors: false }).map((document) => ({ document, source: crd.source })));
        }
      } else {
        const chartDirectory = fs.readdirSync(temporary).map((name) => path.join(temporary, name)).find((candidate) => fs.statSync(candidate).isDirectory());
        const rendered = spawnSync('helm', ['template', 'api-authority', chartDirectory, '--include-crds', '--set', 'crds.install=true'], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
        assert.equal(rendered.status, 0, `${authority.chartKey}: cannot render vendored CRD authority: ${rendered.stderr}`);
        const chart = YAML.parse(fs.readFileSync(path.join(chartDirectory, 'Chart.yaml'), 'utf8'));
        assert(/^v[0-9]+\.[0-9]+\.[0-9]+$/u.test(chart.appVersion), 'API_SCHEMA_APP_VERSION_INVALID');
        documents.push(...YAML.parseAllDocuments(rendered.stdout, { prettyErrors: false }).map((document) => ({ document, source: `${authority.chart}@${authority.version} rendered CRDs`, appVersion: chart.appVersion })));
      }
      for (const item of documents) {
        const { document } = item;
          assert.equal(document.errors.length, 0, `API_SCHEMA_CRD_YAML_INVALID: ${item.source}`);
          const value = document.toJS();
          if (value?.kind !== 'CustomResourceDefinition') continue;
          for (const version of value.spec?.versions ?? []) {
            const key = `${value.spec.group}/${version.name}/${value.spec.names.kind}`;
            customResourceSchemas.set(key, {
              schema: version.schema?.openAPIV3Schema,
              authority: item.source,
              upstreamReference: authority.chartKey === 'argocd' ? `https://github.com/argoproj/argo-cd/blob/${item.appVersion}/manifests/crds/${value.spec.names.singular}-crd.yaml` : item.source,
              archiveSha256: authority.crds
                ? Object.values(authority.crds).find((crd) => crd.source === item.source)?.contentSha256
                : archive.sha256,
            });
          }
      }
    } finally {
      fs.rmSync(temporary, { recursive: true, force: true });
    }
  }
  for (const { value, context } of discoverExternalChartApiOutputs(repositoryRoot)) {
    if(value.kind!=='CustomResourceDefinition')continue;
    for(const version of value.spec?.versions??[]) {
      if(!version.served)continue;
      const key=`${value.spec.group}/${version.name}/${value.spec.names.kind}`;
      if(customResourceSchemas.has(key))continue;
      const schema=structuredClone(version.schema?.openAPIV3Schema);
      assert(schema,`API_SCHEMA_EXTERNAL_CRD_MISSING: ${context.profile}:${value.metadata.name}`);
      customResourceSchemas.set(key,{schema,authority:`Authenticated actual ${context.profile} CRD registration ${value.metadata.name}`,archiveSha256:context.archiveSha256,upstreamReference:context.archivePath});
    }
  }
  for (const { value, context } of discoverHelmSchemaApiOutputs(repositoryRoot)) {
    if (value.kind !== 'CustomResourceDefinition') continue;
    for (const version of value.spec?.versions ?? []) {
      const key = `${value.spec.group}/${version.name}/${value.spec.names.kind}`;
      const schema = structuredClone(version.schema?.openAPIV3Schema);
      assert(schema, `API_SCHEMA_LOCAL_CRD_MISSING: ${context.path}`);
      // Standard CRD envelope fields are served by Kubernetes independently of
      // the custom spec/status schema. ObjectMeta remains opaque here, like the
      // authenticated upstream CRD authorities, and gets its separate receiver.
      schema.properties ??= {};
      schema.properties.apiVersion ??= {type:'string'};
      schema.properties.kind ??= {type:'string'};
      schema.properties.metadata ??= {type:'object'};
      if (customResourceSchemas.has(key)) {
        const existing=customResourceSchemas.get(key);
        assert(existing.owned && JSON.stringify(stable(existing.schema))===JSON.stringify(stable(schema)), `API_SCHEMA_OWNED_CONTEXT_VARIANT_UNQUALIFIED: ${key} ${context.path} ${context.profile}; qualify the configured schema authority before publication`);
        continue;
      }
      customResourceSchemas.set(key, {schema, authority:`KubeClaw-owned CRD ${context.path}`,
        archiveSha256:context.sourceDigest, upstreamReference:context.path, owned:true});
    }
  }
  return customResourceSchemas;
}

export function isProductOwnedApi(apiVersion, kind) {
  return loadCustomResourceSchemas().get(`${apiVersion}/${kind}`)?.owned === true;
}

function resolveReference(schema) {
  let current = schema;
  const visited = new Set();
  while (current?.$ref) {
    assert(current.$ref.startsWith('#/definitions/'), `unsupported OpenAPI reference ${current.$ref}`);
    assert(!visited.has(current.$ref), `cyclic OpenAPI reference ${current.$ref}`);
    visited.add(current.$ref);
    current = kubernetesOpenApi.definitions[current.$ref.slice('#/definitions/'.length)];
    assert(current, `missing OpenAPI definition ${[...visited].at(-1)}`);
  }
  return current;
}

function resolveCollectionReference(schema) {
  if (!schema?.$ref) return schema;
  let current = schema;
  const references = [], siblings = {};
  while (current?.$ref) {
    assert(current.$ref.startsWith('#/definitions/'), `unsupported OpenAPI reference ${current.$ref}`);
    assert(!references.includes(current.$ref), `cyclic OpenAPI reference ${current.$ref}`);
    references.push(current.$ref);
    for (const [key, value] of Object.entries(current)) if (key !== '$ref' && !Object.hasOwn(siblings, key)) siblings[key] = value;
    current = kubernetesOpenApi.definitions[current.$ref.slice('#/definitions/'.length)];
    assert(current, `missing OpenAPI definition ${references.at(-1)}`);
  }
  for (const [key, value] of Object.entries(siblings)) if (!['description', 'title'].includes(key) && Object.hasOwn(current, key)) {
    assert.deepEqual(value, current[key], `API_SCHEMA_REFERENCE_CONFLICT: ${references[0]} sibling ${key} conflicts with its definition`);
  }
  return { ...current, ...siblings, schemaReferenceChain: references, referencedContract: apiSchemaNodeContract(current) };
}

export function apiFieldSchemaAuthority(apiVersion, kind, fieldPath, { includeCollectionContract = false } = {}) {
  if (fieldPath === 'apiVersion' || fieldPath === 'kind') return {
    authority: `Kubernetes ${manifest.kubernetes.version} object envelope plus ${apiVersion}/${kind} selected API contract`,
    authoritySha256: manifest.kubernetes.contentSha256,
    apiVersion,
    kind,
    fieldPath,
    resolvedPath: fieldPath,
    type: 'string',
    enum: [fieldPath === 'apiVersion' ? apiVersion : kind],
    default: '<no schema default>',
    format: null,
    minimum: null,
    maximum: null,
    requiredBySchema: true,
    nullable: false,
    descriptionSha256: null,
  };
  const builtin = builtinDefinitions.get(`${apiVersion}/${kind}`);
  let schema;
  let authority;
  let authoritySha256;
  let fieldTokens = yamlFieldPathTokens(fieldPath).map((token) => typeof token === 'number' ? '[]' : token);
  if (fieldTokens[0] === 'metadata') {
    schema = kubernetesOpenApi.definitions['io.k8s.apimachinery.pkg.apis.meta.v1.ObjectMeta'];
    authority = `Kubernetes ${manifest.kubernetes.version} OpenAPI io.k8s.apimachinery.pkg.apis.meta.v1.ObjectMeta`;
    authoritySha256 = manifest.kubernetes.contentSha256;
    fieldTokens = fieldTokens.slice(1);
  } else if (builtin) {
    schema = kubernetesOpenApi.definitions[builtin];
    authority = `Kubernetes ${manifest.kubernetes.version} OpenAPI ${builtin}`;
    authoritySha256 = manifest.kubernetes.contentSha256;
  } else {
    const custom = loadCustomResourceSchemas().get(`${apiVersion}/${kind}`);
    assert(custom?.schema, `API_SCHEMA_AUTHORITY_MISSING: ${apiVersion}/${kind}`);
    schema = custom.schema;
    authority = custom.authority;
    authoritySha256 = custom.archiveSha256;
  }
  const resolve = includeCollectionContract ? resolveCollectionReference : resolveReference;
  let current = resolve(schema);
  const resolved = [];
  let requiredBySchema = false;
  let parent = null;
  const parentContracts = [];
  for (let index = 0; index < fieldTokens.length; index += 1) {
    const token = fieldTokens[index];
    current = resolve(current);
    parent = current;
    if (includeCollectionContract) parentContracts.push({ path: yamlFieldPath(resolved, { root: false, arrayWildcard: true }), ...apiSchemaNodeContract(parent) });
    if (token === '[]') {
      if (includeCollectionContract) requiredBySchema = false;
      current = resolve(current?.items);
    }
    else if (current?.properties?.[token]) {
      requiredBySchema = Array.isArray(current.required) && current.required.includes(token);
      current = resolve(current.properties[token]);
    }
    else if (typeof current?.additionalProperties === 'object') {
      current = resolve(current.additionalProperties);
      resolved.push(...fieldTokens.slice(index));
      index = fieldTokens.length;
      break;
    } else current = null;
    assert(current, `API_SCHEMA_FIELD_MISSING: ${apiVersion}/${kind} ${fieldPath} stopped at ${resolved.join('.') || '<root>'}`);
    resolved.push(token);
  }
  return {
    authority,
    authoritySha256,
    apiVersion,
    kind,
    fieldPath,
    resolvedPath: yamlFieldPath(resolved, { root: false, arrayWildcard: true }),
    type: current.type ?? (current.properties ? 'object' : null),
    enum: current.enum ?? null,
    default: Object.hasOwn(current, 'default') ? current.default : '<no schema default>',
    format: current.format ?? null,
    minimum: current.minimum ?? null,
    maximum: current.maximum ?? null,
    requiredBySchema,
    nullable: current.nullable === true,
    descriptionSha256: current.description ? sha256(current.description) : null,
    ...(includeCollectionContract ? {
      contract: apiSchemaNodeContract(current),
      children: Object.fromEntries(Object.entries(current.properties ?? {}).map(([name, child]) => [name, apiSchemaNodeContract(resolve(child))])),
      item: current.items ? apiSchemaNodeContract(resolve(current.items)) : null,
      itemChildren: Object.fromEntries(Object.entries(resolve(current.items)?.properties ?? {}).map(([name, child]) => [name, apiSchemaNodeContract(resolve(child))])),
      mapValue: typeof current.additionalProperties === 'object' ? apiSchemaNodeContract(resolve(current.additionalProperties)) : null,
      parent: parent ? apiSchemaNodeContract(parent) : null,
      parentContracts,
      contractScope: 'Exact pinned schema contracts only. Descriptions can state controller behavior; a missing description or schema default does not prove a controller fallback. API patch annotations do not select the apply mode used by a client.',
    } : {}),
  };
}

function apiSchemaNodeContract(schema) {
  if (!schema) return null;
  const keywords = ['type', 'description', 'default', 'nullable', 'enum', 'const', 'format', 'pattern',
    'minimum', 'maximum', 'exclusiveMinimum', 'exclusiveMaximum', 'multipleOf',
    'minLength', 'maxLength', 'minItems', 'maxItems', 'uniqueItems', 'minProperties',
    'maxProperties', 'required', 'additionalProperties', 'oneOf', 'anyOf', 'allOf',
    'not', 'if', 'then', 'else', 'dependencies', 'dependentRequired', 'dependentSchemas',
    'contains', 'minContains', 'maxContains', 'propertyNames', 'patternProperties', 'prefixItems',
    'additionalItems', 'unevaluatedProperties', 'unevaluatedItems', 'readOnly', 'writeOnly',
    'deprecated', 'title', 'example', 'examples', '$schema', '$id', '$comment',
    'schemaReferenceChain', 'referencedContract'];
  // Properties and items are exposed through the named child/item boundaries.
  // Unknown keywords cannot silently disappear from an "exact" contract.
  const structural = ['properties', 'items'];
  // This vocabulary is qualified against the pinned Kubernetes and Cilium
  // authorities. A new vendor keyword needs an explicit contract review;
  // accepting an arbitrary prefix would hide a newly introduced constraint.
  const kubernetesKeywords = ['x-kubernetes-action', 'x-kubernetes-embedded-resource',
    'x-kubernetes-group-version-kind', 'x-kubernetes-int-or-string',
    'x-kubernetes-list-map-keys', 'x-kubernetes-list-type', 'x-kubernetes-map-type',
    'x-kubernetes-patch-merge-key', 'x-kubernetes-patch-strategy',
    'x-kubernetes-preserve-unknown-fields', 'x-kubernetes-unions',
    'x-kubernetes-validations'];
  const unsupportedBranches = ['prefixItems', 'contains', 'additionalItems',
    'unevaluatedProperties', 'unevaluatedItems'];
  // Qualify schema fragments, not instance data such as defaults or examples.
  // References stay bounded: normal boundary traversal resolves their targets.
  const qualified = new WeakSet();
  function qualify(fragment) {
    if (typeof fragment === 'boolean') return;
    assert(fragment && typeof fragment === 'object' && !Array.isArray(fragment),
      'API_SCHEMA_FRAGMENT_UNQUALIFIED');
    if (qualified.has(fragment)) return;
    qualified.add(fragment);
    for (const key of Object.keys(fragment)) {
      assert(keywords.includes(key) || structural.includes(key) || key === '$ref'
        || kubernetesKeywords.includes(key), `API_SCHEMA_COLLECTION_KEYWORD_UNQUALIFIED: ${key}`);
      assert(!unsupportedBranches.includes(key), `API_SCHEMA_STRUCTURAL_BRANCH_UNQUALIFIED: ${key}`);
    }
    if (fragment.$ref) qualify(resolveReference(fragment));
    for (const key of ['properties', 'patternProperties', 'dependentSchemas']) {
      for (const child of Object.values(fragment[key] ?? {})) qualify(child);
    }
    for (const child of Object.values(fragment.dependencies ?? {})) {
      if (!Array.isArray(child)) qualify(child); // Property dependencies contain names.
    }
    for (const key of ['allOf', 'anyOf', 'oneOf']) {
      for (const child of fragment[key] ?? []) qualify(child);
    }
    for (const key of ['not', 'if', 'then', 'else', 'propertyNames', 'additionalProperties']) {
      if (Object.hasOwn(fragment, key)) qualify(fragment[key]);
    }
    if (Object.hasOwn(fragment, 'items')) {
      assert(typeof fragment.items !== 'boolean', 'API_SCHEMA_STRUCTURAL_BRANCH_UNQUALIFIED: Boolean items');
      assert(!Array.isArray(fragment.items), 'API_SCHEMA_TUPLE_BOUNDARY_UNQUALIFIED');
      qualify(fragment.items);
    }
  }
  qualify(schema);
  return { ...Object.fromEntries(Object.entries(schema).filter(([key]) => keywords.includes(key)
    || kubernetesKeywords.includes(key))), observedSchemaKeywords: [...new Set([
      ...Object.keys(schema).filter((key) => !['schemaReferenceChain', 'referencedContract'].includes(key)),
      ...(schema.schemaReferenceChain ? ['$ref'] : []),
    ])].sort() };
}

export function apiFieldCollectionAuthority(apiVersion, kind, fieldPath) {
  return apiFieldSchemaAuthority(apiVersion, kind, fieldPath, { includeCollectionContract: true });
}

export function apiResourceFieldBoundaries(apiVersion, kind) {
  const builtin = builtinDefinitions.get(`${apiVersion}/${kind}`);
  const schema = builtin ? kubernetesOpenApi.definitions[builtin]
    : loadCustomResourceSchemas().get(`${apiVersion}/${kind}`)?.schema;
  assert(schema, `API_SCHEMA_AUTHORITY_MISSING: ${apiVersion}/${kind}`);
  const authority = apiFieldCollectionAuthority(apiVersion, kind, '$');
  const boundaries = [];
  function hasStructure(branch) {
    if (!branch || typeof branch !== 'object' || Array.isArray(branch)) return false;
    if (branch.$ref || branch.properties || branch.patternProperties || branch.items
      || typeof branch.additionalProperties === 'object') return true;
    return ['allOf', 'anyOf', 'oneOf'].some((key) => (branch[key] ?? []).some(hasStructure))
      || ['not', 'if', 'then', 'else'].some((key) => hasStructure(branch[key]))
      || ['dependentSchemas', 'dependencies'].some((key) => Object.values(branch[key] ?? {}).some(hasStructure));
  }
  function visit(raw, tokens, ancestors) {
    const identity = resolveReference(raw);
    const fieldPath = yamlFieldPath(tokens, { arrayWildcard: true });
    assert(identity, `API_SCHEMA_BOUNDARY_MISSING: ${apiVersion}/${kind} ${fieldPath}`);
    assert(!ancestors.has(identity), `API_SCHEMA_RECURSIVE_BOUNDARY_UNQUALIFIED: ${apiVersion}/${kind} ${fieldPath}`);
    const node = resolveCollectionReference(raw);
    const contract = apiSchemaNodeContract(node);
    // The pinned Cilium direction alternatives redeclare existing properties
    // as {} and require their presence. They add no child boundary; retain the
    // complete alternative in the parent contract. Other structural variants
    // need a separately qualified traversal, rather than silent flattening.
    assert(!Object.keys(node.patternProperties ?? {}).length,
      `API_SCHEMA_PATTERN_BOUNDARY_UNQUALIFIED: ${apiVersion}/${kind} ${fieldPath}`);
    const alternatives = [
      ...['allOf', 'anyOf', 'oneOf'].flatMap((key) => (node[key] ?? []).map((branch) => [key, branch])),
      ...['not', 'if', 'then', 'else'].filter((key) => node[key]).map((key) => [key, node[key]]),
      ...['dependentSchemas', 'dependencies'].flatMap((key) => Object.values(node[key] ?? {}).map((branch) => [key, branch])),
    ];
    for (const [keyword, branch] of alternatives) {
      if (!hasStructure(branch)) continue;
      const presenceOnly = Object.keys(branch).every((key) => ['properties', 'required'].includes(key))
        && Object.entries(branch.properties ?? {}).every(([name, child]) =>
          Object.hasOwn(node.properties ?? {}, name) && Object.keys(child).length === 0)
        && (branch.required ?? []).every((name) => Object.hasOwn(node.properties ?? {}, name));
      assert(presenceOnly,
        `API_SCHEMA_COMPOSITION_BOUNDARY_UNQUALIFIED: ${apiVersion}/${kind} ${fieldPath} ${keyword}`);
    }
    boundaries.push({ apiVersion, kind, fieldPath, authority: authority.authority,
      authoritySha256: authority.authoritySha256, contract });
    // A CRD registration embeds a schema definition, rather than a custom
    // resource instance. Its keyword grammar is recursive and belongs to the
    // linked apiextensions API reference. KubeClaw-owned served schemas are
    // independently expanded completely by their own GVK below.
    if(apiVersion==='apiextensions.k8s.io/v1'&&kind==='CustomResourceDefinition'&&fieldPath==='$.spec.versions[].schema.openAPIV3Schema')return;
    const next = new Set(ancestors).add(identity);
    for (const [name, child] of Object.entries(node.properties ?? {}).sort(([a], [b]) => a.localeCompare(b))) {
      visit(child, [...tokens, name], next);
    }
    if (node.items) {
      assert(!Array.isArray(node.items), `API_SCHEMA_TUPLE_BOUNDARY_UNQUALIFIED: ${apiVersion}/${kind} ${fieldPath}`);
      visit(node.items, [...tokens, '[]'], next);
    }
    if (typeof node.additionalProperties === 'object') visit(node.additionalProperties, [...tokens, '*'], next);
  }
  visit(schema, [], new Set());
  return boundaries;
}

export function apiSchemaUpstreamReference(apiVersion, kind) {
  if (builtinDefinitions.has(`${apiVersion}/${kind}`)) return manifest.kubernetes.source;
  const schema = loadCustomResourceSchemas().get(`${apiVersion}/${kind}`);
  assert(schema?.upstreamReference, `API_SCHEMA_REFERENCE_MISSING: ${apiVersion}/${kind}`);
  return schema.upstreamReference;
}

