  }else assert(!(/encoding\/json/u.test(bytes)&&/(?:\b\w+\.)?(?:Marshal|NewEncoder)\s*\(/u.test(bytes)),`API_PRODUCT_GO_SERIALIZED_OUTPUT_ROLE_UNQUALIFIED: ${source}`);
