export function infrastructureChart(name) {
  const manifest = JSON.parse(fs.readFileSync(path.join(root, 'versions.json'), 'utf8'));
  const lock = manifest.infrastructureCharts?.[name];
  return validateInfrastructureChartLock(lock);
}

export function verifyInfrastructureChart(name, file) {
  const lock = infrastructureChart(name);
  const stat = fs.lstatSync(file);
  if (!stat.isFile() || stat.size < 1 || stat.size > maximumBytes) throw new Error('INFRASTRUCTURE_CHART_FILE_INVALID');
  const digest = createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  if (digest !== lock.sha256) throw new Error('INFRASTRUCTURE_CHART_DIGEST_MISMATCH');
  // A version tag alone is insufficient: the checked archive also includes its
  // exact packaged dependencies. Never run helm dependency update at deployment.
  const metadata = load(execFileSync('tar', ['-xOf', file, `${lock.name}/Chart.yaml`], { encoding: 'utf8', maxBuffer: maximumBytes }));
  if (metadata.name !== lock.name || metadata.version !== lock.version) throw new Error('INFRASTRUCTURE_CHART_IDENTITY_MISMATCH');
  if (lock.appVersion !== undefined && metadata.appVersion !== lock.appVersion) throw new Error('INFRASTRUCTURE_CHART_APP_VERSION_MISMATCH');
  return { name: lock.name, version: lock.version, appVersion: metadata.appVersion, sha256: digest };
}

export function stageInfrastructureChart(name) {
  const lock = infrastructureChart(name);
  const cache = path.join(os.tmpdir(), `kubeclaw-infrastructure-charts-${process.getuid()}`);
  fs.mkdirSync(cache, { recursive: true, mode: 0o700 });
  const stat = fs.lstatSync(cache);
  if (!stat.isDirectory() || stat.uid !== process.getuid() || (stat.mode & 0o077) !== 0) {
    throw new Error('INFRASTRUCTURE_CHART_CACHE_NOT_PRIVATE');
  }
  const file = path.join(cache, `${lock.name}-${lock.version}-${lock.sha256}.tgz`);
  if (!fs.existsSync(file)) {
    const temporary = fs.mkdtempSync(path.join(cache, 'download-'));
    try {
      const download = path.join(temporary, 'chart.tgz');
      if (lock.url.startsWith('oci:')) downloadInfrastructureOciChart(lock.url, download);
      else execFileSync('curl', ['--fail', '--silent', '--show-error', '--location', '--proto', '=https',
        '--proto-redir', '=https', '--retry', '4', '--retry-max-time', '120', '--connect-timeout', '15', '--max-time', '60', '--max-filesize', String(maximumBytes),
        '--output', download, lock.url], { stdio: ['ignore', 'ignore', 'inherit'] });
      verifyInfrastructureChart(name, download);
      fs.renameSync(download, file);
    } finally { fs.rmSync(temporary, { recursive: true, force: true }); }
  }
  verifyInfrastructureChart(name, file);
  return file;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [name, file] = process.argv.slice(2);
  if (!name || process.argv.length > 4) throw new Error('Usage: infrastructure-chart.mjs NAME [ARCHIVE_TO_VERIFY]');
  console.log(file ? JSON.stringify(verifyInfrastructureChart(name, file)) : stageInfrastructureChart(name));
}

scripts/infrastructure-oci-chart.mjs.syntax:
function request(url, token, output) {
  const config = token ? `header = ${JSON.stringify(`Authorization: Bearer ${token}`)}\n` : '';
  return execFileSync('curl', ['--config', '-', '--fail', '--silent', '--show-error', '--location', '--proto', '=https',
    '--proto-redir', '=https', '--max-time', '180', '--max-filesize', String(output ? maximumBytes : 1048576),
    '--header', 'Accept: application/vnd.oci.image.manifest.v1+json', ...(output ? ['--output', output] : []), url],
  { input: config, maxBuffer: 1048576, stdio: ['pipe', 'pipe', 'pipe'] });
}

export function downloadInfrastructureOciChart(value, output) {
  const { repository, digest } = parseInfrastructureOciChart(value);
  const tokenUrl = new URL('https://auth.docker.io/token');
  tokenUrl.searchParams.set('service', 'registry.docker.io');
  tokenUrl.searchParams.set('scope', `repository:${repository}:pull`);
  const token = JSON.parse(request(tokenUrl.href)).token;
  if (typeof token !== 'string' || !/^[A-Za-z0-9._-]+$/.test(token)) throw new Error('INFRASTRUCTURE_OCI_TOKEN_INVALID');
  const origin = `https://registry-1.docker.io/v2/${repository}`;
  const bytes = request(`${origin}/manifests/${digest}`, token);
  if (`sha256:${createHash('sha256').update(bytes).digest('hex')}` !== digest) throw new Error('INFRASTRUCTURE_OCI_MANIFEST_DIGEST_MISMATCH');
  const manifest = JSON.parse(bytes);
  const layers = manifest.layers?.filter(layer => layer.mediaType === 'application/vnd.cncf.helm.chart.content.v1.tar+gzip');
  if (manifest.schemaVersion !== 2 || layers?.length !== 1) throw new Error('INFRASTRUCTURE_OCI_CHART_LAYER_REQUIRED');
  const layer = layers[0];
  if (!/^sha256:[a-f0-9]{64}$/.test(layer.digest) || !Number.isSafeInteger(layer.size) || layer.size < 1 || layer.size > maximumBytes) {
    throw new Error('INFRASTRUCTURE_OCI_CHART_LAYER_INVALID');
  }
  request(`${origin}/blobs/${layer.digest}`, token, output);
  const downloaded = fs.readFileSync(output);
  if (downloaded.length !== layer.size || `sha256:${createHash('sha256').update(downloaded).digest('hex')}` !== layer.digest) {
    throw new Error('INFRASTRUCTURE_OCI_CHART_LAYER_DIGEST_MISMATCH');
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 4) throw new Error('Usage: infrastructure-oci-chart.mjs IMMUTABLE_OCI_URL OUTPUT');
  downloadInfrastructureOciChart(process.argv[2], process.argv[3]);
}

