function argumentsMap(values) {
  const output = new Map();
  for (let index = 0; index < values.length; index += 2) {
    const key = values[index], value = values[index + 1];
    if (!key?.startsWith('--') || !value) throw new Error('REVIEW_SUPERVISOR_ARGUMENTS_INVALID');
    output.set(key.slice(2), value);
  }
  return output;
}

function required(args, name) {
  const value = args.get(name);
  if (!value) throw new Error(`REVIEW_SUPERVISOR_${name.toUpperCase().replaceAll('-', '_')}_REQUIRED`);
  return value;
}

function integer(value, label, maximum, minimum = 0) {
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed) || parsed < minimum || parsed > maximum) {
    throw new Error(`REVIEW_SUPERVISOR_${label}_INVALID`);
  }
  return parsed;
}

function isOwnedPipeline(pid, runId) {
  if (!processAlive(pid)) return false;
  let command;
  try { command = fs.readFileSync(`/proc/${pid}/cmdline`, 'utf8').replaceAll('\0', ' '); }
  catch (cause) {
    // The process can exit between the liveness check and the procfs read.
    // Only confirmed absence permits recovery; an unreadable live PID is not
    // permission to replace, adopt, or signal that process.
    if (!processAlive(pid)) return false;
    throw new Error(`REVIEW_SUPERVISOR_PROCESS_OWNERSHIP_UNCONFIRMED:${pid}`, { cause });
  }
  if (!processAlive(pid)) return false;
  if (!command.includes('pipeline') || !command.includes(runId)) {
    throw new Error(`REVIEW_SUPERVISOR_PROCESS_OWNERSHIP_UNCONFIRMED:${pid}`);
  }
  return true;
}

function reviewStatus(script, cwd, platform, runId, heartbeat, resourceLog) {
  const result = spawnSync(process.execPath, [script, '--platform', platform, '--run-id', runId,
    '--heartbeat', heartbeat, '--resource-log', resourceLog, '--stale-after-seconds', '120'],
  { cwd, encoding: 'utf8', timeout: 30_000 });
  if (result.error || result.status !== 0) {
    throw new Error(`REVIEW_SUPERVISOR_STATUS_FAILED: run=${runId}; exit=${result.status}; signal=${result.signal}; ${result.error?.message ?? ''}\n${result.stderr ?? ''}`, { cause: result.error });
  }
  let status;
  try { status = JSON.parse(result.stdout); }
  catch (cause) { throw new Error(`REVIEW_SUPERVISOR_STATUS_INVALID_JSON: run=${runId}`, { cause }); }
  if (status?.schemaVersion !== 'repository-review-status.v1' || status.runId !== runId
    || !['running', 'succeeded', 'failed', 'blocked', 'cancelled'].includes(status.status)) {
    throw new Error(`REVIEW_SUPERVISOR_STATUS_INVALID: run=${runId}`);
  }
  return status;
}

function terminalExit(status) {
  process.stdout.write(`${JSON.stringify(status)}\n`);
  return status.status === 'succeeded' ? 0 : 1;
}

function pipelineArguments(mode, platform, graph, runId) {
  return mode === 'recover'
    ? ['run', 'pipeline', '--', '--platform', platform, '--pipeline', graph, '--recover', runId]
    : ['run', 'pipeline', '--', '--platform', platform, '--pipeline', graph, '--run-id', runId];
}

function runPreflight(args, cwd) {
  const concurrency = args.get('preflight-concurrency');
  const model = args.get('preflight-model');
  if (!concurrency && !model) return;
  if (!concurrency || !model) throw new Error('REVIEW_SUPERVISOR_PREFLIGHT_CONFIG_INCOMPLETE');
  const command = [path.join(cwd, 'scripts', 'openclaw-concurrency-preflight.mjs'),
    '--concurrency', concurrency, '--model', model,
    '--thinking', args.get('preflight-thinking') ?? 'high',
    '--session-key', args.get('controller-session-key') ?? 'agent:main:nova-review-controller',
    '--collector-mode', args.get('preflight-collector-mode') ?? 'false',
    '--spawn-interval-ms', args.get('preflight-spawn-interval-ms') ?? '1500',
    '--timeout-ms', args.get('preflight-timeout-ms') ?? '180000'];
  const result = spawnSync(process.execPath, command, { cwd, encoding: 'utf8', timeout: 240_000,
    maxBuffer: 1024 * 1024 });
  if (result.status !== 0) throw new Error(`REVIEW_SUPERVISOR_PREFLIGHT_FAILED:${result.stderr.trim()}`);
  return JSON.parse(result.stdout);
}

async function runAttempt(params, stopSignal) {
  if (stopSignal.aborted) return { exit: { code: null, signal: null }, stopping: true };
  const descriptor = fs.openSync(params.log, 'a');
  const child = spawn('npm', pipelineArguments(params.mode, params.platform, params.graph, params.runId), {
    cwd: params.cwd, detached: true, stdio: ['ignore', descriptor, descriptor],
  });
  let childError;
  const childExit = new Promise((resolve) => {
    child.once('exit', (code, signal) => resolve({ code, signal }));
    child.once('error', error => {
      childError ??= error;
      // A post-launch signal error is not evidence that the child exited.
      if (child.pid === undefined) resolve({ code: null, signal: null });
    });
  });
  let stopping = false;
  const stop = () => {
    stopping = true;
    if (child.pid !== undefined && child.exitCode === null && child.signalCode === null) {
      try { process.kill(-child.pid, 'SIGTERM'); }
      catch (_error) {
        try { child.kill('SIGTERM'); } catch (error) { childError ??= error; }
      }
    }
  };
  let heartbeatError;
  let pendingHeartbeat = Promise.resolve();
  const heartbeat = (isStopping) => {
    pendingHeartbeat = pendingHeartbeat.then(async () => {
      try { return await writeHeartbeat({ ...params, pipelinePid: child.pid, stopping: isStopping }); }
      catch (error) { heartbeatError ??= error; stop(); return undefined; }
    });
    return pendingHeartbeat;
  };
  stopSignal.addEventListener('abort', stop, { once: true });
  if (stopSignal.aborted) stop();
  await heartbeat(stopping);
  const timer = setInterval(() => {
    void heartbeat(stopping);
  }, SAMPLE_INTERVAL_MS);
  const exit = await childExit;
  clearInterval(timer);
  // No asynchronous sample may overwrite the final stopped heartbeat. Keep the
  // lease and signal listener until both the actual child exit and queued I/O
  // have settled, including when a heartbeat write itself failed.
  await pendingHeartbeat;
  stopSignal.removeEventListener('abort', stop); fs.closeSync(descriptor);
  const sample = await heartbeat(true);
  writeAttemptDiagnostic(params, { exit, stopping, sample, childError, heartbeatError, pipelinePid: child.pid });
  if (childError && heartbeatError) {
    throw new AggregateError([childError, heartbeatError], 'REVIEW_SUPERVISOR_PROCESS_AND_HEARTBEAT_FAILED');
  }
  if (childError) throw new Error(child.pid === undefined
    ? 'REVIEW_SUPERVISOR_LAUNCH_FAILED' : 'REVIEW_SUPERVISOR_PROCESS_FAILED', { cause: childError });
  if (heartbeatError) throw new Error('REVIEW_SUPERVISOR_HEARTBEAT_FAILED', { cause: heartbeatError });
  return { exit, stopping };
}

function writeAttemptDiagnostic(params, { exit, stopping, sample, childError, heartbeatError, pipelinePid }) {
  const diagnostic = {
    schemaVersion: 'repository-review-attempt-diagnostic.v1', capturedAt: new Date().toISOString(),
    runId: params.runId, attempt: params.attempt, mode: params.mode, exit, stopping, sample,
    ...(heartbeatError ? { heartbeatError: { code: heartbeatError.code, name: heartbeatError.name } } : {}),
    ...(childError ? { [pipelinePid === undefined ? 'launchError' : 'processError']:
      { code: childError.code, name: childError.name } } : {}),
  };
  try { atomicJson(path.join(params.diagnosticDir, `attempt-${params.attempt}-exit.json`), diagnostic); }
  catch (error) {
    throw new AggregateError([heartbeatError, childError, error].filter(Boolean), 'REVIEW_SUPERVISOR_DIAGNOSTIC_FAILED');
  }
}

async function observeExistingPipeline(params, pipelinePid, stopSignal) {
  while (!stopSignal.aborted && isOwnedPipeline(pipelinePid, params.runId)) {
    await writeHeartbeat({ ...params, pipelinePid, stopping: false });
    const status = reviewStatus(params.statusScript, params.cwd, params.platform, params.runId,
      params.heartbeat, params.resourceLog);
    if (status.status !== 'running') return { terminal: status };
    await new Promise((resolve) => setTimeout(resolve, SAMPLE_INTERVAL_MS));
  }
  return { terminal: false };
}

function waitForRecovery(stopSignal) {
  return new Promise((resolve) => {
    const finish = (resume) => {
      clearTimeout(timer); stopSignal.removeEventListener('abort', stop); resolve(resume);
    };
    const stop = () => finish(false);
    const timer = setTimeout(() => finish(true), 5_000);
    stopSignal.addEventListener('abort', stop, { once: true });
    if (stopSignal.aborted) stop();
  });
}

async function superviseAttempts(params, maximumRecoveries, stopSignal) {
  let mode = params.mode;
  for (let attempt = 1; attempt <= maximumRecoveries + 1; attempt += 1) {
    if (stopSignal.aborted) return 130;
    const result = await runAttempt({ ...params, mode, attempt }, stopSignal);
    if (result.stopping || stopSignal.aborted) return 130;
    const status = reviewStatus(params.statusScript, params.cwd, params.platform, params.runId,
      params.heartbeat, params.resourceLog);
    if (status.status !== 'running') return terminalExit(status);
    if (attempt > maximumRecoveries) return 75;
    mode = 'recover';
    if (!await waitForRecovery(stopSignal)) return 130;
  }
  return 75;
}

function initialMode(args, platform, runId) {
  const mode = args.get('initial-mode') ?? 'auto';
  if (!['auto', 'start', 'recover'].includes(mode)) throw new Error('REVIEW_SUPERVISOR_INITIAL_MODE_INVALID');
  if (mode !== 'auto') return mode;
  const platformConfig = optionalJson(platform);
  const eventFile = path.join(repositoryReviewRunRoot(platformConfig?.storageRoot ?? '', runId), 'events.jsonl');
  return fs.existsSync(eventFile) ? 'recover' : 'start';
}

async function main(values) {
  const args = argumentsMap(values);
  const cwd = path.resolve(required(args, 'workdir'));
  const platform = path.resolve(required(args, 'platform'));
  const graph = path.resolve(required(args, 'graph'));
  const runId = required(args, 'run-id');
  const heartbeat = path.resolve(required(args, 'heartbeat'));
  const resourceLog = path.resolve(required(args, 'resource-log'));
  const diagnosticDir = path.resolve(required(args, 'diagnostic-dir'));
  const log = path.resolve(required(args, 'log'));
  const gatewayUrl = args.get('gateway-url') ?? 'http://127.0.0.1:18789';
  const maximumRecoveries = integer(args.get('max-recoveries') ?? '5', 'MAX_RECOVERIES', 100);
  const statusScript = path.join(cwd, 'scripts', 'repository-review-status.mjs');
  const lease = acquireLease(path.resolve(args.get('lease') ?? `${heartbeat}.lease`), runId);
  const stopController = new AbortController();
  const stop = () => stopController.abort();
  process.once('SIGINT', stop); process.once('SIGTERM', stop);
  try {
    const existingHeartbeat = optionalJson(heartbeat);
    if (isOwnedPipeline(existingHeartbeat?.pipelinePid, runId)) {
      const observed = await observeExistingPipeline({ cwd, platform, runId, heartbeat, resourceLog,
        statusScript, gatewayUrl, attempt: existingHeartbeat.attempt ?? 0, mode: 'adopted' },
      existingHeartbeat.pipelinePid, stopController.signal);
      if (observed.terminal) return terminalExit(observed.terminal);
    }
    if (stopController.signal.aborted) return 130;
    const initialStatus = reviewStatus(statusScript, cwd, platform, runId, heartbeat, resourceLog);
    if (initialStatus.status !== 'running') return terminalExit(initialStatus);
    const mode = initialMode(args, platform, runId);
    if (mode === 'start') runPreflight(args, cwd);
    return await superviseAttempts({ cwd, platform, graph, runId, heartbeat, resourceLog,
      diagnosticDir, log, gatewayUrl, mode, statusScript }, maximumRecoveries, stopController.signal);
  } finally {
    process.off('SIGINT', stop); process.off('SIGTERM', stop); releaseLease(lease);
  }
}

scripts/lib/repository-review-supervisor.syntax:
function appendJsonLine(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.appendFileSync(file, `${JSON.stringify(value)}\n`, { mode: 0o600 });
}

function optionalResource(file, parse, observationErrors) {
  try {
    return parse(fs.readFileSync(file, 'utf8'));
  } catch (error) {
    observationErrors.push({ file, error: error.code ?? error.name });
    return undefined;
  }
}

function readNumber(file, observationErrors) {
  return optionalResource(file, text => {
    const value = text.trim();
    return value === 'max' ? value : Number(value);
  }, observationErrors);
}

function readKeyValues(file, observationErrors) {
  return optionalResource(file, text => Object.fromEntries(text.trim().split('\n').filter(Boolean)
    .map((line) => line.trim().split(/\s+/u)).map(([key, value]) => [key, Number(value)])), observationErrors);
}

function processRssBytes(pid, observationErrors) {
  return optionalResource(`/proc/${pid}/status`, text => {
    const match = text.match(/^VmRSS:\s+(\d+)\s+kB$/mu);
    return match ? Number(match[1]) * 1024 : undefined;
  }, observationErrors);
}

async function gatewayHealth(gatewayUrl) {
  try {
    const response = await fetch(new URL('/healthz', gatewayUrl), { signal: AbortSignal.timeout(2_000) });
    return { healthy: response.ok, status: response.status };
  } catch (error) {
    return { healthy: false, error: error instanceof Error ? error.name : 'unknown' };
  }
}

async function resourceSample(pipelinePid, gatewayUrl) {
  const observationErrors = [];
  return {
    schemaVersion: 'repository-review-resource-sample.v1',
    observedAt: new Date().toISOString(), pipelinePid,
    pipelineAlive: processAlive(pipelinePid), pipelineRssBytes: processRssBytes(pipelinePid, observationErrors),
    memoryCurrentBytes: readNumber('/sys/fs/cgroup/memory.current', observationErrors),
    memoryPeakBytes: readNumber('/sys/fs/cgroup/memory.peak', observationErrors),
    memoryEvents: readKeyValues('/sys/fs/cgroup/memory.events', observationErrors),
    cpu: readKeyValues('/sys/fs/cgroup/cpu.stat', observationErrors),
    observationErrors,
    gateway: await gatewayHealth(gatewayUrl),
  };
}

export async function writeHeartbeat(params) {
  const sample = await resourceSample(params.pipelinePid, params.gatewayUrl);
  appendJsonLine(params.resourceLog, sample);
  atomicJson(params.heartbeat, { schemaVersion: 'repository-review-supervisor-heartbeat.v1',
    updatedAt: sample.observedAt, supervisorPid: process.pid, pipelinePid: params.pipelinePid,
    processAlive: sample.pipelineAlive && !params.stopping, attempt: params.attempt,
    mode: params.mode, gateway: sample.gateway });
  return sample;
}

export function atomicJson(file, value) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const temporary = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(temporary, `${JSON.stringify(value)}\n`, { mode: 0o600 });
  fs.renameSync(temporary, file);
}

export function optionalJson(file) {
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); }
  catch (cause) {
    if (cause.code === 'ENOENT') return undefined;
    throw new Error(`REVIEW_SUPERVISOR_JSON_READ_FAILED:${file}`, { cause });
  }
}

export function processAlive(pid) {
  if (!Number.isSafeInteger(pid) || pid < 1) return false;
  try { process.kill(pid, 0); return true; }
  catch (error) {
    if (error.code === 'ESRCH') return false;
    if (error.code === 'EPERM') return true;
    throw error;
  }
}

export function acquireLease(file, runId) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  return leaseMutex(file).withLock(() => replaceLease(file, runId));
}

function leaseMutex(file) {
  return new FileMutex(`${file}.lock`, 1000, 'REVIEW_SUPERVISOR_LEASE_BUSY');
}

function replaceLease(file, runId) {
  const existing = optionalJson(file);
  if (existing !== undefined && (existing?.schemaVersion !== 'repository-review-supervisor-lease.v1'
    || typeof existing.instanceId !== 'string' || !existing.instanceId
    || typeof existing.runId !== 'string' || !existing.runId
    || !Number.isSafeInteger(existing.supervisorPid) || existing.supervisorPid < 1)) {
    throw new Error(`REVIEW_SUPERVISOR_LEASE_INVALID:${file}`);
  }
  if (existing && processAlive(existing.supervisorPid)) {
    throw new Error(`REVIEW_SUPERVISOR_ALREADY_ACTIVE:${existing.supervisorPid}`);
  }
  const instanceId = crypto.randomUUID();
  atomicJson(file, { schemaVersion: 'repository-review-supervisor-lease.v1',
    instanceId, runId, supervisorPid: process.pid, acquiredAt: new Date().toISOString() });
  return { file, instanceId };
}

export function releaseLease(lease) {
  leaseMutex(lease.file).withLock(() => {
    const current = optionalJson(lease.file);
    if (current?.instanceId === lease.instanceId) fs.unlinkSync(lease.file);
  });
}

scripts/native-worker-deployment-preflig.syntax:
export function nativePrismDeploymentSelection(documents, namespace, policy) {
  const workload = name => documents.find(document => document?.kind === 'Deployment' && document.metadata.name === `prism-${name}`);
  const worker = workload('worker'); const control = workload('control');
  if (!worker || !control) throw new Error('NATIVE_DEPLOYMENT_WORKLOADS_REQUIRED');
  const container = (workload, name) => workload?.spec.template.spec.containers.find(container => container.name === name);
  const supervisor = container(worker, 'worker');
  if (JSON.stringify(supervisor?.command) !== JSON.stringify(['node', 'skills/prism/server/worker.ts'])
    || worker.spec.template.metadata.annotations?.['kubeclaw.dev/native-worker-role'] !== 'prism') {
    throw new Error('NATIVE_DEPLOYMENT_PROTOCOL_MISMATCH');
  }
  const digest = value => value?.env?.find(item => item.name === 'PRISM_ENGINE_CONTENT_DIGEST')?.value;
  if (!/^sha256:[a-f0-9]{64}$/.test(digest(supervisor) ?? '')
    || digest(supervisor) !== digest(container(control, 'control'))
    || digest(supervisor) !== supervisor.image.split('@')[1]) throw new Error('NATIVE_DEPLOYMENT_IMAGE_MISMATCH');
  const pool = nativePoolPolicy(policy, 'prism');
  if (namespace !== policy.pools.prism.namespace || worker.spec.replicas !== 1
    || worker.spec.template.metadata.annotations?.['kubeclaw.dev/native-worker-policy'] !== pool.policyDigest) {
    throw new Error('NATIVE_DEPLOYMENT_POLICY_MISMATCH');
  }
  const terms = worker.spec.template.spec.affinity?.nodeAffinity?.requiredDuringSchedulingIgnoredDuringExecution?.nodeSelectorTerms;
  const expected = [{ matchFields: [{ key: 'metadata.name', operator: 'In', values: [policy.nodeName] }] }];
  if (JSON.stringify(terms) !== JSON.stringify(expected)) throw new Error('NATIVE_DEPLOYMENT_NODE_MISMATCH');
  return true;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [policyFile, namespace, ...helmArguments] = process.argv.slice(2);
  if (!policyFile || !namespace || helmArguments[0] !== 'template') throw new Error('Usage: native-worker-deployment-preflight.mjs POLICY_YAML NAMESPACE template HELM_ARGUMENTS');
  const documents = loadAll(execFileSync('helm', helmArguments, { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 }));
  const policy = loadNativeNodePolicy(policyFile);
  nativePrismDeploymentSelection(documents, namespace, policy);
  preflightNativeWorkerNode(policy);
}

scripts/native-worker-node-preflight.mjs.syntax:
function kubectl(arguments_) {
  return JSON.parse(execFileSync('kubectl', arguments_, { encoding: 'utf8', timeout: 30000,
    maxBuffer: 8 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] }));
}

function hostIdentity() {
  const podRoot = '/sys/fs/cgroup/kubepods.slice';
  if (fs.statfsSync(podRoot).type !== 0x63677270) throw new Error('NATIVE_NODE_POD_CGROUP_REQUIRED');
  return { machineId: fs.readFileSync('/etc/machine-id', 'utf8').trim(),
    bootId: fs.readFileSync('/proc/sys/kernel/random/boot_id', 'utf8').trim(),
    pidMax: fs.readFileSync('/proc/sys/kernel/pid_max', 'utf8').trim(),
    threadsMax: fs.readFileSync('/proc/sys/kernel/threads-max', 'utf8').trim(),
    podTasksMax: fs.readFileSync(`${podRoot}/pids.max`, 'utf8').trim() };
}

export function preflightNativeWorkerNode(policy) {
  policy = validateNativeNodePolicy(policy);
  const host = hostIdentity();
  const node = kubectl(['get', 'node', policy.nodeName, '-o', 'json']);
  const kubelet = kubectl(['get', '--raw', `/api/v1/nodes/${encodeURIComponent(policy.nodeName)}/proxy/configz`]).kubeletconfig;
  const result = requireNativeNodeCapacity(policy, node, kubelet, host);
  for (const role of ['buster', 'prism']) {
    const pool = nativePoolPolicy(policy, role);
    const installed = readNativeWorkerPoolPolicy(`/etc/kubeclaw/${role}-pool.json`, role);
    if (!isDeepStrictEqual(pool, installed)) throw new Error('NATIVE_NODE_INSTALLED_POLICY_MISMATCH');
    requireNativeWorkerRuntimeIdentity(pool.runtimeIdentityFile);
    new NativeWorkerResourcePool(pool.cgroupRoot, pool.limits, pool.maximumActiveScopes).verify();
  }
  const after = kubectl(['get', 'node', policy.nodeName, '-o', 'json']);
  if (after.metadata.resourceVersion !== node.metadata.resourceVersion) throw new Error('NATIVE_NODE_CHANGED_DURING_PREFLIGHT');
  const current = kubectl(['get', '--raw', `/api/v1/nodes/${encodeURIComponent(policy.nodeName)}/proxy/configz`]).kubeletconfig;
  if (!isDeepStrictEqual(current, kubelet)) throw new Error('NATIVE_NODE_KUBELET_CHANGED_DURING_PREFLIGHT');
  if (!isDeepStrictEqual(hostIdentity(), host)) throw new Error('NATIVE_NODE_HOST_CHANGED_DURING_PREFLIGHT');
  return { ...result, policyDigest: nativePoolPolicy(policy, 'buster').policyDigest, checkedAt: new Date().toISOString() };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 3) throw new Error('Usage: native-worker-node-preflight.mjs POLICY_YAML');
  process.stdout.write(`${JSON.stringify(preflightNativeWorkerNode(loadNativeNodePolicy(process.argv[2])), null, 2)}\n`);
}

