export interface WorkerOwnershipState {
  schemaVersion: 'worker-ownership-store.v2';
  hostIdentity: string | null;
  records: WorkerOwnershipRecord[];
}

export const transitions: Record<WorkerOwnershipPhase, readonly WorkerOwnershipPhase[]> = {
  reserved: ['allocated', 'unresolved', 'abandoned'],
  allocated: ['running', 'quiescing', 'unresolved', 'abandoned'],
  running: ['quiescing', 'unresolved', 'abandoned'],
  quiescing: ['empty', 'unresolved', 'abandoned'],
  empty: ['empty', 'disposed', 'unresolved', 'abandoned'],
  disposed: [],
  unresolved: ['quiescing', 'abandoned'],
  abandoned: [],
};

export function exact(value: unknown, keys: readonly string[]): asserts value is Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)
    || Object.keys(value).length !== keys.length || keys.some(key => !Object.hasOwn(value, key))) {
    throw new Error('WORKER_OWNERSHIP_RECORD_INVALID');
  }
}

export function identityValid(identity: unknown): asserts identity is WorkerOwnershipIdentity {
  exact(identity, ['workerId', 'attemptId', 'claimId', 'generation', 'profileDigest', 'attemptSpecDigest']);
  for (const key of ['workerId', 'attemptId', 'claimId']) {
    const value = identity[key];
    if (typeof value !== 'string' || value.length < 1 || value.length > 512 || value !== value.toWellFormed()) {
      throw new Error('WORKER_OWNERSHIP_IDENTITY_INVALID');
    }
  }
  if (!Number.isSafeInteger(identity.generation) || Number(identity.generation) < 1) {
    throw new Error('WORKER_OWNERSHIP_GENERATION_INVALID');
  }
  for (const key of ['profileDigest', 'attemptSpecDigest']) {
    if (typeof identity[key] !== 'string' || !/^sha256:[a-f0-9]{64}$/u.test(identity[key])) {
      throw new Error('WORKER_OWNERSHIP_DIGEST_INVALID');
    }
  }
}

function bindingValid(binding: unknown, scopeName: string): asserts binding is WorkerScopeBinding {
  exact(binding, ['scopeName', 'bootId', 'device', 'inode']);
  if (binding.scopeName !== scopeName || typeof binding.bootId !== 'string'
    || !/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/u.test(binding.bootId)
    || !Number.isSafeInteger(binding.device) || Number(binding.device) < 0
    || !Number.isSafeInteger(binding.inode) || Number(binding.inode) < 1) {
    throw new Error('WORKER_OWNERSHIP_BINDING_INVALID');
  }
}

export function validateRecord(record: unknown): asserts record is WorkerOwnershipRecord {
  exact(record, ['identity', 'scopeName', 'revision', 'phase', 'binding', 'diagnosis', 'finalObservation']);
  identityValid(record.identity);
  if (typeof record.scopeName !== 'string' || !/^worker-[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/u.test(record.scopeName)
    || !Number.isSafeInteger(record.revision) || Number(record.revision) < 1
    || typeof record.phase !== 'string' || !Object.hasOwn(transitions, record.phase)) {
    throw new Error('WORKER_OWNERSHIP_RECORD_INVALID');
  }
  validateRecordBinding(record);
  validateDiagnosis(record);
  if (record.finalObservation !== null) {
    validateNativeWorkerResourceObservation(record.finalObservation);
    if (record.finalObservation.populated || !['empty', 'disposed', 'unresolved'].includes(String(record.phase))) {
      throw new Error('WORKER_OWNERSHIP_FINAL_OBSERVATION_INVALID');
    }
  }
}

function validateRecordBinding(record: Record<string, unknown>): void {
  if (record.binding !== null) bindingValid(record.binding, String(record.scopeName));
  if (!['reserved', 'unresolved', 'abandoned'].includes(String(record.phase)) && record.binding === null) {
    throw new Error('WORKER_OWNERSHIP_BINDING_REQUIRED');
  }
  if (record.phase === 'reserved' && record.binding !== null) throw new Error('WORKER_OWNERSHIP_RESERVED_BINDING');
}

function validateDiagnosis(record: Record<string, unknown>): void {
  if (record.diagnosis !== null && (typeof record.diagnosis !== 'string' || record.diagnosis.length < 1
    || record.diagnosis.length > 4096)) throw new Error('WORKER_OWNERSHIP_DIAGNOSIS_INVALID');
  if (['unresolved', 'abandoned'].includes(String(record.phase)) && record.diagnosis === null) throw new Error('WORKER_OWNERSHIP_DIAGNOSIS_REQUIRED');
}

export function key(identity: WorkerOwnershipIdentity): string {
  return sha256Digest([identity.workerId, identity.attemptId, identity.generation]);
}

export function decodeOwnershipState(value: unknown, maximumRecords: number): WorkerOwnershipState {
  const { records, hostIdentity } = statePayload(value);
  if (records.length > maximumRecords) throw new Error('WORKER_OWNERSHIP_CAPACITY_EXCEEDED');
  const keys = new Set<string>();
  const scopes = new Set<string>();
  for (const record of records) {
    validateRecord(record);
    const identityKey = key(record.identity);
    if (keys.has(identityKey) || scopes.has(record.scopeName)) throw new Error('WORKER_OWNERSHIP_DUPLICATE');
    keys.add(identityKey); scopes.add(record.scopeName);
  }
  return { schemaVersion: 'worker-ownership-store.v2', hostIdentity, records } as WorkerOwnershipState;
}

function statePayload(value: unknown) {
  const legacy = typeof value === 'object' && value !== null && 'schemaVersion' in value && value.schemaVersion === 'worker-ownership-store.v1';
  exact(value, legacy ? ['schemaVersion', 'records'] : ['schemaVersion', 'hostIdentity', 'records']);
  if (!['worker-ownership-store.v1', 'worker-ownership-store.v2'].includes(String(value.schemaVersion)) || !Array.isArray(value.records)) {
    throw new Error('WORKER_OWNERSHIP_STORE_INVALID');
  }
  const records = legacy ? value.records.map(record => {
    exact(record, ['identity', 'scopeName', 'revision', 'phase', 'binding', 'diagnosis']);
    return { ...record, finalObservation: null };
  }) : value.records;
  const hostIdentity = legacy ? null : value.hostIdentity;
  if (hostIdentity !== null && (typeof hostIdentity !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9:._-]{0,255}$/u.test(hostIdentity))) {
    throw new Error('WORKER_OWNERSHIP_HOST_IDENTITY_INVALID');
  }
  return { records, hostIdentity };
}

skills/worker/core/worker/resource-reser.syntax:
export class NativeWorkerCapacityExceeded extends Error {
  constructor() { super('WORKER_NATIVE_CAPACITY_EXCEEDED'); }
}

function positive(value: number): void {
  if (!Number.isSafeInteger(value) || value < 1) throw new Error('WORKER_NATIVE_CAPACITY_INVALID');
}

export class WorkerResourceReservations {
  readonly #maximum: NativeWorkerScopeLimits;
  readonly #maximumScopes: number;
  #memoryBytes = 0;
  #tasks = 0;
  #scopes = 0;

  constructor(maximum: NativeWorkerScopeLimits, maximumScopes: number) {
    positive(maximum.memoryBytes); positive(maximum.tasks); positive(maximumScopes);
    this.#maximum = Object.freeze({ ...maximum });
    this.#maximumScopes = maximumScopes;
  }

  reserve(limits: NativeWorkerScopeLimits): () => void {
    const { memoryBytes, tasks } = limits;
    positive(memoryBytes); positive(tasks);
    if (this.#scopes >= this.#maximumScopes || memoryBytes > this.#maximum.memoryBytes - this.#memoryBytes
      || tasks > this.#maximum.tasks - this.#tasks) throw new NativeWorkerCapacityExceeded();
    this.#memoryBytes += memoryBytes; this.#tasks += tasks; this.#scopes++;
    let released = false;
    return () => {
      if (released) return;
      released = true;
      this.#memoryBytes -= memoryBytes; this.#tasks -= tasks; this.#scopes--;
    };
  }
}

skills/worker/core/worker/native-pool-po.syntax:
export interface NativeWorkerPoolPolicy {
  readonly schemaVersion: 1;
  readonly role: string;
  readonly nodeName: string;
  readonly policyDigest: string;
  readonly cgroupRoot: string;
  readonly ownershipRoot: string;
  readonly nodeIdentityFile: string;
  readonly runtimeIdentityFile: string;
  readonly maximumActiveScopes: number;
  readonly limits: NativeWorkerPoolLimits;
}

export function readNativeWorkerPoolPolicy(file: string, role: string): NativeWorkerPoolPolicy {
  if (!path.isAbsolute(file)) throw new Error('WORKER_NATIVE_POOL_POLICY_PATH_REQUIRED');
  const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK);
  try {
    const stat = fs.fstatSync(fd);
    if (!stat.isFile() || stat.uid !== 0 || (stat.mode & 0o022) !== 0 || stat.size < 1 || stat.size > 65536) {
      throw new Error('WORKER_NATIVE_POOL_POLICY_NOT_TRUSTED');
    }
    const value = JSON.parse(fs.readFileSync(fd, 'utf8')) as NativeWorkerPoolPolicy;
    validate(value, role);
    return Object.freeze({ ...value, limits: Object.freeze({ ...value.limits }) });
  } finally { fs.closeSync(fd); }
}

function validate(value: NativeWorkerPoolPolicy, role: string): void {
  if (value?.schemaVersion !== 1 || value.role !== role || typeof value.nodeName !== 'string' || !value.nodeName
    || typeof value.policyDigest !== 'string' || !/^[a-f0-9]{64}$/u.test(value.policyDigest)) throw new Error('WORKER_NATIVE_POOL_POLICY_INVALID');
  validatePaths(value);
  validateLimits(value);
}

function validatePaths(value: NativeWorkerPoolPolicy): void {
  for (const location of [value.cgroupRoot, value.ownershipRoot, value.nodeIdentityFile, value.runtimeIdentityFile]) {
    if (typeof location !== 'string' || !path.isAbsolute(location) || location === '/' || path.resolve(location) !== location) {
      throw new Error('WORKER_NATIVE_POOL_POLICY_PATH_INVALID');
    }
  }
}

function validateLimits(value: NativeWorkerPoolPolicy): void {
  for (const number of [value.maximumActiveScopes, value.limits?.memoryBytes, value.limits?.tasks,
    value.limits?.cpuQuotaMicroseconds, value.limits?.cpuPeriodMicroseconds]) {
    if (!Number.isSafeInteger(number) || number < 1) throw new Error('WORKER_NATIVE_POOL_POLICY_LIMIT_INVALID');
  }
}

skills/worker/core/worker/native-runtime.syntax:
interface RuntimeIdentity {
  schemaVersion: 1;
  bootId: string;
  cgroupNamespace: { device: string; inode: string };
}

export function requireNativeWorkerRuntimeIdentity(file: string): void {
  if (!path.isAbsolute(file)) throw new Error('WORKER_NATIVE_RUNTIME_IDENTITY_PATH_REQUIRED');
  const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW | fs.constants.O_NONBLOCK);
  try {
    const stat = fs.fstatSync(fd);
    if (!stat.isFile() || stat.uid !== 0 || (stat.mode & 0o022) !== 0 || stat.size < 1 || stat.size > 4096) {
      throw new Error('WORKER_NATIVE_RUNTIME_IDENTITY_NOT_TRUSTED');
    }
    const identity = JSON.parse(fs.readFileSync(fd, 'utf8')) as RuntimeIdentity;
    const bootId = fs.readFileSync('/proc/sys/kernel/random/boot_id', 'utf8').trim();
    const namespace = fs.statSync('/proc/self/ns/cgroup', { bigint: true });
    if (identity?.schemaVersion !== 1 || identity.bootId !== bootId
      || identity.cgroupNamespace?.device !== String(namespace.dev)
      || identity.cgroupNamespace?.inode !== String(namespace.ino)) {
      throw new Error('WORKER_NATIVE_HOST_CGROUP_NAMESPACE_REQUIRED');
    }
  } finally { fs.closeSync(fd); }
}

scripts/native-worker-node-capacity.mjs.syntax:
export function nativeNodeQuantity(value, scale = 1n) {
  if (typeof value !== 'string' || value.length > 80) throw new Error('NATIVE_NODE_QUANTITY_INVALID');
  const match = /^(\d+)(?:\.(\d+))?([a-zA-Z]*)$/.exec(value);
  if (!match || !Object.hasOwn(suffixes, match[3])) throw new Error('NATIVE_NODE_QUANTITY_INVALID');
  const fraction = match[2] ?? '';
  const [numerator, denominator] = suffixes[match[3]];
  const amount = BigInt(match[1] + fraction) * numerator * scale;
  const divisor = denominator * 10n ** BigInt(fraction.length);
  if (amount % divisor !== 0n) throw new Error('NATIVE_NODE_QUANTITY_PRECISION_UNSUPPORTED');
  return amount / divisor;
}

function minimum(actual, expected, resource) {
  const scale = resource === 'cpu' ? 1000000000n : 1n;
  if (nativeNodeQuantity(actual, scale) < nativeNodeQuantity(expected, scale)) throw new Error(`NATIVE_NODE_RESERVATION_INSUFFICIENT:${resource}`);
}

function taskCapacity(reservation, kubelet, host) {
  minimum(kubelet.systemReserved?.pid, reservation.systemReserved.pid, 'pid');
  minimum(kubelet.kubeReserved?.pid, reservation.kubeReserved.pid, 'pid');
  if (kubelet.cgroupRoot && kubelet.cgroupRoot !== '/') throw new Error('NATIVE_NODE_POD_CGROUP_LAYOUT_UNSUPPORTED');
  const pidMax = nativeNodeQuantity(host.pidMax); const threadsMax = nativeNodeQuantity(host.threadsMax);
  const capacity = pidMax < threadsMax ? pidMax : threadsMax;
  const withheld = nativeNodeQuantity(reservation.systemReserved.pid) + nativeNodeQuantity(reservation.kubeReserved.pid);
  const podMaximum = nativeNodeQuantity(host.podTasksMax);
  if (capacity <= withheld || podMaximum <= 0n || podMaximum > capacity - withheld) throw new Error('NATIVE_NODE_POD_TASKS_NOT_RESERVED');
}

function hostBinding(policy, node, hostIdentity) {
  if (node?.metadata?.name !== policy.nodeName || typeof node.metadata.uid !== 'string'
    || node.status?.nodeInfo?.machineID !== hostIdentity.machineId || node.status.nodeInfo.bootID !== hostIdentity.bootId) throw new Error('NATIVE_NODE_HOST_BINDING_MISMATCH');
  if (!hostIdentity.machineId || !hostIdentity.bootId) throw new Error('NATIVE_NODE_HOST_IDENTITY_REQUIRED');
  if (!node.status.conditions?.some(condition => condition.type === 'Ready' && condition.status === 'True')) throw new Error('NATIVE_NODE_NOT_READY');
  runtimeBinding(policy, node);
}

function runtimeBinding(policy, node) {
  const runtime = policy.runtime?.containerdVersion;
  const actual = node.status.nodeInfo.containerRuntimeVersion;
  if (typeof runtime !== 'string' || typeof actual !== 'string' || !actual.startsWith('containerd://')
    || actual.slice('containerd://'.length).replace(/^v/, '') !== runtime.replace(/^v/, '')) {
    throw new Error('NATIVE_NODE_CONTAINERD_VERSION_MISMATCH');
  }
}

export function requireNativeNodeCapacity(policy, node, kubelet, hostIdentity) {
  validateNativeNodePolicy(policy);
  hostBinding(policy, node, hostIdentity);
  if (kubelet?.cgroupDriver !== 'systemd' || kubelet.cgroupsPerQOS !== true
    || !kubelet.enforceNodeAllocatable?.includes('pods')) throw new Error('NATIVE_NODE_KUBELET_ACCOUNTING_REQUIRED');
  const reservation = nativeNodeReservation(policy);
  taskCapacity(reservation, kubelet, hostIdentity);
  for (const resource of ['cpu', 'memory']) {
    minimum(kubelet.systemReserved?.[resource], reservation.systemReserved[resource], resource);
    minimum(kubelet.kubeReserved?.[resource], reservation.kubeReserved[resource], resource);
    const scale = resource === 'cpu' ? 1000000000n : 1n;
    const capacity = nativeNodeQuantity(node.status.capacity?.[resource], scale);
    const allocatable = nativeNodeQuantity(node.status.allocatable?.[resource], scale);
    const withheld = nativeNodeQuantity(reservation.systemReserved[resource], scale) + nativeNodeQuantity(reservation.kubeReserved[resource], scale);
    if (capacity <= withheld || allocatable <= 0n || allocatable > capacity - withheld) throw new Error(`NATIVE_NODE_ALLOCATABLE_NOT_RESERVED:${resource}`);
  }
  return { nodeName: node.metadata.name, nodeUid: node.metadata.uid, machineId: hostIdentity.machineId, bootId: hostIdentity.bootId,
    scope: 'current-node-cpu-memory-task-reservation-only', reservation };
}

scripts/gitops-owner.mjs.syntax:
export function claimedNamespaces(application) {
  const annotation = application.metadata?.annotations?.['kubeclaw.dev/runtime-namespaces'];
  const declared = annotation === undefined ? [] : JSON.parse(annotation);
  if (!Array.isArray(declared) || !declared.every(gitOpsName)) throw new Error('GITOPS_OWNERSHIP_ANNOTATION_INVALID');
  return [...declared, application.spec?.destination?.namespace];
}

export function assertNoGitOpsOwner(namespace, _release, run = args => execFileSync('kubectl', args, { encoding: 'utf8', timeout: 30000 })) {
  if (!gitOpsName(namespace)) throw new Error('GITOPS_OWNERSHIP_ARGUMENT_INVALID');
  const crd = run(['get', 'crd', 'applications.argoproj.io', '--ignore-not-found', '-o', 'json']);
  const applications = crd.trim()
    ? JSON.parse(run(['get', 'applications.argoproj.io', '--all-namespaces', '-o', 'json'])) : { items: [] };
  if (!Array.isArray(applications.items)) throw new Error('GITOPS_OWNERSHIP_RESPONSE_INVALID');
  const owner = applications.items.find(application => claimedNamespaces(application).includes(namespace));
  if (owner) throw new Error(`GITOPS_OWNER_PRESENT:${namespace}/${owner.metadata?.name}; update its reviewed Git revision instead`);
  // Deleting an Application without cascading its workloads does not transfer ownership.
  const workloads = JSON.parse(run(['get', 'deployments,statefulsets,cronjobs', '-n', namespace, '-o', 'json']));
  if (!Array.isArray(workloads.items)) throw new Error('GITOPS_OWNERSHIP_RESPONSE_INVALID');
  if (workloads.items.some(workload => workload.metadata?.annotations?.['argocd.argoproj.io/tracking-id']
    || workload.metadata?.labels?.['kubeclaw.dev/gitops-owner'])) throw new Error(`GITOPS_RETAINED_RESOURCE_OWNER:${namespace}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { assertNoGitOpsOwner(...process.argv.slice(2)); }
  catch (error) { process.stderr.write(`${error.message}\n`); process.exitCode = 1; }
}

