    return [...records.filter(record=>record.kind!==kind || /^\$\.(metadata(?:\.|\[|$)|apiVersion$|kind$)/.test(record.fieldPath)), ...namespaceIsolationReceiverContracts(apiVersion,kind,selectedPaths)];
