};

for (const [name, object] of [['infra-project', project], ['data-project', dataProject], ['argocd', application], ['tailscale-operator', tailscale], ['codex-ops', ops], ['redis', redis], ['postgresql', postgresql], ['registry-mirror', registryMirror], ['registry-local', registryLocal], ['monitoring-project', monitoringProject], ...monitoringApplications.map(app => [app.metadata.name, app]), ...extraServices.map(object => [object.metadata.name + (object.kind === 'AppProject' ? '-project' : ''), object]), ['../platform', platform]]) {
  const file = path.join(directory, `${name}.yaml`);
  const content = '# Generated by node scripts/argocd-self-management.mjs\n' + yaml.dump(object, { lineWidth: -1, noRefs: true });
  if (process.argv.includes('--check')) {
    if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== content) throw new Error(`Generated Argo manifest differs: ${file}`);
  } else {
    fs.mkdirSync(directory, { recursive: true });
    fs.writeFileSync(file, content);
  }
}

