const reference = name => {
  const image = release.images[name];
  if (typeof image !== 'string' || !/^ghcr\.io\/[a-z0-9_-]+\/kubeclaw-[a-z0-9-]+@sha256:[a-f0-9]{64}$/.test(image)) throw new Error(`Missing immutable image: ${name}`);
  return image;
};

function bindSidecarImages(values) {
  for (const container of values.extraContainers ?? []) {
    const name = container.image?.match(/\/kubeclaw-([^:@]+)(?::|@)/)?.[1];
    if (name) container.image = reference(name);
  }
}

for (const role of family === 'ops' ? ['ops'] : ['nova', 'buster', 'prism-agent', 'prism']) {
  const values = role === 'ops' ? {} : yaml.load(fs.readFileSync(`my-values/${role}-values.yaml`, 'utf8'));
  if (role === 'ops') { values.codexImage = reference('codex-ops'); values.mcpImage = reference('ops-mcp'); }
  else if (role === 'prism') {
    for (const service of ['control', 'studio', 'worker', 'ingestion']) { const image = object(`prism-${service}`); delete image.tag; values.images[service] = image; }
  } else {
    values.image = object(role === 'buster' ? 'buster-gateway' : role);
    bindSidecarImages(values);
    if (values.busterNamespaceBroker?.controller?.image) values.busterNamespaceBroker.controller.image = object('namespace-controller');
  }
  if (code && ['nova', 'buster', 'prism-agent'].includes(role)) {
    const bundle = code.bundles[role === 'prism-agent' ? 'prism' : role];
    values.codeBundle = { ...values.codeBundle, enabled: true, archiveUrl: bundle.url, expectedCommit: code.commit,
      sha256: bundle.sha256, contractVersion: bundle.contractVersion };
  }
  const output = `# Generated from release ${release.commit} and byte-matched source configuration; do not edit.\n${yaml.dump(values, { lineWidth: 120, noRefs: true })}`;
  const file = `releases/values/${role}.yaml`;
  if (process.argv.includes('--check')) { if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== output) throw new Error(`Release values drift: ${file}`); }
  else fs.writeFileSync(file, output);
}

scripts/updates/release-configuration.mj.syntax:
function filesUnder(root, relative) {
  const stat = fs.lstatSync(path.join(root, relative));
  if (stat.isSymbolicLink()) throw new Error(`RELEASE_CONFIGURATION_SYMLINK: ${relative}`);
  if (stat.isFile()) return [relative];
  if (!stat.isDirectory()) throw new Error(`RELEASE_CONFIGURATION_FILE_REQUIRED: ${relative}`);
  return fs.readdirSync(path.join(root, relative)).flatMap(name => filesUnder(root, `${relative}/${name}`));
}

export function verifyReleaseConfiguration(root, commit, family) {
  if (!/^[a-f0-9]{40}$/u.test(commit) || !configurationPaths[family]) throw new Error('RELEASE_CONFIGURATION_IDENTITY_INVALID');
  const git = args => execFileSync('git', ['-C', root, ...args], { encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 });
  const top = git(['rev-parse', '--show-toplevel']).trim();
  if (fs.realpathSync(top) !== fs.realpathSync(root)) throw new Error('RELEASE_CONFIGURATION_REPOSITORY_ROOT_REQUIRED');
  const entries = git(['ls-tree', '-rz', commit, '--', ...configurationPaths[family]])
    .split('\0').filter(Boolean).map(record => {
      const separator = record.indexOf('\t');
      const [mode, type, digest] = record.slice(0, separator).split(' ');
      const name = record.slice(separator + 1);
      if (type !== 'blob' || !['100644', '100755'].includes(mode)) throw new Error(`RELEASE_CONFIGURATION_SOURCE_FILE_INVALID: ${name}`);
      return { name, digest };
    });
  const names = configurationPaths[family].flatMap(relative => filesUnder(root, relative)).sort();
  const expected = entries.map(entry => entry.name).sort();
  if (JSON.stringify(names) !== JSON.stringify(expected)) throw new Error('RELEASE_CONFIGURATION_FILESET_CHANGED');
  for (const { name, digest } of entries) {
    const actual = git(['hash-object', '--no-filters', '--', name]).trim();
    if (actual !== digest) throw new Error(`RELEASE_CONFIGURATION_CHANGED: ${name}; select a successful image build using this configuration`);
  }
  return { sourceCommit: commit, paths: configurationPaths[family] };
}

scripts/check-cni-portability.mjs.syntax:
function render(name, chart, values = [], stringSets = [], typedSets = []) {
  const args = ['template', name, chart];
  for (const value of values) args.push('-f', value);
  for (const setting of stringSets) args.push('--set-string', setting);
  for (const setting of typedSets) args.push('--set', setting);
  return execFileSync('helm', args, {
    cwd: root,
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
}

function documents(source) {
  return source.split(/(?=^---\s*$)/gmu).flatMap((chunk) => {
    const document = YAML.parseDocument(chunk);
    if (document.errors.length > 0 || !document.toJSON()) return [];
    return [document.toJSON()];
  });
}

function walk(directory) {
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const target = path.join(directory, entry.name);
    return entry.isDirectory() ? walk(target) : entry.isFile() ? [target] : [];
  });
}

const renders = [
  ['nova-core', render('agent-nova', 'charts/kubeclaw', ['my-values/nova-values.yaml'], [], [
    'archviewer.enabled=false',
  ])],
  ['buster', render('agent-buster', 'charts/kubeclaw', ['my-values/buster-values.yaml'], [
    'runtimeInfrastructure.registry.endpoint=http://registry-local.kubeclaw.svc.cluster.local:5001',
    'runtimeInfrastructure.registry.transport=http-lab',
  ])],
  ['prism-agent', render('agent-prism', 'charts/kubeclaw', ['my-values/prism-agent-values.yaml'])],
  ['prism', render('prism', 'charts/prism', ['my-values/prism-values.yaml'], [
    'worker.native.namespace=kubeclaw',
    'worker.native.nodeName=cni-portability-node',
    `worker.native.policyDigest=${'a'.repeat(64)}`,
  ])],
];

for (const [profile, source] of renders) {
  const resources = documents(source);
  const ciliumResources = resources.filter((resource) =>
    forbiddenKinds.has(resource.kind) || String(resource.apiVersion ?? '').startsWith('cilium.io/'));
  assert.deepEqual(ciliumResources, [],
    `${profile} core profile renders Cilium-specific resources`);
  renderSummary.push({
    profile,
    resources: resources.length,
    networkPolicies: resources.filter((resource) => resource.kind === 'NetworkPolicy').length,
  });
}

assert.deepEqual(maintainedNovaCiliumResources.map((resource) =>
  `${resource.kind}/${resource.metadata?.name}`).sort(), [
  'CiliumNetworkPolicy/agent-nova-archviewer',
], 'the maintained Nova profile gained an unclassified Cilium dependency');

for (const file of sourceFiles) {
  const source = fs.readFileSync(file, 'utf8');
  if (/cilium\.io|CiliumNetworkPolicy|CiliumClusterwideNetworkPolicy/u.test(source)) {
    ciliumBindings.push(path.relative(root, file).split(path.sep).join('/'));
  }
}

process.stdout.write(`${JSON.stringify({
  ok: true,
  proof: 'render-and-source-portability',
  liveFlannelDeploymentProved: false,
  profiles: renderSummary,
  currentProfileCiliumBoundary: {
    profile: 'nova',
    optionalComponent: 'archviewer',
    resources: maintainedNovaCiliumResources.map((resource) =>
      `${resource.kind}/${resource.metadata?.name}`),
  },
  runtimeSourceFilesChecked: sourceFiles.length,
})}\n`);

scripts/registry-client-config.mjs.syntax:
function closedObject(value,keys,label){
  if(!value || typeof value!=='object' || Array.isArray(value))throw new Error(`${label}: object required`);
  for(const key of Object.keys(value))if(!keys.includes(key))throw new Error(`${label}: unknown field ${key}`);
  if(label!=='registry clients')for(const [key,field] of Object.entries(value))if(key!=='auth' && typeof field!=='string')throw new Error(`${label}: ${key} must be a string`);
}

function contractShape(input){
  closedObject(input,['schemaVersion','registry','dockerHubMirror'],'registry clients');
  const common=['endpoint','transport','caFile','nodeCaFile','caSecretName','caSecretKey'];
  closedObject(input.registry,[...common,'auth','authSecretName','usernameKey','passwordKey'],'registry');
  if(input.registry.auth!==undefined)closedObject(input.registry.auth,['usernameEnvironmentVariable','passwordEnvironmentVariable'],'registry.auth');
  if(input.dockerHubMirror!==undefined){
    const mirror=input.dockerHubMirror;closedObject(mirror,common,'dockerHubMirror');
    if(mirror.endpoint===''){
      if(mirror.transport!=='' || ['caFile','nodeCaFile','caSecretName'].some(key=>mirror[key]!==undefined && mirror[key]!==''))throw new Error('dockerHubMirror: disabled mirror must have empty transport and trust');
    }else if(typeof mirror.endpoint!=='string' || !mirror.endpoint)throw new Error('dockerHubMirror: omit mirror or explicitly supply empty endpoint and transport to disable');
  }
}

function trust(input,label){
  for(const field of ['caFile','nodeCaFile'])if(input[field] && (!path.isAbsolute(input[field]) || /[\r\n\0]/u.test(input[field])))throw new Error(`${label}: ${field} must be an absolute file path`);
  if(input.transport==='http-lab' && (input.caFile || input.nodeCaFile))throw new Error(`${label}: HTTP lab transport cannot specify TLS trust`);
  if(Boolean(input.caFile)!==Boolean(input.nodeCaFile))throw new Error(`${label}: custom trust needs both worker caFile and nodeCaFile`);
}

function endpoint(input,label){
  if(!input || typeof input!=='object')throw new Error(`${label}: endpoint and transport must be explicitly configured`);
  if(typeof input.endpoint!=='string' || input.endpoint!==input.endpoint.trim())throw new Error(`${label}: endpoint must be an explicit unpadded origin`);
  const url=new URL(input.endpoint);
  if(!['https','http-lab'].includes(input.transport) || url.protocol!==(input.transport==='https'?'https:':'http:'))throw new Error(`${label}: transport must match endpoint scheme (https or explicit http-lab)`);
  if(url.username || url.password || url.search || url.hash || url.pathname!=='/' || !/^[a-z0-9.-]+(?::[0-9]+)?$/u.test(url.host))throw new Error(`${label}: use a registry origin without credentials, path, query or fragment`);
  trust(input,label);
  return {...input,endpoint:url.origin,host:url.host};
}

function credentialNames(registry){
  const auth=registry.auth;
  if(!auth){
    if(registry.transport==='https')throw new Error('HTTPS registry requires explicit authentication configuration');
    return undefined;
  }
  if(registry.transport!=='https')throw new Error('registry credentials require HTTPS; lab HTTP must be anonymous');
  const names=[auth.usernameEnvironmentVariable,auth.passwordEnvironmentVariable];
  if(names.some(name=>typeof name!=='string' || !/^[A-Z][A-Z0-9_]+$/u.test(name)))throw new Error('registry auth requires explicit credential environment names');
  return names;
}

function authentication(registry,environment){
  const names=credentialNames(registry);
  if(!names)return undefined;
  const [username,password]=names.map(name=>environment[name]);
  if(!username || !password)throw new Error('registry credential environment variables are missing or empty');
  return {username,password};
}

function nodeConfiguration(registry,mirror,credentials){
  const mirrors={[registry.host]:{endpoint:[registry.endpoint]}};
  if(mirror)mirrors['docker.io']={endpoint:[mirror.endpoint]};
  const configs={};
  for(const client of [registry,mirror].filter(Boolean))if(client.nodeCaFile)configs[client.host]={tls:{ca_file:client.nodeCaFile}};
  if(credentials)configs[registry.host]={...configs[registry.host],auth:credentials};
  return {mirrors,configs};
}

function buildkitConfiguration(registry,mirror){
  const toml=[];
  for(const client of [registry,mirror].filter(Boolean)){
    toml.push(`[registry.${JSON.stringify(client.host)}]`);
    if(client.transport==='http-lab')toml.push('  http = true');
    if(client.caFile)toml.push(`  ca = [${JSON.stringify(client.caFile)}]`);
  }
  if(mirror)toml.push('[registry."docker.io"]',`  mirrors = [${JSON.stringify(mirror.host)}]`);
  return toml.join('\n')+'\n';
}

function validateRouting(registry,mirror){
  if(mirror && (mirror.host==='docker.io' || registry.host==='docker.io'))throw new Error('Docker Hub mirror routing collides with a docker.io endpoint');
  if(mirror?.auth || mirror?.authSecretName)throw new Error('Docker Hub mirror credentials are not configured by this public-cache contract');
  if(mirror?.host===registry.host)throw new Error('writable registry cannot also be a pull-through mirror');
}

function clients(input){
  if(input?.schemaVersion!=='registry-clients.v1')throw new Error('registry-clients.v1 configuration is required; see docs/site/understand/platform-and-operations.md#writable-local-oci-registry');
  contractShape(input);
  const registry=endpoint(input.registry,'registry');
  const mirror=input.dockerHubMirror?.endpoint?endpoint(input.dockerHubMirror,'dockerHubMirror'):null;
  validateRouting(registry,mirror);
  return {registry,mirror};
}

export function registryClientOrigin(input){
  const {registry}=clients(input);
  credentialNames(registry);
  return registry.endpoint;
}

export function registryClientConfig(input,environment={}){
  const {registry,mirror}=clients(input);
  const auth=input.registry.auth;
  const credentials=authentication(registry,environment);
  return {buildkit:buildkitConfiguration(registry,mirror),runtime:{registryBaseUrl:registry.endpoint,registryReference:registry.host,...(registry.caFile?{registryCaFile:registry.caFile}:{}),
    ...(auth?{registryUsernameEnvironmentVariable:auth.usernameEnvironmentVariable,registryPasswordEnvironmentVariable:auth.passwordEnvironmentVariable}:{})},
    node:nodeConfiguration(registry,mirror,credentials),caFile:registry.caFile || ''};
}

export function writeRegistryClients(input,environment,outputs){
  const config=registryClientConfig(input,environment);
  for(const [kind,file] of Object.entries(outputs)){
    if(!['buildkit','runtime','node'].includes(kind))throw new Error('unknown registry output');
    fs.writeFileSync(file,kind==='buildkit'?config.buildkit:JSON.stringify(config[kind],null,2)+'\n',{mode:0o600,flag:'wx'});
  }
  return config;
}

if(process.argv[1] && import.meta.url===pathToFileURL(process.argv[1]).href){
  const [inputFile,kind,outputFile]=process.argv.slice(2);
  if(!inputFile || !['buildkit','runtime','node'].includes(kind) || !outputFile)throw new Error('Usage: registry-client-config.mjs INPUT_JSON buildkit|runtime|node OUTPUT_FILE (new file, private mode)');
  writeRegistryClients(JSON.parse(fs.readFileSync(inputFile,'utf8')),process.env,{[kind]:outputFile});
}

scripts/inspect-node-registry.mjs.syntax:
function origin(value) {
  try {
    const url = new URL(value);
    if (!['http:', 'https:'].includes(url.protocol)) return {invalid: true};
    return {scheme: url.protocol.slice(0, -1), host: url.hostname, port: url.port || null};
  } catch { return {invalid: true}; }
}

export function inspectNodeRegistry(config) {
  if (!config || typeof config !== 'object' || Array.isArray(config)) throw new Error('Registry configuration must be a mapping');
  const mirrors = Object.entries(config.mirrors || {}).map(([host, entry]) => ({
    // Registry keys are normally host:port; sanitize malformed URL keys too.
    registry: origin(`https://${host}`),
    endpoints: Array.isArray(entry?.endpoint) ? entry.endpoint.map(origin) : [],
    rewriteConfigured: Boolean(entry?.rewrite && Object.keys(entry.rewrite).length),
  }));
  const settings = Object.entries(config.configs || {}).map(([host, entry]) => ({
    registry: origin(`https://${host}`),
    authConfigured: Boolean(entry?.auth && Object.keys(entry.auth).length),
    customCA: Boolean(entry?.tls?.ca_file),
    clientCertificate: Boolean(entry?.tls?.cert_file),
    clientKey: Boolean(entry?.tls?.key_file),
    insecureSkipVerify: entry?.tls?.insecure_skip_verify === true,
  }));
  return {scope: 'k3s-registry-source-configuration-only', mirrors, settings,
    limitations: ['Effective containerd configuration, default endpoint fallback, reachability and actual CRI pulls remain unverified.',
      'A custom --private-registry location must be inspected separately. No credential values or file paths are returned.']};
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const file = '/etc/rancher/k3s/registries.yaml';
  try {
    if (!fs.existsSync(file)) console.log(JSON.stringify({scope: 'k3s-registry-source-configuration-only', defaultFilePresent: false}));
    else console.log(JSON.stringify(inspectNodeRegistry(yaml.load(fs.readFileSync(file, 'utf8')) || {}), null, 2));
  } catch {
    // YAML parser diagnostics can quote credentials from the source file.
    console.error('Registry inventory failed; source configuration could not be read or parsed. Raw diagnostics suppressed.');
    process.exitCode = 1;
  }
}

scripts/generate-local-helm-authorities..syntax:
const local = inventory.files.flatMap((file) => file.documents.flatMap((document) => document.fields
  .filter((field) => field.path !== '$'
    && ['template-render-authority', 'template-render-meaning-blocker', 'local-helm-field-authority'].includes(field.meaning?.status))
  .map((field) => ({
    sourcePath: file.path,
    sourceClass: file.sourceClass,
    ...field,
    // Runtime proofs are published as additional readers of an already known
    // value. They are not Helm binding evidence and must not enter the
    // template-proof registry on a maintenance regeneration.
    consumers: field.consumers.filter((consumer) => consumer.path.includes('/templates/')
      && /^helm-/u.test(consumer.kind ?? '')),
  }))));

const chartRootFor = (sourcePath) => {
  const declaration = approvedRegistry.files[sourcePath];
  if (declaration) return declaration.chartRoot;
  const discovered = local.find((field) => field.sourcePath === sourcePath)?.consumers[0]?.path.split('/templates/')[0];
  if (discovered) return discovered;
  if (sourcePath.startsWith('charts/')) return sourcePath.split('/').slice(0, 2).join('/');
  if (sourcePath === 'my-values/prism-values.yaml') return 'charts/prism';
  return 'charts/kubeclaw';
};

const fieldPathTokens = (value) => [...value.replace(/^\$/u, '').matchAll(/\.([^.[\]]+)|\["((?:\\.|[^"])*)"\]|\['((?:\\.|[^'])*)'\]|\[([0-9]+)\]/gu)]
  .map((match) => match[1] ?? (match[2] !== undefined ? JSON.parse(`"${match[2]}"`) : undefined)
    ?? match[3]?.replaceAll("\\'", "'").replaceAll('\\\\', '\\') ?? Number(match[4]));

const parsedSource = (sourcePath) => {
  if (!parsedSources.has(sourcePath)) parsedSources.set(sourcePath, YAML.parse(fs.readFileSync(path.join(root, sourcePath), 'utf8')));
  return parsedSources.get(sourcePath);
};

const valueAtExactPath = (value, fieldPath) => {
  return fieldPathTokens(fieldPath).reduce((current, token) => current?.[token], value);
};

const chartSchema = (chartRoot) => {
  if (chartSchemas.has(chartRoot)) return chartSchemas.get(chartRoot);
  const schemaPath = path.join(root, chartRoot, 'values.schema.json');
  const schema = fs.existsSync(schemaPath) ? JSON.parse(fs.readFileSync(schemaPath, 'utf8')) : null;
  chartSchemas.set(chartRoot, schema);
  return schema;
};

const resolveLocalSchemaReference = (rootSchema, node) => {
  let current = node;
  const visited = new Set();
  while (current?.$ref?.startsWith('#/')) {
    assert(!visited.has(current.$ref), `cyclic local schema reference ${current.$ref}`);
    visited.add(current.$ref);
    current = current.$ref.slice(2).split('/').reduce((value, token) => value?.[
      token.replaceAll('~1', '/').replaceAll('~0', '~')
    ], rootSchema);
  }
  return current;
};

const schemaAtField = (field) => {
  const schema = chartSchema(chartRootFor(field.sourcePath));
  if (!schema) return null;
  let current = resolveLocalSchemaReference(schema, schema);
  for (const token of fieldPathTokens(field.path)) {
    current = resolveLocalSchemaReference(schema,
      typeof token === 'number' ? current?.items : current?.properties?.[token]);
    if (!current) return null;
  }
  return current;
};

const booleanInputContract = (field) => {
  const schema = schemaAtField(field);
  const schemaRequiresBoolean = schema?.type === 'boolean'
    || (Array.isArray(schema?.enum) && schema.enum.length > 0 && schema.enum.every((value) => typeof value === 'boolean'));
  const classifyReceiver = (expression) => {
    if (/kindIs\s+"bool"|typeIs\s+"bool"/u.test(expression)) return 'explicit-boolean-type-guard';
    if (/\bternary\b/u.test(expression)) return 'strict-boolean-function';
    if (/\btoYaml\b|\btoJson\b/u.test(expression)) return 'structural-pass-through';
    if (/\{\{-?\s*(?:if|else\s+if|with)\b/u.test(expression)
      || /\{\{-?\s*\$[A-Za-z_][A-Za-z0-9_]*\s*:?=\s*(?:and|or|not)\b/u.test(expression)) return 'helm-truthiness';
    if (/\|\s*(?:quote|squote)\b/u.test(expression)) return 'quoted-runtime-string';
    return 'raw-scalar-pass-through';
  };
  const receiverSemantics = [...new Set(field.consumers
    .map((consumer) => classifyReceiver(consumer.templateExpression ?? '')))].sort();
  const hasTruthiness = receiverSemantics.includes('helm-truthiness');
  const hasStrictBooleanFunction = receiverSemantics.includes('strict-boolean-function');
  const hasExplicitGuard = receiverSemantics.includes('explicit-boolean-type-guard');
  const hasQuotedReceiver = receiverSemantics.includes('quoted-runtime-string');
  const hasRawReceiver = receiverSemantics.includes('raw-scalar-pass-through');
  const hasStructuralReceiver = receiverSemantics.includes('structural-pass-through');
  if (schemaRequiresBoolean) return {
    validation: 'chart-schema-boolean',
    receiverSemantics,
    emptyBehavior: 'An omitted override keeps the selected values file or chart default. An explicit empty or null value fails Helm chart-schema validation because this field must be Boolean.',
    invalidBehavior: 'Helm chart-schema validation rejects a non-Boolean value before template rendering.',
  };
  const invalidParts = ['This chart has no Boolean schema for this field.'];
  if (hasTruthiness) invalidParts.push('Helm treats every non-empty string, including the string `"false"`, as true in its condition receiver.');
  if (hasStrictBooleanFunction) invalidParts.push('Its `ternary` receiver requires a Boolean and stops rendering when it receives a string.');
  if (hasExplicitGuard) invalidParts.push('Its exact template type guard admits only a Boolean to the guarded branch.');
  if (hasQuotedReceiver) invalidParts.push('Its quoted receiver forwards text to the selected process, which owns the final parse.');
  if (hasRawReceiver) invalidParts.push('Its raw scalar receiver is parsed again as YAML or JSON, so the receiving format or API decides whether another type is accepted.');
  if (hasStructuralReceiver) invalidParts.push('Its structural receiver preserves the supplied type for the receiving API or process.');
  invalidParts.push('Use the YAML Boolean values `true` and `false`; do not quote them.');
  const emptyParts = ['An omitted override keeps the selected values file or chart default.'];
  if (hasTruthiness) emptyParts.push('Helm treats an explicit empty or null value as false in its condition receiver.');
  if (hasStrictBooleanFunction) emptyParts.push('The strict Boolean function rejects an explicit empty, null, or string value.');
  if (hasExplicitGuard) emptyParts.push('The exact type guard does not admit an empty or null value as a Boolean.');
  if (hasQuotedReceiver || hasRawReceiver || hasStructuralReceiver) {
    emptyParts.push('A pass-through receiver can preserve, replace, reject, or reinterpret that empty value as stated by its exact expression and downstream contract.');
  }
  return {
    validation: hasExplicitGuard ? 'template-boolean-guard' : 'receiver-specific-without-schema',
    receiverSemantics,
    emptyBehavior: emptyParts.join(' '),
    invalidBehavior: invalidParts.join(' '),
  };
};

const booleanRuntimeProof = (field) => {
  const proofByPath = {
    '$.codeBundle.enabled': [
      ['charts/kubeclaw/templates/deployment.yaml', 878, 'runtime-boolean-parser', 'The health script applies the false default and validates the bundle manifest in startup and readiness modes.'],
      ['charts/kubeclaw/templates/deployment.yaml', 937, 'runtime-shell-consumer', 'The init script installs the bundle only when the quoted environment value is exactly `true`.'],
    ],
    '$.discord.enabled': [
