  if (consumer.conditionalSignal && conditionProof.length === 0) conditionProof.push({
    path: consumer.path,
    line: consumer.line,
    kind: 'expression-selection',
    branch: 'inline',
    expression: sourceLine.trim().slice(0, 240),
    sourceLineSha256: digest(sourceLine),
