      && comparisonOperators.has(child.parent.operatorToken.kind);
    if (ts.isStringLiteralLike(child) && !ts.isTemplateExpression(child)
      && !comparisonLiteral) values.push(child.text);
    else ts.forEachChild(child, visit);
  };
