const WORKLOAD_PATHS: Record<string, Array<string | number>> = {
  Deployment: ['spec', 'template', 'spec'], StatefulSet: ['spec', 'template', 'spec'], DaemonSet: ['spec', 'template', 'spec'], ReplicaSet: ['spec', 'template', 'spec'],
  Job: ['spec', 'template', 'spec'], CronJob: ['spec', 'jobTemplate', 'spec', 'template', 'spec'], Pod: ['spec'],
};

function resourceName(resource: AnyRecord): string {
  return `${resource.value.kind || 'Unknown'}/${resource.value.metadata?.name || '<unnamed>'}`;
}

function finding(resource: AnyRecord, rule: AnyRecord, message: string, keys: Array<string | number> = []): AnyRecord {
  return { file: resource.source, line: nodeLine(resource, keys), column: 1, severity: rule.severity, code: `kubernetes-policy/${rule.id}`, message };
}

function indexes(resources: AnyRecord[]) {
  const secrets = new Map<string, Set<string>>();
  const configMaps = new Map<string, Set<string>>();
  const serviceAccounts = new Map<string, string[]>();
  for (const resource of resources) {
    const namespace = resource.value.metadata?.namespace || 'default';
    const name = resource.value.metadata?.name;
    if (!name) continue;
    const key = `${namespace}/${name}`;
    if (resource.value.kind === 'Secret') secrets.set(key, new Set([...Object.keys(resource.value.data || {}), ...Object.keys(resource.value.stringData || {})]));
    if (resource.value.kind === 'ConfigMap') configMaps.set(key, new Set(Object.keys(resource.value.data || {})));
    if (resource.value.kind === 'ServiceAccount') serviceAccounts.set(key, (resource.value.imagePullSecrets || []).map((entry: AnyRecord) => entry?.name).filter(Boolean));
  }
  return { secrets, configMaps, serviceAccounts };
}

function availableEnvironment(container: AnyRecord, namespace: string, lookup: AnyRecord): { names: Set<string>; unresolved: string[] } {
  const names = new Set<string>((container.env || []).map((entry: AnyRecord) => entry?.name).filter((name: unknown): name is string => typeof name === 'string' && name.length > 0));
  const unresolved: string[] = [];
  for (const source of container.envFrom || []) {
    const secret = source?.secretRef?.name;
    const configMap = source?.configMapRef?.name;
    const values = secret ? lookup.secrets.get(`${namespace}/${secret}`) : configMap ? lookup.configMaps.get(`${namespace}/${configMap}`) : null;
    if (values) for (const name of values) names.add(`${source.prefix || ''}${name}`);
    else unresolved.push(secret ? `Secret/${secret}` : configMap ? `ConfigMap/${configMap}` : 'unknown envFrom source');
  }
  return { names, unresolved };
}

function pullSecrets(pod: AnyRecord, namespace: string, lookup: AnyRecord): string[] {
  const direct = (pod.imagePullSecrets || []).map((entry: AnyRecord) => entry?.name).filter(Boolean);
  const serviceAccount = pod.serviceAccountName || 'default';
  return [...new Set([...direct, ...(lookup.serviceAccounts.get(`${namespace}/${serviceAccount}`) || [])])];
}

function environmentRule(ctx: AnyRecord): AnyRecord[] {
  const { resource, rule, lookup, pod, namespace, group, container, keys, label } = ctx;
  const results: AnyRecord[] = [];
      const environment = availableEnvironment(container, namespace, lookup);
      for (const name of rule.parameters.names) if (!environment.names.has(name)) results.push(finding(resource, rule, `${label} does not declare required environment variable ${name}${environment.unresolved.length ? `; unresolved envFrom: ${environment.unresolved.join(', ')}` : ''}.`, keys));

  return results;
}

function secretRule(ctx: AnyRecord): AnyRecord[] {
  const { resource, rule, lookup, pod, namespace, group, container, keys, label } = ctx;
  const results: AnyRecord[] = [];
      for (const [envIndex, env] of (container.env || []).entries()) {
        const ref = env?.valueFrom?.secretKeyRef;
        if (ref && ref.optional !== true && !lookup.secrets.get(`${namespace}/${ref.name}`)?.has(ref.key)) results.push(finding(resource, rule, `${label} references missing Secret key ${ref.name}/${ref.key}.`, [...keys, 'env', envIndex]));
      }
  results.push(...secretSourceRule(ctx));

  return results;
}

function secretSourceRule(ctx: AnyRecord): AnyRecord[] {
  const { resource, rule, lookup, namespace, container, keys, label } = ctx;
  const results: AnyRecord[] = [];
      for (const [sourceIndex, source] of (container.envFrom || []).entries()) {
        const ref = source?.secretRef;
        if (ref?.name && ref.optional !== true && !lookup.secrets.has(`${namespace}/${ref.name}`)) results.push(finding(resource, rule, `${label} references missing Secret ${ref.name}.`, [...keys, 'envFrom', sourceIndex]));
      }
  return results;
}

function pullSecretRule(ctx: AnyRecord): AnyRecord[] {
  const { resource, rule, lookup, pod, namespace, group, container, keys, label } = ctx;
  const results: AnyRecord[] = [];
      const registry = rule.parameters.registries.find((prefix: string) => typeof container.image === 'string' && (container.image === prefix || container.image.startsWith(`${prefix}/`)));
      if (registry && pullSecrets(pod, namespace, lookup).length === 0) results.push(finding(resource, rule, `${label} uses private registry ${registry} without imagePullSecrets.`, keys));

  return results;
}

function resourceRule(ctx: AnyRecord): AnyRecord[] {
  const { resource, rule, lookup, pod, namespace, group, container, keys, label } = ctx;
  const results: AnyRecord[] = [];
      if (rule.parameters.cpu && !container.resources?.limits?.cpu) results.push(finding(resource, rule, `${label} has no CPU limit.`, keys));
      if (rule.parameters.memory && !container.resources?.limits?.memory) results.push(finding(resource, rule, `${label} has no memory limit.`, keys));

  return results;
}

function containerRule(ctx: AnyRecord): AnyRecord[] {
  const { resource, rule, group, container, keys, label } = ctx;
  switch (rule.type) {
    case 'required-env': return environmentRule(ctx);
    case 'secret-ref': return secretRule(ctx);
    case 'private-registry-pull-secret': return pullSecretRule(ctx);
    case 'resource-limits': return resourceRule(ctx);
    case 'readiness-probe': return group.probes && !container.readinessProbe
      ? [finding(resource, rule, `${label} has no readinessProbe.`, keys)] : [];
    case 'liveness-probe': return group.probes && !container.livenessProbe
      ? [finding(resource, rule, `${label} has no livenessProbe.`, keys)] : [];
    default: return [];
  }
}

function evaluateRule(resource: AnyRecord, podPath: Array<string | number>, rule: AnyRecord, lookup: AnyRecord): AnyRecord[] {
  const pod = podPath.reduce((value: AnyRecord, key) => value?.[key], resource.value);
  if (!pod || typeof pod !== 'object') return [];
  const namespace = resource.value.metadata?.namespace || 'default';
  const containerGroups = [
    { field: 'containers', values: Array.isArray(pod.containers) ? pod.containers : [], probes: true },
    { field: 'initContainers', values: Array.isArray(pod.initContainers) ? pod.initContainers : [], probes: false },
  ];
  const results: AnyRecord[] = [];
  for (const group of containerGroups) group.values.forEach((container: AnyRecord, index: number) => {
    const keys = [...podPath, group.field, index];
    const label = `${resourceName(resource)} ${group.field === 'initContainers' ? 'init container' : 'container'} '${container?.name || index}'`;
    results.push(...containerRule({ resource, rule, lookup, pod, namespace, group, container, keys, label }));
  });
  return results;
}

function kubernetesPolicyTool() {
  return {
    id: 'kubernetes-policy', name: 'Kubernetes manifest policy', binary: 'node', tier: 'full',
    detect: (ctx: AnyRecord) => ctx.policyProject.kubernetes.policy_packs.length > 0,
    run: async (ctx: AnyRecord) => {
      const { resources, sources } = await loadKubernetesResources(ctx);
      const lookup = indexes(resources);
      const packs = ctx.policy.kubernetes_policy_packs.filter((pack: AnyRecord) => ctx.policyProject.kubernetes.policy_packs.includes(pack.id));
      const findings: AnyRecord[] = [];
      for (const resource of resources) {
        const podPath = WORKLOAD_PATHS[resource.value.kind];
        if (!podPath) continue;
        for (const pack of packs) for (const rule of pack.rules) findings.push(...evaluateRule(resource, podPath, rule, lookup));
      }
      return {
        errors: findings.filter((entry) => entry.severity === 'error').length,
        warnings: findings.filter((entry) => entry.severity === 'warning').length,
        findings,
        evidence: [...sources, ...packs.map((pack: AnyRecord) => ({ kind: 'policy-pack', source: path.basename(pack.path), sha256: pack.digest, bytes: pack.bytes }))],
      };
    },
  };
}

scripts/kubernetes-api-probe.mjs.syntax:
export function validateApiOrigins(origins) {
  if (!Array.isArray(origins) || origins.length < 2 || origins.length > 32 || new Set(origins).size !== origins.length) {
    throw new Error('API_SERVICE_AND_ENDPOINT_ORIGINS_REQUIRED');
  }
  for (const [index, origin] of origins.entries()) {
    const url = new URL(origin);
    validateHttpsOrigin(url);
    if (index === 0) {
      if (url.hostname !== 'kubernetes.default.svc' || url.port) throw new Error('API_PROBE_SERVICE_443_REQUIRED');
    } else if (!isIP(url.hostname.replace(/^\[|\]$/g, ''))) throw new Error('API_PROBE_ENDPOINT_IP_REQUIRED');
  }
}

function validateHttpsOrigin(url) {
  if (url.protocol !== 'https:' || url.username || url.password || url.pathname !== '/' || url.search || url.hash) {
    throw new Error('API_PROBE_HTTPS_ORIGIN_REQUIRED');
  }
}

export async function verifyKubernetesApiPaths(options) {
  const { namespace, serviceAccount, origins, tokenFile, caFile } = options;
  for (const value of [namespace, serviceAccount]) {
    if (!/^[a-z0-9](?:[a-z0-9.-]{0,251}[a-z0-9])?$/.test(value)) throw new Error('API_PROBE_IDENTITY_INVALID');
  }
  validateApiOrigins(origins);
  const token = fs.readFileSync(tokenFile, 'utf8').trim();
  const claims = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (claims.sub !== `system:serviceaccount:${namespace}:${serviceAccount}`) throw new Error('API_PROBE_WRONG_SERVICE_ACCOUNT');
  const ca = fs.readFileSync(caFile);
  for (const origin of origins) {
    const url = new URL(origin);
    url.pathname = `/api/v1/namespaces/${namespace}/services`;
    url.search = '?limit=1';
    const body = await getApi(url, ca, token);
    if (body.kind !== 'ServiceList' || !Array.isArray(body.items)) throw new Error('API_PROBE_NOT_KUBERNETES_SERVICE_LIST');
  }
  return { ok: true, serviceAccount: claims.sub, checkedOrigins: origins,
    excluded: ['negative-private-target', 'CNI-drop-verdict', 'controller-reconciliation'] };
}

function getApi(url, ca, token) {
  return new Promise((resolve, reject) => {
    const request = https.get(url, { ca, servername: 'kubernetes.default.svc', rejectUnauthorized: true,
      signal: AbortSignal.timeout(15000), headers: { authorization: `Bearer ${token}` } }, response => {
      if (response.statusCode !== 200) { response.destroy(); reject(new Error(`API_PROBE_HTTP_${response.statusCode}`)); return; }
      const chunks = []; let size = 0;
      response.on('data', bytes => {
        size += bytes.length;
        if (size > 8 * 1024 * 1024) { response.destroy(new Error('API_PROBE_RESPONSE_LIMIT')); return; }
        chunks.push(bytes);
      });
      response.on('error', reject);
      response.on('end', () => {
        try { resolve(JSON.parse(Buffer.concat(chunks).toString('utf8'))); } catch { reject(new Error('API_PROBE_RESPONSE_INVALID')); }
      });
    });
    request.on('error', reject);
  });
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 3) throw new Error('Usage: kubernetes-api-probe.mjs OPTIONS_JSON_FILE');
  const result = await verifyKubernetesApiPaths(JSON.parse(fs.readFileSync(process.argv[2], 'utf8')));
  process.stdout.write(JSON.stringify(result) + '\n');
}

skills/buster/plugins/visual/src/browser.syntax:
export function assertBaselineVersion(schemaVersion) {
  if (schemaVersion === 'kubeclaw.visual-baselines.v1') {
    throw new Error('VISUAL_BASELINE_MIGRATION_REQUIRED:recapture and approve browser-bound v2 baselines');
  }
  if (schemaVersion !== 'kubeclaw.visual-baselines.v2') throw new Error('VISUAL_MANIFEST_INVALID');
}

export function assertBrowserVersion(value) {
  if (typeof value !== 'string' || value.length === 0 || value.length > 256
    || value.trim() !== value || /[\u0000-\u001f\u007f]/u.test(value)) {
    throw new Error('VISUAL_BROWSER_VERSION_INVALID');
  }
  return value;
}

export function assertBaselineBrowserVersion(baseline, current, id) {
  const expected = assertBrowserVersion(baseline);
  const actual = assertBrowserVersion(current);
  if (actual !== expected) {
    throw new Error(`VISUAL_BASELINE_BROWSER_VERSION_MISMATCH:${id}:expected=${expected}:actual=${actual}`);
  }
}

skills/nova/project_setup/tools/progress.syntax:
function existingModuleIdForDir(progress: AnyRecord, dir: string): string {
  const match = entriesOf(progress.modules).find(([, module]) => isPlainObject(module) && module.dir === dir);
  return match?.[0] ?? dir;
}

function inferSuites(moduleDir: string, hasBuster: boolean, existing: unknown): string[] {
  if (Array.isArray(existing)) return existing.filter((suite) => typeof suite === 'string' && !MIGRATED_SUITES.has(suite));
  if (!hasBuster) return [];
  const suites: string[] = [];
  if (fs.existsSync(path.join(moduleDir, 'test-spec.json'))) suites.push('api');
  if (fs.existsSync(path.join(moduleDir, 'baselines', 'paths.json'))) suites.push('visual-reg');
  return suites;
}

function inferRequiredSuites(markdown: string): string[] {
  const suites: string[] = [];
  let inRequired = false;
  for (const line of markdown.split(/\r?\n/)) {
    if (/^##\s+Required Suites\b/i.test(line)) {
      inRequired = true;
      continue;
    }
    if (inRequired && /^##\s+/.test(line)) break;
    if (!inRequired) continue;
    const suite = line.match(/^\s*[-*]\s+`?([A-Za-z0-9-]+)`?\s*$/)?.[1];
    if (suite && VALID_SUITES.has(suite)) suites.push(suite);
  }
  return [...new Set(suites)];
}

function packageScripts(projectSrcDir: string) {
  const packageJson = readJsonIfExists(path.join(projectSrcDir, 'package.json'));
  const scripts = isPlainObject(packageJson?.scripts) ? packageJson.scripts : {};
  return {
    start: typeof scripts.start === 'string' ? 'npm start' : 'npm start',
    test: typeof scripts.test === 'string' ? 'npm test' : 'npm test',
  };
}

function addServeConfig(config: AnyRecord, input: AnyRecord) {
  const serveSuites = ['security', 'a11y', 'perf', 'e2e', 'visual-reg'];
  if (!input.suites.some((suite: string) => serveSuites.includes(suite))) return;
  config.serve = {
    type: 'server',
    project_dir: `Projects/${input.project}/src`,
    start_cmd: input.scripts.start,
    image: `localhost/${input.project}:${input.moduleId}`,
    port: 3000,
  };
  const dockerfile = path.join(input.projectSrcDir, 'Dockerfile');
  if (!fs.existsSync(dockerfile)) return;
  config.serve.dockerfile = relFromRepo(input.repoRoot, dockerfile);
  config.serve.build_context = `Projects/${input.project}/src`;
}

function addSuiteConfigs(config: AnyRecord, input: AnyRecord) {
  if (input.suites.includes('api')) {
    config.api = { spec_file: relFromSwarm(path.join(input.projectSrcDir, '.swarm'), path.join(input.moduleDir, 'test-spec.json')) };
  }
}

function sanitizedTestConfig(value: unknown, suites: string[]): AnyRecord | undefined {
  if (!isPlainObject(value)) return undefined;
  const config = structuredClone(value);
  delete config.k8s;
  delete config.bundle;
  delete config.manifest;
  delete config.api;
  delete config.a11y;
  delete config.perf;
  delete config['visual-reg'];
  delete config.e2e;
  delete config.security;
  if (isPlainObject(config.serve)) {
    for (const field of ['health_path', 'health_retries', 'health_base_delay', 'health_timeout',
      'smoke_paths', 'smoke_expected_text', 'deployment_yaml', 'secret_yaml']) delete config.serve[field];
    if (!suites.some((suite) => ['security', 'a11y', 'perf', 'e2e', 'visual-reg'].includes(suite))) delete config.serve;
  }
  return Object.keys(config).length ? config : undefined;
}

function legacyManifestPath(config: AnyRecord, field: 'deployment_yaml' | 'secret_yaml'): string | null {
  const manifest = objectOrEmpty(config.manifest);
  const serve = objectOrEmpty(config.serve);
  const value = manifest[field] ?? serve[field];
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function lintDeclaration(existing: unknown, progress: AnyRecord, repositoryRoot: string): AnyRecord | undefined {
  const current = objectOrEmpty(existing);
  const raw = Array.isArray(current.rawManifests)
    ? current.rawManifests.filter((entry) => typeof entry === 'string') : [];
  const charts = Array.isArray(current.helmCharts)
    ? current.helmCharts.filter((entry) => typeof entry === 'string') : [];
  const scopes = [...entriesOf(progress.modules), ...entriesOf(progress.gates)];
  for (const [scopeId, scope] of scopes) {
    const selected = Array.isArray(scope.test_suites) && scope.test_suites.includes('manifest');
    const config = objectOrEmpty(scope.test_config);
    if (!selected && !isPlainObject(config.manifest)) continue;
    const deployment = legacyManifestPath(config, 'deployment_yaml');
    if (!deployment) throw new Error(`LEGACY_MANIFEST_DEPLOYMENT_MISSING:${scopeId}`);
    raw.push(relativeRepositoryPath(repositoryRoot, deployment, `${scopeId}:manifest.deployment_yaml`));
    const secret = legacyManifestPath(config, 'secret_yaml');
    if (secret) raw.push(relativeRepositoryPath(repositoryRoot, secret, `${scopeId}:manifest.secret_yaml`));
  }
  const rawManifests = [...new Set(raw)];
  const helmCharts = [...new Set(charts)];
  if (rawManifests.length + helmCharts.length === 0) return undefined;
  return {
    uses: 'kubeclaw.lint.full',
    policyProject: typeof current.policyProject === 'string' && current.policyProject.trim()
      ? current.policyProject.trim() : 'workspace',
    rawManifests,
    helmCharts,
  };
}

function safeNodeId(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9-]+/gu, '-').replace(/^-+|-+$/gu, '').slice(0, 64) || 'scope';
}

function relativeRepositoryPath(repositoryRoot: string, value: string, label: string): string {
  const absolute = path.isAbsolute(value) ? path.resolve(value) : path.resolve(repositoryRoot, value);
  const relative = path.relative(repositoryRoot, absolute).split(path.sep).join('/');
  if (!relative || relative === '..' || relative.startsWith('../')) {
    throw new Error(`LEGACY_BUILD_PATH_DENIED:${label}:${value}`);
  }
  return relative;
}

function legacyBuildNode(existingConfig: unknown, projectSrcDir: string, repositoryRoot: string, scopeId: string): AnyRecord {
  const serve = objectOrEmpty(objectOrEmpty(existingConfig).serve);
  const defaultContext = path.relative(repositoryRoot, projectSrcDir).split(path.sep).join('/');
  const configuredContext = typeof serve.build_context === 'string' && serve.build_context.trim()
    ? serve.build_context.trim() : defaultContext;
  const buildContext = relativeRepositoryPath(repositoryRoot, configuredContext, `${scopeId}:build_context`);
  const configuredDockerfile = typeof serve.dockerfile === 'string' && serve.dockerfile.trim()
    ? serve.dockerfile.trim() : path.join(buildContext, 'Dockerfile').split(path.sep).join('/');
  const dockerfile = relativeRepositoryPath(repositoryRoot, configuredDockerfile, `${scopeId}:dockerfile`);
  if (!fs.existsSync(path.join(repositoryRoot, buildContext)) || !fs.statSync(path.join(repositoryRoot, buildContext)).isDirectory()) {
    throw new Error(`LEGACY_BUILD_CONTEXT_MISSING:${scopeId}:${buildContext}`);
  }
  if (!fs.existsSync(path.join(repositoryRoot, dockerfile)) || !fs.statSync(path.join(repositoryRoot, dockerfile)).isFile()) {
    throw new Error(`LEGACY_BUILD_DOCKERFILE_MISSING:${scopeId}:${dockerfile}`);
  }
  const definition: AnyRecord = { type: 'dockerfile', dockerfile };
  if (typeof serve.target === 'string' && serve.target.trim()) definition.target = serve.target.trim();
  if (isPlainObject(serve.build_args)) definition.buildArgs = structuredClone(serve.build_args);
  const values: AnyRecord = {
    buildContext,
    definition,
    outputName: safeNodeId(scopeId),
    platform: typeof serve.platform === 'string' && serve.platform.trim() ? serve.platform.trim() : 'linux/amd64',
  };
  return {
    uses: 'kubeclaw.container-build@1', mode: 'blocking', retries: 1,
    concurrencyGroup: 'container-build', config: values,
  };
}

function legacyBundleNodes(existingConfig: unknown, projectSrcDir: string, repositoryRoot: string, scopeId: string): AnyRecord {
  const bundle = objectOrEmpty(objectOrEmpty(existingConfig).bundle);
  const configured = bundle.www_dir;
  if (typeof configured !== 'string' || configured.trim().length === 0) {
    throw new Error(`LEGACY_BUNDLE_CONFIGURATION_RETIRED:${scopeId}: set bundle.www_dir once so the scaffold can create an explicit size-budget artifact producer`);
  }
  const absolute = path.isAbsolute(configured) ? path.resolve(configured) : path.resolve(projectSrcDir, configured);
  const relative = path.relative(projectSrcDir, absolute).split(path.sep).join('/');
  if (!relative || relative === '..' || relative.startsWith('../')) {
    throw new Error(`LEGACY_BUNDLE_OUTPUT_PATH_DENIED:${scopeId}:${configured}`);
  }
  const workingDirectory = path.relative(repositoryRoot, projectSrcDir).split(path.sep).join('/');
  if (!workingDirectory || workingDirectory === '..' || workingDirectory.startsWith('../')) {
    throw new Error(`LEGACY_BUNDLE_PROJECT_PATH_DENIED:${scopeId}:${projectSrcDir}`);
  }
  const thresholds = objectOrEmpty(bundle.thresholds);
  const config: AnyRecord = { format: 'tar', largestFiles: 5 };
  if (Number.isFinite(thresholds.max_size_kb) && thresholds.max_size_kb >= 0) {
    config.maximumTotalBytes = Math.trunc(thresholds.max_size_kb * 1024);
  }
  if (Number.isSafeInteger(thresholds.max_file_count) && thresholds.max_file_count >= 0) {
    config.maximumFileCount = thresholds.max_file_count;
  }
  const blocking = config.maximumTotalBytes !== undefined || config.maximumFileCount !== undefined;
  const archive = `.swarm/size-budget-${safeNodeId(scopeId)}.tar`;
  return {
    'size-budget-artifact': {
      uses: 'kubeclaw.direct-command@1', mode: 'blocking', retries: 0, concurrencyGroup: 'size-budget',
      config: { executable: 'tar', args: ['--format=ustar', '--transform=s,^\\./,,;s,^\\.$,root,',
        '-cf', archive, '-C', relative, '.'],
        workingDirectory, resultMode: 'exit-code', artifacts: [
          { id: 'build-output', path: archive, mediaType: 'application/vnd.kubeclaw.build-output.tar' },
        ] },
    },
    'size-budget': {
      uses: 'kubeclaw.size-budget@1', mode: blocking ? 'blocking' : 'advisory', retries: 0,
      concurrencyGroup: 'size-budget', config,
      inputs: { 'build-output': { from: 'size-budget-artifact', output: 'artifact-1' } },
    },
  };
}

function legacyApiNode(existingConfig: unknown, repositoryRoot: string, projectSrcDir: string, scopeId: string,
  deploymentNode?: string): AnyRecord {
  const config = objectOrEmpty(existingConfig);
  const api = objectOrEmpty(config.api);
  const serve = objectOrEmpty(config.serve);
  if (typeof api.spec_file !== 'string' || !api.spec_file.trim()) throw new Error(`LEGACY_API_SPEC_MISSING:${scopeId}`);
  const base = typeof serve.project_dir === 'string' && serve.project_dir.trim()
    ? path.resolve(repositoryRoot, serve.project_dir) : projectSrcDir;
  const baseRelative = path.relative(repositoryRoot, base);
  if (baseRelative === '..' || baseRelative.startsWith(`..${path.sep}`)) {
    throw new Error(`LEGACY_API_PROJECT_PATH_DENIED:${scopeId}:${String(serve.project_dir)}`);
  }
  const absolute = path.resolve(base, api.spec_file);
  const scopedRelative = path.relative(base, absolute);
  const relative = path.relative(repositoryRoot, absolute).split(path.sep).join('/');
  if (!relative || relative === '..' || relative.startsWith('../') || scopedRelative === '..'
    || scopedRelative.startsWith(`..${path.sep}`) || !fs.existsSync(absolute)) {
    throw new Error(`LEGACY_API_SPEC_DENIED:${scopeId}:${api.spec_file}`);
  }
  let realSpec: string;
  try { realSpec = fs.realpathSync(absolute); } catch { throw new Error(`LEGACY_API_SPEC_DENIED:${scopeId}:${api.spec_file}`); }
  const realRepository = fs.realpathSync(repositoryRoot);
  if (!realSpec.startsWith(`${realRepository}${path.sep}`) || !fs.statSync(realSpec).isFile()) {
    throw new Error(`LEGACY_API_SPEC_DENIED:${scopeId}:${api.spec_file}`);
  }
  const parsed = readJsonIfExists(realSpec);
  if (parsed?.schemaVersion !== 'kubeclaw.api-flow.v1') {
    throw new Error(`LEGACY_API_SPEC_VERSION_RETIRED:${scopeId}: convert ${api.spec_file} to kubeclaw.api-flow.v1`);
  }
  return { uses: 'kubeclaw.api-flow@1', mode: 'blocking', retries: 0, concurrencyGroup: 'api',
    ...(deploymentNode ? { needs: [deploymentNode] } : {}),
    config: { flowFile: relative, ...(deploymentNode ? {} : { url: `${TODO_PREFIX} provider-reachable API origin or add a deployment input` }) },
    ...(deploymentNode ? { inputs: { deployment: { from: deploymentNode, output: 'deployment',
      schemaId: 'kubeclaw.kubernetes-deployment-fixture@1' } } } : {}) };
}

function legacyA11yNode(existingConfig: unknown, scopeId: string, deploymentNode?: string): AnyRecord {
  const config = objectOrEmpty(existingConfig);
  const a11y = objectOrEmpty(config.a11y);
  if (isPlainObject(a11y.thresholds)) {
    throw new Error(`LEGACY_A11Y_THRESHOLDS_RETIRED:${scopeId}: replace numeric thresholds with exact rule, route, selector, reason, and expiry acceptances`);
  }
  const route = typeof a11y.path === 'string' && a11y.path.trim() ? a11y.path.trim() : '/';
  if (!route.startsWith('/') || route.startsWith('//') || /[?#\r\n]/u.test(route)) {
    throw new Error(`LEGACY_A11Y_PATH_INVALID:${scopeId}:${route}`);
  }
  if (a11y.timeout !== undefined
    && (!Number.isSafeInteger(a11y.timeout) || Number(a11y.timeout) < 1000 || Number(a11y.timeout) > 120000)) {
    throw new Error(`LEGACY_A11Y_TIMEOUT_INVALID:${scopeId}:${String(a11y.timeout)}`);
  }
  const values: AnyRecord = { routes: [route], profiles: ['desktop', 'mobile'],
    tags: Array.isArray(a11y.tags) && a11y.tags.length ? structuredClone(a11y.tags) : ['wcag2a', 'wcag2aa'],
    exclude: Array.isArray(a11y.exclude) ? structuredClone(a11y.exclude) : [],
    ...(Number.isSafeInteger(a11y.timeout) ? { timeoutMs: a11y.timeout } : {}),
    ...(deploymentNode ? {} : { url: `${TODO_PREFIX} provider-reachable browser origin or add a deployment input` }),
  };
  return { uses: 'kubeclaw.axe@1', mode: 'blocking', retries: 0, concurrencyGroup: 'browser-axe', config: values,
    ...(deploymentNode ? { needs: [deploymentNode], inputs: { deployment: { from: deploymentNode, output: 'deployment',
      schemaId: 'kubeclaw.kubernetes-deployment-fixture@1' } } } : {}) };
}

function inferTestConfig(input: AnyRecord): AnyRecord | undefined {
  if (isPlainObject(input.existingConfig)) return sanitizedTestConfig(input.existingConfig, input.suites);
  if (!Array.isArray(input.suites) || input.suites.length === 0) return undefined;
  const config: AnyRecord = {};
  const enriched = { ...input, scripts: packageScripts(input.projectSrcDir) };
  addServeConfig(config, enriched);
  addSuiteConfigs(config, enriched);
  return config;
}

function httpNodes(existingConfig: unknown, deploymentNode?: string): AnyRecord {
  const config = objectOrEmpty(existingConfig);
  const serve = objectOrEmpty(config.serve);
  const baseConfig: AnyRecord = {
    ...(deploymentNode ? {} : { url: `${TODO_PREFIX} provider-reachable HTTP origin or use a deployment input` }),
    path: typeof serve.health_path === 'string' ? serve.health_path : '/',
    expectedStatuses: [200],
    requestTimeoutMs: Number.isSafeInteger(serve.health_timeout) ? serve.health_timeout : 10_000,
  };
  const tests: AnyRecord = {
    'http-health': {
      uses: 'kubeclaw.http@1', mode: 'blocking',
      retries: Number.isSafeInteger(serve.health_retries) ? Math.max(0, serve.health_retries - 1) : 2,
      concurrencyGroup: 'http', config: baseConfig,
      ...(deploymentNode ? { inputs: { deployment: { from: deploymentNode, output: 'deployment',
        schemaId: 'kubeclaw.kubernetes-deployment-fixture@1' } } } : {}),
    },
  };
  const expected = objectOrEmpty(serve.smoke_expected_text);
  const paths = Array.isArray(serve.smoke_paths) ? serve.smoke_paths : [];
  paths.forEach((requestPath: unknown, index: number) => {
    if (typeof requestPath !== 'string') return;
    tests[`smoke-${index + 1}`] = {
      uses: 'kubeclaw.http@1', mode: 'blocking', needs: ['http-health'], concurrencyGroup: 'http',
      config: { ...baseConfig, path: requestPath,
        ...(typeof expected[requestPath] === 'string' ? { expectedText: expected[requestPath] } : {}) },
      ...(deploymentNode ? { inputs: { deployment: { from: deploymentNode, output: 'deployment',
        schemaId: 'kubeclaw.kubernetes-deployment-fixture@1' } } } : {}),
    };
  });
  return tests;
}

function exposureNodes(existingConfig: unknown, deploymentNode: string): { fixtures: AnyRecord; tests: AnyRecord } {
  const preview = objectOrEmpty(objectOrEmpty(existingConfig).tailscale_preview);
  const exposureId = 'tailscale-exposure';
  const config: AnyRecord = { path: '/' };
  if (typeof preview.hostname === 'string' && preview.hostname.trim()) config.hostname = preview.hostname.trim();
  const maxTimeSeconds = preview.max_time_seconds ?? 30;
  if (!Number.isSafeInteger(maxTimeSeconds) || maxTimeSeconds < 1 || maxTimeSeconds > 300) {
    throw new Error('LEGACY_TAILSCALE_PREVIEW_MAX_TIME_INVALID: use an integer from 1 to 300 seconds');
  }
  const baseHttp: AnyRecord = { path: '/', expectedStatuses: [200], requestTimeoutMs: maxTimeSeconds * 1000 };
  if (typeof preview.expected_text === 'string' && preview.expected_text) baseHttp.expectedText = preview.expected_text;
  const tests: AnyRecord = {
    'public-http-health': { uses: 'kubeclaw.http@1', mode: 'blocking', retries: 2,
      needs: [exposureId], concurrencyGroup: 'http', config: baseHttp,
      inputs: { endpoint: { from: exposureId, output: 'exposure', schemaId: 'kubeclaw.public-endpoint-fixture@1' } } },
  };
  const expected = objectOrEmpty(preview.smoke_expected_text);
  const paths = Array.isArray(preview.smoke_paths) ? preview.smoke_paths : [];
  paths.forEach((requestPath: unknown, index: number) => {
    if (typeof requestPath !== 'string') return;
    tests[`public-smoke-${index + 1}`] = { uses: 'kubeclaw.http@1', mode: 'blocking', retries: 1,
      needs: ['public-http-health'], concurrencyGroup: 'http', config: { ...baseHttp, path: requestPath,
        ...(typeof expected[requestPath] === 'string' ? { expectedText: expected[requestPath] } : {}) },
      inputs: { endpoint: { from: exposureId, output: 'exposure', schemaId: 'kubeclaw.public-endpoint-fixture@1' } } };
  });
  return { fixtures: { [exposureId]: { uses: 'kubeclaw.tailscale-exposure@1', retries: 0,
    needs: [deploymentNode], concurrencyGroup: 'tailscale-exposure', config,
    inputs: { deployment: { from: deploymentNode, output: 'deployment', schemaId: 'kubeclaw.kubernetes-deployment-fixture@1' } } } }, tests };
}

function withDependency(node: unknown, dependency: string): unknown {
  if (!isPlainObject(node)) return node;
  const needs = Array.isArray(node.needs) ? node.needs.filter((item) => typeof item === 'string') : [];
  return { ...node, needs: [...new Set([...needs, dependency])] };
}

function withImageInput(node: unknown, buildNode: string): unknown {
  if (!isPlainObject(node)) return node;
  const inputs = objectOrEmpty(node.inputs);
  return { ...node, inputs: { ...inputs, image: {
    from: buildNode, output: 'image', schemaId: 'kubeclaw.container-image@1',
  } } };
}

function scopeWithProviders(existingScope: unknown, testConfig: unknown, options: {
  addContainerBuild: boolean; addHttp: boolean; addSizeBudget: boolean; addExposure: boolean; addApi: boolean; addA11y: boolean; legacyUnitSelected: boolean;
  legacyPerfSelected: boolean;
  legacyVisualSelected: boolean;
  legacyE2eSelected: boolean;
  legacySecuritySelected: boolean;
  projectSrcDir: string; repositoryRoot: string; swarmDir: string; scopeId: string;
}): AnyRecord {
  const scope = objectOrEmpty(existingScope);
  const fixtures = objectOrEmpty(scope.fixtures);
  const deploymentNode = Object.entries(fixtures).find(([, fixture]) => isPlainObject(fixture)
    && fixture.uses === 'kubeclaw.kubernetes-fixture@1')?.[0];
  const tests = objectOrEmpty(scope.tests);
  const hasLighthouse = Object.values(tests).some((test) => isPlainObject(test)
    && test.uses === 'kubeclaw.lighthouse@1');
  if (isPlainObject(objectOrEmpty(testConfig).perf)) {
    throw new Error(`LEGACY_PERF_CONFIGURATION_RETIRED:${options.scopeId}: define named Lighthouse profiles, budgets, and kubeclaw.lighthouse@1 nodes in .swarm/pipeline.json`);
  }
  if (options.legacyPerfSelected && !hasLighthouse) {
    throw new Error(`LEGACY_PERF_CONFIGURATION_RETIRED:${options.scopeId}: define kubeclaw.lighthouse@1 in .swarm/pipeline.json`);
  }
  if (isPlainObject(objectOrEmpty(testConfig)['visual-reg'])) {
    throw new Error(`LEGACY_VISUAL_CONFIGURATION_RETIRED:${options.scopeId}: define reviewed baselines, profiles, and kubeclaw.visual@1 in .swarm/pipeline.json`);
  }
  if (options.legacyVisualSelected) {
    throw new Error(`LEGACY_VISUAL_CONFIGURATION_RETIRED:${options.scopeId}: define kubeclaw.visual@1 in .swarm/pipeline.json`);
  }
  if (isPlainObject(objectOrEmpty(testConfig).e2e) || options.legacyE2eSelected) {
    throw new Error(`LEGACY_E2E_CONFIGURATION_RETIRED:${options.scopeId}: define a project-owned Playwright config and kubeclaw.playwright@1 in .swarm/pipeline.json`);
  }
  if (isPlainObject(objectOrEmpty(testConfig).security) || options.legacySecuritySelected) {
    throw new Error(`LEGACY_SECURITY_CONFIGURATION_RETIRED:${options.scopeId}: define explicit kubeclaw.security-headers@1, dependency-scan-trivy@1, image-scan-trivy@1, kubernetes-policy-security@1, and kubernetes-runtime-security@1 nodes in .swarm/pipeline.json`);
  }
  if (options.addExposure && !deploymentNode) {
    throw new Error(`LEGACY_TAILSCALE_PREVIEW_CONFIGURATION_RETIRED:${options.scopeId}: define kubeclaw.kubernetes-fixture@1 before Tailscale exposure`);
  }
  const exposure = options.addExposure ? exposureNodes(testConfig, deploymentNode!) : { fixtures: {}, tests: {} };
  const hasDirectCommand = Object.values(tests).some((test) => isPlainObject(test)
    && test.uses === 'kubeclaw.direct-command@1');
  if (options.legacyUnitSelected && !hasDirectCommand) {
    throw new Error(`LEGACY_UNIT_CONFIGURATION_RETIRED:${options.scopeId}: define kubeclaw.direct-command@1 in .swarm/pipeline.json`);
  }
  const hasHttp = Object.values(tests).some((test) => isPlainObject(test) && test.uses === 'kubeclaw.http@1');
  const existingContainerBuild = Object.entries(tests).find(([, test]) => isPlainObject(test)
    && test.uses === 'kubeclaw.container-build@1');
  const hasContainerBuild = existingContainerBuild !== undefined;
  const hasDependencySecurity = Object.values(tests).some((test) => isPlainObject(test)
    && test.uses === 'kubeclaw.dependency-scan-trivy@1');
  const existingSizeBudget = Object.entries(tests).find(([, test]) => isPlainObject(test) && test.uses === 'kubeclaw.size-budget@1');
  const hasSizeBudget = existingSizeBudget !== undefined;
  const generatedA11y = options.addA11y ? legacyA11yNode(testConfig, options.scopeId, deploymentNode) : null;
  const generatedBudget = !hasSizeBudget && options.addSizeBudget
    ? legacyBundleNodes(testConfig, options.projectSrcDir, options.repositoryRoot, options.scopeId) : {};
  const generatedBuild = !hasContainerBuild && options.addContainerBuild
    ? { 'container-build': legacyBuildNode(testConfig, options.projectSrcDir, options.repositoryRoot, options.scopeId) }
    : {};
  const combinedTests = { ...tests,
    ...(!hasDependencySecurity ? { 'dependency-security': { uses: 'kubeclaw.dependency-scan-trivy@1', mode: 'blocking', retries: 0,
      concurrencyGroup: 'security-dependency', config: { projectDirectory: '.', policy: { profile: 'strict-v1' } } } } : {}),
    ...generatedBuild, ...generatedBudget, ...exposure.tests,
    ...(options.addApi && !Object.values(tests).some((test) => isPlainObject(test) && test.uses === 'kubeclaw.api-flow@1')
      ? { 'api-flow': legacyApiNode(testConfig, options.repositoryRoot, options.projectSrcDir, options.scopeId, deploymentNode) } : {}),
    ...(options.addA11y && !Object.values(tests).some((test) => isPlainObject(test) && test.uses === 'kubeclaw.axe@1')
      ? { axe: generatedA11y } : {}),
    ...(!hasHttp && options.addHttp ? httpNodes(testConfig, deploymentNode) : {}) };
  const budgetNodeId = existingSizeBudget?.[0] ?? 'size-budget';
  const orderedTests = options.addSizeBudget
    ? Object.fromEntries(Object.entries(combinedTests).map(([id, test]) => [id,
      isPlainObject(test) && test.uses === 'kubeclaw.http@1' ? withDependency(test, budgetNodeId) : test]))
    : combinedTests;
  const buildNodeId = existingContainerBuild?.[0] ?? 'container-build';
  const orderedFixtures = Object.fromEntries(Object.entries({ ...fixtures, ...exposure.fixtures }).map(([id, fixture]) => {
    let next = options.addSizeBudget ? withDependency(fixture, budgetNodeId) : fixture;
    if (options.addContainerBuild && isPlainObject(next) && next.uses === 'kubeclaw.kubernetes-fixture@1') {
      next = withImageInput(withDependency(next, buildNodeId), buildNodeId);
    }
    return [id, next];
  }));
  return { ...scope,
    tests: orderedTests,
    fixtures: orderedFixtures,
    concurrencyLimits: { ...(options.addContainerBuild ? { 'container-build': 1 } : {}),
      ...(options.addHttp || options.addExposure ? { http: 4 } : {}), ...(options.addSizeBudget ? { 'size-budget': 2 } : {}),
      ...(options.addExposure ? { 'tailscale-exposure': 1 } : {}),
      ...(options.addApi ? { api: 1 } : {}),
      ...(options.addA11y ? { 'browser-axe': 2 } : {}),
      'security-dependency': 1,
      ...objectOrEmpty(scope.concurrencyLimits) } };
}

function rejectRetiredKubernetesConfig(scope: AnyRecord, scopeId: string) {
  const suites = scope.test_suites;
  if ((Array.isArray(suites) && suites.includes('k8s')) || isPlainObject(objectOrEmpty(scope.test_config).k8s)) {
    throw new Error(`LEGACY_K8S_CONFIGURATION_RETIRED:${scopeId}: define kubeclaw.kubernetes-fixture@1 in .swarm/pipeline.json`);
  }
}

function buildPipeline(context: Context, progress: AnyRecord, modules: AnyRecord, gates: AnyRecord, published: readonly [unknown,unknown]): AnyRecord {
  const existing = objectOrEmpty(published[1]);
  const existingModules = objectOrEmpty(existing.modules);
  const existingGates = objectOrEmpty(existing.gates);
  const progressModules = objectOrEmpty(progress.modules);
  const progressGates = objectOrEmpty(progress.gates);
  const projectSrcDir = path.dirname(context.swarmDir);
  const moduleScopes = Object.fromEntries(Object.entries(modules)
    .filter(([, module]) => isPlainObject(module) && Array.isArray(module.stages) && module.stages.includes('buster'))
    .map(([id]) => {
      const prior = objectOrEmpty(progressModules[id]);
      rejectRetiredKubernetesConfig(prior, id);
      const selected = prior.test_suites;
      // Provider conversion consumes the raw prior record here. Sanitization
      // applies only to the separately persisted residual progress record.
      return [id, scopeWithProviders(existingModules[id], prior.test_config, {
        addContainerBuild: Array.isArray(selected) && selected.includes('build'),
        addHttp: !Array.isArray(selected) || selected.includes('health'),
        addSizeBudget: Array.isArray(selected) && selected.includes('bundle'),
        addExposure: Array.isArray(selected) && selected.includes('tailscale-preview'),
        addApi: Array.isArray(selected) && selected.includes('api'),
        addA11y: Array.isArray(selected) && selected.includes('a11y'),
        legacyPerfSelected: Array.isArray(selected) && selected.includes('perf'),
        legacyVisualSelected: Array.isArray(selected) && selected.includes('visual-reg'),
        legacyE2eSelected: Array.isArray(selected) && selected.includes('e2e'),
        legacySecuritySelected: Array.isArray(selected) && selected.includes('security'),
        legacyUnitSelected: Array.isArray(selected) && selected.includes('unit'), projectSrcDir,
        repositoryRoot: context.repoRoot, swarmDir: context.swarmDir, scopeId: id,
      })];
    }));
  const gateScopes = Object.fromEntries(Object.entries(gates)
    .filter(([, gate]) => isPlainObject(gate) && gate.type === 'buster')
    .map(([id]) => {
      const prior = objectOrEmpty(progressGates[id]);
      rejectRetiredKubernetesConfig(prior, id);
      const selected = prior.test_suites;
      return [id, scopeWithProviders(existingGates[id], prior.test_config, {
        addContainerBuild: Array.isArray(selected) && selected.includes('build'),
        addHttp: !Array.isArray(selected) || selected.includes('health'),
        addSizeBudget: Array.isArray(selected) && selected.includes('bundle'),
        addExposure: Array.isArray(selected) && selected.includes('tailscale-preview'),
        addApi: Array.isArray(selected) && selected.includes('api'),
        addA11y: Array.isArray(selected) && selected.includes('a11y'),
        legacyPerfSelected: Array.isArray(selected) && selected.includes('perf'),
        legacyVisualSelected: Array.isArray(selected) && selected.includes('visual-reg'),
        legacyE2eSelected: Array.isArray(selected) && selected.includes('e2e'),
        legacySecuritySelected: Array.isArray(selected) && selected.includes('security'),
        legacyUnitSelected: Array.isArray(selected) && selected.includes('unit'), projectSrcDir,
        repositoryRoot: context.repoRoot, swarmDir: context.swarmDir, scopeId: id,
      })];
    }));
  return omitEmpty({ project: context.project,
    lint: lintDeclaration(existing.lint, progress, context.repoRoot),
    modules: moduleScopes, gates: gateScopes });
}

function discoverModules(context: Context, existingProgress: AnyRecord) {
  const modulesDir = path.join(context.swarmDir, 'modules');
  const projectSrcDir = path.dirname(context.swarmDir);
  const modules: AnyRecord = {};
  for (const dir of listDirs(modulesDir)) {
    const moduleDir = path.join(modulesDir, dir);
    const id = existingModuleIdForDir(existingProgress, dir);
    const existing = objectOrEmpty(objectOrEmpty(existingProgress.modules)[id]);
    const forgeText = readTextIfExists(path.join(moduleDir, 'FORGE.md'));
    const hasBuster = fs.existsSync(path.join(moduleDir, 'BUSTER.md'));
    const stages = Array.isArray(existing.stages) ? existing.stages : (hasBuster ? ['forge', 'buster'] : ['forge']);
    const suites = inferSuites(moduleDir, hasBuster, existing.test_suites);
    const substeps = listDirs(moduleDir).filter((substep) => fs.existsSync(path.join(moduleDir, substep, 'FORGE.md')));
    modules[id] = omitEmpty({
      title: nonEmptyStringOrDefault(existing.title, firstHeading(forgeText, id)),
      dir,
      substeps: Array.isArray(existing.substeps) && existing.substeps.length > 0 ? existing.substeps : (substeps.length ? substeps : undefined),
      depends_on: Array.isArray(existing.depends_on) ? existing.depends_on : [],
      stages,
      timeout_minutes: valueOrDefault(existing.timeout_minutes, DEFAULTS.module_timeout_minutes),
      max_fails: valueOrDefault(existing.max_fails, DEFAULTS.module_max_fails),
      thinking_level: nonEmptyStringOrDefault(existing.thinking_level, DEFAULTS.thinking_level),
      forge_model: existing.forge_model,
      forge_subagent: existing.forge_subagent,
      session: existing.session,
      capabilities: existing.capabilities,
      test_suites: suites,
      test_config: inferTestConfig({
        repoRoot: context.repoRoot,
        project: context.project,
        projectSrcDir,
        moduleId: id,
        moduleDir,
        suites,
        existingConfig: existing.test_config,
      }),
    });
  }
  return modules;
}

function existingGate(progress: AnyRecord, field: string, value: string) {
  const match = entriesOf(progress.gates).find(([, gate]) => isPlainObject(gate) && gate[field] === value);
  return match ? { id: match[0], gate: match[1] } : null;
}

function discoverReviewGates(context: Context, progress: AnyRecord) {
  const gates: AnyRecord = {};
  const reviewDir = path.join(context.swarmDir, 'echo-review');
  for (const file of listFiles(reviewDir, (name) => /\.md$/i.test(name))) {
    const relativePath = relFromSwarm(context.swarmDir, file);
    const prior = existingGate(progress, 'instructions_file', relativePath);
    const id = prior?.id ?? slugFromName(path.basename(file));
    const existing = objectOrEmpty(prior?.gate);
    const reviewName = nonEmptyStringOrDefault(existing.review_name, upperNameFromId(id));
    gates[id] = omitEmpty({
      type: 'review',
      title: nonEmptyStringOrDefault(existing.title, titleFromId(id)),
      review_name: reviewName,
      on_fail: nonEmptyStringOrDefault(existing.on_fail, DEFAULTS.review_on_fail),
      instructions_file: nonEmptyStringOrDefault(existing.instructions_file, relativePath),
      output_file: nonEmptyStringOrDefault(existing.output_file, `logs/echo-review/${reviewName}.json`),
      review_output_dir: nonEmptyStringOrDefault(existing.review_output_dir, DEFAULTS.review_output_dir),
      reviewers: existing.reviewers,
      primary_reviewer: existing.primary_reviewer,
      timeout_minutes: valueOrDefault(existing.timeout_minutes, DEFAULTS.review_timeout_minutes),
      max_fix_cycles: valueOrDefault(existing.max_fix_cycles, DEFAULTS.review_max_fix_cycles),
      lint_tier: nonEmptyStringOrDefault(existing.lint_tier, DEFAULTS.review_lint_tier),
    });
  }
  return gates;
}

function discoverBusterGates(context: Context, progress: AnyRecord) {
  const gates: AnyRecord = {};
  const busterDir = path.join(context.swarmDir, 'buster-test');
  const projectSrcDir = path.dirname(context.swarmDir);
  for (const file of listFiles(busterDir, (name) => /\.md$/i.test(name))) {
    const relativePath = relFromSwarm(context.swarmDir, file);
    const prior = existingGate(progress, 'instructions_file', relativePath);
    const id = prior?.id ?? slugFromName(path.basename(file));
    const existing = objectOrEmpty(prior?.gate);
    const required = inferRequiredSuites(readTextIfExists(file));
    const suites = (Array.isArray(existing.test_suites) ? existing.test_suites : required)
      .filter((suite) => typeof suite === 'string' && !MIGRATED_SUITES.has(suite));
    gates[id] = omitEmpty({
      type: 'buster',
      title: nonEmptyStringOrDefault(existing.title, titleFromId(id)),
      on_fail: nonEmptyStringOrDefault(existing.on_fail, DEFAULTS.buster_on_fail),
      instructions_file: nonEmptyStringOrDefault(existing.instructions_file, relativePath),
      output_file: nonEmptyStringOrDefault(existing.output_file, `buster-test/${upperNameFromId(id)}-RESULT.json`),
      timeout_minutes: valueOrDefault(existing.timeout_minutes, DEFAULTS.buster_timeout_minutes),
      max_fix_cycles: valueOrDefault(existing.max_fix_cycles, DEFAULTS.buster_max_fix_cycles),
      test_suites: suites,
      test_config: inferTestConfig({
        repoRoot: context.repoRoot,
        project: context.project,
        projectSrcDir,
        moduleId: id,
        moduleDir: busterDir,
        suites,
        existingConfig: existing.test_config,
      }),
    });
  }
  return gates;
}

function mergeObjects(discovered: AnyRecord, existing: unknown) {
  if (!isPlainObject(existing)) return discovered;
  const merged = { ...discovered };
  for (const [id, value] of Object.entries(existing)) {
    merged[id] = isPlainObject(merged[id]) && isPlainObject(value) ? { ...merged[id], ...value } : value;
  }
  return merged;
}

export function buildScaffold(context: Context): AnyRecord {
  const published=readPublishedPair(context.swarmDir,['progress.json','pipeline.json'],false);
  const progress = objectOrEmpty(published[0]);
  const prior = objectOrEmpty(readJsonIfExists(context.scaffoldFile));
  const modules = discoverModules(context, progress);
  const gates = mergeObjects(
    { ...objectOrEmpty(progress.gates), ...discoverReviewGates(context, progress), ...discoverBusterGates(context, progress) },
    prior.gates,
  );
  const moduleIds = objectKeys(modules).sort(naturalSort);
  const gateIds = objectKeys(gates).sort(naturalSort);
  const inferredOrder = gateIds.length
    ? [...moduleIds, ...gateIds.map((gateId) => `${TODO_PREFIX} place gate:${gateId} among [${moduleIds.join(', ')}]`)]
    : moduleIds;
  // Provider conversion reads raw legacy config before retired fields are removed from persisted progress.
  // Once generated, the scaffold is the operator's editable source until apply.
  // Regeneration must not replace its provider plans with applied or inferred data.
  if (Object.hasOwn(prior, 'pipeline') && (!isPlainObject(prior.pipeline) || prior.pipeline.project !== context.project)) {
    throw new Error('SCAFFOLD_PIPELINE_INVALID: repair the existing scaffold pipeline before regeneration; no files were written');
  }
  const pipeline = Object.hasOwn(prior, 'pipeline') ? prior.pipeline : buildPipeline(context, progress, modules, gates, published);
  return {
    _schema: SCHEMA,
    _instructions: ['Edit TODO values and gate placements.',
      'Regeneration preserves the existing scaffold pipeline; add explicit provider plans for newly discovered scopes.',
      'Run with --apply to write progress.json and pipeline.json.'],
    project: context.project,
    version: valueOrDefault(prior.version, valueOrDefault(progress.version, DEFAULTS.version)),
    description: valueOrDefault(prior.description, valueOrDefault(progress.description, `${TODO_PREFIX} one-sentence project purpose`)),
    notes: valueOrDefault(prior.notes, valueOrDefault(progress.notes, [`${TODO_PREFIX} operator-visible scope note`])),
    defaults: valueOrDefault(prior.defaults, valueOrDefault(progress.defaults, {})),
    policy: isPlainObject(prior.policy) ? prior.policy : {
      arch_validation: valueOrDefault(progress.arch_validation, DEFAULTS.policy.arch_validation),
      pipeline_review: valueOrDefault(progress.pipeline_review, DEFAULTS.policy.pipeline_review),
      case_study: valueOrDefault(progress.case_study, DEFAULTS.policy.case_study),
      telemetry: valueOrDefault(progress.telemetry, DEFAULTS.policy.telemetry),
      payload: valueOrDefault(progress.payload, DEFAULTS.policy.payload),
    },
    execution_order: valueOrDefault(prior.execution_order, valueOrDefault(progress.execution_order, inferredOrder)),
    modules: mergeObjects(modules, prior.modules),
    gates,
    pipeline,
  };
}

export type Args = {
  apply: boolean;
  check: boolean;
  print: boolean;
  help: boolean;
  project: string | null;
  repo: string | null;
  swarm: string | null;
  scaffold: string | null;
};

export type Context = {
  repoRoot: string;
  project: string;
  swarmDir: string;
  scaffoldFile: string;
  progressFile: string;
  pipelineFile: string;
};

export type Diagnostic = {
  level: 'error';
  kind: 'form_check' | 'strict_content_check';
  field: string;
  message: string;
};

export function isPlainObject(value: unknown): value is AnyRecord {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

export function objectOrEmpty(value: unknown): AnyRecord {
  return isPlainObject(value) ? value : {};
}

export function entriesOf(value: unknown): Array<[string, any]> {
  return Object.entries(objectOrEmpty(value));
}

export function objectKeys(value: unknown): string[] {
  return Object.keys(objectOrEmpty(value));
}

export function valueOrDefault<T>(value: T | null | undefined, defaultValue: T): T {
  if (value === undefined || value === null) return defaultValue;
  if (typeof value === 'string' && value.length === 0) return defaultValue;
  return value;
}

export function nonEmptyStringOrDefault(value: unknown, defaultValue: string): string {
  return typeof value === 'string' && value.trim() ? value : defaultValue;
}

export function omitEmpty(value: unknown): any {
  if (!isPlainObject(value)) return value;
  const out: AnyRecord = {};
  for (const [key, entry] of Object.entries(value)) {
    if (entry === undefined || entry === null) continue;
    if (isPlainObject(entry) && Object.keys(entry).length === 0) continue;
    out[key] = entry;
  }
  return out;
}

export function naturalSort(a: unknown, b: unknown): number {
  return String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: 'base' });
}

export function listDirs(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true })
    .filter((entry: Dirent) => entry.isDirectory() && !entry.name.startsWith('.'))
    .map((entry: Dirent) => entry.name)
    .sort(naturalSort);
}

export function listFiles(dir: string, predicate: (name: string) => boolean): string[] {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true })
    .filter((entry: Dirent) => entry.isFile() && predicate(entry.name))
    .map((entry: Dirent) => path.join(dir, entry.name))
    .sort(naturalSort);
}

export function readTextIfExists(filePath: string): string {
  return fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : '';
}

export function readJsonIfExists(filePath: string): any | null {
  return fs.existsSync(filePath) ? JSON.parse(fs.readFileSync(filePath, 'utf8')) : null;
}

export function writeJson(filePath: string, value: unknown): void {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`);
}

export function relFromRepo(repoRoot: string, filePath: string): string {
  return path.relative(repoRoot, filePath).split(path.sep).join('/');
}

export function relFromSwarm(swarmDir: string, filePath: string): string {
  return path.relative(swarmDir, filePath).split(path.sep).join('/');
}

export function titleFromId(id: string): string {
  return String(id)
    .replace(/\.[^.]+$/, '')
    .replace(/-INSTRUCTIONS$/i, '')
    .replace(/[_-]+/g, ' ')
    .replace(/\b\w/g, (character) => character.toUpperCase())
    .trim();
}

export function firstHeading(markdown: string, fallback: string): string {
  const match = markdown.match(/^#\s+(.+?)\s*$/m);
  if (!match) return titleFromId(fallback);
  return valueOrDefault(match[1], '').replace(/^Module\s+[A-Za-z0-9._-]+\s+[—-]\s+/i, '').trim();
}

export function slugFromName(name: string): string {
  return String(name)
    .replace(/\.[^.]+$/, '')
    .replace(/-INSTRUCTIONS$/i, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function upperNameFromId(id: string): string {
  return String(id).toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

export function diagnostic(kind: Diagnostic['kind'], message: string, field: string): Diagnostic {
  return { level: 'error', kind, field, message };
}

export function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function safeSegment(value: unknown, label: string) {
  if (typeof value !== 'string' || !value.trim()) throw new Error(`${label} must be a non-empty string.`);
  if (!/^[A-Za-z0-9._-]+$/.test(value) || value.includes('..')) throw new Error(`${label} must be a safe path segment: ${value}`);
}

function collectTodos(value: unknown, diagnostics: Diagnostic[], field = '$') {
  if (typeof value === 'string') {
    if (value.startsWith(TODO_PREFIX)) diagnostics.push(diagnostic('form_check', `unresolved TODO at ${field}`, field));
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((entry, index) => collectTodos(entry, diagnostics, `${field}.${index}`));
    return;
  }
  if (isPlainObject(value)) {
    Object.entries(value).forEach(([key, entry]) => collectTodos(entry, diagnostics, `${field}.${key}`));
  }
}

function validateStringArray(value: unknown, allowed: Set<string>, diagnostics: Diagnostic[], field: string) {
  if (!Array.isArray(value)) {
    diagnostics.push(diagnostic('form_check', `${field} must be an array`, field));
    return;
  }
  for (const entry of value) {
    if (typeof entry !== 'string') diagnostics.push(diagnostic('form_check', `${field} entries must be strings`, field));
    else if (!allowed.has(entry)) diagnostics.push(diagnostic('form_check', `${field} contains invalid value '${entry}'`, field));
  }
}

function validateForgeFiles(id: string, module: AnyRecord, moduleDir: string, diagnostics: Diagnostic[]) {
  if (Array.isArray(module.substeps) && module.substeps.length > 0) {
    for (const substep of module.substeps) {
      if (typeof substep !== 'string') {
        diagnostics.push(diagnostic('form_check', `module '${id}' substep must be a string`, `modules.${id}.substeps`));
      } else if (!fs.existsSync(path.join(moduleDir, substep, 'FORGE.md'))) {
        diagnostics.push(diagnostic('strict_content_check', `module '${id}' substep FORGE.md missing: ${substep}/FORGE.md`, `modules.${id}.substeps`));
      }
    }
    return;
  }
  if (!fs.existsSync(path.join(moduleDir, 'FORGE.md'))) {
    diagnostics.push(diagnostic('strict_content_check', `module '${id}' FORGE.md missing`, `modules.${id}.dir`));
  }
}

function validateDependencies(id: string, module: AnyRecord, moduleIds: Set<string>, gateIds: Set<string>, diagnostics: Diagnostic[]) {
  if (!Array.isArray(module.depends_on)) {
    diagnostics.push(diagnostic('form_check', `module '${id}' depends_on must be an array`, `modules.${id}.depends_on`));
    return;
  }
  for (const dependency of module.depends_on) {
    if (typeof dependency !== 'string') {
      diagnostics.push(diagnostic('form_check', `module '${id}' dependency must be a string`, `modules.${id}.depends_on`));
    } else if (dependency.startsWith('gate:') && !gateIds.has(dependency.slice('gate:'.length))) {
      diagnostics.push(diagnostic('strict_content_check', `module '${id}' dependency references unrecognized gate '${dependency}'`, `modules.${id}.depends_on`));
    } else if (!dependency.startsWith('gate:') && !moduleIds.has(dependency)) {
      diagnostics.push(diagnostic('strict_content_check', `module '${id}' dependency references unrecognized module '${dependency}'`, `modules.${id}.depends_on`));
    }
  }
}

function validateModule(id: string, module: AnyRecord, scaffold: AnyRecord, context: Context, diagnostics: Diagnostic[]) {
  try {
    safeSegment(id, `module id '${id}'`);
  } catch (error) {
    diagnostics.push(diagnostic('form_check', errorMessage(error), `modules.${id}`));
  }
  if (!isPlainObject(module)) {
    diagnostics.push(diagnostic('form_check', `module '${id}' must be an object`, `modules.${id}`));
    return;
  }
  if (!module.title) diagnostics.push(diagnostic('form_check', `module '${id}' needs title`, `modules.${id}.title`));
  if (!module.dir) {
    diagnostics.push(diagnostic('form_check', `module '${id}' needs dir`, `modules.${id}.dir`));
  } else {
    const moduleDir = path.join(context.swarmDir, 'modules', module.dir);
    try {
      safeSegment(module.dir, `module '${id}' dir`);
    } catch (error) {
      diagnostics.push(diagnostic('form_check', errorMessage(error), `modules.${id}.dir`));
    }
    if (!fs.existsSync(moduleDir)) {
      diagnostics.push(diagnostic('strict_content_check', `module '${id}' dir does not exist: ${relFromRepo(context.repoRoot, moduleDir)}`, `modules.${id}.dir`));
    }
    validateForgeFiles(id, module, moduleDir, diagnostics);
  }
  validateDependencies(id, module, new Set(objectKeys(scaffold.modules)), new Set(objectKeys(scaffold.gates)), diagnostics);
  if (module.stages !== undefined) validateStringArray(module.stages, VALID_STAGES, diagnostics, `modules.${id}.stages`);
  if (module.test_suites !== undefined) validateStringArray(module.test_suites, VALID_SUITES, diagnostics, `modules.${id}.test_suites`);
  validateTestConfig(module.test_config, module.test_suites || [], context, diagnostics, `modules.${id}.test_config`);
}

function validateModules(scaffold: AnyRecord, context: Context, diagnostics: Diagnostic[]) {
  entriesOf(scaffold.modules).forEach(([id, module]) => validateModule(id, module, scaffold, context, diagnostics));
}

function validateReviewOrBusterGate(id: string, gate: AnyRecord, context: Context, diagnostics: Diagnostic[]) {
  if (gate.type === 'review') {
    if (!gate.review_name) diagnostics.push(diagnostic('form_check', `review gate '${id}' needs review_name`, `gates.${id}.review_name`));
    if (gate.on_fail !== undefined && gate.on_fail !== 'stop') diagnostics.push(diagnostic('form_check', `review gate '${id}' on_fail must be stop`, `gates.${id}.on_fail`));
  }
  if (gate.type === 'buster' && gate.on_fail !== undefined && gate.on_fail !== 'fix_and_retest') {
    diagnostics.push(diagnostic('form_check', `buster gate '${id}' on_fail must be fix_and_retest`, `gates.${id}.on_fail`));
  }
  requireExistingSwarmFile(context, gate.instructions_file, diagnostics, `gates.${id}.instructions_file`);
  if (!gate.output_file) diagnostics.push(diagnostic('form_check', `gate '${id}' needs output_file`, `gates.${id}.output_file`));
  if (gate.type !== 'buster') return;
  validateStringArray(gate.test_suites, VALID_SUITES, diagnostics, `gates.${id}.test_suites`);
  validateTestConfig(gate.test_config, gate.test_suites || [], context, diagnostics, `gates.${id}.test_config`);
}

function validateGate(id: string, gate: AnyRecord, context: Context, diagnostics: Diagnostic[]) {
  try {
    safeSegment(id, `gate id '${id}'`);
  } catch (error) {
    diagnostics.push(diagnostic('form_check', errorMessage(error), `gates.${id}`));
  }
  if (!isPlainObject(gate)) {
    diagnostics.push(diagnostic('form_check', `gate '${id}' must be an object`, `gates.${id}`));
    return;
  }
  if (!VALID_GATE_TYPES.has(gate.type)) diagnostics.push(diagnostic('form_check', `gate '${id}' type is invalid`, `gates.${id}.type`));
  if (!gate.title) diagnostics.push(diagnostic('form_check', `gate '${id}' needs title`, `gates.${id}.title`));
  if (['review', 'buster'].includes(gate.type)) validateReviewOrBusterGate(id, gate, context, diagnostics);
  if (gate.type === 'approval' && !['block', 'continue'].includes(gate.on_timeout)) {
    diagnostics.push(diagnostic('form_check', `approval gate '${id}' on_timeout must be block or continue`, `gates.${id}.on_timeout`));
  }
}

function validateExecutionOrder(scaffold: AnyRecord, diagnostics: Diagnostic[]) {
  if (!Array.isArray(scaffold.execution_order)) {
    diagnostics.push(diagnostic('form_check', 'execution_order must be an array', 'execution_order'));
    return [];
  }
  const modules = new Set(objectKeys(scaffold.modules));
  const gates = new Set(objectKeys(scaffold.gates));
  const seen = new Set();
  scaffold.execution_order.forEach((entry: any, index: number) => {
    const field = `execution_order.${index}`;
    if (typeof entry !== 'string' || !entry.trim() || entry.startsWith(TODO_PREFIX)) {
      diagnostics.push(diagnostic('form_check', `execution_order[${index}] needs a concrete module id or gate:<id>`, field));
      return;
    }
    const gateEntry = entry.startsWith('gate:');
    const key = gateEntry ? entry.slice('gate:'.length) : entry;
    if (!(gateEntry ? gates : modules).has(key)) diagnostics.push(diagnostic('strict_content_check', `execution_order references unrecognized '${key}'`, field));
    if (seen.has(entry)) diagnostics.push(diagnostic('form_check', `execution_order repeats '${entry}'`, field));
    seen.add(entry);
  });
  return [...scaffold.execution_order];
}

function validatePipelineScope(scope: unknown, diagnostics: Diagnostic[], field: string) {
  if (!isPlainObject(scope)) {
    diagnostics.push(diagnostic('form_check', `${field} must be an object`, field));
    return;
  }
  const tests = objectOrEmpty(scope.tests);
  const http = Object.entries(tests).filter(([, test]) => isPlainObject(test) && test.uses === 'kubeclaw.http@1');
  if (http.length === 0) return;
  for (const [id, test] of http) {
    const config = objectOrEmpty(test.config);
    const inputs = objectOrEmpty(test.inputs);
    if (typeof config.url !== 'string' && !isPlainObject(inputs.deployment)) {
      diagnostics.push(diagnostic('form_check', `${field}.tests.${id} needs config.url or a deployment input`, `${field}.tests.${id}`));
    }
  }
}

function validatePipeline(scaffold: AnyRecord, diagnostics: Diagnostic[]) {
  if (!isPlainObject(scaffold.pipeline) || scaffold.pipeline.project !== scaffold.project) {
    diagnostics.push(diagnostic('form_check', 'pipeline must contain the project test plan', 'pipeline'));
    return;
  }
  const pipelineModules = objectOrEmpty(scaffold.pipeline.modules);
  const pipelineGates = objectOrEmpty(scaffold.pipeline.gates);
  const lint = scaffold.pipeline.lint;
  if (lint !== undefined) {
    if (!isPlainObject(lint) || lint.uses !== 'kubeclaw.lint.full'
      || typeof lint.policyProject !== 'string' || lint.policyProject.length === 0
      || !Array.isArray(lint.rawManifests) || !Array.isArray(lint.helmCharts)
      || lint.rawManifests.length + lint.helmCharts.length === 0
      || [...lint.rawManifests, ...lint.helmCharts].some((entry) => typeof entry !== 'string' || entry.length === 0)) {
      diagnostics.push(diagnostic('form_check', 'pipeline.lint must declare kubeclaw.lint.full, one policy project, and explicit Kubernetes inputs', 'pipeline.lint'));
    }
  }
  for (const [id, module] of entriesOf(scaffold.modules)) {
    if (Array.isArray(module.stages) && module.stages.includes('buster')) {
      validatePipelineScope(pipelineModules[id], diagnostics, `pipeline.modules.${id}`);
    }
  }
  for (const [id, gate] of entriesOf(scaffold.gates)) {
    if (gate.type === 'buster') validatePipelineScope(pipelineGates[id], diagnostics, `pipeline.gates.${id}`);
  }
}

export function validateScaffold(scaffold: unknown, context: Context): Diagnostic[] {
  const diagnostics: Diagnostic[] = [];
  if (!isPlainObject(scaffold)) return [diagnostic('form_check', 'scaffold must be a JSON object', '$')];
  if (scaffold._schema && scaffold._schema !== SCHEMA) diagnostics.push(diagnostic('form_check', `unsupported scaffold schema '${scaffold._schema}'`, '_schema'));
  collectTodos(scaffold, diagnostics);
  if (scaffold.project !== context.project) diagnostics.push(diagnostic('strict_content_check', `project must be '${context.project}'`, 'project'));
  if (!isPlainObject(scaffold.modules) || Object.keys(scaffold.modules).length === 0) {
    diagnostics.push(diagnostic('strict_content_check', 'modules must contain at least one module', 'modules'));
  }
  validateModules(scaffold, context, diagnostics);
  entriesOf(scaffold.gates).forEach(([id, gate]) => validateGate(id, gate, context, diagnostics));
  validatePipeline(scaffold, diagnostics);
  return diagnostics;
}

export function scaffoldToProgress(scaffold: AnyRecord, context: Context) {
  const diagnostics = validateScaffold(scaffold, context);
  const executionOrder = validateExecutionOrder(scaffold, diagnostics);
  if (diagnostics.length > 0) {
    const error: Error & { diagnostics?: Diagnostic[] } = new Error('progress scaffold validation failed');
    error.diagnostics = diagnostics;
    throw error;
  }
  return {
    diagnostics,
    pipeline: scaffold.pipeline,
    progress: omitEmpty({
      project: scaffold.project,
      version: valueOrDefault(scaffold.version, DEFAULTS.version),
      description: scaffold.description,
      notes: scaffold.notes,
      defaults: scaffold.defaults,
      arch_validation: scaffold.policy?.arch_validation,
      pipeline_review: scaffold.policy?.pipeline_review,
      case_study: scaffold.policy?.case_study,
      telemetry: scaffold.policy?.telemetry,
      payload: scaffold.policy?.payload,
      execution_order: executionOrder,
      modules: scaffold.modules,
      gates: Object.fromEntries(entriesOf(scaffold.gates).map(([id, gate]) => [id, objectOrEmpty(gate)])),
    }),
  };
}

function safeRelativePath(relativePath: string) {
  return !relativePath.includes('\0')
    && !/[\r\n]/.test(relativePath)
    && !path.isAbsolute(relativePath)
    && !relativePath.split(/[\\/]+/).includes('..');
}

function validateRepoPath(context: Context, value: unknown, diagnostics: Diagnostic[], field: string) {
  if (typeof value !== 'string' || !value.trim()) {
    diagnostics.push(diagnostic('form_check', `${field} must be a non-empty string`, field));
    return false;
  }
  if (!safeRelativePath(value)) {
    diagnostics.push(diagnostic('form_check', `${field} must be a safe relative path`, field));
    return false;
  }
  const resolved = path.resolve(context.repoRoot, value);
  if (!resolved.startsWith(`${context.repoRoot}${path.sep}`) && resolved !== context.repoRoot) {
    diagnostics.push(diagnostic('form_check', `${field} must stay inside repository root`, field));
    return false;
  }
  return true;
}

export function requireExistingSwarmFile(context: Context, value: unknown, diagnostics: Diagnostic[], field: string) {
  if (typeof value !== 'string' || !value.trim()) {
    diagnostics.push(diagnostic('form_check', `${field} must be a non-empty string`, field));
    return;
  }
  if (!safeRelativePath(value)) {
    diagnostics.push(diagnostic('form_check', `${field} must be a safe relative path`, field));
    return;
  }
  const resolved = path.resolve(context.swarmDir, value);
  if (!resolved.startsWith(`${context.swarmDir}${path.sep}`) && resolved !== context.swarmDir) {
    diagnostics.push(diagnostic('form_check', `${field} must stay inside .swarm`, field));
  } else if (!fs.existsSync(resolved)) {
    diagnostics.push(diagnostic('strict_content_check', `${field} does not exist: ${value}`, field));
  }
}

function validateServe(config: any, context: Context, diagnostics: Diagnostic[], field: string) {
  if (!config.serve) return;
  if (typeof config.serve.project_dir !== 'string') diagnostics.push(diagnostic('form_check', `${field}.serve.project_dir must be a string`, `${field}.serve.project_dir`));
  if (typeof config.serve.start_cmd !== 'string' && typeof config.serve.build_cmd !== 'string') {
    diagnostics.push(diagnostic('form_check', `${field}.serve needs start_cmd or build_cmd`, `${field}.serve`));
  }
  if (config.serve.port !== undefined && (!Number.isInteger(config.serve.port) || config.serve.port <= 0)) {
    diagnostics.push(diagnostic('form_check', `${field}.serve.port must be a positive integer`, `${field}.serve.port`));
  }
  if (config.serve.dockerfile) validateRepoPath(context, config.serve.dockerfile, diagnostics, `${field}.serve.dockerfile`);
}

function validateK8s(config: any, context: Context, diagnostics: Diagnostic[], field: string) {
  const k8s = objectOrEmpty(config.k8s);
  validateRepoPath(context, k8s.dockerfile, diagnostics, `${field}.k8s.dockerfile`);
  if (!Array.isArray(k8s.manifests) || k8s.manifests.length === 0) {
    diagnostics.push(diagnostic('form_check', `${field}.k8s.manifests must be a non-empty array`, `${field}.k8s.manifests`));
  } else {
    k8s.manifests.forEach((manifest: any) => validateRepoPath(context, manifest, diagnostics, `${field}.k8s.manifests`));
  }
  if (!k8s.image_name) diagnostics.push(diagnostic('form_check', `${field}.k8s.image_name is required`, `${field}.k8s.image_name`));
  if (!k8s.service_name) diagnostics.push(diagnostic('form_check', `${field}.k8s.service_name is required`, `${field}.k8s.service_name`));
  if (k8s.cleanup_policy && !VALID_CLEANUP.has(k8s.cleanup_policy)) {
    diagnostics.push(diagnostic('form_check', `${field}.k8s.cleanup_policy must be delete or keep`, `${field}.k8s.cleanup_policy`));
  }
  if (k8s.preview?.provider && !VALID_PREVIEW.has(k8s.preview.provider)) {
    diagnostics.push(diagnostic('form_check', `${field}.k8s.preview.provider must be off or tailscale-ingress`, `${field}.k8s.preview.provider`));
  }
}

function validateApiAndVisual(config: any, suites: string[], context: Context, diagnostics: Diagnostic[], field: string) {
  if (suites.includes('api')) requireExistingSwarmFile(context, config.api?.spec_file, diagnostics, `${field}.api.spec_file`);
  if (suites.includes('visual-reg')) {
    diagnostics.push(diagnostic('form_check', `LEGACY_VISUAL_CONFIGURATION_RETIRED:${field}: define kubeclaw.visual@1 in .swarm/pipeline.json`, `${field}.visual-reg`));
  }
}

function validateLocalSuites(config: any, suites: string[], context: Context, diagnostics: Diagnostic[], field: string) {
  validateServe(config, context, diagnostics, field);
  if (suites.includes('k8s')) validateK8s(config, context, diagnostics, field);
}

export function validateTestConfig(
  testConfig: unknown,
  suites: unknown,
  context: Context,
  diagnostics: Diagnostic[],
  field: string,
) {
  if (isPlainObject(testConfig) && isPlainObject(testConfig['visual-reg'])) {
    diagnostics.push(diagnostic('form_check', `LEGACY_VISUAL_CONFIGURATION_RETIRED:${field}: define kubeclaw.visual@1 in .swarm/pipeline.json`, `${field}.visual-reg`));
  }
  if (isPlainObject(testConfig) && isPlainObject(testConfig.e2e)) {
    diagnostics.push(diagnostic('form_check', `LEGACY_E2E_CONFIGURATION_RETIRED:${field}: define kubeclaw.playwright@1 in .swarm/pipeline.json`, `${field}.e2e`));
  }
  if (isPlainObject(testConfig) && isPlainObject(testConfig.security)) {
    diagnostics.push(diagnostic('form_check', `LEGACY_SECURITY_CONFIGURATION_RETIRED:${field}: define explicit security provider nodes in .swarm/pipeline.json`, `${field}.security`));
  }
  if (!Array.isArray(suites) || suites.length === 0) return;
  if (!isPlainObject(testConfig)) {
    diagnostics.push(diagnostic('form_check', `${field} must be an object when test_suites are configured`, field));
    return;
  }
  validateApiAndVisual(testConfig, suites, context, diagnostics, field);
  validateLocalSuites(testConfig, suites, context, diagnostics, field);
}

