function include(name){
 if(reachable.has(name))return;reachable.add(name);
 const scan=value=>{if(!value || typeof value!=='object')return;if(typeof value.$ref==='string' && value.$ref.startsWith('#/$defs/'))include(value.$ref.slice(8));Object.values(value).forEach(scan);};
 scan(defs[name]);
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://kubeclaw.dev/contracts/pipeline-worker-core/v1/schema.json",
  "title": "KubeClaw pipeline worker-core contracts v1",
  "$defs": {
    "nonEmptyString": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
    },
    "stableId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:/-]*$",
      "maxLength": 256
    },
    "contractId": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9._/-]*@[1-9][0-9]*$",
      "maxLength": 256
    },
    "digest": {
      "type": "string",
      "pattern": "^sha256:[a-f0-9]{64}$"
    },
    "timestamp": {
      "type": "string",
      "format": "date-time"
    },
    "protocolVersion": {
      "const": "worker-protocol.v1"
    },
    "supportedProtocolVersion": {
      "type": "string",
      "pattern": "^worker-protocol\\.v[1-9][0-9]*$",
      "maxLength": 64
    },
    "jsonValue": {
      "oneOf": [
        { "type": "null" },
        { "type": "boolean" },
        { "type": "number" },
        { "type": "string" },
        {
          "type": "array",
          "maxItems": 1024,
          "items": { "$ref": "#/$defs/jsonValue" }
        },
        {
          "type": "object",
          "maxProperties": 256,
          "additionalProperties": { "$ref": "#/$defs/jsonValue" }
        }
      ]
    },
    "jsonObject": {
      "type": "object",
      "maxProperties": 256,
      "additionalProperties": { "$ref": "#/$defs/jsonValue" }
    },
    "workerLifecycleState": {
      "enum": ["starting", "ready", "draining", "stopped", "unhealthy"]
    },
    "workerTrustEnvelope": {
      "type": "object",
      "additionalProperties": false,
      "required": ["schemaVersion", "kind", "issuer", "audience", "purpose", "subjectDigest", "contextDigest", "issuedAt", "expiresAt", "nonce", "keyId", "algorithm", "signature"],
      "properties": {
        "schemaVersion": { "const": "worker-trust-envelope.v1" },
        "kind": { "enum": ["request", "artifact"] },
        "issuer": { "type": "string", "pattern": "^spiffe://[a-z0-9.-]+/[A-Za-z0-9._~!$&'()*+,;=:@%/-]+$", "maxLength": 512 },
        "audience": { "type": "string", "pattern": "^spiffe://[a-z0-9.-]+/[A-Za-z0-9._~!$&'()*+,;=:@%/-]+$", "maxLength": 512 },
        "purpose": { "$ref": "#/$defs/stableId" },
        "subjectDigest": { "$ref": "#/$defs/digest" },
        "contextDigest": { "$ref": "#/$defs/digest" },
        "issuedAt": { "$ref": "#/$defs/timestamp" },
        "expiresAt": { "$ref": "#/$defs/timestamp" },
        "nonce": { "type": "string", "pattern": "^[A-Za-z0-9_-]{22,128}$" },
        "keyId": { "$ref": "#/$defs/stableId" },
        "algorithm": { "const": "ed25519" },
        "signature": { "type": "string", "pattern": "^[A-Za-z0-9+/]{86}==$" }
      }
    },
    "workerAttemptState": {
      "enum": ["completed", "errored", "cancelled", "timed_out", "interrupted"]
    },
    "frozenPackageRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["packageId", "packageVersion", "contentDigest"],
      "properties": {
        "packageId": { "$ref": "#/$defs/stableId" },
        "packageVersion": { "$ref": "#/$defs/nonEmptyString" },
        "contentDigest": { "$ref": "#/$defs/digest" }
      }
    },
    "workerEngineRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["engineId", "contractId", "engineVersion", "contentDigest"],
      "properties": {
        "engineId": { "$ref": "#/$defs/stableId" },
        "contractId": { "$ref": "#/$defs/contractId" },
        "engineVersion": { "$ref": "#/$defs/nonEmptyString" },
        "contentDigest": { "$ref": "#/$defs/digest" }
      }
    },
    "workerProfile": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schemaVersion",
        "profileId",
        "profileDigest",
        "workerType",
        "coreContractId",
        "engine",
        "capabilities"
      ],
      "properties": {
        "schemaVersion": { "const": "worker-profile.v1" },
        "profileId": { "$ref": "#/$defs/stableId" },
        "profileDigest": { "$ref": "#/$defs/digest" },
        "workerType": { "$ref": "#/$defs/stableId" },
        "coreContractId": { "$ref": "#/$defs/contractId" },
        "engine": { "$ref": "#/$defs/workerEngineRef" },
        "capabilities": {
          "type": "array",
          "maxItems": 128,
          "items": { "$ref": "#/$defs/stableId" },
          "uniqueItems": true
        }
      }
    },
    "workerCapacity": {
      "type": "object",
      "additionalProperties": false,
      "required": ["total", "available", "active"],
      "properties": {
        "total": { "type": "integer", "minimum": 1, "maximum": 4096 },
        "available": { "type": "integer", "minimum": 0, "maximum": 4096 },
        "active": { "type": "integer", "minimum": 0, "maximum": 4096 }
      }
    },
    "workerRegistration": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schemaVersion",
        "workerId",
        "workerType",
        "coreVersion",
        "protocolVersions",
        "profiles",
        "capacity",
        "lifecycleState",
        "startedAt",
        "sentAt"
      ],
      "properties": {
        "schemaVersion": { "const": "worker-registration.v1" },
        "workerId": { "$ref": "#/$defs/stableId" },
        "workerType": { "$ref": "#/$defs/stableId" },
        "coreVersion": { "$ref": "#/$defs/nonEmptyString" },
        "protocolVersions": {
          "type": "array",
          "minItems": 1,
          "maxItems": 16,
          "items": { "$ref": "#/$defs/supportedProtocolVersion" },
          "uniqueItems": true
        },
        "profiles": {
          "type": "array",
          "minItems": 1,
          "maxItems": 64,
          "items": { "$ref": "#/$defs/workerProfile" }
        },
        "capacity": { "$ref": "#/$defs/workerCapacity" },
        "lifecycleState": { "$ref": "#/$defs/workerLifecycleState" },
        "startedAt": { "$ref": "#/$defs/timestamp" },
        "sentAt": { "$ref": "#/$defs/timestamp" }
      }
    },
    "workerHealth": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schemaVersion",
        "workerId",
        "sequence",
        "lifecycleState",
        "capacity",
        "activeAttemptIds",
        "sentAt"
      ],
      "properties": {
        "schemaVersion": { "const": "worker-health.v1" },
        "workerId": { "$ref": "#/$defs/stableId" },
        "sequence": { "type": "integer", "minimum": 0 },
        "lifecycleState": { "$ref": "#/$defs/workerLifecycleState" },
        "capacity": { "$ref": "#/$defs/workerCapacity" },
