export interface AdmissionCompletionReference {
  file: string;
  maximumBytes: number;
  pipelineRunId: string;
  planId: string;
  nodeId: string;
  attemptId: string;
  claimGeneration: number;
  resultDigest: string;
  closureDigest: string;
}

export interface AdmissionRetiredEntry {
  key: string;
  acknowledgement: AdmissionAcknowledgementV1;
  source: AdmissionCompletionReference;
  operationId: string;
  actor: string;
  authority: {runRoot:string;journalHead:string;snapshotDigest:string};
}

export function assertAdmissionRetiredEntry(entry: AdmissionRetiredEntry): void {
  replayObject(entry, ['key','acknowledgement','source','operationId','actor','authority'], 'admission-retired-entry');
  replayAssert(replayIdentity(entry.operationId) && replayIdentity(entry.actor), 'admission-retirement-author');
  validatePipelineObservabilityContract('admissionAcknowledgement',entry.acknowledgement);
  replayAssert(entry.acknowledgement.state === 'duplicate','admission-retirement-ack');
  const s=entry.source, a=entry.acknowledgement;
  replayObject(entry.authority,['runRoot','journalHead','snapshotDigest'],'admission-retirement-authority');
  replayAssert(typeof entry.authority.runRoot==='string' && path.isAbsolute(entry.authority.runRoot) && path.resolve(entry.authority.runRoot)===entry.authority.runRoot
    && /^sha256:[a-f0-9]{64}$/.test(entry.authority.journalHead) && /^sha256:[a-f0-9]{64}$/.test(entry.authority.snapshotDigest),'admission-retirement-authority-binding');
  replayObject(s,['file','maximumBytes','pipelineRunId','planId','nodeId','attemptId','claimGeneration','resultDigest','closureDigest'],'admission-retirement-source');
  replayAssert(s.file === path.join(entry.authority.runRoot,'observability/attempts/attempt-store.json'),'admission-retirement-file');
  replayAssert(Number.isSafeInteger(s.maximumBytes) && s.maximumBytes > 0 && Number.isSafeInteger(s.claimGeneration) && s.claimGeneration > 0,'admission-retirement-bounds');
  for(const field of ['pipelineRunId','planId','nodeId','attemptId'] as const)replayAssert(replayIdentity(s[field]),'admission-retirement-owner');
  replayAssert(/^sha256:[a-f0-9]{64}$/.test(s.resultDigest) && /^sha256:[a-f0-9]{64}$/.test(s.closureDigest),'admission-retirement-digest');
  replayAssert(a.pipelineRunId === s.pipelineRunId && entry.key === [a.producer.producerId,a.producer.bootId,a.producer.producerType,a.pipelineRunId,String(a.sequence)].join('|'),'admission-retirement-identity');
}

async function readRetirementBytes(file:string,maximumBytes:number):Promise<Buffer> {
  replayAssert(await fs.realpath(file)===file,'admission-retirement-source-path');
  const handle=await fs.open(file,constants.O_RDONLY|constants.O_NOFOLLOW|constants.O_NONBLOCK);
  let bytes:Buffer;
  try {
    const stat=await handle.stat();
    replayAssert(stat.isFile() && stat.size<=maximumBytes,'admission-retirement-source-size');
    bytes=Buffer.alloc(stat.size);let offset=0;
    while(offset<bytes.length){const read=await handle.read(bytes,offset,bytes.length-offset,offset);replayAssert(read.bytesRead>0,'admission-retirement-source-truncated');offset+=read.bytesRead;}
    replayAssert((await handle.read(Buffer.alloc(1),0,1,offset)).bytesRead===0,'admission-retirement-source-grew');
  } finally {await handle.close();}
  replayAssert(await fs.realpath(file)===file,'admission-retirement-source-path');
  return bytes;
}

async function readSource(s:AdmissionCompletionReference):Promise<DurableAttemptStoreSnapshot> {
  const state=JSON.parse((await readRetirementBytes(s.file,s.maximumBytes)).toString()) as DurableAttemptStoreSnapshot;
  return decodeAttemptState(state,path.dirname(s.file),{
    maximumEvidenceObjects:Number.MAX_SAFE_INTEGER,maximumEvidenceBytes:Number.MAX_SAFE_INTEGER,
    maximumEvidenceObjectBytes:Number.MAX_SAFE_INTEGER,maximumResults:Number.MAX_SAFE_INTEGER,
    maximumClosures:Number.MAX_SAFE_INTEGER,maximumMetadataBytes:s.maximumBytes,maximumPendingEvidenceAgeMs:Number.MAX_SAFE_INTEGER,
  }).state;
}

export function resolveAdmissionRetiredSnapshot(entry:AdmissionRetiredEntry,state:DurableAttemptStoreSnapshot):AdmittedRecordView {
  assertAdmissionRetiredEntry(entry);
  const s=entry.source;
  const result=state.results.find(item=>item.pipelineRunId===s.pipelineRunId && item.attemptId===s.attemptId && item.claimGeneration===s.claimGeneration);
  replayAssert(result?.storedAt && result.planId===s.planId && result.nodeId===s.nodeId && result.result.resultDigest===s.resultDigest,'admission-retirement-source-result');
  const intent=result.completionIntent;
  replayAssert(intent && intent.closure.closureDigest===s.closureDigest && state.closures.some(item=>canonicalJson(item)===canonicalJson(intent.closure)),'admission-retirement-source-closure');
  const record=intent.record,a=entry.acknowledgement;
  replayAssert(record.recordDigest===a.recordDigest && record.recordId===a.recordId && canonicalJson(record.producer)===canonicalJson(a.producer)
    && record.sequence===a.sequence && record.correlation.pipelineRunId===a.pipelineRunId,'admission-retirement-source-record');
  return {record:structuredClone(record),canonicalCursor:a.canonicalCursor,admittedAt:a.admittedAt};
}

export async function resolveAdmissionRetiredEntries(entries:readonly AdmissionRetiredEntry[]):Promise<AdmittedRecordView[]> {
  const sources=new Map<string,Promise<DurableAttemptStoreSnapshot>>();
  return Promise.all(entries.map(async entry=>{
    assertAdmissionRetiredEntry(entry);
    const key=canonicalJson([entry.source.file,entry.source.maximumBytes]);
    let source=sources.get(key);
    if(!source){source=readSource(entry.source);sources.set(key,source);}
    return resolveAdmissionRetiredSnapshot(entry,await source);
  }));
}

export async function resolveAdmissionRetiredEntry(entry:AdmissionRetiredEntry):Promise<AdmittedRecordView> {
  return (await resolveAdmissionRetiredEntries([entry]))[0]!;
}

async function assertCompletionEvidence(state:DurableAttemptStoreSnapshot,result:DurableResultMetadata):Promise<void> {
      for(const evidenceId of result.completionIntent!.closure.requiredEvidenceIds) {
        const metadata=state.evidence.find(item=>item.pipelineRunId===result.pipelineRunId && item.attemptId===result.attemptId && item.claimGeneration===result.claimGeneration
          && canonicalJson(item.producer)===canonicalJson(result.completionIntent!.closure.producer) && scopedEvidenceId(item.attemptId,item.claimGeneration,item.evidenceId)===evidenceId
          && result.result.evidence.some(ref=>ref.evidenceId===item.evidenceId));
        if(!metadata)throw new Error('OBSERVABILITY_RETIREMENT_EVIDENCE_REQUIRED');
        const bytes=await readRetirementBytes(fileURLToPath(metadata.artifact.storageUrl),metadata.artifact.sizeBytes);
        if(bytes.length!==metadata.artifact.sizeBytes || `sha256:${createHash('sha256').update(bytes).digest('hex')}`!==metadata.artifact.contentDigest)throw new Error('OBSERVABILITY_RETIREMENT_EVIDENCE_CHANGED');
      }
}

export async function completionRetirementSource(state:DurableAttemptStoreSnapshot,scope:{pipelineRunId:string;attemptId:string;claimGeneration:number;recordDigest:string},file:string,maximumBytes:number):Promise<AdmissionCompletionReference> {
      const result=state.results.find(item=>item.pipelineRunId===scope.pipelineRunId && item.attemptId===scope.attemptId && item.claimGeneration===scope.claimGeneration);
      if(!result?.storedAt || !result.planId || !result.nodeId || !result.completionIntent)throw new Error('OBSERVABILITY_RETIREMENT_COMPLETION_REQUIRED');
      const {record,closure}=result.completionIntent;
      if(record.recordDigest!==scope.recordDigest || closure.recordCount!==1 || closure.firstSequence!==1 || closure.finalSequence!==1 || record.sequence!==1
        || !state.closures.some(item=>canonicalJson(item)===canonicalJson(closure)))throw new Error('OBSERVABILITY_RETIREMENT_CLOSURE_REQUIRED');

  await assertCompletionEvidence(state,result);
  return {file,maximumBytes,pipelineRunId:scope.pipelineRunId,planId:result.planId,nodeId:result.nodeId,attemptId:scope.attemptId,claimGeneration:scope.claimGeneration,resultDigest:result.result.resultDigest,closureDigest:closure.closureDigest};
}

export interface DurableRecord<T = unknown> {
  readonly schemaVersion: "pipeline-durable-record.v1" | "pipeline-durable-record.v2";
  readonly owner?: string;
  readonly stream: string;
  readonly sequence: number;
  readonly idempotencyKey: string;
  readonly committedAt: string;
  readonly payloadDigest: string;
  readonly payload: T;
}

export interface DurableRecordState {
  readonly schemaVersion: "pipeline-durable-record-store.v1" | "pipeline-durable-record-store.v2";
  readonly records: DurableRecord[];
  readonly tombstones?: RecordTombstone[];
  readonly retirements?: RecordRetirement[];
}

export interface RecordRetirementIntent {
  readonly operationId: string;
  readonly actor: string;
  readonly owner: string;
  readonly stream: string;
  readonly records: readonly { readonly idempotencyKey: string; readonly payloadDigest: string }[];
  readonly evidence: Readonly<Record<string, unknown>>;
}

export interface RecordRetirement {
  readonly intent: RecordRetirementIntent;
  readonly intentDigest: string;
  readonly releasedBytesHex: string;
}

export interface RecordTombstone extends Omit<DurableRecord, 'payload'> {
  readonly retirementId: string;
}

export function payloadDigest(payload: unknown): string {
  return `sha256:${crypto.createHash("sha256").update(canonicalJson(payload)).digest("hex")}`;
}

export function ownerValid(owner: unknown): owner is string {
  return typeof owner === 'string' && owner.length > 0 && owner.length <= 512 && !/[\u0000-\u001f\u007f]/u.test(owner);
}

function recordHeaderValid(record: Omit<DurableRecord, 'payload'>): boolean {
  return (record.schemaVersion === 'pipeline-durable-record.v1' && record.owner === undefined
    || record.schemaVersion === 'pipeline-durable-record.v2' && ownerValid(record.owner))
    && IDENTITY.test(record.stream) && IDENTITY.test(record.idempotencyKey)
    && Number.isSafeInteger(record.sequence) && record.sequence > 0
    && typeof record.committedAt === 'string' && DIGEST.test(record.payloadDigest);
}

export function assertRetirementIntent(intent: RecordRetirementIntent): void {
  if (!intent || Object.keys(intent).sort().join(',') !== 'actor,evidence,operationId,owner,records,stream'
    || !IDENTITY.test(intent.operationId) || !ownerValid(intent.actor) || !ownerValid(intent.owner)
    || !IDENTITY.test(intent.stream) || !Array.isArray(intent.records) || !intent.records.length
    || !intent.evidence || typeof intent.evidence !== 'object' || Array.isArray(intent.evidence)) throw new Error('DURABLE_RETIREMENT_INTENT_INVALID');
  assertRetirementSelection(intent.records);
}

function assertRetirementSelection(records: RecordRetirementIntent['records']): void {
  const ids = new Set<string>();
  for (const item of records) {
    if (!item || Object.keys(item).sort().join(',') !== 'idempotencyKey,payloadDigest'
      || !IDENTITY.test(item.idempotencyKey) || !DIGEST.test(item.payloadDigest) || ids.has(item.idempotencyKey)) throw new Error('DURABLE_RETIREMENT_INTENT_INVALID');
    ids.add(item.idempotencyKey);
  }
}

function assertStoreFormat(state: DurableRecordState): void {
  if (!state || !Array.isArray(state.records)) throw new Error('DURABLE_RECORD_STORE_INVALID');
  const v2 = state.schemaVersion === 'pipeline-durable-record-store.v2';
  if (v2 ? !Array.isArray(state.tombstones) || !Array.isArray(state.retirements)
    : state.schemaVersion !== 'pipeline-durable-record-store.v1' || state.tombstones !== undefined || state.retirements !== undefined) throw new Error('DURABLE_RECORD_STORE_INVALID');
 }

export function assertDurableRecordReplay(state: DurableRecordState): void {
  assertStoreFormat(state);
  for (const record of state.records) {
    if (!recordHeaderValid(record) || !Object.hasOwn(record, 'payload') || payloadDigest(record.payload) !== record.payloadDigest) throw new Error('DURABLE_RECORD_STORE_INVALID');
  }
  assertRetiredRecords(state);
  assertRecordSequences(state);
}

function assertRetiredRecords(state: DurableRecordState): void {
  const retirements = new Map<string, RecordRetirement>();
  for (const entry of state.retirements ?? []) {
    assertRetirementIntent(entry.intent);
    if (entry.intentDigest !== payloadDigest(entry.intent) || retirements.has(entry.intent.operationId)
      || !/^[a-f0-9]{16}$/u.test(entry.releasedBytesHex) || !Number.isSafeInteger(Number.parseInt(entry.releasedBytesHex,16)) || Number.parseInt(entry.releasedBytesHex,16) < 1) throw new Error('DURABLE_RETIREMENT_INVALID');
    retirements.set(entry.intent.operationId, entry);
  }
  for (const record of state.tombstones ?? []) assertTombstone(record, retirements);
  for (const retirement of retirements.values()) {
    if (state.tombstones!.filter(record => record.retirementId === retirement.intent.operationId).length !== retirement.intent.records.length) throw new Error('DURABLE_TOMBSTONE_INCOMPLETE');
  }
}

function assertTombstone(record: RecordTombstone, retirements: Map<string, RecordRetirement>): void {

    const retirement = retirements.get(record.retirementId);
    if (!recordHeaderValid(record) || record.schemaVersion !== 'pipeline-durable-record.v2' || Object.hasOwn(record, 'payload')
      || !retirement || record.stream !== retirement.intent.stream || record.owner !== retirement.intent.owner
      || !retirement.intent.records.some(item => item.idempotencyKey === record.idempotencyKey && item.payloadDigest === record.payloadDigest)) throw new Error('DURABLE_TOMBSTONE_INVALID');
 }

function assertRecordSequences(state: DurableRecordState): void {
  const sequences = new Map<string, number>(); const identities = new Set<string>();
  const v2 = state.schemaVersion === 'pipeline-durable-record-store.v2';
  const activeSequences = new Map<string, number>();
  for (const record of state.records) {
    if (record.sequence <= (activeSequences.get(record.stream) ?? 0)) throw new Error('DURABLE_RECORD_SEQUENCE_INVALID');
    activeSequences.set(record.stream, record.sequence);
  }
  const all = v2 ? [...state.records, ...state.tombstones!].sort((a,b) => a.sequence - b.sequence) : state.records;
  for (const record of all) {
    const expected = (sequences.get(record.stream) ?? 0) + 1;
    if (record.sequence !== expected) throw new Error('DURABLE_RECORD_SEQUENCE_INVALID');
    sequences.set(record.stream, record.sequence);
    const key = `${record.stream}|${record.idempotencyKey}`;
    if (identities.has(key)) throw new Error('DURABLE_RECORD_IDENTITY_DUPLICATE');
    identities.add(key);
  }
}

export function existingRecord<T>(state: DurableRecordState, stream: string, idempotencyKey: string, digest: string, snapshot: T, owner?: string): DurableRecord<T> | undefined {
      const existing = state.records.find(
        (record) => record.stream === stream && record.idempotencyKey === idempotencyKey,
      );
      if (existing) {
        if (existing.payloadDigest !== digest || (existing.schemaVersion === "pipeline-durable-record.v2" && existing.owner !== owner)) throw new Error("DURABLE_RECORD_IDEMPOTENCY_CONFLICT");
        return structuredClone(existing) as DurableRecord<T>;
      }
      const retired = state.tombstones?.find(record => record.stream === stream && record.idempotencyKey === idempotencyKey);
      if (retired) {
        if (retired.payloadDigest !== digest || retired.owner !== owner) throw new Error('DURABLE_RECORD_IDEMPOTENCY_CONFLICT');
        const { retirementId: _retirementId, ...header } = retired;
        return { ...header, payload: snapshot } as DurableRecord<T>;
      }
      return undefined;
}

export interface AttemptRetirementIntent {
  pipelineRunId:string; attemptId:string; claimGeneration:number; resultDigest:string;
  recordDigest:string; operationId:string; actor:string; runRoot:string;
  runJournalHead:string; snapshotDigest:string; expectedStoreDigest:string;
  journalSequence:number; journalHash:string;
}

export interface AttemptResultReference {
  schemaVersion:'attempt-result-reference.v1';
  intent:AttemptRetirementIntent;
  journalPrefixBytes:number;
}

export interface PersistedAttemptV2 extends Omit<DurableAttemptStoreSnapshot,'schemaVersion'|'results'> {
  schemaVersion:'durable-attempt-store.v2';
  results:(DurableResultMetadata|ProjectedResultMetadata)[];
}

interface ImportEntry {
  schemaVersion:string;
  decisionKey:string;
  decision:{pipelineRunId:string;planId:string;nodeId:string;attemptId:string;claimGeneration:number;action:string;
    nextClaimGeneration:number|null;result:WorkerAttemptResultV1;completeness:{pipelineRunId:string;state:string;requiredClosureIds:string[];admittedClosureIds:string[];missingClosureIds:string[];missingRanges:unknown[];unresolvedItems:unknown[]}};
}

function removeUncommittedFile(file:string):void {
  try {fs.unlinkSync(file);} catch(error) {if((error as NodeJS.ErrnoException).code!=='ENOENT')throw error;}
}

export function replaceAttemptProjectionSync(file:string,value:DurableAttemptStoreSnapshot|PersistedAttemptV2):void {
  replayAssert(fs.realpathSync(file)===file&&fs.lstatSync(file).isFile(),'attempt-store-path');
  const directory=path.dirname(file),temporary=`${file}.${process.pid}.${randomUUID()}.tmp`;
  let renamed=false;
  try {
    const fd=fs.openSync(temporary,fs.constants.O_WRONLY|fs.constants.O_CREAT|fs.constants.O_EXCL|fs.constants.O_NOFOLLOW,0o600);
    try {fs.writeFileSync(fd,canonicalJson(value));fs.fsyncSync(fd);} finally {fs.closeSync(fd);}
    fs.renameSync(temporary,file);renamed=true;
    const dir=fs.openSync(directory,fs.constants.O_RDONLY|fs.constants.O_DIRECTORY|fs.constants.O_NOFOLLOW);
    try {fs.fsyncSync(dir);} finally {fs.closeSync(dir);}
  } finally {if(!renamed)removeUncommittedFile(temporary);}
}

export function assertAttemptRetirementIntent(intent:AttemptRetirementIntent,root:string):void {
  replayObject(intent,['pipelineRunId','attemptId','claimGeneration','resultDigest','recordDigest','operationId','actor','runRoot','runJournalHead','snapshotDigest','expectedStoreDigest','journalSequence','journalHash'],'attempt-retirement-intent');
  for(const field of ['pipelineRunId','attemptId','operationId','actor'] as const)replayAssert(replayIdentity(intent[field]),'attempt-retirement-identity');
  for(const field of ['resultDigest','recordDigest','runJournalHead','snapshotDigest','expectedStoreDigest','journalHash'] as const)replayAssert(DIGEST.test(intent[field]),'attempt-retirement-digest');
  replayAssert(Number.isSafeInteger(intent.claimGeneration)&&intent.claimGeneration>0&&Number.isSafeInteger(intent.journalSequence)&&intent.journalSequence>0,'attempt-retirement-sequence');
  replayAssert(typeof intent.runRoot==='string'&&path.isAbsolute(intent.runRoot)&&path.resolve(intent.runRoot)===intent.runRoot
    &&root===path.join(intent.runRoot,'observability/attempts'),'attempt-retirement-root');
}

export function readAttemptJournalPrefix(file:string,maximumBytes:number,prefixBytes?:number):Buffer {
  replayAssert(Number.isSafeInteger(maximumBytes)&&maximumBytes>0,'attempt-journal-read-limit');
  replayAssert(fs.realpathSync(file)===file,'attempt-journal-path');
  const fd=fs.openSync(file,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW|fs.constants.O_NONBLOCK);
  try {
    const stat=fs.fstatSync(fd),length=prefixBytes??stat.size;
    replayAssert(stat.isFile()&&Number.isSafeInteger(length)&&length>0&&length<=maximumBytes&&stat.size>=length,'attempt-journal-size');
    const bytes=Buffer.alloc(length);let offset=0;
    while(offset<length){const count=fs.readSync(fd,bytes,offset,length-offset,offset);replayAssert(count>0,'attempt-journal-truncated');offset+=count;}
    replayAssert(fs.realpathSync(file)===file,'attempt-journal-path');
    return bytes;
  } finally {fs.closeSync(fd);}
}

function assertReference(item:ProjectedResultMetadata,root:string,maximumBytes:number):void {
  replayObject(item,['pipelineRunId','planId','nodeId','attemptId','claimGeneration','workerId','completionIntent','storedAt','resultReference'],'attempt-projected-result');
  const reference=item.resultReference;
  replayObject(reference,['schemaVersion','intent','journalPrefixBytes'],'attempt-result-reference');
  replayAssert(reference.schemaVersion==='attempt-result-reference.v1','attempt-result-reference-version');
  assertAttemptRetirementIntent(reference.intent,root);
  replayAssert(attemptProjectionKey(item)===attemptProjectionKey(reference.intent)&&item.completionIntent?.record.recordDigest===reference.intent.recordDigest,'attempt-result-reference-owner');
  replayAssert(Number.isSafeInteger(reference.journalPrefixBytes)&&reference.journalPrefixBytes>0&&reference.journalPrefixBytes<=maximumBytes,'attempt-result-reference-budget');
}

function assertImportedCompleteness(item:ProjectedResultMetadata,d:ImportEntry['decision']):void {
  validatePipelineObservabilityContract('observabilityCompleteness',d.completeness);
  const closure=item.completionIntent?.closure,c=d.completeness;
  replayAssert(closure&&c.pipelineRunId===item.pipelineRunId&&c.state==='complete'&&!c.missingClosureIds.length&&!c.missingRanges.length&&!c.unresolvedItems.length
    &&c.requiredClosureIds.includes(closure.closureId)&&c.admittedClosureIds.includes(closure.closureId),'attempt-result-import-completeness');
}

function resolveResult(item:ProjectedResultMetadata,record:HashJournalRecord<ImportEntry>):WorkerAttemptResultV1 {
  const {intent}=item.resultReference,entry=record.entry,d=entry.decision;
  replayAssert(record.sequence===intent.journalSequence&&record.hash===intent.journalHash&&entry.schemaVersion==='nova-observability-reconciliation.v1','attempt-result-journal-binding');
  replayAssert(d?.pipelineRunId===item.pipelineRunId&&d.planId===item.planId&&d.nodeId===item.nodeId&&d.attemptId===item.attemptId&&d.claimGeneration===item.claimGeneration
    &&d.action==='imported'&&d.nextClaimGeneration===null,'attempt-result-import-owner');
  validatePipelineWorkerCoreContract('workerAttemptResult',d.result);
  replayAssert(d.result.resultDigest===intent.resultDigest&&d.result.workerId===item.workerId&&item.storedAt!==null,'attempt-result-import-digest');
  replayAssert(entry.decisionKey===[item.pipelineRunId,item.planId,item.nodeId,item.attemptId,String(item.claimGeneration),intent.resultDigest,'imported'].join('|'),'attempt-result-import-key');
  assertImportedCompleteness(item,d);
  return structuredClone(d.result);
}

function offsets(bytes:Buffer):number[] {
  const ends:number[]=[];let at=-1;
  while((at=bytes.indexOf(10,at+1))!==-1)ends.push(at+1);
  return ends;
}

export function decodeAttemptState(raw:DurableAttemptStoreSnapshot|PersistedAttemptV2,root:string,limits:DurableAttemptStoreLimits,
  readPrefix:(file:string,maximumBytes:number,prefixBytes:number)=>Buffer=readAttemptJournalPrefix,
):{state:DurableAttemptStoreSnapshot;projections:AttemptProjections} {
  if(raw.schemaVersion==='durable-attempt-store.v1') {assertAttemptReplay(raw,root,limits);return {state:raw,projections:new Map()};}
  replayObject(raw,['schemaVersion','evidence','results','closures'],'attempt-v2-envelope');
  replayAssert(raw.schemaVersion==='durable-attempt-store.v2'&&Array.isArray(raw.results),'attempt-v2-version');
  const projected=raw.results.filter((item):item is ProjectedResultMetadata=>Object.hasOwn(item,'resultReference'));
  replayAssert(projected.length>0,'attempt-v2-empty-projections');
  for(const item of projected)assertReference(item,root,limits.maximumMetadataBytes);
  const maximumPrefix=projected.reduce((maximum,item)=>Math.max(maximum,item.resultReference.journalPrefixBytes),0);
  const journal=attemptImportJournal(root),bytes=readPrefix(journal,limits.maximumMetadataBytes,maximumPrefix);
  replayAssert(bytes.length===maximumPrefix,'attempt-journal-prefix-length');
  const records=parseHashJournal<ImportEntry>(bytes,journal),ends=offsets(bytes),projections:AttemptProjections=new Map();
  const results=raw.results.map(item=>{
    if(!('resultReference' in item))return item;
    const ref=item.resultReference,record=records[ref.intent.journalSequence-1];
    replayAssert(record&&ends[ref.intent.journalSequence-1]===ref.journalPrefixBytes,'attempt-journal-prefix-binding');
    const key=attemptProjectionKey(item);replayAssert(!projections.has(key),'attempt-result-projection-duplicate');projections.set(key,item);
    const {resultReference:_,...metadata}=item;
    return {...metadata,result:resolveResult(item,record)};
  });
  const state:DurableAttemptStoreSnapshot={...raw,schemaVersion:'durable-attempt-store.v1',results};
  assertAttemptReplay(state,root,limits,projections.size);
  return {state,projections};
}

export function encodeAttemptState(state:DurableAttemptStoreSnapshot,projections:AttemptProjections):DurableAttemptStoreSnapshot|PersistedAttemptV2 {
  if(!projections.size)return state;
  let found=0;
  const results=state.results.map(item=>{
    const projected=projections.get(attemptProjectionKey(item));if(!projected)return item;
    const {result,...metadata}=item,{resultReference,...retained}=projected;
    replayAssert(result.resultDigest===resultReference.intent.resultDigest&&canonicalJson(metadata)===canonicalJson(retained),'attempt-projection-mutated');
    found++;return projected;
  });
  replayAssert(found===projections.size,'attempt-projection-removed');
  return {...state,schemaVersion:'durable-attempt-store.v2',results};
}

export function createAttemptProjection(item:DurableResultMetadata,intent:AttemptRetirementIntent,root:string,maximumBytes:number):ProjectedResultMetadata {
  assertAttemptRetirementIntent(intent,root);
  const journal=attemptImportJournal(root),bytes=readAttemptJournalPrefix(journal,maximumBytes);
  const records=parseHashJournal<ImportEntry>(bytes,journal),end=offsets(bytes)[intent.journalSequence-1];
  replayAssert(end!==undefined,'attempt-import-checkpoint-missing');
  const {result,...metadata}=item;
  const projected:ProjectedResultMetadata={...metadata,resultReference:{schemaVersion:'attempt-result-reference.v1',intent:structuredClone(intent),journalPrefixBytes:end}};
  assertReference(projected,root,maximumBytes);
  replayAssert(canonicalJson(resolveResult(projected,records[intent.journalSequence-1]!))===canonicalJson(result),'attempt-import-result-changed');
  return projected;
}

function sameProducer(left: ProducerIdentityV1, right: ProducerIdentityV1): boolean {
  return canonicalJson(left) === canonicalJson(right);
}

export function assertCompletionIntent(pipelineRunId: string, snapshot: WorkerAttemptResultV1, intent: DurableCompletionIntent | null): void {
  if (intent === null) return;
  replayObject(intent, ['record', 'closure'], 'attempt-intent');
  validatePipelineObservabilityContract('producerRecord', intent.record);
  validatePipelineObservabilityContract('producerClosure', intent.closure);
  const declared = new Set(intent.closure.requiredEvidenceIds);
  const evidenceBound = snapshot.evidence.every((item) => declared.has(scopedEvidenceId(snapshot.attemptId, snapshot.claimGeneration, item.evidenceId)));
  const payload = intent.record.payload as Record<string, unknown> | null;
  if (intent.record.recordType !== 'attempt.completed' || !payload || payload.resultDigest !== snapshot.resultDigest || payload.workerId !== snapshot.workerId
    || intent.record.correlation.pipelineRunId !== pipelineRunId || intent.record.correlation.attemptId !== snapshot.attemptId
    || intent.record.correlation.claimId !== snapshot.claimId || intent.record.correlation.claimGeneration !== snapshot.claimGeneration
    || intent.closure.pipelineRunId !== pipelineRunId || !sameProducer(intent.record.producer, intent.closure.producer) || !evidenceBound) {
    throw new Error('OBSERVABILITY_COMPLETION_INTENT_IDENTITY_MISMATCH');
  }
}

function evidenceKey(item: { pipelineRunId: string; attemptId: string; claimGeneration: number; evidenceId: string }): string {
  return canonicalJson([item.pipelineRunId, item.attemptId, item.claimGeneration, item.evidenceId]);
}

function evidenceReplay(item: DurableEvidenceMetadata, root: string, keys: Set<string>): void {
  replayObject(item, ['pipelineRunId', 'attemptId', 'claimGeneration', 'producer', 'evidenceId', 'type', 'mediaType', 'artifact', 'stagedAt'], 'attempt-evidence');
  for (const field of ['pipelineRunId', 'attemptId', 'evidenceId', 'type', 'mediaType'] as const) replayAssert(replayIdentity(item[field]), `attempt-evidence-${field}`);
  replayAssert(Number.isSafeInteger(item.claimGeneration) && item.claimGeneration > 0 && replayTimestamp(item.stagedAt), 'attempt-evidence-generation');
  validatePipelineObservabilityContract('producerIdentity', item.producer);
  validatePipelineWorkerCoreContract('workerEvidenceRef', { evidenceId: item.evidenceId, type: item.type, artifact: item.artifact });
  const hex = item.artifact.contentDigest.slice(7);
  replayAssert(item.artifact.artifactId === `artifact:${hex}` && item.artifact.type === item.type && item.artifact.mediaType === item.mediaType
    && item.artifact.storageUrl === pathToFileURL(path.join(root, 'blobs', hex.slice(0, 2), hex)).href, 'attempt-evidence-artifact');
  replayUnique(keys, evidenceKey(item), 'attempt-evidence-duplicate');
}

function resultReplay(item: DurableResultMetadata, evidence: Map<string, DurableEvidenceMetadata>, keys: Set<string>): void {
  replayObject(item, ['pipelineRunId', 'planId', 'nodeId', 'attemptId', 'claimGeneration', 'workerId', 'result', 'completionIntent', 'storedAt'], 'attempt-result');
  replayAssert(replayIdentity(item.pipelineRunId) && (item.storedAt === null || replayTimestamp(item.storedAt)), 'attempt-result-metadata');
  replayAssert((item.planId === null && item.nodeId === null) || (replayIdentity(item.planId) && replayIdentity(item.nodeId)), 'attempt-result-owner');
  validatePipelineWorkerCoreContract('workerAttemptResult', item.result);
  replayAssert(item.attemptId === item.result.attemptId && item.claimGeneration === item.result.claimGeneration && item.workerId === item.result.workerId, 'attempt-result-identity');
  replayUnique(keys, canonicalJson([item.pipelineRunId, item.attemptId, item.claimGeneration]), 'attempt-result-duplicate');
  assertCompletionIntent(item.pipelineRunId, item.result, item.completionIntent);
  if (item.completionIntent !== null) closureEvidenceReplay(item.completionIntent.closure, evidence.values());
  for (const reference of item.result.evidence) {
    const metadata = evidence.get(evidenceKey({ ...item, evidenceId: reference.evidenceId }));
    replayAssert(metadata && canonicalJson(metadata.artifact) === canonicalJson(reference.artifact) && metadata.type === reference.type, 'attempt-result-evidence');
    if (item.completionIntent !== null) replayAssert(sameProducer(metadata.producer, item.completionIntent.record.producer), 'attempt-result-evidence-producer');
  }
}

function closureEvidenceReplay(closure: ProducerClosureV1, evidence: Iterable<DurableEvidenceMetadata>): void {
  for (const metadata of evidence) {
    if (metadata.pipelineRunId !== closure.pipelineRunId) continue;
    const scoped = scopedEvidenceId(metadata.attemptId, metadata.claimGeneration, metadata.evidenceId);
    if (closure.requiredEvidenceIds.includes(scoped)) replayAssert(sameProducer(metadata.producer, closure.producer), 'attempt-closure-evidence-producer');
  }
  // Closure-only staged evidence may already have expired under the existing
  // retention contract. Missing bytes/metadata remain a completeness issue;
  // present metadata must never contradict the closure's producer identity.
}

export function assertAttemptReplay(state: DurableAttemptStoreSnapshot, root: string, limits: DurableAttemptStoreLimits, validatedProjectedResults = 0): void {
  replayObject(state, ['schemaVersion', 'evidence', 'results', 'closures'], 'attempt-envelope');
  replayAssert(state.schemaVersion === 'durable-attempt-store.v1' && Array.isArray(state.evidence) && Array.isArray(state.results) && Array.isArray(state.closures), 'attempt-version');
  replayAssert(Number.isSafeInteger(validatedProjectedResults) && validatedProjectedResults >= 0 && validatedProjectedResults <= state.results.length, 'attempt-projection-count');
  replayAssert(state.evidence.length <= limits.maximumEvidenceObjects && state.results.length - validatedProjectedResults <= limits.maximumResults && state.closures.length <= limits.maximumClosures, 'attempt-count');
  const evidenceKeys = new Set<string>();
  const evidence = new Map<string, DurableEvidenceMetadata>();
  for (const item of state.evidence) { evidenceReplay(item, root, evidenceKeys); evidence.set(evidenceKey(item), item); }
  const resultKeys = new Set<string>();
  const generations = new Map<string, number>();
  for (const item of state.results) {
    resultReplay(item, evidence, resultKeys);
    const attemptKey = canonicalJson([item.pipelineRunId, item.attemptId]);
    replayAssert(item.claimGeneration > (generations.get(attemptKey) ?? 0), 'attempt-generation-order');
    generations.set(attemptKey, item.claimGeneration);
  }
  const closureKeys = new Set<string>();
  for (const closure of state.closures) {
    validatePipelineObservabilityContract('producerClosure', closure);
    closureEvidenceReplay(closure, state.evidence);
    replayUnique(closureKeys, canonicalJson([closure.pipelineRunId, closure.closureId]), 'attempt-closure-duplicate');
    const owners = state.results.filter((item) => item.pipelineRunId === closure.pipelineRunId && item.completionIntent?.closure.closureId === closure.closureId);
    for (const owner of owners) replayAssert(canonicalJson(owner.completionIntent!.closure) === canonicalJson(closure), 'attempt-closure-intent');
  }
}

