function scopeValue(input) {
  const scope = structuredClone(input);
  if (!scope || Object.keys(scope).sort().join(',') !== 'action,intent,inventoryLimits,novaStorageRoot,orchestratorIssuerId,schemaVersion'
    || scope.schemaVersion !== 'operator-request-retirement-scope.v1' || scope.action !== 'compact-completed-human-approval-request'
    || typeof scope.novaStorageRoot !== 'string' || !path.isAbsolute(scope.novaStorageRoot) || path.resolve(scope.novaStorageRoot) !== scope.novaStorageRoot
    || typeof scope.orchestratorIssuerId !== 'string' || !scope.orchestratorIssuerId
    || !scope.inventoryLimits || Object.keys(scope.inventoryLimits).sort().join(',') !== 'maximumFiles,maximumSnapshotBytes,maximumTotalBytes') {
    throw new Error('OPERATOR_RETENTION_SCOPE_INVALID');
  }
  assertDeliveryProjectionIntent(scope.intent);
  return scope;
}

function assertInventory(inventory) {
  const blocker = inventory.blockers.find(item => item.code !== 'RUN_RETIREMENT_AUTHORIZATION_MISSING');
  if (blocker) throw new Error(`OPERATOR_RETENTION_BLOCKED:${blocker.code}`);
}

function distinctRoots(scope) {
  const inventory = new Inventory(scope.inventoryLimits), roots = [scope.intent.waitRoot, scope.intent.deliveryRoot];
  const identities = new Set();
  for (const root of roots) {
    inventory.root(root, root, false);
    if (roots.some(other => other !== root && (root.startsWith(`${other}${path.sep}`) || other.startsWith(`${root}${path.sep}`)))) throw new Error('OPERATOR_RETENTION_ALIASED_STORE');
    const stat = fs.lstatSync(path.join(root, 'records/store.json')), id = `${stat.dev}:${stat.ino}`;
    if (!stat.isFile() || stat.isSymbolicLink() || stat.nlink !== 1 || identities.has(id)) throw new Error('OPERATOR_RETENTION_ALIASED_STORE');
    identities.add(id);
  }
  return inventory;
}

function retainedRun(scope) {
  const inventory = new Inventory(scope.inventoryLimits);
  inventory.root(scope.intent.runRoot, scope.intent.runId);
  const run = inspectRun(inventory, scope.intent.runRoot, scope.intent.runId);
  if (run.snapshot?.digest !== scope.intent.snapshotDigest
    || run.journals.find(item => item.path === path.join(scope.intent.runRoot, 'events.jsonl'))?.head !== scope.intent.runJournalHead) throw new Error('OPERATOR_RETENTION_RUN_CHANGED');
  const configuration = operatorConfiguration(inventory, scope);
  assertInventory(inventory);
  return { inventory, configuration };
}

function finalReceipt(records, scope, authority) {
  const selected = records.filter(record => record.stream === `notifications/${authority.request.resource.canonicalId}`
    && record.payload?.schemaVersion === 'notification-delivery-receipt.v1'
    && record.payloadDigest === scope.intent.terminalPayloadDigest);
  if (selected.length !== 1 || payloadDigest(selected[0].payload.receipt) !== payloadDigest(authority.receipt)) throw new Error('OPERATOR_RETENTION_RECEIPT_CHANGED');
}

export async function retireOperatorRequest(input) {
  const scope = scopeValue(input), roots = distinctRoots(scope);
  const canonical = runRoot(scope.novaStorageRoot, scope.intent.runId, { maximumLegacyBytes: scope.inventoryLimits.maximumSnapshotBytes });
  if (canonical !== scope.intent.runRoot) throw new Error('OPERATOR_RETENTION_FOREIGN_RUN');
  return withRunMutationLock(canonical, async signal => {
    signal.throwIfAborted();
    const initial = retainedRun(scope), config = initial.configuration;
    const waits = new FileDurableRecordStore(scope.intent.waitRoot, config.waitLimits);
    const deliveries = new FileDurableRecordStore(scope.intent.deliveryRoot, config.deliveryLimits);
    return waits.withRecords('waits/all', async waitRecords => {
      const authority = operatorAuthority(initial.inventory, scope, config, waitRecords);
      return projectDeliveryRequest(deliveries, authority.request, scope.intent, authority.digest, records => {
        signal.throwIfAborted();
        const current = retainedRun(scope), confirmed = operatorAuthority(current.inventory, scope, current.configuration, waitRecords);
        if (confirmed.digest !== authority.digest) throw new Error('OPERATOR_RETENTION_AUTHORITY_CHANGED');
        finalReceipt(records, scope, confirmed);
        initial.inventory.verifyUnchanged(); current.inventory.verifyUnchanged(); roots.verifyUnchanged();
        for (const inventory of [initial.inventory, current.inventory, roots]) assertInventory(inventory);
        signal.throwIfAborted();
      });
    });
  });
}

async function main() {
  if (process.argv.length !== 4 || process.argv[2] !== '--apply' || !path.isAbsolute(process.argv[3])) throw new Error('OPERATOR_RETENTION_USAGE');
  const file = process.argv[3], inventory = new Inventory({ maximumFiles: 1, maximumTotalBytes: 1048576, maximumSnapshotBytes: 1048576 });
  inventory.root(path.dirname(file), 'scope', false);
  const stat = fs.lstatSync(file);
  if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 1048576) throw new Error('OPERATOR_RETENTION_SCOPE_FILE_INVALID');
  inventory.files.set(file, { path: file, bytes: stat.size, stamp: `${stat.dev}:${stat.ino}:${stat.size}:${stat.mtimeMs}:${stat.ctimeMs}`,
    hash: inventory.hashFile(file, stat), disposition: 'retain' });
  console.log(JSON.stringify(await retireOperatorRequest(inventory.json(file))));
}

source:skills/common/plugins/operator-me.syntax:
export interface DeliveryProjectionIntent {
  readonly operationId: string;
  readonly actor: string;
  readonly runId: string;
  readonly runRoot: string;
  readonly deliveryRoot: string;
  readonly waitRoot: string;
  readonly effectKey: string;
  readonly expectedPayloadDigest: string;
  readonly terminalPayloadDigest: string;
  readonly runJournalHead: string;
  readonly snapshotDigest: string;
}

interface ProjectionReceipt {
  readonly schemaVersion: 'operator-request-projection-receipt.v1';
  readonly intent: DeliveryProjectionIntent;
  readonly intentDigest: string;
  readonly authorityDigest: string;
  readonly releasedBytesHex: string;
}

interface ProjectedRequest {
  readonly schemaVersion: 'notification-delivery-request-projected.v1';
  readonly originalDigest: string;
  readonly deliveryId: string;
  readonly target: string;
  readonly attempt: EffectRequest['attempt'];
  readonly effectId: string;
  readonly terminalKey: string;
  readonly terminalDigest: string;
  readonly projection: ProjectionReceipt;
}

export function deliveryRequestKey(request: EffectRequest): string {
  return `delivery:request:${hash(request.idempotencyKey)}`;
}

export function originalJsonDeliveryCandidate(request: EffectRequest, transportPayload?: Payload): Payload {
  if (request.deliveryId !== undefined || request.capability !== 'operator.request' || request.operation !== 'publish'
    || request.resource.type !== 'operator.target') fail();
  const payload = parsePayload(request.payload, 1048576);
  if (transportPayload !== undefined && !same(payload, transportPayload)) fail();
  return { schemaVersion: 'notification-delivery-request.v1', idempotencyKey: request.idempotencyKey,
    target: request.resource.canonicalId, payload };
}

export function assertDeliveryProjectionIntent(intent: DeliveryProjectionIntent): void {
  if (!shape(intent, 'actor,deliveryRoot,effectKey,expectedPayloadDigest,operationId,runId,runJournalHead,runRoot,snapshotDigest,terminalPayloadDigest,waitRoot')
    || ![intent.operationId, intent.actor, intent.runId, intent.effectKey].every(value => typeof value === 'string'
      && value.length > 0 && value.length <= 256 && !/[\u0000-\u001f\u007f]/u.test(value))
    || ![intent.runRoot, intent.deliveryRoot, intent.waitRoot].every(value => typeof value === 'string'
      && path.isAbsolute(value) && path.resolve(value) === value)
    || ![intent.expectedPayloadDigest, intent.terminalPayloadDigest, intent.runJournalHead, intent.snapshotDigest].every(digest)) fail();
}

function retainedTerminal(records: ReadonlyArray<DurableRecord>, request: EffectRequest): DurableRecord<Payload> {
  const stream = `notifications/${request.resource.canonicalId}`, suffix = `:${hash(request.idempotencyKey)}`;
  const selected = records.filter(record => record.stream === stream && record.idempotencyKey.endsWith(suffix)
    && record.idempotencyKey !== deliveryRequestKey(request));
  const key = `delivery:attempt-${request.attempt.attemptNumber}-${hash(request.attempt.attemptId).slice(0, 16)}${suffix}`;
  const terminal = selected[0] as DurableRecord<Payload> | undefined;
  if (selected.length !== 1 || !terminal || terminal.idempotencyKey !== key
    || !shape(terminal.payload, 'attempt,receipt,schemaVersion')
    || terminal.payload.schemaVersion !== 'notification-delivery-receipt.v1'
    || !same(terminal.payload.attempt, request.attempt)) fail();
  assertJsonReceipt(terminal.payload.receipt as Payload | undefined, request.resource.canonicalId);
  return terminal;
}

function assertJsonReceipt(receipt: Payload | undefined, target: string): void {
  if (!receipt || receipt.accepted !== true || receipt.target !== target
    || !Number.isInteger(receipt.status) || Number(receipt.status) < 200 || Number(receipt.status) >= 300
    || Object.keys(receipt).some(key => !['accepted', 'target', 'status', 'messageId'].includes(key))
    || (receipt.messageId !== undefined && (typeof receipt.messageId !== 'string' || !receipt.messageId || receipt.messageId.length > 512))) fail();
}

function assertProjection(value: ProjectedRequest, request: EffectRequest, terminal: DurableRecord<Payload>, candidate: Payload): void {
  if (!shape(value, 'attempt,deliveryId,effectId,originalDigest,projection,schemaVersion,target,terminalDigest,terminalKey')
    || !shape(value.projection, 'authorityDigest,intent,intentDigest,releasedBytesHex,schemaVersion')) fail();
  const receipt = value.projection;
  assertDeliveryProjectionIntent(receipt.intent);
  if (receipt.schemaVersion !== 'operator-request-projection-receipt.v1'
    || !digest(receipt.authorityDigest) || receipt.intentDigest !== payloadDigest(receipt.intent)
    || !/^[a-f0-9]{16}$/u.test(receipt.releasedBytesHex) || Number.parseInt(receipt.releasedBytesHex, 16) < 1
    || !Number.isSafeInteger(Number.parseInt(receipt.releasedBytesHex, 16))) fail();
  assertProjectionBinding(value, request, terminal, candidate);
}

function assertProjectionBinding(value: ProjectedRequest, request: EffectRequest, terminal: DurableRecord<Payload>, candidate: Payload): void {
  const receipt = value.projection;
  if (value.originalDigest !== payloadDigest(candidate) || value.originalDigest !== receipt.intent.expectedPayloadDigest
    || value.deliveryId !== request.idempotencyKey || receipt.intent.effectKey !== request.idempotencyKey
    || value.target !== request.resource.canonicalId || !same(value.attempt, request.attempt)
    || receipt.intent.runId !== request.attempt.runId || value.effectId !== request.effectId
    || value.terminalKey !== terminal.idempotencyKey || value.terminalDigest !== terminal.payloadDigest
    || receipt.intent.terminalPayloadDigest !== terminal.payloadDigest) fail();
}

export function projectedDeliveryReceipt(records: ReadonlyArray<DurableRecord>, request: EffectRequest, transportPayload?: Payload): Payload | undefined {
  const record = records.find(entry => entry.stream === `notifications/${request.resource.canonicalId}`
    && entry.idempotencyKey === deliveryRequestKey(request));
  if ((record?.payload as Payload | undefined)?.schemaVersion !== 'notification-delivery-request-projected.v1') return undefined;
  const candidate = originalJsonDeliveryCandidate(request, transportPayload), terminal = retainedTerminal(records, request);
  assertProjection(record!.payload as ProjectedRequest, request, terminal, candidate);
  return terminal.payload.receipt as Payload;
}

export async function projectDeliveryRequest(records: FileDurableRecordStore, request: EffectRequest, intent: DeliveryProjectionIntent,
  authorityDigest: string, authorize: (records: ReadonlyArray<DurableRecord>) => void): Promise<{ newlyProjected: boolean; releasedBytes: number }> {
  request = structuredClone(request); intent = structuredClone(intent);
  assertDeliveryProjectionIntent(intent);
  const candidate = originalJsonDeliveryCandidate(request), stream = `notifications/${request.resource.canonicalId}`;
  if (!digest(authorityDigest) || intent.runId !== request.attempt.runId || intent.effectKey !== request.idempotencyKey
    || intent.expectedPayloadDigest !== payloadDigest(candidate)) fail();
  const observed = await records.read(stream), terminal = retainedTerminal(observed, request);
  if (terminal.payloadDigest !== intent.terminalPayloadDigest) fail();
  if (projectedDeliveryReceipt(observed, request)) {
    return records.withRecords(stream, async current => {
      if (!projectedDeliveryReceipt(current, request)) fail();
      const stored = current.find(record => record.idempotencyKey === deliveryRequestKey(request))!.payload as ProjectedRequest;
      if (!same(stored.projection.intent, intent) || stored.projection.authorityDigest !== authorityDigest) fail();
      if (authorize(current) !== undefined) fail();
      return { newlyProjected: false, releasedBytes: 0 };
    });
  }
  const projection: ProjectionReceipt = { schemaVersion: 'operator-request-projection-receipt.v1', intent,
    intentDigest: payloadDigest(intent), authorityDigest, releasedBytesHex: '0000000000000000' };
  const value: ProjectedRequest = { schemaVersion: 'notification-delivery-request-projected.v1', originalDigest: intent.expectedPayloadDigest,
    deliveryId: request.idempotencyKey, target: request.resource.canonicalId, attempt: request.attempt, effectId: request.effectId,
    terminalKey: terminal.idempotencyKey, terminalDigest: terminal.payloadDigest, projection };
  const original = observed.find(record => record.idempotencyKey === deliveryRequestKey(request));
  if (!original || original.payloadDigest !== intent.expectedPayloadDigest) fail();
  const replacement = { ...original, committedAt: '2000-01-01T00:00:00.000Z', payloadDigest: payloadDigest(value), payload: value };
  const releasedBytes = Buffer.byteLength(canonicalJson(original)) - Buffer.byteLength(canonicalJson(replacement));
  if (releasedBytes < 1) throw new Error('OPERATOR_PROJECTION_NO_NET_SAVINGS');
  const retained = { ...value, projection: { ...projection, releasedBytesHex: releasedBytes.toString(16).padStart(16, '0') } };
  await records.transition(stream, deliveryRequestKey(request), intent.expectedPayloadDigest, retained, current => {
    const actual = retainedTerminal(current, request);
    if (actual.payloadDigest !== terminal.payloadDigest) fail();
    if (authorize(current) !== undefined) fail();
  });
  return { newlyProjected: true, releasedBytes };
}

source:contracts/pipeline-test-gate/v1/s.syntax:
import type {
  AttemptResultV1,
  NodeResultV1,
  RemotePlanJobV1,
  RemotePlanResultV1,
  RepositoryArchiveV1,
  ResolvedTestPlanV1,
  SourceSnapshotV1,
} from './types.ts';

export function remotePlanJobId(idempotencyKey: string): string {
  return `job:${crypto.createHash('sha256').update(idempotencyKey).digest('hex')}`;
}

export function resolvedTestPlanDigest(
  value: Omit<ResolvedTestPlanV1, 'planDigest'> | ResolvedTestPlanV1,
): string {
  const { planDigest: _ignored, ...unsigned } = value as ResolvedTestPlanV1;
  return remotePlanDigest(unsigned);
}

export function stableTestIdentity(value: {
  project: string;
  moduleId: string | null;
  gateId: string | null;
  suiteInstanceId: string | null;
  nodeId: string;
  variation: Readonly<Record<string, unknown>>;
}): string {
  return `test:${crypto.createHash('sha256').update(canonicalJson(value)).digest('hex')}`;
}

export function repositoryArchive(content: Uint8Array): RepositoryArchiveV1 {
  const bytes = Buffer.from(content);
  return Object.freeze({
    schemaVersion: 'repository-archive.v1',
    encoding: 'base64',
    contentDigest: `sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}`,
    sizeBytes: bytes.byteLength,
    data: bytes.toString('base64'),
  });
}

export function repositoryArchiveBytes(value: RepositoryArchiveV1): Buffer {
  const bytes = Buffer.from(value.data, 'base64');
  if (
    value.schemaVersion !== 'repository-archive.v1'
    || value.encoding !== 'base64'
    || bytes.toString('base64') !== value.data
    || bytes.byteLength !== value.sizeBytes
    || `sha256:${crypto.createHash('sha256').update(bytes).digest('hex')}` !== value.contentDigest
  ) throw new Error('REMOTE_PLAN_ARCHIVE_INVALID');
  return bytes;
}

function unsignedSourceSnapshot(value: Omit<SourceSnapshotV1, 'attestation'> | SourceSnapshotV1) {
  const { attestation: _ignored, ...unsigned } = value as SourceSnapshotV1;
  return unsigned;
}

function sourceSnapshotAttestationMessage(
  value: Omit<SourceSnapshotV1, 'attestation'> | SourceSnapshotV1,
): Buffer {
  return Buffer.from(`kubeclaw-source-snapshot-v1\0${canonicalJson(unsignedSourceSnapshot(value))}`, 'utf8');
}

export function attestSourceSnapshot(
  value: Omit<SourceSnapshotV1, 'attestation'>,
  privateKey: string | Buffer,
): SourceSnapshotV1 {
  let key: crypto.KeyObject;
  try { key = crypto.createPrivateKey(privateKey); }
  catch (error) { throw new Error('SOURCE_SNAPSHOT_PRIVATE_KEY_INVALID', { cause: error }); }
  if (key.asymmetricKeyType !== 'ed25519') throw new Error('SOURCE_SNAPSHOT_PRIVATE_KEY_INVALID');
  return Object.freeze({ ...value, attestation: Object.freeze({
    schemaVersion: 'source-snapshot-attestation.v1', algorithm: 'ed25519',
    authority: value.creatorAuthority,
    signature: crypto.sign(null, sourceSnapshotAttestationMessage(value), key).toString('base64'),
  }) });
}

export function verifySourceSnapshotAttestation(
  value: SourceSnapshotV1,
  expectedAuthority: string,
  publicKey: string | Buffer,
): boolean {
  if (
    value.creatorAuthority !== expectedAuthority
    || value.attestation.authority !== expectedAuthority
    || value.attestation.schemaVersion !== 'source-snapshot-attestation.v1'
    || value.attestation.algorithm !== 'ed25519'
  ) return false;
  try {
    const key = crypto.createPublicKey(publicKey);
    return key.asymmetricKeyType === 'ed25519'
      && crypto.verify(null, sourceSnapshotAttestationMessage(value), key,
        Buffer.from(value.attestation.signature, 'base64'));
  } catch { return false; }
}

export function remotePlanJobDigest(value: Omit<RemotePlanJobV1, 'requestDigest'> | RemotePlanJobV1): string {
  const { requestDigest: _ignored, ...unsigned } = value as RemotePlanJobV1;
  return remotePlanDigest(unsigned);
}

export function remotePlanResultDigest(
  value: Omit<RemotePlanResultV1, 'resultDigest' | 'receipt'> | RemotePlanResultV1,
): string {
  const { resultDigest: _digest, receipt: _receipt, ...unsigned } = value as RemotePlanResultV1;
  return remotePlanDigest(unsigned);
}

export function attemptResultDigest(
  value: Omit<AttemptResultV1, 'resultDigest' | 'receipt'> | AttemptResultV1,
): string {
  const { resultDigest: _digest, receipt: _receipt, ...unsigned } = value as AttemptResultV1;
  return remotePlanDigest(unsigned);
}

export function nodeResultDigest(
  value: Omit<NodeResultV1, 'resultDigest' | 'receipt'> | NodeResultV1,
): string {
  const { resultDigest: _digest, receipt: _receipt, ...unsigned } = value as NodeResultV1;
  return remotePlanDigest(unsigned);
}

export function remotePlanResultReceipt(jobId: string, resultDigest: string) {
  const receiptId = `receipt:${crypto.createHash('sha256').update(`${jobId}:${resultDigest}`).digest('hex')}`;
  return Object.freeze({
    receiptId,
    receiptDigest: remotePlanDigest({ authority: 'buster-plan-service.v1', receiptId, resultDigest }),
  });
}

