function relativeModule(value) {
  if (typeof value !== 'string') return null;
  const normalized = value.replace(/^\.\//u, '');
  return /\.(?:[cm]?[jt]sx?)$/u.test(normalized) && !normalized.startsWith('dist/')
    ? normalized
    : null;
}

function packageEntrypoints(packageJson) {
  const entries = [];
  const visit = (value) => {
    if (typeof value === 'string') {
      const entry = relativeModule(value);
      if (entry) entries.push(entry);
      return;
    }
    if (Array.isArray(value)) {
      value.forEach(visit);
      return;
    }
    if (value && typeof value === 'object') Object.values(value).forEach(visit);
  };
  visit(packageJson.main);
  visit(packageJson.bin);
  visit(packageJson.exports);
  visit(packageJson.openclaw?.extensions);
  return entries;
}

function pluginEntrypoints(pluginJson) {
  return ['stages', 'observers', 'adapters', 'testProviders', 'reportAdapters']
    .flatMap((kind) => Array.isArray(pluginJson?.[kind]) ? pluginJson[kind] : [])
    .map((registration) => relativeModule(registration?.module))
    .filter(Boolean);
}

function childDirectories(parent) {
  const absolute = path.join(repoRoot, parent);
  if (!fs.existsSync(absolute)) return [];
  return fs.readdirSync(absolute, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => path.posix.join(parent, entry.name))
    .sort();
}

function pluginWorkspace(directory) {
  const packageJson = readJson(path.posix.join(directory, 'package.json'));
  const manifestPath = path.posix.join(directory, 'plugin.json');
  const manifestEntries = fs.existsSync(path.join(repoRoot, manifestPath))
    ? pluginEntrypoints(readJson(manifestPath))
    : [];
  const overrides = {
    'skills/common/plugins/openclaw-agent-observer': ['src/index.ts'],
  }[directory] ?? [];
  const entry = [...new Set([
    ...manifestEntries,
    ...packageEntrypoints(packageJson),
    ...overrides,
    'tests/**/*.{mjs,mts,ts}',
  ])].sort();
  if (entry.length === 1) throw new Error(`No production entrypoint discovered for ${directory}`);
  return {
    entry,
    project: [
      'src/**/*.{ts,mjs}',
      'common/**/*.{ts,mjs}',
      'contracts/**/*.{ts,mjs}',
      'tests/**/*.{ts,mts,mjs}',
    ],
  };
}

const workspaces = {
  '.': {
    // The live Kubernetes fixture invokes this host executable via execFileSync;
    // it is not a JavaScript module import.
    ignoreUnresolved: ['^/usr/local/bin/kubectl$'],
    entry: [
      'scripts/**/*.{mjs,cjs}',
      'charts/kubeclaw/files/config/eslint*.mjs',
      'skills/nova/pipeline.ts',
      'skills/nova/project_setup/**/*.ts',
      'tests/**/*.{mjs,mts,ts}',
      ...childDirectories('tests/fixtures/plugin-system-v2').flatMap(directory => {
        const manifest = path.posix.join(directory, 'plugin.json');
        return fs.existsSync(path.join(repoRoot, manifest))
          ? pluginEntrypoints(readJson(manifest)).map(entry => path.posix.join(directory, entry)) : [];
      }),
    ],
    project: [
      'scripts/**/*.{js,mjs,cjs}',
      'charts/kubeclaw/files/config/*.mjs',
      'skills/nova/pipeline.ts',
      'skills/nova/project_setup/**/*.{ts,mjs}',
      'tests/**/*.{js,mjs,mts,cjs,ts}',
    ],
  },
  'contracts/agent-observability/v1': {
    entry: ['src/index.ts'],
    project: ['src/**/*.ts'],
  },
  'contracts/pipeline-test-gate/v1': {
    entry: [...packageEntrypoints(readJson('contracts/pipeline-test-gate/v1/package.json')), 'tests/**/*.ts'],
    project: ['src/**/*.ts', 'tests/**/*.ts'],
  },
  'contracts/prism/v1': {
    entry: [...packageEntrypoints(readJson('contracts/prism/v1/package.json')),
      'src/validators.generated.d.mts', 'tests/**/*.mts'],
    project: ['src/**/*.{ts,mts,mjs}', 'tests/**/*.mts'],
  },
  'skills/common/plugin-runtime/foundation': {
    entry: ['isolation/child.mjs'],
    project: ['**/*.{ts,mjs}'],
  },
  'skills/nova/core': {
    entry: ['src/index.ts', 'cli.ts'],
    project: ['**/*.{ts,mjs}'],
  },
  'skills/worker/core': {
    entry: ['src/index.ts'],
    project: ['**/*.{ts,mjs}'],
  },
  'skills/buster/engine': {
    entry: ['src/index.ts', 'test-gates/provider-child.mjs', 'test-gates/report-adapter-child.mjs'],
    project: ['**/*.{ts,mjs}'],
  },
  'skills/common/plugin-runtime/sdk': {
    entry: ['src/index.ts', 'src/testing/index.ts'],
    project: ['src/**/*.ts'],
  },
  'skills/prism': {
    entry: [...packageEntrypoints(readJson('skills/prism/package.json')),
      'server/{control,worker,studio}.ts', 'server/agent-bridge.mjs',
      'tests/**/*.{ts,mts,mjs}', 'integration/*.mts', 'studio/*.test.tsx', 'studio/main.tsx'],
    project: ['**/*.{ts,tsx,mts,mjs}'],
  },
  'tools/ops-mcp': {
    entry: ['src/server.mjs', 'test/*.test.mjs'],
    project: ['src/**/*.mjs', 'test/**/*.mjs'],
  },
  'spikes/prism/puck-adapter': {
    entry: ['tests/*.test.ts'],
    project: ['**/*.{ts,tsx}'],
    // Puck's transitive @tiptap/react and Radix packages require these peers.
    // This source-only adapter does not import their DOM entrypoints directly.
    ignoreDependencies: ['react-dom', '@types/react-dom'],
  },
};

if (checkOnly) {
  const current = fs.existsSync(outputPath) ? fs.readFileSync(outputPath, 'utf8') : '';
  if (current !== rendered) {
    console.error(`Generated Knip configuration is stale: ${path.relative(repoRoot, outputPath)}`);
    process.exit(1);
  }
  console.log(JSON.stringify({ ok: true, plugins: pluginDirectories.length, output: path.relative(repoRoot, outputPath) }));
} else {
  fs.writeFileSync(outputPath, rendered);
  console.log(JSON.stringify({ ok: true, plugins: pluginDirectories.length, output: path.relative(repoRoot, outputPath) }));
}

source:scripts/gitops-continuous.mjs.syntax:
export function continuousDocuments(result, namespace) {
  const documents = structuredClone(result.documents);
  const application = documents.find(document => document.kind === 'Application');
  application.spec.source = { repoURL: result.values.repository, targetRevision: 'main',
    path: `${environment}/apps`, directory: { include: 'applications.yaml' } };
  if (application.metadata.namespace !== namespace) throw new Error('GITOPS_ARGO_NAMESPACE_MISMATCH');
  return documents;
}

export function continuousApplications(manifest) {
  const documents = yaml.loadAll(manifest).filter(Boolean);
  for (const document of documents) {
    if (document.kind === 'Application') {
      // Unique bundle directories survive later promotions. Tracking main also
      // survives squash merges; no transient PR commit needs to stay reachable.
      document.spec.source.targetRevision = 'main';
    }
  }
  return documents;
}

function configuration(repository) {
  const config = JSON.parse(fs.readFileSync(path.join(repository, environment, 'config.json'), 'utf8'));
  for (const field of ['namespace', 'prismNamespace', 'argoNamespace']) {
    if (!gitOpsName(config[field])) throw new Error(`GITOPS_CONFIG_INVALID:${field}`);
  }
  return config;
}

export function renderContinuousEnvironment(repository, directory, url, revision, config) {
  const result = bootstrapDocuments(repository, directory, url, revision, config.argoNamespace);
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'gitops-continuous-'));
  try {
    const values = path.join(temporary, 'values.yaml');
    fs.writeFileSync(values, yaml.dump(result.values));
    const rendered = execFileSync('helm', ['template', 'runtime', path.join(repository, 'charts/gitops'),
      '-n', config.argoNamespace, '-f', values], { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 });
    return { result: { ...result, documents: continuousDocuments(result, config.argoNamespace) },
      files: { 'apps/applications.yaml': dump(continuousApplications(rendered)),
        'bootstrap.yaml': dump(continuousDocuments(result, config.argoNamespace)),
        'selection.json': JSON.stringify({ directory }, null, 2) + '\n' } };
  } finally { fs.rmSync(temporary, { recursive: true, force: true }); }
}

export function exportContinuousBundle(repository, directory, config, env = process.env) {
  const variables = { ...env };
  const names = { buster: 'BUSTER_VALUES_FILE', nova: 'NOVA_VALUES_FILE', prism: 'PRISM_VALUES_FILE', 'prism-agent': 'PRISM_AGENT_VALUES_FILE' };
  for (const [role, relative] of Object.entries(config.overlays ?? {})) {
    if (!names[role] || typeof relative !== 'string' || !relative.startsWith('gitops/production/overlays/')
      || relative.split('/').includes('..') || !fs.existsSync(path.join(repository, relative))) throw new Error(`GITOPS_OVERLAY_INVALID:${role}`);
    variables[names[role]] = path.join(repository, relative);
  }
  return exportGitOpsBundle(repository, directory, config.namespace, config.prismNamespace, variables);
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  try {
    const [command, directory, url, revision] = process.argv.slice(2);
    const config = configuration(root);
    if (command === 'export' && directory && !url) exportContinuousBundle(root, directory, config);
    else if (['prepare', 'check', 'preflight', 'apply'].includes(command) && directory && url && revision) {
      const { result, files } = renderContinuousEnvironment(root, directory, url, revision, config);
      if (command === 'prepare' || command === 'check') {
        for (const [relative, bytes] of Object.entries(files)) {
          const file = path.join(root, environment, relative);
          if (command === 'check') {
            if (!fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== bytes) throw new Error(`GITOPS_ENVIRONMENT_DRIFT:${relative}`);
          } else { fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, bytes); }
        }
      } else {
        preflightGitOps(root, result, config.argoNamespace);
        if (command === 'apply') process.stdout.write(execFileSync('kubectl', ['apply', '-f', '-'],
          { input: dump(result.documents), encoding: 'utf8', timeout: 60000 }));
      }
    } else throw new Error('Usage: gitops-continuous.mjs export releases/gitops/NAME | prepare|check|preflight|apply releases/gitops/NAME HTTPS_REPOSITORY COMMIT');
  } catch (error) { process.stderr.write(`${error.message}\n`); process.exitCode = 1; }
}

source:scripts/gitops-owner.mjs.syntax:
export function claimedNamespaces(application) {
  const annotation = application.metadata?.annotations?.['kubeclaw.dev/runtime-namespaces'];
  const declared = annotation === undefined ? [] : JSON.parse(annotation);
  if (!Array.isArray(declared) || !declared.every(gitOpsName)) throw new Error('GITOPS_OWNERSHIP_ANNOTATION_INVALID');
  return [...declared, application.spec?.destination?.namespace];
}

export function assertNoGitOpsOwner(namespace, _release, run = args => execFileSync('kubectl', args, { encoding: 'utf8', timeout: 30000 })) {
  if (!gitOpsName(namespace)) throw new Error('GITOPS_OWNERSHIP_ARGUMENT_INVALID');
  const crd = run(['get', 'crd', 'applications.argoproj.io', '--ignore-not-found', '-o', 'json']);
  const applications = crd.trim()
    ? JSON.parse(run(['get', 'applications.argoproj.io', '--all-namespaces', '-o', 'json'])) : { items: [] };
  if (!Array.isArray(applications.items)) throw new Error('GITOPS_OWNERSHIP_RESPONSE_INVALID');
  const owner = applications.items.find(application => claimedNamespaces(application).includes(namespace));
  if (owner) throw new Error(`GITOPS_OWNER_PRESENT:${namespace}/${owner.metadata?.name}; update its reviewed Git revision instead`);
  // Deleting an Application without cascading its workloads does not transfer ownership.
  const workloads = JSON.parse(run(['get', 'deployments,statefulsets,cronjobs', '-n', namespace, '-o', 'json']));
  if (!Array.isArray(workloads.items)) throw new Error('GITOPS_OWNERSHIP_RESPONSE_INVALID');
  if (workloads.items.some(workload => workload.metadata?.annotations?.['argocd.argoproj.io/tracking-id']
    || workload.metadata?.labels?.['kubeclaw.dev/gitops-owner'])) throw new Error(`GITOPS_RETAINED_RESOURCE_OWNER:${namespace}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { assertNoGitOpsOwner(...process.argv.slice(2)); }
  catch (error) { process.stderr.write(`${error.message}\n`); process.exitCode = 1; }
}

source:scripts/gitops-rollback.mjs.syntax:
export function rollbackRevision(root, requested = 'previous') {
  const current = selection(root, 'HEAD').directory;
  if (requested !== 'previous') {
    if (!/^[a-f0-9]{40}$/u.test(requested)) throw new Error('ROLLBACK_TARGET_MUST_BE_FULL_COMMIT');
    git(root, ['merge-base', '--is-ancestor', requested, 'HEAD']);
    if (selection(root, requested).directory === current) throw new Error('ROLLBACK_ALREADY_SELECTED');
    return requested;
  }
  // First-parent history represents merged deployment choices, not intermediate
  // commits inside a PR. Never call the previous choice "known healthy".
  const revisions = git(root, ['log', '--first-parent', '--format=%H', 'HEAD', '--', selectionFile]).trim().split('\n').filter(Boolean);
  for (const revision of revisions) {
    if (selection(root, revision).directory !== current) return revision;
  }
  throw new Error('ROLLBACK_NO_PREVIOUS_SELECTION');
}

export function planGitOpsRollback(root, url, requested = 'previous') {
  const revision = rollbackRevision(root, requested);
  const directory = selection(root, revision).directory;
  const current = readCommittedBundle(root, selection(root, 'HEAD').directory, git(root, ['rev-parse', 'HEAD']).trim());
  const config = JSON.parse(fs.readFileSync(path.join(root, 'gitops/production/config.json'), 'utf8'));
  const { result, files: generated } = renderContinuousEnvironment(root, directory, url, revision, config);
  const scope = bundle => bundle.groups.map(group => ({ name: group.name, namespace: group.namespace, helmReleases: group.helmReleases }));
  if (JSON.stringify(scope(current)) !== JSON.stringify(scope(result.bundle))) throw new Error('ROLLBACK_DEPLOYMENT_SCOPE_CHANGED');
  // main is the Argo source. Historical manifests must still exist there with
  // their original bytes, even when the selected receipt has since changed.
  for (const file of [`${directory}/bundle.receipt`, ...result.bundle.groups.map(group => `${group.path}/resources.yaml`)]) {
    if (read(root, 'HEAD', file) !== read(root, revision, file)) throw new Error(`ROLLBACK_BUNDLE_CHANGED:${file}`);
  }
  const files = { 'releases/runtime-images.json': read(root, revision, 'releases/runtime-images.json') };
  const remove = [];
  if (result.bundle.receipt.code) files['releases/runtime-code.json'] = read(root, revision, 'releases/runtime-code.json');
  else if (current.receipt.code) remove.push('releases/runtime-code.json');
  for (const role of ['buster', 'prism', 'prism-agent', 'nova']) files[`releases/values/${role}.yaml`] = read(root, revision, `releases/values/${role}.yaml`);
  for (const [name, bytes] of Object.entries(generated)) files[`gitops/production/${name}`] = bytes;
  return { revision, directory, files, remove };
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  try {
    const [url, requested = 'previous'] = process.argv.slice(2);
    const root = path.resolve(import.meta.dirname, '..');
    const plan = planGitOpsRollback(root, url, requested);
    // Build and validate the entire plan before changing any file. Only the
    // explicit deployment selection is restored; source and data stay intact.
    for (const [relative, bytes] of Object.entries(plan.files)) {
      const file = path.join(root, relative);
      fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, bytes);
    }
    for (const relative of plan.remove) fs.rmSync(path.join(root, relative), { force: true });
    process.stdout.write(JSON.stringify({ revision: plan.revision, directory: plan.directory }) + '\n');
  } catch (error) { process.stderr.write(`${error.message}\n`); process.exitCode = 1; }
}

source:scripts/gitops.mjs.syntax:
function inspectCommittedGroup(repository, directory, revision, group, receipt) {
  if (!gitOpsName(group.name) || !gitOpsName(group.namespace)
    || group.path !== `${directory}/${group.role}` || group.wave !== (group.role === 'nova' ? 1 : 0)
    || !Array.isArray(group.helmReleases) || !group.helmReleases.length || !group.helmReleases.every(gitOpsName)) throw new Error('GITOPS_GROUP_INVALID');
  const bytes = gitFile(repository, revision, `${group.path}/resources.yaml`);
  if (gitOpsDigest(bytes) !== group.manifestDigest) throw new Error('GITOPS_MANIFEST_DIGEST_MISMATCH');
  validateRenderedRelease(bytes, bytes, receipt, group.role === 'prism');
  const documents = yaml.loadAll(bytes).filter(Boolean);
  const inspection = inspectGitOpsResources(documents, group.namespace);
  for (const field of ['resources', 'images', 'requiredSecrets']) {
    if (JSON.stringify(inspection[field]) !== JSON.stringify(group[field])) throw new Error(`GITOPS_BUNDLE_INVENTORY_MISMATCH:${field}`);
  }
  for (const document of documents) {
    if (document.metadata.labels?.['kubeclaw.dev/gitops-owner'] !== group.name) throw new Error('GITOPS_RESOURCE_OWNER_MISMATCH');
  }
  return inspection.resources;
}

function verifyCommittedChart(repository, revision) {
  const files = ['Chart.yaml', 'values.yaml', 'templates/applications.yaml', 'files/application-health.lua'].map(file => `charts/gitops/${file}`);
  const committed = git(repository, ['ls-tree', '-r', '--name-only', revision, '--', 'charts/gitops']).trim().split('\n');
  if (JSON.stringify(committed.sort()) !== JSON.stringify([...files].sort())) throw new Error('GITOPS_BOOTSTRAP_CHART_FILE_SET');
  for (const file of files) {
    if (gitFile(repository, revision, file) !== fs.readFileSync(path.join(repository, file), 'utf8')) throw new Error('GITOPS_BOOTSTRAP_CHART_DRIFT');
  }
}

export function readCommittedBundle(repository, directory, revision) {
  if (!/^[a-f0-9]{40}$/u.test(revision)) throw new Error('GITOPS_REVISION_MUST_BE_COMMIT');
  if (!/^releases\/gitops\/[a-z0-9][a-z0-9-]{0,50}$/u.test(directory)) throw new Error('GITOPS_BUNDLE_PATH_INVALID');
  if (git(repository, ['rev-parse', `${revision}^{commit}`]).trim() !== revision) throw new Error('GITOPS_REVISION_INVALID');
  const bundle = JSON.parse(gitFile(repository, revision, `${directory}/bundle.receipt`));
  if (bundle.schemaVersion !== 'kubeclaw-gitops-bundle.v1' || !Array.isArray(bundle.groups)
    || bundle.groups.map(group => group.role).join(',') !== 'buster,prism,nova') throw new Error('GITOPS_BUNDLE_SCHEMA_INVALID');
  validateReleaseReceipt(bundle.receipt, 'runtime');
  const selected = JSON.parse(gitFile(repository, revision, 'releases/runtime-images.json'));
  if (bundle.receipt.code) selected.code = JSON.parse(gitFile(repository, revision, 'releases/runtime-code.json'));
  if (JSON.stringify(selected) !== JSON.stringify(bundle.receipt)) throw new Error('GITOPS_SELECTED_RECEIPT_MISMATCH');
  const owned = new Set(), names = new Set();
  for (const group of bundle.groups) {
    if (names.has(group.name)) throw new Error('GITOPS_DUPLICATE_APPLICATION');
    names.add(group.name);
    for (const resource of inspectCommittedGroup(repository, directory, revision, group, bundle.receipt)) {
      const identity = `${resource.apiVersion.split('/').slice(0, -1).join('/')}/${resource.kind}/${resource.namespace}/${resource.name}`;
      if (owned.has(identity)) throw new Error('GITOPS_RESOURCE_HAS_MULTIPLE_OWNERS');
      owned.add(identity);
    }
  }
  verifyCommittedChart(repository, revision);
  return bundle;
}

export function bootstrapDocuments(repository, directory, url, revision, argoNamespace) {
  const address = new URL(url);
  if (address.protocol !== 'https:' || address.username || address.password || address.search || address.hash
    || !address.hostname || !gitOpsName(argoNamespace)) throw new Error('GITOPS_REPOSITORY_OR_NAMESPACE_INVALID');
  const bundle = readCommittedBundle(repository, directory, revision);
  if (bundle.groups.some(group => group.namespace === argoNamespace || group.resources.some(resource => resource.namespace === argoNamespace))) throw new Error('GITOPS_ADMIN_NAMESPACE_CANNOT_HOST_WORKLOADS');
  const name = `${bundle.groups[0].namespace}-runtime`;
  if (!gitOpsName(name)) throw new Error('GITOPS_APPLICATION_NAME_INVALID');
  const cluster = new Map(), namespaced = new Map();
  for (const group of bundle.groups) for (const resource of group.resources) {
    const entry = { group: resource.apiVersion.includes('/') ? resource.apiVersion.split('/')[0] : '', kind: resource.kind };
    (gitOpsClusterKinds.has(resource.kind) ? cluster : namespaced).set(`${entry.group}/${entry.kind}`, entry);
  }
  const destinations = [...new Set(bundle.groups.flatMap(group => [group.namespace, ...group.resources.map(resource => resource.namespace).filter(Boolean)]))].sort();
  const values = { repository: url, revision, destinations, rootName: name, project: `${name}-workloads`, groups: bundle.groups,
    clusterResourceWhitelist: [...cluster.values()], namespaceResourceWhitelist: [...namespaced.values()] };
  if (!gitOpsName(values.project)) throw new Error('GITOPS_PROJECT_NAME_INVALID');
  const documents = [
    { apiVersion: 'argoproj.io/v1alpha1', kind: 'AppProject', metadata: { name, namespace: argoNamespace, labels: { 'kubeclaw.dev/gitops-root': name } }, spec: {
      description: 'Administrative bootstrap: only this reviewed repository may define runtime Applications and their Project.',
      sourceRepos: [url], destinations: [{ namespace: argoNamespace, server: 'https://kubernetes.default.svc' }],
      clusterResourceWhitelist: [], namespaceResourceWhitelist: [{ group: 'argoproj.io', kind: 'Application' }, { group: 'argoproj.io', kind: 'AppProject' }],
    } },
    { apiVersion: 'argoproj.io/v1alpha1', kind: 'Application', metadata: { name, namespace: argoNamespace, labels: { 'kubeclaw.dev/gitops-root': name },
      annotations: { 'kubeclaw.dev/runtime-namespaces': JSON.stringify([...new Set(bundle.groups.map(group => group.namespace))]) } }, spec: {
      project: name, source: { repoURL: url, targetRevision: revision, path: 'charts/gitops', helm: { valuesObject: values } },
      destination: { server: 'https://kubernetes.default.svc', namespace: argoNamespace },
      syncPolicy: { automated: { prune: false, selfHeal: true, allowEmpty: false }, syncOptions: ['FailOnSharedResource=true'] },
    } },
  ];
  return { bundle, documents, values };
}

function verifyArgoConfiguration(repository, argoNamespace, get) {
  const cm = get(['get', 'configmap', 'argocd-cm', '-n', argoNamespace]);
  if (cm.data?.['application.resourceTrackingMethod'] !== 'annotation'
    || cm.data?.['resource.customizations.health.argoproj.io_Application'] !== fs.readFileSync(path.join(repository, 'charts/gitops/files/application-health.lua'), 'utf8')) throw new Error('GITOPS_ARGO_HEALTH_OR_TRACKING_NOT_INSTALLED');
  get(['get', 'csidriver', 'csi.spiffe.io']);
}

function isBootstrapApplication(application, rootName, argoNamespace) {
  return application.metadata?.name === rootName && application.metadata?.namespace === argoNamespace
    && application.metadata?.labels?.['kubeclaw.dev/gitops-root'] === rootName && application.spec?.project === rootName;
}

function verifyApplicationOwners(result, argoNamespace, applications, namespace) {
  for (const application of applications) {
    if (!claimedNamespaces(application).includes(namespace)) continue;
    if (isBootstrapApplication(application, result.values.rootName, argoNamespace)) continue;
    const expected = result.bundle.groups.some(group => group.name === application.metadata?.name && group.namespace === namespace);
    if (!expected || application.metadata?.namespace !== argoNamespace || application.spec?.project !== result.values.project) throw new Error(`GITOPS_OTHER_APPLICATION_PRESENT:${namespace}`);
  }
}

function verifyResourceOwner(resource, group, run) {
  const apiGroup = resource.apiVersion.includes('/') ? resource.apiVersion.split('/')[0] : '';
  const type = `${resource.kind}${apiGroup ? `.${apiGroup}` : ''}`;
  const output = run('kubectl', ['get', type, resource.name, ...(resource.namespace ? ['-n', resource.namespace] : []), '--ignore-not-found', '-o', 'json']);
  if (!output.trim()) return;
  const object = JSON.parse(output), annotations = object.metadata?.annotations ?? {};
  const owner = annotations['argocd.argoproj.io/tracking-id'];
  const label = object.metadata?.labels?.['kubeclaw.dev/gitops-owner'];
  if (annotations['meta.helm.sh/release-name'] || (owner && !owner.startsWith(`${group.name}:`)) || (label && label !== group.name)) throw new Error(`GITOPS_EXISTING_RESOURCE_OWNER:${type}/${resource.name}`);
  if (!owner) throw new Error(`GITOPS_UNMANAGED_EXISTING_RESOURCE_REQUIRES_REVIEW:${type}/${resource.name}`);
}

function verifyGroupPrerequisites(group, get, run) {
  const releases = JSON.parse(run('helm', ['list', '-n', group.namespace, '--all', '-o', 'json']));
  if (!Array.isArray(releases) || releases.some(release => group.helmReleases.includes(release.name))) throw new Error(`GITOPS_HELM_OWNER_PRESENT:${group.namespace}`);
  for (const secret of group.requiredSecrets) {
    const object = get(['get', 'secret', secret.name, '-n', group.namespace]);
    if (secret.keys.some(key => !object.data?.[key])) throw new Error(`GITOPS_REQUIRED_SECRET_KEY_MISSING:${group.namespace}/${secret.name}`);
  }
  for (const resource of group.resources) verifyResourceOwner(resource, group, run);
}

function verifyBootstrapOwners(result, argoNamespace, run) {
  const expected = [...result.documents, { kind: 'AppProject', metadata: { name: result.values.project } }];
  for (const document of expected) {
    const output = run('kubectl', ['get', `${document.kind}.argoproj.io`, document.metadata.name, '-n', argoNamespace, '--ignore-not-found', '-o', 'json']);
    if (!output.trim()) continue;
    const object = JSON.parse(output);
    if (object.metadata?.labels?.['kubeclaw.dev/gitops-root'] !== result.values.rootName) throw new Error('GITOPS_BOOTSTRAP_OWNER_CONFLICT');
    if (document.kind === 'Application' && (object.spec?.source?.repoURL !== result.values.repository
      || object.metadata.annotations?.['kubeclaw.dev/runtime-namespaces'] !== document.metadata.annotations['kubeclaw.dev/runtime-namespaces'])) throw new Error('GITOPS_BOOTSTRAP_SCOPE_CHANGE');
  }
}

export function preflightGitOps(repository, result, argoNamespace, run = runCommand, policyFile = path.join(repository, 'my-values/infra/native-worker-pools.yaml')) {
  const get = args => JSON.parse(run('kubectl', [...args, '-o', 'json']));
  verifyArgoConfiguration(repository, argoNamespace, get);
  verifyBootstrapOwners(result, argoNamespace, run);
  const applications = get(['get', 'applications.argoproj.io', '--all-namespaces']).items;
  if (!Array.isArray(applications)) throw new Error('GITOPS_APPLICATION_LIST_INVALID');
  for (const namespace of result.values.destinations) get(['get', 'namespace', namespace]);
  for (const group of result.bundle.groups) {
    verifyApplicationOwners(result, argoNamespace, applications, group.namespace);
    verifyGroupPrerequisites(group, get, run);
  }
  const prism = result.bundle.groups.find(group => group.role === 'prism');
  const resources = yaml.loadAll(gitFile(repository, result.values.revision, `${prism.path}/resources.yaml`)).filter(Boolean);
  nativePrismDeploymentSelection(resources, prism.namespace, loadNativeNodePolicy(policyFile));
  run(process.execPath, [path.join(repository, 'scripts/native-worker-node-preflight.mjs'), policyFile]);
}

function performBootstrap(command, args) {
  const result = bootstrapDocuments(root, ...args.slice(0, 4));
  if (command === 'bootstrap') {
    process.stdout.write(result.documents.map(document => yaml.dump(document, { noRefs: true, lineWidth: 120 })).join('---\n'));
    return;
  }
  preflightGitOps(root, result, args[3], runCommand, args[4]);
  if (command === 'preflight') {
    process.stdout.write('GitOps ownership, Secrets, host policy and Argo configuration preflight passed. No resources changed.\n');
    return;
  }
  const input = result.documents.map(document => yaml.dump(document, { noRefs: true, lineWidth: 120 })).join('---\n');
  process.stdout.write(execFileSync('kubectl', ['apply', '-f', '-'], { input, encoding: 'utf8', timeout: 60000 }));
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const [command, ...args] = process.argv.slice(2);
    if (command === 'export' && (args.length === 2 || args.length === 3)) {
      const result = exportGitOpsBundle(root, args[0], args[1], args[2] ?? args[1], process.env);
      process.stdout.write(`Exported ${result.groups.length} groups. Review and commit the release bundle before bootstrap.\n`);
    } else if (['bootstrap', 'preflight', 'apply'].includes(command) && (args.length === 4 || args.length === 5)) {
      performBootstrap(command, args);
    } else throw new Error('Usage: gitops.mjs export releases/gitops/NAME NAMESPACE [PRISM_NAMESPACE] | bootstrap|preflight|apply releases/gitops/NAME HTTPS_REPOSITORY COMMIT ARGO_NAMESPACE [NODE_POLICY]');
  } catch (error) { process.stderr.write(`${error.message}\n`); process.exitCode = 1; }
}

