export interface DependencyProcessOptions {
  readonly executable: string;
  readonly args: readonly string[];
  readonly maximumExecutionMs: number;
  readonly maximumOutputBytes: number;
  readonly signal?: AbortSignal;
}

export interface DependencyProcessResult {
  readonly ok: boolean;
  readonly code: 'DEPENDENCY_OK' | 'DEPENDENCY_CANCELLED' | 'DEPENDENCY_TIMEOUT' | 'DEPENDENCY_OUTPUT_LIMIT' | 'DEPENDENCY_SPAWN_FAILED' | 'DEPENDENCY_EXIT_FAILED';
  readonly exitCode: number | null;
  readonly signal: string | null;
  readonly errno: string | null;
  readonly outputBytes: number;
  readonly outputDigest: string;
  readonly durationMs: number;
}

export function validateDependencyProcessLimits(options: Pick<DependencyProcessOptions, 'maximumExecutionMs' | 'maximumOutputBytes'>): void {
  for (const [value, maximum] of [[options.maximumExecutionMs, 30_000], [options.maximumOutputBytes, 1024 * 1024]] as const) {
    if (!Number.isSafeInteger(value) || value < 1 || value > maximum) throw new Error('DEPENDENCY_PROCESS_LIMIT_INVALID');
  }
}

export async function runDependencyProcess(options: DependencyProcessOptions): Promise<DependencyProcessResult> {
  validateDependencyProcessLimits(options);
  const started = Date.now();
  if (options.signal?.aborted) return { ok: false, code: 'DEPENDENCY_CANCELLED', exitCode: null, signal: null, errno: null,
    outputBytes: 0, outputDigest: `sha256:${crypto.createHash('sha256').digest('hex')}`, durationMs: 0 };
  return await new Promise<DependencyProcessResult>((resolve) => {
    const child = spawn(options.executable, [...options.args], {
      detached: true, stdio: ['ignore', 'pipe', 'pipe'], env: { PATH: '/usr/local/bin:/usr/bin:/bin', LANG: 'C.UTF-8', LC_ALL: 'C.UTF-8' },
    });
    let failure: DependencyProcessResult['code'] | undefined;
    let errno: string | null = null;
    let outputBytes = 0;
    const digest = crypto.createHash('sha256');
    const stop = (code: DependencyProcessResult['code']): void => {
      failure ??= code;
      if (!child.pid) return;
      try { process.kill(-child.pid, 'SIGKILL'); }
      catch (error) {
        const code = (error as NodeJS.ErrnoException).code;
        if (code !== 'ESRCH') { errno = 'TERMINATION_FAILED'; child.kill('SIGKILL'); }
      }
    };
    const cancel = (): void => stop('DEPENDENCY_CANCELLED');
    options.signal?.addEventListener('abort', cancel, { once: true });
    if (options.signal?.aborted) cancel();
    const timer = setTimeout(() => stop('DEPENDENCY_TIMEOUT'), options.maximumExecutionMs);
    const output = (chunk: Buffer): void => {
      if (failure) return;
      outputBytes += chunk.byteLength;
      if (outputBytes > options.maximumOutputBytes) { stop('DEPENDENCY_OUTPUT_LIMIT'); return; }
      digest.update(chunk);
    };
    child.stdout.on('data', output); child.stderr.on('data', output);
    child.once('error', (error: NodeJS.ErrnoException) => {
      failure ??= 'DEPENDENCY_SPAWN_FAILED';
      errno = typeof error.code === 'string' && /^[A-Z0-9_]+$/u.test(error.code) ? error.code : 'UNKNOWN';
    });
    child.once('close', (exitCode, signal) => {
      clearTimeout(timer);
      options.signal?.removeEventListener('abort', cancel);
      const code = failure ?? (exitCode === 0 ? 'DEPENDENCY_OK' : 'DEPENDENCY_EXIT_FAILED');
      resolve({ ok: code === 'DEPENDENCY_OK', code, exitCode, signal, errno, outputBytes,
        outputDigest: `sha256:${digest.digest('hex')}`, durationMs: Date.now() - started });
    });
  });
}

source:skills/common/plugin-runtime/foun.syntax:
function createInitialization() {
  let resolveCommand;
  const command = new Promise((resolve) => { resolveCommand = resolve; });
  return Object.freeze({
    command,
    accept(message) { resolveCommand(message); },
  });
}

function createRpcIdFactory() {
  let sequence = 0;
  return () => {
    sequence += 1;
    return `rpc:${sequence}`;
  };
}

function send(value) {
  process.stdout.write(`${JSON.stringify(value)}\n`);
}

lines.on('line', (line) => {
  let message;
  try {
    message = JSON.parse(line);
  } catch {
    send({ kind: 'fatal', error: 'ISOLATION_PROTOCOL_INVALID_JSON' });
    process.exit(70);
    return;
  }
  if (message.kind === 'response') {
    const request = pending.get(message.id);
    if (!request) return;
    pending.delete(message.id);
    if (message.ok) request.resolve(message.value);
    else request.reject(new Error(String(message.error || 'isolated capability failed')));
    return;
  }
  initialization.accept(message);
});

function rpc(kind, payload) {
  const id = nextRpcId();
  send({ kind, id, ...payload });
  return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
}

function contextProxy(contract) {
  const artifacts = new Map(contract.artifacts.map((artifact) => [artifact.artifactId, artifact]));
  return Object.freeze({
    contract: Object.freeze(contract),
    invoke(capability, request) {
      return rpc('capability', { capability, request });
    },
    emit(type, identity, payload) {
      return rpc('event', { type, identity, payload });
    },
    artifact(id) {
      return artifacts.get(id);
    },
  });
}

try {
  const command = await initialization.command;
  if (!command || command.kind !== 'invoke') throw new Error('ISOLATION_PROTOCOL_INIT_REQUIRED');
  if (!['stage', 'observer'].includes(command.surface)) throw new Error('ISOLATION_SURFACE_UNSUPPORTED');
  const module = await import(pathToFileURL(command.modulePath).href);
  const execute = module[command.exportName];
  if (typeof execute !== 'function') throw new Error('ISOLATION_EXPORT_INVALID');
  const value = await execute(command.argument, contextProxy(command.context));
  send({ kind: 'result', value });
} catch (error) {
  send({
    kind: 'error',
    error: error instanceof Error
      ? { name: error.name, message: error.message }
      : { name: 'Error', message: String(error) },
  });
  process.exitCode = 1;
} finally {
  lines.close();
}

function serializable(value: unknown, label: string, limit = 1024 * 1024): string {
  let encoded: string;
  try { encoded = JSON.stringify(value); }
  catch { throw new Error(`ISOLATION_${label}_NOT_SERIALIZABLE`); }
  if (encoded === undefined) throw new Error(`ISOLATION_${label}_NOT_SERIALIZABLE`);
  if (Buffer.byteLength(encoded) > limit) throw new Error(`ISOLATION_${label}_TOO_LARGE`);
  return encoded;
}

interface SessionInput {
  readonly child: ChildProcessWithoutNullStreams;
  readonly context: PluginInvocationContext;
  readonly signal?: AbortSignal;
  readonly wallTimeMs: number;
  readonly invocationMessage: Readonly<Record<string, unknown>>;
  /** Host-owned hard process-tree boundary; the supervisor receives TERM first. */
  readonly terminateTree?: () => void;
}

export function runIsolationSession(input: SessionInput): Promise<unknown> {
  return new IsolationSession(input).run();
}

class IsolationSession {
  readonly #input: SessionInput;
  readonly #protocol = new ProtocolLines();
  #finishing = false;
  #closed = false;
  #error: Error | undefined;
  #value: unknown;
  #stderr: Buffer = Buffer.alloc(0);
  #timer: NodeJS.Timeout | undefined;
  #terminationTimer: NodeJS.Timeout | undefined;
  #pending = 0;
  #resolve: (value: unknown) => void = () => undefined;
  #reject: (error: Error) => void = () => undefined;
  constructor(input: SessionInput) { this.#input = input; }

  run(): Promise<unknown> {
    return new Promise((resolve, reject) => {
      this.#resolve = resolve; this.#reject = reject;
      // All pipe handlers exist before the first write, including pre-abort.
      this.#input.child.stdin.on('error', this.#pipeError);
      this.#input.child.stdout.on('error', this.#pipeError);
      this.#input.child.stderr.on('error', this.#pipeError);
      this.#input.child.stderr.on('data', this.#stderrData);
      this.#input.child.stdout.on('data', this.#stdoutData);
      this.#input.child.once('error', this.#pipeError);
      this.#input.child.once('close', this.#onClose);
      if (this.#input.signal?.aborted) { this.#finish(new Error('ISOLATED_PLUGIN_CANCELLED')); return; }
      this.#input.signal?.addEventListener('abort', this.#abort, { once: true });
      this.#timer = setTimeout(() => this.#finish(new Error('ISOLATED_PLUGIN_TIMEOUT')), this.#input.wallTimeMs);
      try { this.#write(serializable(this.#input.invocationMessage, 'INVOCATION')); }
      catch (error) { this.#finish(this.#asError(error)); }
    });
  }

  #asError(error: unknown): Error { return error instanceof Error ? error : new Error(String(error)); }
  readonly #abort = (): void => this.#finish(new Error('ISOLATED_PLUGIN_CANCELLED'));
  readonly #pipeError = (cause: Error): void => this.#finish(new Error(`ISOLATION_PIPE_FAILED:${cause.message}`, { cause }));
  readonly #stderrData = (chunk: Buffer): void => {
    if (this.#stderr.length + chunk.length > 64 * 1024) { this.#finish(new Error('ISOLATED_PLUGIN_STDERR_LIMIT')); return; }
    this.#stderr = Buffer.concat([this.#stderr, chunk]);
  };
  readonly #stdoutData = (chunk: Buffer): void => {
    if (this.#finishing) return;
    try { this.#protocol.push(chunk, (message) => { if (!this.#finishing) this.#handle(message); }); }
    catch (error) { this.#finish(this.#asError(error)); }
  };

  #write(encoded: string): void {
    if (this.#finishing || this.#input.child.stdin.destroyed || !this.#input.child.stdin.writable) return;
    if (this.#input.child.stdin.writableLength + Buffer.byteLength(encoded) > 1024 * 1024) {
      this.#finish(new Error('ISOLATION_PROTOCOL_INPUT_LIMIT')); return;
    }
    this.#input.child.stdin.write(`${encoded}\n`, (error) => { if (error) this.#pipeError(error); });
  }

  #response(id: string, operation: () => Promise<unknown>): void {
    if (++this.#pending > 64) { this.#finish(new Error('ISOLATION_RPC_LIMIT')); return; }
    void Promise.resolve().then(() => {
      if (this.#finishing) throw new Error('ISOLATION_SESSION_CLOSED');
      return operation();
    }).then(
      (value) => this.#sendResponse({ kind: 'response', id, ok: true, value }),
      (error: unknown) => this.#sendResponse({ kind: 'response', id, ok: false, error: this.#asError(error).message }),
    ).catch((error: unknown) => this.#finish(this.#asError(error))).finally(() => { this.#pending--; });
  }

  #sendResponse(message: Readonly<Record<string, unknown>>): void {
    if (this.#finishing) return;
    this.#write(serializable(message, 'RESPONSE'));
  }

  #handle(message: Record<string, unknown>): void {
    if (message.kind === 'capability' && typeof message.id === 'string') { this.#capability(message); return; }
    if (message.kind === 'event' && typeof message.id === 'string') { this.#event(message); return; }
    if (message.kind === 'result') { this.#result(message.value); return; }
    if (message.kind === 'error' || message.kind === 'fatal') { this.#failure(message.error); return; }
    this.#finish(new Error('ISOLATION_PROTOCOL_INVALID_MESSAGE'));
  }

  #capability(message: Record<string, unknown>): void {
    const request = message.request;
    if (typeof message.capability !== 'string' || message.capability.length > 128 || !request || typeof request !== 'object') {
      this.#finish(new Error('ISOLATION_PROTOCOL_CAPABILITY_INVALID')); return;
    }
    this.#response(String(message.id), () => this.#input.context.invoke(message.capability as string, request as never));
  }

  #event(message: Record<string, unknown>): void {
    if (typeof message.type !== 'string' || message.type.length > 256) { this.#finish(new Error('ISOLATION_PROTOCOL_EVENT_INVALID')); return; }
    this.#response(String(message.id), () => this.#input.context.emit(message.type as string, message.identity as never, message.payload as never));
  }

  #result(value: unknown): void {
    if (this.#pending) { this.#finish(new Error('ISOLATION_RPC_NOT_DRAINED')); return; }
    try { serializable(value, 'RESULT'); }
    catch (error) { this.#finish(this.#asError(error)); return; }
    this.#finish(undefined, value);
  }

  #failure(error: unknown): void {
    const detail = error && typeof error === 'object' ? String((error as Record<string, unknown>).message) : String(error);
    this.#finish(new Error(`ISOLATED_PLUGIN_FAILED:${detail}`));
  }

  readonly #onClose = (code: number | null, signal: NodeJS.Signals | null): void => {
    this.#closed = true;
    if (!this.#finishing) {
      try { this.#protocol.finish(); }
      catch (error) { this.#finish(this.#asError(error)); return; }
      this.#finish(new Error(`ISOLATED_PLUGIN_EXITED:${String(code)}:${String(signal)}:${this.#stderr.toString('utf8').slice(0, 4096)}`));
    }
    this.#settle();
  };

  #settle(): void {
    if (this.#terminationTimer) clearTimeout(this.#terminationTimer);
    if (this.#error) this.#reject(this.#error); else this.#resolve(this.#value);
  }

  #finish(error?: Error, value?: unknown): void {
    if (this.#finishing) return;
    this.#finishing = true; this.#error = error; this.#value = value;
    if (this.#timer) clearTimeout(this.#timer);
    this.#input.signal?.removeEventListener('abort', this.#abort);
    if (this.#closed) { this.#settle(); return; }
    this.#input.child.stdin.destroy();
    this.#input.child.kill('SIGTERM');
    this.#terminationTimer = setTimeout(() => {
      try { this.#input.terminateTree?.(); }
      catch (cause) { this.#error = new Error('ISOLATION_TREE_TERMINATION_FAILED', { cause }); }
      this.#input.child.kill('SIGKILL');
      this.#terminationTimer = setTimeout(() => {
        if (this.#closed) return;
        this.#error = new Error('ISOLATION_PROCESS_CLEANUP_TIMEOUT', { cause: this.#error });
        this.#input.child.stdout.destroy(); this.#input.child.stderr.destroy();
        this.#settle();
      }, 1000);
    }, 1000);
  }
}

export interface IsolatedInvocation {
  readonly packageRoot: string; readonly modulePath: string; readonly exportName: string;
  readonly cgroupRoot?: string;
  readonly surface: 'stage' | 'observer'; readonly argument: unknown; readonly context: PluginInvocationContext; readonly signal?: AbortSignal;
}

function sandboxPaths(): { readonly launcher: string; readonly child: string } {
  const directory = path.dirname(fileURLToPath(import.meta.url));
  const launcher = path.join(directory, 'plugin-sandbox'); const child = path.join(directory, 'child.mjs');
  if (!fs.existsSync(launcher)) throw new Error('ISOLATION_SANDBOX_NOT_BUILT');
  return { launcher, child };
}

function canonicalModule(packageRootValue: string, modulePathValue: string): { readonly packageRoot: string; readonly modulePath: string } {
  const packageRoot = fs.realpathSync(packageRootValue); const modulePath = fs.realpathSync(modulePathValue);
  if (!modulePath.startsWith(`${packageRoot}${path.sep}`) || !fs.statSync(modulePath).isFile()) throw new Error('ISOLATION_MODULE_OUTSIDE_PACKAGE');
  return { packageRoot, modulePath };
}

export function invokeIsolated(invocation: IsolatedInvocation): Promise<unknown> {
  if (invocation.signal?.aborted) return Promise.reject(new Error('ISOLATED_PLUGIN_CANCELLED'));
  const paths = sandboxPaths(); const canonical = canonicalModule(invocation.packageRoot, invocation.modulePath);
  serializable(invocation.argument, 'ARGUMENT'); serializable(invocation.context.contract, 'CONTEXT');
  return runBounded(invocation, paths, canonical);
}

async function runBounded(invocation: IsolatedInvocation, paths: ReturnType<typeof sandboxPaths>, canonical: ReturnType<typeof canonicalModule>): Promise<unknown> {
  const limits = invocation.context.contract.lease.limits;
  const group = IsolationCgroup.create(invocation.cgroupRoot, limits.memoryBytes);
  let failure: unknown;
  try {
    const child = spawn(paths.launcher, [
      String(limits.memoryBytes), String(Math.max(1, Math.ceil(limits.cpuMillis / 1000))), '64', '--child-cgroup', group.path, process.execPath,
      `--max-old-space-size=${Math.max(16, Math.floor(limits.memoryBytes / (1024 * 1024) * 0.7))}`, '--permission',
      `--allow-fs-read=${paths.child}`, `--allow-fs-read=${canonical.packageRoot}`, '--no-addons', paths.child,
    ], { stdio: ['pipe', 'pipe', 'pipe'], env: { NODE_NO_WARNINGS: '1' }, cwd: canonical.packageRoot });
    return await runIsolationSession({
      child, terminateTree: () => group.kill(), context: invocation.context, ...(invocation.signal ? { signal: invocation.signal } : {}), wallTimeMs: limits.wallTimeMs,
      invocationMessage: { kind: 'invoke', surface: invocation.surface, modulePath: canonical.modulePath, exportName: invocation.exportName,
        argument: invocation.argument, context: invocation.context.contract },
    });
  } catch (error) { failure = error; throw error; }
  finally {
    try { await group.close(); }
    catch (cleanup) {
      if (failure) throw new AggregateError([failure, cleanup], `ISOLATION_CLEANUP_FAILED:${cleanup instanceof Error ? cleanup.message : String(cleanup)}`);
      throw cleanup;
    }
  }
}

