}

function trim(value) {
  sub(/^[[:space:]]+/, "", value)
  sub(/[[:space:]]+$/, "", value)
  gsub(/^"/, "", value)
  gsub(/"$/, "", value)
  gsub(/^'/, "", value)
  gsub(/'$/, "", value)
  return value
}

$0 ~ ("^" section ":[[:space:]]*$") {
  in_section = 1
  next
}

in_section && $0 ~ /^[^[:space:]]/ {
  in_section = 0
}

in_section && $0 ~ /^[[:space:]]*-[[:space:]]+name:[[:space:]]*/ {
  value = $0
  sub(/^[[:space:]]*-[[:space:]]+name:[[:space:]]*/, "", value)
  print trim(value)
  exit
}

