normalize_boolish() {
  local value
  value="$(echo "${1:-}" | tr '[:upper:]' '[:lower:]')"
  case "$value" in
    1 | true | yes | on | enabled) echo "true" ;;
    0 | false | no | off | disabled) echo "false" ;;
    *) echo "$value" ;;
  esac
}

